CREATE OR REPLACE FUNCTION "public"."_cancel_purchase_document_core"("p_document_id" "uuid", "p_reason" "text", "p_master_password" "text" DEFAULT NULL::"text", "p_require_master_password" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  v_doc record;
  v_item record;

  v_stock_password_hash text;

  v_default_location_id uuid;
  v_default_location_name text;

  v_location_id uuid;
  v_location_name text;
  v_reversal_qty numeric;

  v_location_on_hand_before numeric := 0;
  v_location_on_hand_after numeric := 0;
  v_location_reserved numeric := 0;

  v_product_stock_before integer := 0;
  v_product_stock_after integer := 0;

  v_movement_id uuid;
  v_cancelled_items integer := 0;
  v_cancelled_quantity numeric := 0;

  v_reference text;
  v_supplier_name text;
BEGIN
  IF p_document_id IS NULL THEN
    RAISE EXCEPTION 'Documento de compra não informado.';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'Informe um motivo válido para o cancelamento.';
  END IF;

  SELECT
    pd.id,
    pd.store_id,
    pd.supplier_id,
    pd.document_code,
    pd.invoice_number,
    pd.issue_date,
    pd.total_amount,
    pd.notes,
    pd.status,
    s.name AS supplier_name
  INTO v_doc
  FROM public.purchase_documents pd
  JOIN public.suppliers s
    ON s.id = pd.supplier_id
   AND s.store_id = pd.store_id
  WHERE pd.id = p_document_id
  FOR UPDATE;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Documento não encontrado.';
  END IF;

  IF NOT public.user_can_purchase_action(v_doc.store_id, 'cancel') THEN
    RAISE EXCEPTION 'Sem permissão para cancelar compras nesta loja.';
  END IF;

  IF v_doc.status = 'cancelled' THEN
    RAISE EXCEPTION 'Documento já está cancelado.';
  END IF;

  IF v_doc.status <> 'confirmed' THEN
    RAISE EXCEPTION 'Somente documentos confirmados podem ser cancelados.';
  END IF;

  -- Compatibilidade com fluxo legado.
  -- O caminho novo deve preferir permissão efetiva + PIN/token.
  IF p_require_master_password THEN
    IF p_master_password IS NULL OR length(trim(p_master_password)) = 0 THEN
      RAISE EXCEPTION 'Informe a senha master.';
    END IF;

    SELECT st.stock_password_hash
    INTO v_stock_password_hash
    FROM public.stores st
    WHERE st.id = v_doc.store_id;

    IF v_stock_password_hash IS NULL THEN
      RAISE EXCEPTION 'Senha master da loja não configurada.';
    END IF;

    IF crypt(p_master_password, v_stock_password_hash) <> v_stock_password_hash THEN
      RAISE EXCEPTION 'Senha master inválida.';
    END IF;
  END IF;

  v_reference := COALESCE(v_doc.document_code, v_doc.invoice_number, v_doc.id::text);
  v_supplier_name := v_doc.supplier_name;

  SELECT
    sl.id,
    sl.name
  INTO
    v_default_location_id,
    v_default_location_name
  FROM public.stock_locations sl
  WHERE sl.store_id = v_doc.store_id
    AND COALESCE(sl.active, true) = true
  ORDER BY
    COALESCE(sl.is_default, false) DESC,
    (upper(COALESCE(sl.code, '')) = 'MAIN') DESC,
    sl.sort_order ASC,
    sl.created_at ASC
  LIMIT 1;

  FOR v_item IN
    SELECT
      pdi.id AS item_id,
      pdi.product_id,
      pdi.quantity AS item_quantity,
      pdi.unit_cost,
      COALESCE(pdi.total_cost, pdi.quantity * pdi.unit_cost) AS total_cost,

      pdla.id AS application_id,
      pdla.location_id AS applied_location_id,
      pdla.quantity AS applied_quantity,

      sl.name AS applied_location_name
    FROM public.purchase_document_items pdi
    LEFT JOIN public.purchase_document_location_applications pdla
      ON pdla.purchase_document_item_id = pdi.id
     AND pdla.purchase_document_id = pdi.purchase_document_id
     AND pdla.store_id = pdi.store_id
    LEFT JOIN public.stock_locations sl
      ON sl.id = pdla.location_id
     AND sl.store_id = pdi.store_id
    WHERE pdi.purchase_document_id = p_document_id
      AND pdi.store_id = v_doc.store_id
    ORDER BY pdi.id
  LOOP
    v_location_id := COALESCE(v_item.applied_location_id, v_default_location_id);
    v_location_name := COALESCE(v_item.applied_location_name, v_default_location_name);
    v_reversal_qty := COALESCE(v_item.applied_quantity, v_item.item_quantity, 0);

    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'Não foi possível identificar o local de estoque para o item %.', v_item.item_id;
    END IF;

    IF v_reversal_qty IS NULL OR v_reversal_qty <= 0 THEN
      RAISE EXCEPTION 'Quantidade inválida para cancelar o item %.', v_item.item_id;
    END IF;

    IF trunc(v_reversal_qty) <> v_reversal_qty THEN
      RAISE EXCEPTION 'O item % possui quantidade fracionada. A movimentação física atual exige quantidade inteira.', v_item.item_id;
    END IF;

    SELECT
      COALESCE(ilb.on_hand, 0),
      COALESCE(ilb.reserved, 0)
    INTO
      v_location_on_hand_before,
      v_location_reserved
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_doc.store_id
      AND ilb.location_id = v_location_id
      AND ilb.product_id = v_item.product_id
      AND ilb.variant_id IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Saldo local não encontrado para cancelar o item %. Local: %.', v_item.item_id, v_location_name;
    END IF;

    IF v_location_on_hand_before < v_reversal_qty THEN
      RAISE EXCEPTION 'Saldo insuficiente no local % para cancelar o item %. Disponível físico: %, necessário: %.',
        v_location_name,
        v_item.item_id,
        v_location_on_hand_before,
        v_reversal_qty;
    END IF;

    v_location_on_hand_after := v_location_on_hand_before - v_reversal_qty;

    UPDATE public.inventory_location_balances ilb
    SET
      on_hand = v_location_on_hand_after,
      updated_at = now()
    WHERE ilb.store_id = v_doc.store_id
      AND ilb.location_id = v_location_id
      AND ilb.product_id = v_item.product_id
      AND ilb.variant_id IS NULL;

    SELECT COALESCE(p.stock_quantity, 0)
    INTO v_product_stock_before
    FROM public.products p
    WHERE p.id = v_item.product_id
      AND p.store_id = v_doc.store_id
    FOR UPDATE;

    v_product_stock_after := v_product_stock_before - v_reversal_qty::integer;

    IF v_product_stock_after < 0 THEN
      RAISE EXCEPTION 'O cancelamento deixaria o estoque global do produto negativo. Produto: %, saldo atual: %, cancelamento: %.',
        v_item.product_id,
        v_product_stock_before,
        v_reversal_qty;
    END IF;

    PERFORM set_config('app.allow_stock_update', 'true', true);

    UPDATE public.products p
    SET stock_quantity = v_product_stock_after
    WHERE p.id = v_item.product_id
      AND p.store_id = v_doc.store_id;

    INSERT INTO public.stock_movements (
      store_id,
      product_id,
      location_id,
      from_location_id,
      to_location_id,
      type,
      quantity,
      previous_stock,
      new_stock,
      reason,
      source,
      source_id,
      reason_code,
      affects_physical,
      created_by,
      supplier_id,
      metadata
    )
    VALUES (
      v_doc.store_id,
      v_item.product_id,
      v_location_id,
      v_location_id,
      NULL,
      'exit'::public.stock_movement_type,
      -(v_reversal_qty::integer),
      v_product_stock_before,
      v_product_stock_after,
      'Cancelamento de entrada: ' || v_reference,
      'purchase_document_cancel',
      v_doc.id,
      'purchase_document_cancelled',
      true,
      auth.uid(),
      v_doc.supplier_id,
      jsonb_build_object(
        'origin', 'purchase_document_cancel',
        'purchase_document_id', v_doc.id,
        'purchase_document_item_id', v_item.item_id,
        'purchase_document_location_application_id', v_item.application_id,
        'document_code', v_doc.document_code,
        'invoice_number', v_doc.invoice_number,
        'reference', v_reference,
        'supplier_id', v_doc.supplier_id,
        'supplier_name', v_supplier_name,
        'unit_cost', v_item.unit_cost,
        'total_cost', v_item.total_cost,
        'cancel_reason', trim(p_reason),
        'location_id', v_location_id,
        'location_name', v_location_name,
        'from_location_id', v_location_id,
        'from_location_name', v_location_name,
        'destination_label', 'Cancelamento da compra',
        'movement_label', 'Cancelamento de compra',
        'on_hand_before_location', v_location_on_hand_before,
        'on_hand_after_location', v_location_on_hand_after
      )
    )
    RETURNING id INTO v_movement_id;

    v_cancelled_items := v_cancelled_items + 1;
    v_cancelled_quantity := v_cancelled_quantity + v_reversal_qty;
  END LOOP;

  UPDATE public.supplier_price_history sph
  SET
    is_active = false,
    cancelled_at = now(),
    cancelled_reason = trim(p_reason),
    metadata = COALESCE(sph.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelled_by_purchase_document', true,
      'cancelled_purchase_document_id', v_doc.id,
      'cancelled_document_code', v_doc.document_code,
      'cancel_reason', trim(p_reason),
      'phase', '9.3C.6-C'
    )
  WHERE sph.purchase_document_id = v_doc.id
    AND sph.store_id = v_doc.store_id
    AND sph.is_active = true
    AND sph.cancelled_at IS NULL;

  UPDATE public.purchase_documents pd
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    cancel_reason = trim(p_reason)
  WHERE pd.id = v_doc.id
    AND pd.store_id = v_doc.store_id;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_doc.store_id,
    p_entity_type := 'purchase_document',
    p_entity_id := v_doc.id,
    p_event_type := 'purchase_document_cancelled',
    p_title := 'Compra cancelada',
    p_description := 'Documento de compra cancelado: ' || v_reference || '.',
    p_severity := 'warning',
    p_status := 'cancelled',
    p_actor_user_id := auth.uid(),
    p_channel := 'manual',
    p_source := 'cancel_purchase_document',
    p_source_id := v_doc.id,
    p_old_data := jsonb_build_object(
      'status', v_doc.status,
      'document_code', v_doc.document_code,
      'invoice_number', v_doc.invoice_number,
      'total_amount', v_doc.total_amount
    ),
    p_new_data := jsonb_build_object(
      'status', 'cancelled',
      'cancel_reason', trim(p_reason),
      'cancelled_items', v_cancelled_items,
      'cancelled_quantity', v_cancelled_quantity,
      'document_code', v_doc.document_code,
      'invoice_number', v_doc.invoice_number
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-C',
      'origin', 'purchase_document_cancel_by_applied_location',
      'document_code', v_doc.document_code,
      'invoice_number', v_doc.invoice_number,
      'supplier_name', v_supplier_name
    ),
    p_related_supplier_id := v_doc.supplier_id,
    p_related_purchase_document_id := v_doc.id
  );
END;
$$;


ALTER FUNCTION "public"."_cancel_purchase_document_core"("p_document_id" "uuid", "p_reason" "text", "p_master_password" "text", "p_require_master_password" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_store_member_invite"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_email text;
  v_invite public.store_member_invites%ROWTYPE;
  v_member_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT email::text
  INTO v_email
  FROM auth.users
  WHERE id = v_user_id;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'E-mail do usuário autenticado não encontrado.';
  END IF;

  SELECT *
  INTO v_invite
  FROM public.store_member_invites
  WHERE store_id = p_store_id
    AND normalized_email = lower(btrim(v_email))
    AND status = 'pending'
  ORDER BY invited_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Convite pendente não encontrado para este e-mail.';
  END IF;

  IF v_invite.expires_at < now() THEN
    UPDATE public.store_member_invites
    SET
      status = 'expired',
      updated_at = now()
    WHERE id = v_invite.id;

    RAISE EXCEPTION 'Convite expirado.';
  END IF;

  INSERT INTO public.store_members (
    store_id,
    user_id,
    role,
    status,
    permissions,
    sensitive_actions,
    invited_by,
    invited_at,
    accepted_at
  )
  VALUES (
    v_invite.store_id,
    v_user_id,
    v_invite.role,
    'active',
    COALESCE(v_invite.permissions, '{}'::jsonb),
    COALESCE(v_invite.sensitive_actions, '{}'::jsonb),
    v_invite.invited_by,
    v_invite.invited_at,
    now()
  )
  ON CONFLICT (store_id, user_id)
  DO UPDATE SET
    role = EXCLUDED.role,
    status = 'active',
    permissions = EXCLUDED.permissions,
    sensitive_actions = EXCLUDED.sensitive_actions,
    updated_at = now()
  RETURNING id
  INTO v_member_id;

  UPDATE public.store_member_invites
  SET
    status = 'accepted',
    accepted_at = now(),
    accepted_by = v_user_id,
    updated_at = now()
  WHERE id = v_invite.id;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_invite.store_id,
    v_user_id,
    v_email,
    'store_member_invite_accepted',
    jsonb_build_object(
      'invite_id', v_invite.id,
      'member_id', v_member_id,
      'role', v_invite.role
    ),
    'success',
    now()
  );

  RETURN jsonb_build_object(
    'mode', 'accepted_invite',
    'invite_id', v_invite.id,
    'member_id', v_member_id,
    'store_id', v_invite.store_id,
    'user_id', v_user_id,
    'email', v_email,
    'role', v_invite.role,
    'status', 'active'
  );
END;
$$;


ALTER FUNCTION "public"."accept_store_member_invite"("p_store_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."stock_transfer_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "transfer_id" "uuid" NOT NULL,
    "store_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "requested_qty" numeric DEFAULT 0 NOT NULL,
    "shipped_qty" numeric DEFAULT 0 NOT NULL,
    "received_qty" numeric DEFAULT 0 NOT NULL,
    "divergence_qty" numeric DEFAULT 0 NOT NULL,
    "unit_cost" numeric,
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "divergence_resolution" "text",
    "divergence_reason" "text",
    "divergence_notes" "text",
    "loss_qty" numeric DEFAULT 0 NOT NULL,
    "returned_to_origin_qty" numeric DEFAULT 0 NOT NULL,
    "accepted_shortage_qty" numeric DEFAULT 0 NOT NULL,
    "divergence_resolved_at" timestamp with time zone,
    CONSTRAINT "ck_stock_transfer_items_divergence_qty_pos" CHECK (("divergence_qty" >= (0)::numeric)),
    CONSTRAINT "ck_stock_transfer_items_received_qty_pos" CHECK (("received_qty" >= (0)::numeric)),
    CONSTRAINT "ck_stock_transfer_items_requested_qty_pos" CHECK (("requested_qty" >= (0)::numeric)),
    CONSTRAINT "ck_stock_transfer_items_shipped_qty_pos" CHECK (("shipped_qty" >= (0)::numeric)),
    CONSTRAINT "stock_transfer_items_accepted_shortage_nonnegative_check" CHECK (("accepted_shortage_qty" >= (0)::numeric)),
    CONSTRAINT "stock_transfer_items_divergence_resolution_check" CHECK ((("divergence_resolution" IS NULL) OR ("divergence_resolution" = ANY (ARRAY['loss'::"text", 'return_to_origin'::"text", 'accepted_shortage'::"text"])))),
    CONSTRAINT "stock_transfer_items_loss_qty_nonnegative_check" CHECK (("loss_qty" >= (0)::numeric)),
    CONSTRAINT "stock_transfer_items_returned_qty_nonnegative_check" CHECK (("returned_to_origin_qty" >= (0)::numeric))
);


ALTER TABLE "public"."stock_transfer_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."stock_transfer_items" IS 'Itens da transferência com quantidades solicitadas, expedidas, recebidas e divergência.';



CREATE OR REPLACE FUNCTION "public"."add_stock_transfer_item"("p_transfer_id" "uuid", "p_product_id" "uuid", "p_requested_qty" numeric, "p_variant_id" "uuid" DEFAULT NULL::"uuid", "p_unit_cost" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."stock_transfer_items"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer public.stock_transfers;
    v_item public.stock_transfer_items;
begin
    select *
      into v_transfer
      from public.stock_transfers
     where id = p_transfer_id
     for update;

    if v_transfer.id is null then
        raise exception 'Transferência não encontrada' using errcode = '23503';
    end if;

    if v_transfer.status <> 'draft' then
        raise exception 'Só é permitido adicionar itens em transferências draft' using errcode = '23514';
    end if;

    if p_requested_qty is null or p_requested_qty <= 0 then
        raise exception 'p_requested_qty deve ser maior que zero' using errcode = '23514';
    end if;

    if not public.product_belongs_to_store(p_product_id, v_transfer.store_id) then
        raise exception 'Produto não pertence à store da transferência' using errcode = '23514';
    end if;

    insert into public.stock_transfer_items (
        transfer_id,
        store_id,
        product_id,
        variant_id,
        requested_qty,
        shipped_qty,
        received_qty,
        divergence_qty,
        unit_cost,
        notes,
        metadata
    )
    values (
        v_transfer.id,
        v_transfer.store_id,
        p_product_id,
        p_variant_id,
        p_requested_qty,
        0,
        0,
        0,
        p_unit_cost,
        p_notes,
        coalesce(p_metadata, '{}'::jsonb)
    )
    returning * into v_item;

    return v_item;
end;
$$;


ALTER FUNCTION "public"."add_stock_transfer_item"("p_transfer_id" "uuid", "p_product_id" "uuid", "p_requested_qty" numeric, "p_variant_id" "uuid", "p_unit_cost" numeric, "p_notes" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_stock_transfer_item"("p_transfer_id" "uuid", "p_product_id" "uuid", "p_requested_qty" numeric, "p_variant_id" "uuid", "p_unit_cost" numeric, "p_notes" "text", "p_metadata" "jsonb") IS 'Adiciona item a uma transferência draft.';



CREATE OR REPLACE FUNCTION "public"."add_store_member_by_email"("p_store_id" "uuid", "p_email" "text", "p_role" "text" DEFAULT 'staff'::"text", "p_status" "text" DEFAULT 'active'::"text", "p_permissions" "jsonb" DEFAULT '{}'::"jsonb", "p_sensitive_actions" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_email" "text", "role" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_target_user_id uuid;
  v_target_email text;
  v_member_id uuid;
  v_actor_email text;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if p_email is null or btrim(p_email) = '' then
    raise exception 'E-mail do usuário é obrigatório.';
  end if;

  if p_role not in (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'viewer',
    'staff'
  ) then
    raise exception 'Papel inválido para novo membro: %', p_role;
  end if;

  if p_status not in ('active', 'inactive', 'suspended', 'invited') then
    raise exception 'Status inválido para novo membro: %', p_status;
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.user_has_store_permission(p_store_id, 'users.manage')
  ) then
    raise exception 'Você não tem permissão para adicionar usuários.';
  end if;

  select
    au.id,
    au.email::text
  into
    v_target_user_id,
    v_target_email
  from auth.users au
  where lower(au.email::text) = lower(btrim(p_email))
  limit 1;

  if v_target_user_id is null then
    raise exception 'Usuário não encontrado no Auth com este e-mail: %', p_email;
  end if;

  if v_target_user_id = auth.uid() then
    raise exception 'Você não pode adicionar ou alterar seu próprio vínculo por esta rotina.';
  end if;

  select email::text
  into v_actor_email
  from auth.users
  where id = auth.uid();

  insert into public.store_members (
    store_id,
    user_id,
    role,
    status,
    permissions,
    sensitive_actions,
    invited_by,
    invited_at,
    accepted_at
  )
  values (
    p_store_id,
    v_target_user_id,
    p_role,
    p_status,
    coalesce(p_permissions, '{}'::jsonb),
    coalesce(p_sensitive_actions, '{}'::jsonb),
    auth.uid(),
    now(),
    case when p_status = 'active' then now() else null end
  )
  on conflict (store_id, user_id)
  do update set
    role = excluded.role,
    status = excluded.status,
    permissions = excluded.permissions,
    sensitive_actions = excluded.sensitive_actions,
    updated_at = now()
  returning id
  into v_member_id;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  values (
    p_store_id,
    auth.uid(),
    v_actor_email,
    'store_member_added_or_updated_by_email',
    jsonb_build_object(
      'member_id', v_member_id,
      'target_user_id', v_target_user_id,
      'target_email', v_target_email,
      'role', p_role,
      'status', p_status
    ),
    'success',
    now()
  );

  return query
  select
    sm.id as member_id,
    sm.store_id,
    sm.user_id,
    v_target_email as user_email,
    sm.role,
    sm.status,
    sm.created_at,
    sm.updated_at
  from public.store_members sm
  where sm.id = v_member_id;
end;
$$;


ALTER FUNCTION "public"."add_store_member_by_email"("p_store_id" "uuid", "p_email" "text", "p_role" "text", "p_status" "text", "p_permissions" "jsonb", "p_sensitive_actions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_stock_to_physical_count"("p_product_id" "uuid", "p_location_id" "uuid", "p_counted_quantity" numeric, "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("movement_id" "uuid", "product_id" "uuid", "location_id" "uuid", "previous_quantity" numeric, "counted_quantity" numeric, "adjustment_quantity" numeric, "movement_type" "public"."stock_movement_type", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_movement_id uuid;

  v_on_hand_before numeric := 0;
  v_on_hand_after numeric := 0;
  v_reserved numeric := 0;
  v_available numeric := 0;

  v_adjustment numeric := 0;
  v_movement_type public.stock_movement_type;
  v_reason text;

  v_has_balance boolean := false;
BEGIN
  IF p_counted_quantity IS NULL OR p_counted_quantity < 0 THEN
    RAISE EXCEPTION 'A contagem física não pode ser negativa.';
  END IF;

  SELECT p.store_id
    INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao produto informado.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stock_locations sl
    WHERE sl.id = p_location_id
      AND sl.store_id = v_store_id
      AND sl.active = true
  ) THEN
    RAISE EXCEPTION 'Local de estoque inválido ou inativo.';
  END IF;

  SELECT
    true,
    COALESCE(ilb.on_hand, 0),
    COALESCE(ilb.reserved, 0)
  INTO
    v_has_balance,
    v_on_hand_before,
    v_reserved
  FROM public.inventory_location_balances ilb
  WHERE ilb.store_id = v_store_id
    AND ilb.product_id = p_product_id
    AND ilb.location_id = p_location_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_has_balance := false;
    v_on_hand_before := 0;
    v_reserved := 0;
  END IF;

  v_available := v_on_hand_before - v_reserved;
  v_on_hand_after := p_counted_quantity;
  v_adjustment := v_on_hand_after - v_on_hand_before;

  IF v_adjustment = 0 THEN
    RETURN QUERY
    SELECT
      NULL::uuid,
      p_product_id,
      p_location_id,
      v_on_hand_before,
      p_counted_quantity,
      0::numeric,
      NULL::public.stock_movement_type,
      'Nenhum ajuste necessário. A contagem física confere com o estoque atual.'::text;

    RETURN;
  END IF;

  IF p_counted_quantity < v_reserved THEN
    RAISE EXCEPTION 'A contagem física informada é menor que a quantidade reservada. Reservado: %, contado: %.',
      v_reserved,
      p_counted_quantity;
  END IF;

  IF v_adjustment > 0 THEN
    v_movement_type := 'entry';
    v_reason := COALESCE(NULLIF(p_reason, ''), 'Entrada por ajuste de inventário');
  ELSE
    v_movement_type := 'clearance';
    v_reason := COALESCE(NULLIF(p_reason, ''), 'Baixa por ajuste de inventário');
  END IF;

  IF v_has_balance THEN
    UPDATE public.inventory_location_balances ilb
    SET
      on_hand = v_on_hand_after,
      updated_at = now()
    WHERE ilb.store_id = v_store_id
      AND ilb.product_id = p_product_id
      AND ilb.location_id = p_location_id;
  ELSE
    INSERT INTO public.inventory_location_balances (
      store_id,
      product_id,
      location_id,
      on_hand,
      reserved
    )
    VALUES (
      v_store_id,
      p_product_id,
      p_location_id,
      v_on_hand_after,
      0
    );
  END IF;

  INSERT INTO public.stock_movements (
    store_id,
    product_id,
    location_id,
    type,
    quantity,
    previous_stock,
    new_stock,
    reason,
    source,
    source_id,
    affects_physical,
    created_by,
    metadata
  )
  VALUES (
    v_store_id,
    p_product_id,
    p_location_id,
    v_movement_type,
    v_adjustment::integer,
    v_on_hand_before::integer,
    v_on_hand_after::integer,
    v_reason,
    'physical_count_adjustment',
    NULL,
    true,
    auth.uid(),
    jsonb_build_object(
      'adjustment_kind', 'physical_count',
      'notes', p_notes,
      'created_from', 'stock_movements_page',
      'location_id', p_location_id,
      'on_hand_before', v_on_hand_before,
      'counted_quantity', p_counted_quantity,
      'adjustment_quantity', v_adjustment,
      'reserved', v_reserved,
      'available_before', v_available
    )
  )
  RETURNING id INTO v_movement_id;

  RETURN QUERY
  SELECT
    v_movement_id,
    p_product_id,
    p_location_id,
    v_on_hand_before,
    p_counted_quantity,
    v_adjustment,
    v_movement_type,
    'Estoque ajustado para a contagem física informada.'::text;
END;
$$;


ALTER FUNCTION "public"."adjust_stock_to_physical_count"("p_product_id" "uuid", "p_location_id" "uuid", "p_counted_quantity" numeric, "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."adjust_stock_to_physical_count"("p_product_id" "uuid", "p_location_id" "uuid", "p_counted_quantity" numeric, "p_reason" "text", "p_notes" "text") IS 'Ajusta o estoque de um produto/local para uma contagem física informada, calculando automaticamente a diferença e registrando o histórico.';



CREATE OR REPLACE FUNCTION "public"."admin_cancel_public_order_safe"("p_order_id" "uuid", "p_reason" "text" DEFAULT 'Cancelado pelo painel administrativo'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_res record;
  v_before_reserved numeric := 0;
  v_after_reserved numeric := 0;
  v_released_count integer := 0;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_order_id');
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status,
    o.commercial_metadata
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF v_order.status::text = 'completed' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_already_completed',
      'message', 'Pedido concluído não deve ser cancelado por este fluxo.'
    );
  END IF;

  IF v_order.status::text = 'cancelled' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_cancelled',
      'order_id', v_order.id,
      'order_code', v_order.order_code
    );
  END IF;

  FOR v_res IN
    SELECT
      sr.id,
      sr.store_id,
      sr.product_id,
      sr.location_id,
      sr.quantity
    FROM public.stock_reservations sr
    WHERE sr.order_id = v_order.id
      AND sr.status = 'active'
  LOOP
    SELECT COALESCE(ilb.reserved, 0)
    INTO v_before_reserved
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_res.store_id
      AND ilb.product_id = v_res.product_id
      AND ilb.location_id = v_res.location_id;

    UPDATE public.stock_reservations
    SET
      status = 'cancelled',
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'cancelled_at', now(),
        'cancelled_by', auth.uid(),
        'cancel_reason', p_reason,
        'cancelled_by_function', 'admin_cancel_public_order_safe'
      )
    WHERE id = v_res.id;

    SELECT COALESCE(ilb.reserved, 0)
    INTO v_after_reserved
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_res.store_id
      AND ilb.product_id = v_res.product_id
      AND ilb.location_id = v_res.location_id;

    -- Se nenhum trigger liberou a reserva, libera manualmente.
    IF v_after_reserved >= v_before_reserved THEN
      UPDATE public.inventory_location_balances ilb
      SET reserved = GREATEST(COALESCE(ilb.reserved, 0) - COALESCE(v_res.quantity, 0), 0)
      WHERE ilb.store_id = v_res.store_id
        AND ilb.product_id = v_res.product_id
        AND ilb.location_id = v_res.location_id;
    END IF;

    v_released_count := v_released_count + 1;
  END LOOP;

  UPDATE public.orders
  SET
    status = 'cancelled',
    commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelled_at', now(),
      'cancelled_by', auth.uid(),
      'cancelled_reason', p_reason,
      'cancelled_by_function', 'admin_cancel_public_order_safe'
    ),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'last_status_update_function', 'admin_cancel_public_order_safe'
    )
  WHERE id = v_order.id;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'order_code', v_order.order_code,
    'status', 'cancelled',
    'reservations_released', v_released_count
  );
END;
$$;


ALTER FUNCTION "public"."admin_cancel_public_order_safe"("p_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_complete_public_order_safe"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_result jsonb;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_order_id');
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF v_order.status::text = 'completed' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_completed',
      'order_id', v_order.id,
      'order_code', v_order.order_code
    );
  END IF;

  IF v_order.status::text <> 'confirmed' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_confirmed',
      'current_status', v_order.status::text,
      'message', 'Só pedidos confirmados/em preparo devem ser finalizados por este fluxo.'
    );
  END IF;

  v_result := public.complete_confirmed_public_order(v_order.id);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."admin_complete_public_order_safe"("p_order_id" "uuid") OWNER TO "postgres";


