    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    coalesce(
      nullif(public.app_jwt_claim('store_id'), '')::uuid,
      (select s.id from public.stores s where s.user_id = auth.uid() limit 1)
    );
