CREATE OR REPLACE FUNCTION "public"."app_current_store_role"("p_store_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT sm.role
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = auth.uid()
    AND sm.status = 'active'
  ORDER BY
    CASE sm.role
      WHEN 'owner' THEN 1
      WHEN 'admin' THEN 2
      WHEN 'manager' THEN 3
      WHEN 'stock_operator' THEN 4
      WHEN 'cashier' THEN 5
      WHEN 'sales' THEN 6
      WHEN 'staff' THEN 7
      WHEN 'viewer' THEN 8
      ELSE 99
    END
  LIMIT 1;
$$;


ALTER FUNCTION "public"."app_current_store_role"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_generate_otp"("p_length" integer DEFAULT 6) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  otp text := '';
  i int;
begin
  if p_length < 4 then
    p_length := 4;
  end if;

  for i in 1..p_length loop
    otp := otp || floor(random() * 10)::int::text;
  end loop;

  return otp;
end;
$$;


ALTER FUNCTION "public"."app_generate_otp"("p_length" integer) OWNER TO "postgres";


