CREATE OR REPLACE FUNCTION "public"."app_role_rank"("p_role" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
  SELECT CASE p_role
    WHEN 'owner' THEN 100
    WHEN 'admin' THEN 90
    WHEN 'manager' THEN 70
    WHEN 'stock_operator' THEN 60
    WHEN 'cashier' THEN 50
    WHEN 'sales' THEN 40
    WHEN 'staff' THEN 30
    WHEN 'viewer' THEN 10
    ELSE 0
  END;
