CREATE TABLE IF NOT EXISTS "public"."inventory_balances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "on_hand" numeric(12,3) DEFAULT 0 NOT NULL,
    "reserved" numeric(12,3) DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."inventory_balances" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_inventory_balance_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid", "p_delta_on_hand" numeric, "p_delta_reserved" numeric) RETURNS "public"."inventory_balances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_current public.inventory_balances;
    v_new_on_hand numeric;
    v_new_reserved numeric;
    v_row public.inventory_balances;
begin
    v_current := public.get_inventory_balance_for_update(
        p_store_id,
        p_product_id,
        p_variant_id
    );

    v_new_on_hand := coalesce(v_current.on_hand, 0) + coalesce(p_delta_on_hand, 0);
    v_new_reserved := coalesce(v_current.reserved, 0) + coalesce(p_delta_reserved, 0);

    if v_new_on_hand < 0 then
        raise exception 'Saldo físico consolidado insuficiente. Atual: %, delta: %, resultado: %',
            v_current.on_hand, p_delta_on_hand, v_new_on_hand
            using errcode = '23514';
    end if;

    if v_new_reserved < 0 then
        raise exception 'Saldo reservado consolidado insuficiente. Atual: %, delta: %, resultado: %',
            v_current.reserved, p_delta_reserved, v_new_reserved
            using errcode = '23514';
    end if;

    if v_new_reserved > v_new_on_hand then
        raise exception 'Saldo reservado consolidado não pode exceder saldo físico'
            using errcode = '23514';
    end if;

    update public.inventory_balances
       set on_hand = v_new_on_hand,
           reserved = v_new_reserved,
           updated_at = now()
     where id = v_current.id
    returning *
      into v_row;

    return v_row;
end;
$$;


ALTER FUNCTION "public"."apply_inventory_balance_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid", "p_delta_on_hand" numeric, "p_delta_reserved" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."inventory_location_balances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "on_hand" numeric DEFAULT 0 NOT NULL,
    "reserved" numeric DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ck_inventory_location_balances_non_negative" CHECK ((("on_hand" >= (0)::numeric) AND ("reserved" >= (0)::numeric))),
    CONSTRAINT "ck_inventory_location_balances_reserved_le_on_hand" CHECK (("reserved" <= "on_hand"))
);


ALTER TABLE "public"."inventory_location_balances" OWNER TO "postgres";


COMMENT ON TABLE "public"."inventory_location_balances" IS 'Saldo por local de estoque e por produto/variante. Base do multiestoque.';



CREATE OR REPLACE FUNCTION "public"."apply_inventory_location_delta"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid", "p_delta_on_hand" numeric, "p_delta_reserved" numeric) RETURNS "public"."inventory_location_balances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_current public.inventory_location_balances;
    v_new_on_hand numeric;
    v_new_reserved numeric;
    v_row public.inventory_location_balances;
begin
    v_current := public.get_inventory_location_balance_for_update(
        p_store_id,
        p_location_id,
        p_product_id,
        p_variant_id
    );

    v_new_on_hand := coalesce(v_current.on_hand, 0) + coalesce(p_delta_on_hand, 0);
    v_new_reserved := coalesce(v_current.reserved, 0) + coalesce(p_delta_reserved, 0);

    if v_new_on_hand < 0 then
        raise exception 'Saldo físico insuficiente no local. Atual: %, delta: %, resultado: %',
            v_current.on_hand, p_delta_on_hand, v_new_on_hand
            using errcode = '23514';
    end if;

    if v_new_reserved < 0 then
        raise exception 'Saldo reservado insuficiente no local. Atual: %, delta: %, resultado: %',
            v_current.reserved, p_delta_reserved, v_new_reserved
            using errcode = '23514';
    end if;

    if v_new_reserved > v_new_on_hand then
        raise exception 'Saldo reservado não pode exceder saldo físico no local. on_hand: %, reserved: %',
            v_new_on_hand, v_new_reserved
            using errcode = '23514';
    end if;

    update public.inventory_location_balances
       set on_hand = v_new_on_hand,
           reserved = v_new_reserved,
           updated_at = now()
     where id = v_current.id
    returning *
      into v_row;

    return v_row;
end;
$$;


ALTER FUNCTION "public"."apply_inventory_location_delta"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid", "p_delta_on_hand" numeric, "p_delta_reserved" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_order_loyalty_points_advanced"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_calc jsonb;
  v_order record;
  v_points integer := 0;
  v_program_id uuid;
  v_transaction_id uuid;
  v_new_points integer := 0;
  v_new_tier_id uuid;
  v_new_tier_name text;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_order_id');
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.customer_id,
    o.status,
    o.order_code,
    o.total
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_customer_id');
  END IF;

  IF v_order.status::text <> 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_completed');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.loyalty_transactions lt
    WHERE lt.order_id = p_order_id
      AND lt.customer_id = v_order.customer_id
      AND lt.type = 'order'
  ) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'loyalty_already_applied',
      'order_id', p_order_id
    );
  END IF;

  v_calc := public.calculate_order_loyalty_points_advanced(p_order_id);

  IF COALESCE((v_calc->>'ok')::boolean, false) = false THEN
    RETURN v_calc;
  END IF;

  v_points := COALESCE((v_calc->>'points')::integer, 0);
  v_program_id := NULLIF(v_calc->>'program_id', '')::uuid;

  IF v_points <= 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', COALESCE(v_calc->>'reason', 'zero_points'),
      'order_id', p_order_id,
      'points', 0,
      'calculation', v_calc
    );
  END IF;

  INSERT INTO public.loyalty_transactions (
    customer_id,
    type,
    points,
    description,
    order_id,
    program_id,
    created_by
  )
  VALUES (
    v_order.customer_id,
    'order',
    v_points,
    'Pontos ganhos pelo pedido ' || COALESCE(v_order.order_code, '#' || substring(v_order.id::text, 1, 8)),
    v_order.id,
    v_program_id,
    auth.uid()
  )
  RETURNING id INTO v_transaction_id;

  UPDATE public.customers c
  SET
    loyalty_points = COALESCE(c.loyalty_points, 0) + v_points,
    last_point_activity_at = now()
  WHERE c.id = v_order.customer_id
  RETURNING loyalty_points INTO v_new_points;

  SELECT
    ft.id,
    ft.name
  INTO
    v_new_tier_id,
    v_new_tier_name
  FROM public.fidelity_tiers ft
  WHERE ft.store_id = v_order.store_id
    AND ft.min_points <= v_new_points
  ORDER BY ft.min_points DESC
  LIMIT 1;

  IF v_new_tier_id IS NOT NULL THEN
    UPDATE public.customers
    SET
      current_tier_id = v_new_tier_id,
      loyalty_tier = v_new_tier_name
    WHERE id = v_order.customer_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', p_order_id,
    'customer_id', v_order.customer_id,
    'transaction_id', v_transaction_id,
    'points_awarded', v_points,
    'new_points_balance', v_new_points,
    'new_tier_id', v_new_tier_id,
    'new_tier_name', v_new_tier_name,
    'calculation', v_calc
  );
END;
$$;


ALTER FUNCTION "public"."apply_order_loyalty_points_advanced"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_purchase_document_to_default_location"("p_purchase_document_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("purchase_document_id" "uuid", "location_id" "uuid", "applied_items" integer, "applied_quantity" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_document public.purchase_documents%ROWTYPE;
  v_location_id uuid;
  v_location_name text;
  v_item record;
  v_inserted integer;
  v_applied_items integer := 0;
  v_applied_quantity numeric := 0;
BEGIN
  IF p_purchase_document_id IS NULL THEN
    RAISE EXCEPTION 'Documento de compra não informado.';
  END IF;

  SELECT *
  INTO v_document
  FROM public.purchase_documents pd
  WHERE pd.id = p_purchase_document_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Documento de compra não encontrado.';
  END IF;

  IF NOT public.user_can_purchase_action(v_document.store_id, 'apply_stock') THEN
    RAISE EXCEPTION 'Sem permissão para aplicar compra ao estoque nesta loja.';
  END IF;

  IF v_document.status <> 'confirmed' THEN
    RAISE EXCEPTION 'Documento de compra ainda não está confirmado.';
  END IF;

  IF p_location_id IS NOT NULL THEN
    SELECT
      sl.id,
      sl.name
    INTO
      v_location_id,
      v_location_name
    FROM public.stock_locations sl
    WHERE sl.id = p_location_id
      AND sl.store_id = v_document.store_id
      AND COALESCE(sl.active, true) = true;

    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'Local de estoque informado é inválido para esta loja.';
    END IF;
  ELSE
    SELECT
      sl.id,
      sl.name
    INTO
      v_location_id,
      v_location_name
    FROM public.stock_locations sl
    WHERE sl.store_id = v_document.store_id
      AND COALESCE(sl.active, true) = true
    ORDER BY
      COALESCE(sl.is_default, false) DESC,
      (upper(COALESCE(sl.code, '')) = 'MAIN') DESC,
      sl.sort_order ASC,
      sl.created_at ASC
    LIMIT 1;

    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'Nenhum local de estoque ativo encontrado para a loja.';
    END IF;
  END IF;

  IF v_document.document_code IS NULL THEN
    UPDATE public.purchase_documents pd
    SET document_code = public.generate_purchase_document_code(v_document.store_id)
    WHERE pd.id = v_document.id
    RETURNING * INTO v_document;
  END IF;

  FOR v_item IN
    SELECT
      pdi.id AS item_id,
      pdi.product_id,
      pdi.quantity,
      pdi.unit_cost
    FROM public.purchase_document_items pdi
    WHERE pdi.purchase_document_id = v_document.id
      AND pdi.store_id = v_document.store_id
      AND pdi.quantity > 0
  LOOP
    INSERT INTO public.purchase_document_location_applications (
      purchase_document_id,
      purchase_document_item_id,
      store_id,
      supplier_id,
      location_id,
      product_id,
      quantity,
      unit_cost,
      metadata
    )
    VALUES (
      v_document.id,
      v_item.item_id,
      v_document.store_id,
      v_document.supplier_id,
      v_location_id,
      v_item.product_id,
      v_item.quantity,
      COALESCE(v_item.unit_cost, 0),
      jsonb_build_object(
        'source', 'purchase_document_confirmed',
        'applied_by', 'apply_purchase_document_to_default_location',
        'document_code', v_document.document_code,
        'location_name', v_location_name
      )
    )
    ON CONFLICT (purchase_document_item_id) DO NOTHING;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    IF v_inserted > 0 THEN
      UPDATE public.inventory_location_balances ilb
      SET
        on_hand = ilb.on_hand + v_item.quantity,
        updated_at = now()
      WHERE ilb.store_id = v_document.store_id
        AND ilb.location_id = v_location_id
        AND ilb.product_id = v_item.product_id
        AND ilb.variant_id IS NULL;

      IF NOT FOUND THEN
        INSERT INTO public.inventory_location_balances (
          store_id,
          location_id,
          product_id,
          variant_id,
          on_hand,
          reserved,
          updated_at
        )
        VALUES (
          v_document.store_id,
          v_location_id,
          v_item.product_id,
          NULL,
          v_item.quantity,
          0,
          now()
        );
      END IF;

      UPDATE public.products p
      SET
        last_entry_unit_cost = COALESCE(v_item.unit_cost, p.last_entry_unit_cost),
        last_stock_entry_at = now()
      WHERE p.id = v_item.product_id
        AND p.store_id = v_document.store_id;

      UPDATE public.stock_movements sm
      SET
        location_id = v_location_id,
        to_location_id = v_location_id,
        supplier_id = v_document.supplier_id,
        source_id = v_document.id,
        metadata = COALESCE(sm.metadata, '{}'::jsonb) || jsonb_build_object(
          'purchase_document_id', v_document.id,
          'purchase_document_item_id', v_item.item_id,
          'document_code', v_document.document_code,
          'invoice_number', v_document.invoice_number,
          'location_id', v_location_id,
          'location_name', v_location_name,
          'origin', 'purchase_document',
          'location_applied_by', 'apply_purchase_document_to_default_location'
        )
      WHERE sm.id = (
        SELECT sm2.id
        FROM public.stock_movements sm2
        WHERE sm2.store_id = v_document.store_id
          AND sm2.product_id = v_item.product_id
          AND sm2.type = 'entry'::public.stock_movement_type
          AND sm2.source = 'purchase_document'
          AND (
            sm2.source_id = v_document.id
            OR sm2.metadata->>'purchase_document_id' = v_document.id::text
          )
        ORDER BY sm2.created_at DESC
        LIMIT 1
      );

      v_applied_items := v_applied_items + 1;
      v_applied_quantity := v_applied_quantity + v_item.quantity;
    END IF;
  END LOOP;

  IF v_applied_items > 0 THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_document.store_id,
      p_entity_type := 'purchase_document',
      p_entity_id := v_document.id,
      p_event_type := 'purchase_document_applied_to_inventory',
      p_title := 'Compra aplicada ao estoque',
      p_description := 'Compra aplicada ao estoque no local ' || COALESCE(v_location_name, v_location_id::text) || '.',
      p_severity := 'success',
      p_status := 'done',
      p_channel := 'system',
      p_source := 'apply_purchase_document_to_default_location',
      p_source_id := v_document.id,
      p_new_data := jsonb_build_object(
        'purchase_document_id', v_document.id,
        'document_code', v_document.document_code,
        'invoice_number', v_document.invoice_number,
        'location_id', v_location_id,
        'location_name', v_location_name,
        'applied_items', v_applied_items,
        'applied_quantity', v_applied_quantity
      ),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-C',
        'origin', 'purchase_document_location_application',
        'document_code', v_document.document_code,
        'invoice_number', v_document.invoice_number,
        'location_name', v_location_name
      ),
      p_related_supplier_id := v_document.supplier_id,
      p_related_purchase_document_id := v_document.id
    );
  END IF;

  RETURN QUERY
  SELECT
    v_document.id AS purchase_document_id,
    v_location_id AS location_id,
    v_applied_items AS applied_items,
    v_applied_quantity AS applied_quantity;
END;
$$;


ALTER FUNCTION "public"."apply_purchase_document_to_default_location"("p_purchase_document_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_purchase_document_to_default_location"("p_purchase_document_id" "uuid", "p_location_id" "uuid") IS 'FASE 6.5A: aplica itens de documento de compra confirmado no estoque por local padrão da loja, com ledger idempotente para evitar dupla aplicação.';



CREATE OR REPLACE FUNCTION "public"."apply_stock_movement_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_quantity" integer, "p_type" "public"."stock_movement_type", "p_reason" "text", "p_created_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
begin
  perform public.apply_stock_movement_delta(
    p_store_id,
    p_product_id,
    p_type,
    p_quantity::numeric,
    true,
    p_reason,
    null::uuid,
    null::text,
    '{}'::jsonb,
    p_created_by
  );
end;
$$;


ALTER FUNCTION "public"."apply_stock_movement_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_quantity" integer, "p_type" "public"."stock_movement_type", "p_reason" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_stock_movement_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_type" "public"."stock_movement_type", "p_quantity" numeric, "p_affects_physical" boolean, "p_reason" "text", "p_order_id" "uuid", "p_source" "text", "p_metadata" "jsonb", "p_created_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_current integer;
  v_new integer;
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_movement_quantity integer;
begin
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Quantidade inválida';
  end if;

  select stock_quantity
    into v_current
  from public.products
  where id = p_product_id
    and store_id = p_store_id
  for update;

  if v_current is null then
    raise exception 'Produto não encontrado';
  end if;

  if p_type = 'entry' then
    v_new := v_current + p_quantity::integer;
    v_movement_quantity := p_quantity::integer;
  elsif p_type in ('exit', 'clearance') then
    v_new := v_current - p_quantity::integer;
    v_movement_quantity := -(p_quantity::integer);
  else
    raise exception 'Tipo de movimento não suportado nesta função: %', p_type;
  end if;

  if v_new < 0 then
    raise exception 'Estoque não pode ficar negativo';
  end if;

  if coalesce(p_affects_physical, true) then
    perform set_config('app.allow_stock_update', 'true', true);

    update public.products
    set
      stock_quantity = v_new,
      last_stock_entry_at = case
        when p_type = 'entry' then now()
        else last_stock_entry_at
      end,
      last_entry_unit_cost = case
        when p_type = 'entry'
          and (v_metadata ? 'unit_cost')
          and nullif(v_metadata->>'unit_cost', '') is not null
        then (v_metadata->>'unit_cost')::numeric
        else last_entry_unit_cost
      end
    where id = p_product_id
      and store_id = p_store_id;
  end if;

  insert into public.stock_movements (
    product_id,
    order_id,
    quantity,
    type,
    reason,
    previous_stock,
    new_stock,
    created_at,
    store_id,
    affects_physical,
    source,
    source_id,
    metadata,
    created_by
  )
  values (
    p_product_id,
    p_order_id,
    v_movement_quantity,
    p_type,
    p_reason,
    v_current,
    v_new,
    now(),
    p_store_id,
    coalesce(p_affects_physical, true),
    p_source,
    null,
    v_metadata,
    p_created_by
  );
end;
$$;


ALTER FUNCTION "public"."apply_stock_movement_delta"("p_store_id" "uuid", "p_product_id" "uuid", "p_type" "public"."stock_movement_type", "p_quantity" numeric, "p_affects_physical" boolean, "p_reason" "text", "p_order_id" "uuid", "p_source" "text", "p_metadata" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_stock_movement_delta_v2"("p_store_id" "uuid", "p_product_id" "uuid", "p_movement_type" "public"."stock_movement_type", "p_quantity" numeric, "p_affects_physical" boolean DEFAULT true, "p_reason" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_from_location_id" "uuid" DEFAULT NULL::"uuid", "p_to_location_id" "uuid" DEFAULT NULL::"uuid", "p_transfer_id" "uuid" DEFAULT NULL::"uuid", "p_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_reason_code" "text" DEFAULT NULL::"text", "p_variant_id" "uuid" DEFAULT NULL::"uuid", "p_sync_legacy_balance" boolean DEFAULT true) RETURNS TABLE("movement_id" "uuid", "store_id" "uuid", "product_id" "uuid", "variant_id" "uuid", "movement_type" "public"."stock_movement_type", "quantity" numeric, "location_id" "uuid", "from_location_id" "uuid", "to_location_id" "uuid", "transfer_id" "uuid", "on_hand_after_location" numeric, "reserved_after_location" numeric, "on_hand_after_store" numeric, "reserved_after_store" numeric, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_effective_location_id uuid;
    v_effective_from_location_id uuid;
    v_effective_to_location_id uuid;

    v_delta_on_hand numeric := 0;
    v_delta_reserved numeric := 0;

    v_location_after public.inventory_location_balances;
    v_store_after public.inventory_balances;

    v_previous_stock integer := 0;
    v_new_stock integer := 0;
    v_movement_id uuid;
    v_created_at timestamptz := now();

    v_legacy_quantity integer := 0;
    v_legacy_affects_physical boolean := p_affects_physical;
    v_write_stock_movements boolean := true;
    v_write_audit_log boolean := false;
begin
    if p_store_id is null then
        raise exception 'p_store_id é obrigatório' using errcode = '23514';
    end if;

    if p_product_id is null then
        raise exception 'p_product_id é obrigatório' using errcode = '23514';
    end if;

    if p_quantity is null or p_quantity <= 0 then
        raise exception 'p_quantity deve ser maior que zero' using errcode = '23514';
    end if;

    if trunc(p_quantity) <> p_quantity then
        raise exception 'Nesta fase, p_quantity deve ser inteira para compatibilidade com stock_movements.quantity'
            using errcode = '23514';
    end if;

    if not public.product_belongs_to_store(p_product_id, p_store_id) then
        raise exception 'Produto % não pertence à loja %', p_product_id, p_store_id
            using errcode = '23514';
    end if;

    v_effective_location_id := p_location_id;
    v_effective_from_location_id := p_from_location_id;
    v_effective_to_location_id := p_to_location_id;

    if v_effective_location_id is null
       and v_effective_from_location_id is null
       and v_effective_to_location_id is null then
        v_effective_location_id := public.get_default_stock_location_id(p_store_id);
    end if;

    case p_movement_type
        when 'entry' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := p_quantity;
            v_delta_reserved := 0;
            v_legacy_quantity := p_quantity::integer;
            v_legacy_affects_physical := true;
            v_write_stock_movements := true;
            v_write_audit_log := false;

        when 'exit' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := -p_quantity;
            v_delta_reserved := 0;
            v_legacy_quantity := (p_quantity::integer) * -1;
            v_legacy_affects_physical := true;
            v_write_stock_movements := true;
            v_write_audit_log := false;

        when 'reservation' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := 0;
            v_delta_reserved := p_quantity;
            v_write_stock_movements := false;
            v_write_audit_log := true;

        when 'confirmation' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := -p_quantity;
            v_delta_reserved := -p_quantity;
            v_legacy_quantity := (p_quantity::integer) * -1;
            v_legacy_affects_physical := true;
            v_write_stock_movements := true;
            v_write_audit_log := false;

        when 'cancellation' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := 0;
            v_delta_reserved := -p_quantity;
            v_write_stock_movements := false;
            v_write_audit_log := true;

        when 'clearance' then
            v_effective_location_id := coalesce(v_effective_location_id, public.get_default_stock_location_id(p_store_id));
            v_delta_on_hand := -p_quantity;
            v_delta_reserved := 0;
            v_legacy_quantity := (p_quantity::integer) * -1;
            v_legacy_affects_physical := true;
            v_write_stock_movements := true;
            v_write_audit_log := false;

        else
            raise exception 'Tipo de movimento não suportado na V2: %', p_movement_type
                using errcode = '23514';
    end case;

    if v_effective_location_id is not null
       and not public.stock_location_belongs_to_store(v_effective_location_id, p_store_id) then
        raise exception 'location_id % não pertence à store_id %',
            v_effective_location_id, p_store_id
            using errcode = '23514';
    end if;

    if v_effective_from_location_id is not null
       and not public.stock_location_belongs_to_store(v_effective_from_location_id, p_store_id) then
        raise exception 'from_location_id % não pertence à store_id %',
            v_effective_from_location_id, p_store_id
            using errcode = '23514';
    end if;

    if v_effective_to_location_id is not null
       and not public.stock_location_belongs_to_store(v_effective_to_location_id, p_store_id) then
        raise exception 'to_location_id % não pertence à store_id %',
            v_effective_to_location_id, p_store_id
            using errcode = '23514';
    end if;

    v_location_after := public.apply_inventory_location_delta(
        p_store_id,
        v_effective_location_id,
        p_product_id,
        p_variant_id,
        v_delta_on_hand,
        v_delta_reserved
    );

    if p_sync_legacy_balance then
        v_store_after := public.apply_inventory_balance_delta(
            p_store_id,
            p_product_id,
            p_variant_id,
            v_delta_on_hand,
            v_delta_reserved
        );
    else
        select *
          into v_store_after
          from public.get_inventory_balance_for_update(p_store_id, p_product_id, p_variant_id);
    end if;

    v_previous_stock := (coalesce(v_store_after.on_hand, 0) - v_delta_on_hand)::integer;
    v_new_stock := coalesce(v_store_after.on_hand, 0)::integer;

    if v_write_stock_movements then
        insert into public.stock_movements (
            product_id,
            order_id,
            quantity,
            type,
            reason,
            user_id,
            previous_stock,
            new_stock,
            created_at,
            store_id,
            affects_physical,
            source,
            source_id,
            reason_code,
            metadata,
            created_by,
            supplier_id,
            location_id,
            from_location_id,
            to_location_id,
            transfer_id
        )
        values (
            p_product_id,
            p_order_id,
            v_legacy_quantity,
            p_movement_type,
            p_reason,
            p_created_by,
            v_previous_stock,
            v_new_stock,
            v_created_at,
            p_store_id,
            v_legacy_affects_physical,
            p_source,
            p_transfer_id,
            p_reason_code,
            coalesce(p_metadata, '{}'::jsonb),
            p_created_by,
            p_supplier_id,
            v_effective_location_id,
            v_effective_from_location_id,
            v_effective_to_location_id,
            p_transfer_id
        )
        returning id into v_movement_id;

    elsif v_write_audit_log then
        insert into public.audit_logs (
            store_id,
            user_id,
            action,
            entity,
            entity_id,
            old_data,
            new_data,
            created_at
        )
        values (
            p_store_id,
            p_created_by,
            p_movement_type::text,
            'inventory_location_balances',
            v_location_after.id,
            jsonb_build_object(
                'product_id', p_product_id,
                'variant_id', p_variant_id,
                'location_id', v_effective_location_id,
                'from_location_id', v_effective_from_location_id,
                'to_location_id', v_effective_to_location_id,
                'transfer_id', p_transfer_id
            ),
            jsonb_strip_nulls(
                coalesce(p_metadata, '{}'::jsonb)
                || jsonb_build_object(
                    'movement_type', p_movement_type,
                    'quantity', p_quantity,
                    'reason', p_reason,
                    'order_id', p_order_id,
                    'source', p_source,
                    'reason_code', p_reason_code,
                    'affects_physical', false,
                    'product_id', p_product_id,
                    'variant_id', p_variant_id,
                    'location_id', v_effective_location_id,
                    'from_location_id', v_effective_from_location_id,
                    'to_location_id', v_effective_to_location_id,
                    'transfer_id', p_transfer_id,
                    'on_hand_after_location', v_location_after.on_hand,
                    'reserved_after_location', v_location_after.reserved,
                    'on_hand_after_store', v_store_after.on_hand,
                    'reserved_after_store', v_store_after.reserved
                )
            ),
            v_created_at
        )
        returning id into v_movement_id;
    end if;

    return query
    select
        v_movement_id as movement_id,
        p_store_id as store_id,
        p_product_id as product_id,
        p_variant_id as variant_id,
        p_movement_type as movement_type,
        p_quantity as quantity,
        v_effective_location_id as location_id,
        v_effective_from_location_id as from_location_id,
        v_effective_to_location_id as to_location_id,
        p_transfer_id as transfer_id,
        v_location_after.on_hand as on_hand_after_location,
        v_location_after.reserved as reserved_after_location,
        v_store_after.on_hand as on_hand_after_store,
        v_store_after.reserved as reserved_after_store,
        v_created_at as created_at;
end;
$$;


ALTER FUNCTION "public"."apply_stock_movement_delta_v2"("p_store_id" "uuid", "p_product_id" "uuid", "p_movement_type" "public"."stock_movement_type", "p_quantity" numeric, "p_affects_physical" boolean, "p_reason" "text", "p_order_id" "uuid", "p_source" "text", "p_metadata" "jsonb", "p_created_by" "uuid", "p_location_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_transfer_id" "uuid", "p_supplier_id" "uuid", "p_reason_code" "text", "p_variant_id" "uuid", "p_sync_legacy_balance" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_stock_movement_delta_v2"("p_store_id" "uuid", "p_product_id" "uuid", "p_movement_type" "public"."stock_movement_type", "p_quantity" numeric, "p_affects_physical" boolean, "p_reason" "text", "p_order_id" "uuid", "p_source" "text", "p_metadata" "jsonb", "p_created_by" "uuid", "p_location_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_transfer_id" "uuid", "p_supplier_id" "uuid", "p_reason_code" "text", "p_variant_id" "uuid", "p_sync_legacy_balance" boolean) IS 'RPC principal da V2 de estoque por local. Atualiza saldo por local, saldo consolidado e auditoria física/não física.';



CREATE OR REPLACE FUNCTION "public"."assign_store_custom_role_to_member"("p_member_id" "uuid", "p_custom_role_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_clear_individual_overrides" boolean DEFAULT false, "p_create_occurrence" boolean DEFAULT true) RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "role" "text", "custom_role_id" "uuid", "custom_role_name" "text", "custom_role_base_role" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_custom_role public.store_custom_roles%ROWTYPE;
  v_old_custom_role_id uuid;
  v_old_custom_role_name text;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_old_permissions jsonb;
  v_old_sensitive_actions jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Membro não informado.';
  END IF;

  SELECT sm.*
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  IF v_member.role = 'owner' THEN
    RAISE EXCEPTION 'Não é permitido atribuir função personalizada ao proprietário.';
  END IF;

  IF v_member.user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode alterar sua própria função personalizada.';
  END IF;

  IF NOT (
    public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para atribuir função personalizada.';
  END IF;

  v_old_custom_role_id := v_member.custom_role_id;
  v_old_permissions := COALESCE(v_member.permissions, '{}'::jsonb);
  v_old_sensitive_actions := COALESCE(v_member.sensitive_actions, '{}'::jsonb);

  IF v_old_custom_role_id IS NOT NULL THEN
    SELECT scr.name
    INTO v_old_custom_role_name
    FROM public.store_custom_roles scr
    WHERE scr.id = v_old_custom_role_id;
  END IF;

  IF p_custom_role_id IS NOT NULL THEN
    SELECT scr.*
    INTO v_custom_role
    FROM public.store_custom_roles scr
    WHERE scr.id = p_custom_role_id
      AND scr.store_id = v_member.store_id
      AND scr.active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Função personalizada não encontrada, inativa ou pertence a outra loja.';
    END IF;

    UPDATE public.store_members sm
    SET
      role = v_custom_role.base_role,
      custom_role_id = p_custom_role_id,
      permissions = CASE
        WHEN p_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.permissions, '{}'::jsonb)
      END,
      sensitive_actions = CASE
        WHEN p_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.sensitive_actions, '{}'::jsonb)
      END,
      updated_at = now()
    WHERE sm.id = p_member_id;
  ELSE
    UPDATE public.store_members sm
    SET
      custom_role_id = NULL,
      permissions = CASE
        WHEN p_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.permissions, '{}'::jsonb)
      END,
      sensitive_actions = CASE
        WHEN p_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.sensitive_actions, '{}'::jsonb)
      END,
      updated_at = now()
    WHERE sm.id = p_member_id;
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    CASE
      WHEN p_custom_role_id IS NULL THEN 'store_custom_role_removed'
      ELSE 'store_custom_role_assigned'
    END,
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'old_custom_role_id', v_old_custom_role_id,
      'old_custom_role_name', v_old_custom_role_name,
      'new_custom_role_id', p_custom_role_id,
      'new_custom_role_name', CASE WHEN p_custom_role_id IS NULL THEN NULL ELSE v_custom_role.name END,
      'new_base_role', CASE WHEN p_custom_role_id IS NULL THEN v_member.role ELSE v_custom_role.base_role END,
      'reason', p_reason,
      'clear_individual_overrides', p_clear_individual_overrides,
      'old_permissions', v_old_permissions,
      'old_sensitive_actions', v_old_sensitive_actions
    ),
    'success',
    now()
  );

  IF p_create_occurrence THEN
    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_member.store_id,
      p_member_id,
      v_member.user_id,
      'role_change',
      'info',
      CASE
        WHEN p_custom_role_id IS NULL THEN 'Função personalizada removida'
        ELSE 'Função personalizada atribuída'
      END,
      CASE
        WHEN p_custom_role_id IS NULL THEN
          'Função personalizada removida.' ||
          CASE
            WHEN p_reason IS NOT NULL AND length(trim(p_reason)) > 0
              THEN ' Motivo: ' || p_reason
            ELSE ''
          END
        ELSE
          'Função personalizada atribuída: ' || v_custom_role.name ||
          ' herdando de ' || v_custom_role.base_role || '.' ||
          CASE
            WHEN p_reason IS NOT NULL AND length(trim(p_reason)) > 0
              THEN ' Motivo: ' || p_reason
            ELSE ''
          END
      END,
      now(),
      true,
      auth.uid(),
      v_actor_email,
      jsonb_build_object(
        'origin', 'assign_store_custom_role_to_member',
        'old_custom_role_id', v_old_custom_role_id,
        'old_custom_role_name', v_old_custom_role_name,
        'new_custom_role_id', p_custom_role_id,
        'new_custom_role_name', CASE WHEN p_custom_role_id IS NULL THEN NULL ELSE v_custom_role.name END,
        'new_base_role', CASE WHEN p_custom_role_id IS NULL THEN v_member.role ELSE v_custom_role.base_role END,
        'reason', p_reason,
        'actor_user_id', auth.uid(),
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'target_user_id', v_member.user_id,
        'target_user_name', v_target_name,
        'target_user_email', v_target_email,
        'clear_individual_overrides', p_clear_individual_overrides
      ),
      now(),
      now()
    );
  END IF;

  RETURN QUERY
  SELECT
    sm.id AS member_id,
    sm.store_id,
    sm.user_id,
    sm.role,
    sm.custom_role_id,
    scr.name AS custom_role_name,
    scr.base_role AS custom_role_base_role,
    COALESCE(sm.permissions, '{}'::jsonb) AS permissions,
    COALESCE(sm.sensitive_actions, '{}'::jsonb) AS sensitive_actions,
    sm.updated_at
  FROM public.store_members sm
  LEFT JOIN public.store_custom_roles scr
    ON scr.id = sm.custom_role_id
  WHERE sm.id = p_member_id;
END;
$$;


ALTER FUNCTION "public"."assign_store_custom_role_to_member"("p_member_id" "uuid", "p_custom_role_id" "uuid", "p_reason" "text", "p_clear_individual_overrides" boolean, "p_create_occurrence" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_loyalty_points"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    target_customer_id uuid;
    points_to_award integer;
    current_points integer;
    current_tier text;
BEGIN
    -- Only proceed if status changed to 'completed'
    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
        
        -- Find customer by phone (normalized)
        -- Assumes customers.phone is stored as digits only
        SELECT id, loyalty_points, loyalty_tier INTO target_customer_id, current_points, current_tier
        FROM public.customers 
        WHERE phone = regexp_replace(NEW.customer_phone, '\D', '', 'g') 
        AND store_id = NEW.store_id;
        
        IF target_customer_id IS NOT NULL THEN
            -- Calculate points: 1 point per 1.00 currency unit (floor)
            points_to_award := floor(NEW.total);
            
            IF points_to_award > 0 THEN
                -- Insert transaction
                INSERT INTO public.loyalty_transactions (customer_id, type, points, description, order_id)
                VALUES (target_customer_id, 'earn', points_to_award, 'Pontos ganhos pelo pedido #' || substring(NEW.id::text, 1, 8), NEW.id);
                
                -- Update customer points
                UPDATE public.customers
                SET loyalty_points = loyalty_points + points_to_award
                WHERE id = target_customer_id;
                
                -- Check for Tier Upgrade
                -- Bronze < 100, Prata < 500, Ouro >= 500 (Simple logic)
                IF (current_points + points_to_award) >= 500 AND current_tier != 'Ouro' THEN
                    UPDATE public.customers SET loyalty_tier = 'Ouro' WHERE id = target_customer_id;
                    -- Log tier change? Maybe in future.
                ELSIF (current_points + points_to_award) >= 100 AND current_tier = 'Bronze' THEN
                    UPDATE public.customers SET loyalty_tier = 'Prata' WHERE id = target_customer_id;
                END IF;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."award_loyalty_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_points_on_delivery"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.status = 'delivered' AND OLD.status != 'delivered' THEN
        INSERT INTO public.loyalty_transactions (user_id, order_id, amount, description)
        VALUES (
            NEW.user_id, 
            NEW.id, 
            FLOOR(NEW.total)::INTEGER, -- 1 point per 1.00 currency unit
            'Pontos por compra - Pedido #' || SUBSTRING(NEW.id::text, 1, 6)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."award_points_on_delivery"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."build_campaign_recipients_preview_safe"("p_store_id" "uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_target_type" "text" DEFAULT 'all'::"text", "p_target_segment_id" "uuid" DEFAULT NULL::"uuid", "p_target_customer_id" "uuid" DEFAULT NULL::"uuid", "p_target_tag" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT 'whatsapp'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign record;
  v_target_type text;
  v_target_segment_id uuid;
  v_target_customer_id uuid;
  v_target_tag text;
  v_channel text;
  v_limit integer;
  v_recipients jsonb;
  v_total integer := 0;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  v_limit := GREATEST(1, LEAST(COALESCE(p_limit, 100), 500));

  IF p_campaign_id IS NOT NULL THEN
    SELECT *
    INTO v_campaign
    FROM public.promotion_campaigns pc
    WHERE pc.id = p_campaign_id
      AND pc.store_id = p_store_id;

    IF v_campaign.id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
    END IF;

    v_target_type := COALESCE(v_campaign.target_type, p_target_type, 'all');
    v_target_segment_id := COALESCE(v_campaign.target_segment_id, p_target_segment_id);
    v_target_customer_id := COALESCE(v_campaign.target_customer_id, p_target_customer_id);
    v_target_tag := COALESCE(v_campaign.target_tag, p_target_tag);
    v_channel := COALESCE(v_campaign.channel, p_channel, 'whatsapp');
  ELSE
    v_target_type := COALESCE(p_target_type, 'all');
    v_target_segment_id := p_target_segment_id;
    v_target_customer_id := p_target_customer_id;
    v_target_tag := p_target_tag;
    v_channel := COALESCE(p_channel, 'whatsapp');
  END IF;

  IF v_target_type NOT IN ('all', 'segment', 'customer', 'tag', 'loyalty_tier', 'custom') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_target_type');
  END IF;

  IF v_channel NOT IN ('whatsapp', 'email', 'sms', 'in_app', 'manual', 'mixed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_channel');
  END IF;

  IF v_target_type = 'segment' AND v_target_segment_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_target_segment');
  END IF;

  IF v_target_type = 'customer' AND v_target_customer_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_target_customer');
  END IF;

  IF v_target_type = 'tag' AND length(trim(COALESCE(v_target_tag, ''))) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_target_tag');
  END IF;

  WITH eligible_customers AS (
    SELECT DISTINCT
      c.id,
      c.full_name,
      c.phone,
      c.email,
      c.source,
      c.data_ownership,
      c.loyalty_points,
      c.loyalty_tier,
      c.current_tier_id,
      c.tags,
      c.marketing_consent,
      c.loyalty_opt_in
    FROM public.customers c
    LEFT JOIN public.customer_segment_members csm
      ON csm.customer_id = c.id
      AND csm.active = true
    WHERE c.store_id = p_store_id
      AND c.status = 'active'
      AND (
        v_target_type = 'all'

        OR (
          v_target_type = 'segment'
          AND csm.segment_id = v_target_segment_id
        )

        OR (
          v_target_type = 'customer'
          AND c.id = v_target_customer_id
        )

        OR (
          v_target_type = 'tag'
          AND trim(v_target_tag) = ANY(COALESCE(c.tags, ARRAY[]::text[]))
        )

        OR (
          v_target_type = 'loyalty_tier'
          AND c.current_tier_id::text = COALESCE(v_target_tag, '')
        )
      )
      AND (
        v_channel <> 'whatsapp'
        OR NULLIF(trim(COALESCE(c.phone, '')), '') IS NOT NULL
      )
      AND (
        v_channel <> 'email'
        OR NULLIF(trim(COALESCE(c.email, '')), '') IS NOT NULL
      )
  ),
  counted AS (
    SELECT COUNT(*)::integer AS total_count
    FROM eligible_customers
  ),
  limited AS (
    SELECT *
    FROM eligible_customers
    ORDER BY full_name NULLS LAST, phone NULLS LAST
    LIMIT v_limit
  )
  SELECT
    COALESCE((SELECT total_count FROM counted), 0),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'customer_id', limited.id,
          'customer_name', limited.full_name,
          'phone', limited.phone,
          'email', limited.email,
          'source', limited.source,
          'data_ownership', limited.data_ownership,
          'loyalty_points', limited.loyalty_points,
          'loyalty_tier', limited.loyalty_tier,
          'tags', limited.tags,
          'marketing_consent', limited.marketing_consent,
          'loyalty_opt_in', limited.loyalty_opt_in
        )
      ),
      '[]'::jsonb
    )
  INTO v_total, v_recipients
  FROM limited;

  RETURN jsonb_build_object(
    'ok', true,
    'target_type', v_target_type,
    'target_segment_id', v_target_segment_id,
    'target_customer_id', v_target_customer_id,
    'target_tag', v_target_tag,
    'channel', v_channel,
    'total_recipients', COALESCE(v_total, 0),
    'preview_limit', v_limit,
    'recipients', COALESCE(v_recipients, '[]'::jsonb)
  );
END;
$$;


