CREATE OR REPLACE FUNCTION "public"."calculate_order_loyalty_points_advanced"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_program record;
  v_rule record;

  v_total_points integer := 0;
  v_rule_points integer := 0;
  v_applied_rules jsonb := '[]'::jsonb;
  v_completed_orders_count integer := 0;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_order_id',
      'points', 0,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.customer_id,
    o.total,
    o.subtotal,
    o.status,
    o.sales_channel,
    o.fulfillment_type,
    o.delivery_method_code,
    o.payment_method_code,
    o.created_at,
    o.completed_at
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_found',
      'points', 0,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_customer_id',
      'points', 0,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  IF v_order.status::text <> 'completed' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_completed',
      'points', 0,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'points', 0,
        'applied_rules', '[]'::jsonb
      );
    END IF;
  END IF;

  SELECT *
  INTO v_program
  FROM public.fidelity_programs fp
  WHERE fp.store_id = v_order.store_id
  ORDER BY fp.created_at DESC
  LIMIT 1;

  IF v_program.id IS NULL OR COALESCE(v_program.is_active, false) = false THEN
    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'loyalty_program_inactive',
      'points', 0,
      'program_id', v_program.id,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  IF COALESCE(v_order.total, 0) < COALESCE(v_program.min_order_value, 0) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'below_min_order_value',
      'points', 0,
      'program_id', v_program.id,
      'applied_rules', '[]'::jsonb
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_completed_orders_count
  FROM public.orders o
  WHERE o.customer_id = v_order.customer_id
    AND o.store_id = v_order.store_id
    AND o.status = 'completed';

  FOR v_rule IN
    SELECT *
    FROM public.loyalty_point_rules lpr
    WHERE lpr.store_id = v_order.store_id
      AND lpr.active = true
      AND lpr.trigger_event IN ('order_completed', 'first_order')
      AND (lpr.starts_at IS NULL OR lpr.starts_at <= now())
      AND (lpr.ends_at IS NULL OR lpr.ends_at >= now())
    ORDER BY lpr.priority ASC, lpr.created_at ASC
  LOOP
    v_rule_points := 0;

    IF v_rule.trigger_event = 'first_order' AND v_completed_orders_count > 1 THEN
      CONTINUE;
    END IF;

    IF v_rule.points_mode = 'per_currency' THEN
      v_rule_points := floor(COALESCE(v_order.total, 0) * COALESCE(v_rule.points_value, 0))::integer;

    ELSIF v_rule.points_mode = 'fixed' THEN
      v_rule_points := floor(COALESCE(v_rule.points_value, 0))::integer;

    ELSIF v_rule.points_mode = 'multiplier' THEN
      v_rule_points := floor(COALESCE(v_order.total, 0) * COALESCE(v_program.points_per_currency, 1) * COALESCE(v_rule.points_value, 1))::integer;
    END IF;

    IF v_rule_points < 0 THEN
      v_rule_points := 0;
    END IF;

    IF v_rule_points > 0 THEN
      v_total_points := v_total_points + v_rule_points;

      v_applied_rules := v_applied_rules || jsonb_build_array(
        jsonb_build_object(
          'rule_id', v_rule.id,
          'code', v_rule.code,
          'name', v_rule.name,
          'trigger_event', v_rule.trigger_event,
          'rule_type', v_rule.rule_type,
          'points_mode', v_rule.points_mode,
          'points_value', v_rule.points_value,
          'points_awarded', v_rule_points,
          'stackable', v_rule.stackable
        )
      );
    END IF;

    IF COALESCE(v_rule.stackable, true) = false AND v_rule_points > 0 THEN
      EXIT;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'store_id', v_order.store_id,
    'customer_id', v_order.customer_id,
    'program_id', v_program.id,
    'points', v_total_points,
    'applied_rules', v_applied_rules
  );
END;
$$;


ALTER FUNCTION "public"."calculate_order_loyalty_points_advanced"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_security_section"("p_store_id" "uuid", "p_section" "text", "p_manage" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_has_root boolean := false;
  v_has_manage_root boolean := false;
  v_view_permission text;
  v_manage_permission text;
begin
  if auth.uid() is null then
    return false;
  end if;

  if p_store_id is null or p_section is null then
    return false;
  end if;

  if public.app_is_store_owner(p_store_id) then
    return true;
  end if;

  v_has_root := public.user_has_store_permission(p_store_id, 'security.view');

  if not v_has_root then
    return false;
  end if;

  v_has_manage_root := public.user_has_store_permission(p_store_id, 'security.manage');

  if v_has_manage_root then
    return true;
  end if;

  case p_section
    when 'context' then
      v_view_permission := 'security.context.view';
      v_manage_permission := 'security.context.manage';
    when 'logs' then
      v_view_permission := 'security.logs.view';
      v_manage_permission := 'security.logs.manage';
    when 'roles' then
      v_view_permission := 'security.roles.view';
      v_manage_permission := 'security.roles.manage';
    when 'custom_roles' then
      v_view_permission := 'security.custom_roles.view';
      v_manage_permission := 'security.custom_roles.manage';
    when 'user_permissions' then
      v_view_permission := 'security.user_permissions.view';
      v_manage_permission := 'security.user_permissions.manage';
    when 'sensitive_actions' then
      v_view_permission := 'security.sensitive_actions.view';
      v_manage_permission := 'security.sensitive_actions.manage';
    when 'pin_token' then
      v_view_permission := 'security.pin_token.view';
      v_manage_permission := 'security.pin_token.manage';
    when 'sessions' then
      v_view_permission := 'security.sessions.view';
      v_manage_permission := 'security.sessions.manage';
    else
      return false;
  end case;

  if p_manage then
    return (
      (
        public.user_has_store_permission(p_store_id, v_view_permission)
        or public.user_has_store_permission(p_store_id, v_manage_permission)
      )
      and public.user_has_store_permission(p_store_id, v_manage_permission)
    );
  end if;

  return (
    public.user_has_store_permission(p_store_id, v_view_permission)
    or public.user_has_store_permission(p_store_id, v_manage_permission)
  );
end;
$$;


