CREATE OR REPLACE FUNCTION "public"."can_access_security_section_v3"("p_store_id" "uuid", "p_section" "text", "p_manage" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_section text := lower(trim(coalesce(p_section, '')));
  v_root_view boolean := false;
  v_root_manage boolean := false;
  v_section_view boolean := false;
  v_section_manage boolean := false;
begin
  if auth.uid() is null then
    return false;
  end if;

  if p_store_id is null or v_section = '' then
    return false;
  end if;

  if public.app_is_store_owner(p_store_id) then
    return true;
  end if;

  v_root_view := public.user_has_store_permission(p_store_id, 'security.view');

  if not v_root_view then
    return false;
  end if;

  if v_section = 'root' then
    if p_manage then
      return public.user_has_store_permission(p_store_id, 'security.manage');
    end if;

    return true;
  end if;

  v_section_view :=
    public.user_has_store_permission(p_store_id, 'security.' || v_section || '.view');

  if not v_section_view then
    return false;
  end if;

  if not p_manage then
    return true;
  end if;

  v_root_manage :=
    public.user_has_store_permission(p_store_id, 'security.manage');

  v_section_manage :=
    public.user_has_store_permission(p_store_id, 'security.' || v_section || '.manage');

  return v_root_manage and v_section_manage;
end;
$$;


