CREATE OR REPLACE FUNCTION "public"."can_manage_user_avatar"("p_target_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_target_user_id = auth.uid() THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.store_members target_member
    JOIN public.store_members actor_member
      ON actor_member.store_id = target_member.store_id
     AND actor_member.user_id = auth.uid()
     AND actor_member.status = 'active'
    WHERE target_member.user_id = p_target_user_id
      AND (
        public.app_is_store_owner(target_member.store_id)
        OR public.user_has_store_permission(target_member.store_id, 'users.manage')
        OR public.user_has_store_permission(target_member.store_id, 'security.manage')
      )
  );
END;
$$;


