CREATE OR REPLACE FUNCTION "public"."cancel_expired_reservations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
    v_count INTEGER := 0;
BEGIN
    -- Find expired reservations distinct orders
    FOR v_order_id IN 
        SELECT DISTINCT order_id 
        FROM stock_reservations 
        WHERE expires_at < NOW()
    LOOP
        -- Update order status to cancelled
        UPDATE orders SET status = 'cancelled' WHERE id = v_order_id AND status = 'reserved';
        
        -- Delete reservations (releasing stock availability)
        DELETE FROM stock_reservations WHERE order_id = v_order_id;
        
        v_count := v_count + 1;
    END LOOP;
    
    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."cancel_expired_reservations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_expired_reservations"("p_store_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
    v_rec RECORD;
BEGIN
    -- Find expired reservations for this store
    FOR v_rec IN 
        SELECT DISTINCT order_id 
        FROM stock_reservations 
        WHERE store_id = p_store_id 
        AND expires_at < NOW()
    LOOP
        v_order_id := v_rec.order_id;
        
        -- Update Order Status to Cancelled
        UPDATE orders 
        SET status = 'cancelled' 
        WHERE id = v_order_id 
        AND status = 'reserved'; -- Only cancel if still reserved
        
        -- If order was updated, log history (facultative, or handled by trigger/app)
        -- The important part is deleting the reservation to free stock.
        
        -- Delete the reservation (triggering stock release if any, but our model releases by NOT committing)
        -- Actually, our availability calculation is physical - reserved.
        -- So deleting the reservation increases availability immediately.
        
        DELETE FROM stock_reservations WHERE order_id = v_order_id;
        
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."cancel_expired_reservations"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_my_profile_change_request"("p_request_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "reason" "text", "admin_notes" "text", "member_feedback" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_email text;
  v_request public.store_member_profile_change_requests%ROWTYPE;
  v_now timestamp with time zone := now();
  v_cancel_reason text;
BEGIN
  v_actor_id := auth.uid();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Solicitação não informada.';
  END IF;

  SELECT *
  INTO v_request
  FROM public.store_member_profile_change_requests r
  WHERE r.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitação não encontrada.';
  END IF;

  IF v_request.user_id <> v_actor_id THEN
    RAISE EXCEPTION 'Você só pode cancelar suas próprias solicitações.';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Somente solicitações pendentes podem ser canceladas pelo solicitante.';
  END IF;

  v_cancel_reason := COALESCE(
    NULLIF(trim(p_reason), ''),
    'Solicitação cancelada pelo próprio usuário antes da análise.'
  );

  SELECT au.email::text
  INTO v_actor_email
  FROM auth.users au
  WHERE au.id = v_actor_id;

  UPDATE public.store_member_profile_change_requests r
  SET
    status = 'cancelled',
    member_feedback = v_cancel_reason,
    member_responded_at = v_now,
    updated_at = v_now,
    metadata = COALESCE(r.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelled_by', 'member',
      'cancelled_by_function', 'cancel_my_profile_change_request'
    )
  WHERE r.id = v_request.id;

  INSERT INTO public.store_member_occurrences (
    store_id,
    member_id,
    user_id,
    occurrence_type,
    severity,
    title,
    description,
    occurred_at,
    visible_to_member,
    created_by,
    created_by_email,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_request.store_id,
    v_request.member_id,
    v_request.user_id,
    'note',
    'info',
    'Solicitação cadastral cancelada',
    v_cancel_reason,
    v_now,
    true,
    v_actor_id,
    v_actor_email,
    jsonb_build_object(
      'origin', 'cancel_my_profile_change_request',
      'request_id', v_request.id,
      'request_type', v_request.request_type
    ),
    v_now,
    v_now
  );

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.reason,
    r.admin_notes,
    r.member_feedback,
    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  WHERE r.id = v_request.id;
END;
$$;


ALTER FUNCTION "public"."cancel_my_profile_change_request"("p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- 1. Update status
    UPDATE orders 
    SET status = 'cancelled' 
    WHERE id = p_order_id;
    
    -- 2. Delete reservations (this releases stock)
    DELETE FROM stock_reservations WHERE order_id = p_order_id;
    
    -- 3. Log history (Optional, could add an explicit log here if desired)
    -- But deleting reservation implicitly increases stock which is what we want.
END;
$$;


