CREATE OR REPLACE FUNCTION "public"."cancel_order_reservations"("p_store_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT *
    FROM public.stock_reservations
    WHERE store_id = p_store_id
      AND order_id = p_order_id
      AND status = 'active'
  LOOP
    UPDATE public.stock_reservations
    SET status = 'cancelled',
        cancelled_at = now()
    WHERE id = r.id;

    -- Auditoria sem mexer no físico
    PERFORM public.apply_stock_movement_delta(
      p_store_id,
      r.product_id,
      'cancellation',
      0,
      false,
      'order',
      p_order_id,
      'cancel_before_confirm',
      '{}'::jsonb,
      p_created_by
    );
  END LOOP;
END;
$$;


