CREATE OR REPLACE FUNCTION "public"."cancel_reserved_public_order"("p_order_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_reservation record;
  v_released_count integer := 0;
BEGIN
  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  LIMIT 1;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_found'
    );
  END IF;

  -- Segurança para chamadas reais via API/JWT.
  -- No SQL Editor, auth.role() costuma não ser anon/authenticated.
  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied'
      );
    END IF;
  END IF;

  IF v_order.status <> 'reserved' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_reserved',
      'status', v_order.status
    );
  END IF;

  FOR v_reservation IN
    SELECT
      sr.id,
      sr.store_id,
      sr.product_id,
      sr.location_id,
      sr.quantity
    FROM public.stock_reservations sr
    WHERE sr.order_id = v_order.id
      AND sr.status = 'active'
  LOOP
    UPDATE public.inventory_location_balances ilb
    SET
      reserved = GREATEST(0, ilb.reserved - v_reservation.quantity),
      updated_at = now()
    WHERE ilb.store_id = v_reservation.store_id
      AND ilb.product_id = v_reservation.product_id
      AND ilb.location_id = v_reservation.location_id;

    UPDATE public.inventory_balances ib
    SET
      reserved = GREATEST(0, ib.reserved - v_reservation.quantity),
      updated_at = now()
    WHERE ib.store_id = v_reservation.store_id
      AND ib.product_id = v_reservation.product_id;

    UPDATE public.stock_reservations
    SET
      status = 'cancelled',
      cancelled_at = now(),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'cancelled_at', now(),
        'cancelled_by', auth.uid(),
        'cancel_reason', COALESCE(p_reason, 'Pedido cancelado')
      )
    WHERE id = v_reservation.id;

    v_released_count := v_released_count + 1;
  END LOOP;

  UPDATE public.orders
  SET
    status = 'cancelled',
    commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelled_reason', COALESCE(p_reason, 'Pedido cancelado'),
      'cancelled_at', now(),
      'cancelled_by', auth.uid()
    ),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'cancel_reason', COALESCE(p_reason, 'Pedido cancelado')
    )
  WHERE id = v_order.id;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'order_code', v_order.order_code,
    'status', 'cancelled',
    'reservations_released', v_released_count
  );
END;
$$;


ALTER FUNCTION "public"."cancel_reserved_public_order"("p_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancel_reason" "text") RETURNS TABLE("transfer_id" "uuid", "transfer_code" "text", "status" "text", "cancelled_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.stock_transfers%ROWTYPE;
BEGIN
  IF p_transfer_id IS NULL THEN
    RAISE EXCEPTION 'Transferência não informada.';
  END IF;

  IF NULLIF(trim(COALESCE(p_cancel_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.';
  END IF;

  SELECT *
  INTO v_transfer
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transferência não encontrada.';
  END IF;

  IF NOT public.is_store_member(v_transfer.store_id) THEN
    RAISE EXCEPTION 'Acesso negado à transferência informada.';
  END IF;

  IF v_transfer.status <> 'draft'::public.stock_transfer_status THEN
    RAISE EXCEPTION 'Nesta etapa, apenas rascunhos podem ser cancelados. Status atual: %', v_transfer.status;
  END IF;

  UPDATE public.stock_transfers st
  SET
    status = 'cancelled'::public.stock_transfer_status,
    cancelled_at = now(),
    cancel_reason = trim(p_cancel_reason),
    metadata = COALESCE(st.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancel_source', 'cancel_stock_transfer'
    ),
    updated_at = now()
  WHERE st.id = p_transfer_id;

  RETURN QUERY
  SELECT
    st.id,
    st.transfer_code,
    st.status::text,
    st.cancelled_at
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id;
END;
$$;


ALTER FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancel_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancel_reason" "text") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC operacional para cancelar rascunhos de transferência. Mantida para authenticated com validação interna.';



