);


ALTER TABLE "public"."stock_transfers" OWNER TO "postgres";


COMMENT ON TABLE "public"."stock_transfers" IS 'Cabeçalho de transferências internas de estoque entre locais da mesma store.';



CREATE OR REPLACE FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancelled_by" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."stock_transfers"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer public.stock_transfers;
begin
    select *
      into v_transfer
      from public.stock_transfers
     where id = p_transfer_id
     for update;

    if v_transfer.id is null then
        raise exception 'Transferência não encontrada' using errcode = '23503';
    end if;

    if v_transfer.status in ('received', 'cancelled') then
        raise exception 'Não é possível cancelar transferência com status %', v_transfer.status using errcode = '23514';
    end if;

    if v_transfer.status = 'shipped' then
        raise exception 'Nesta versão, não é permitido cancelar após envio. Use recebimento ou reversão manual.' using errcode = '23514';
    end if;

    update public.stock_transfers
       set status = 'cancelled',
           cancelled_at = now(),
           cancel_reason = p_reason,
           updated_at = now(),
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('cancelled_by', p_cancelled_by)
     where id = v_transfer.id
    returning * into v_transfer;

    return v_transfer;
end;
$$;


ALTER FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_cancelled_by" "uuid", "p_reason" "text") IS 'Cancela transferência ainda não enviada/recebida.';



CREATE OR REPLACE FUNCTION "public"."cancel_store_member_invite"("p_invite_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_invite public.store_member_invites%ROWTYPE;
  v_actor_email text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT *
  INTO v_invite
  FROM public.store_member_invites
  WHERE id = p_invite_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Convite não encontrado.';
  END IF;

  IF NOT (
    public.app_is_store_owner(v_invite.store_id)
    OR public.user_has_store_permission(v_invite.store_id, 'users.manage')
  ) THEN
    RAISE EXCEPTION 'Você não tem permissão para cancelar convites.';
  END IF;

  IF v_invite.status <> 'pending' THEN
    RAISE EXCEPTION 'Apenas convites pendentes podem ser cancelados.';
  END IF;

  SELECT email::text
  INTO v_actor_email
  FROM auth.users
  WHERE id = auth.uid();

  UPDATE public.store_member_invites
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    cancel_reason = p_reason,
    updated_at = now()
  WHERE id = p_invite_id;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_invite.store_id,
    auth.uid(),
    v_actor_email,
    'store_member_invite_cancelled',
    jsonb_build_object(
      'invite_id', p_invite_id,
      'target_email', v_invite.email,
      'reason', p_reason
    ),
    'success',
    now()
  );

  RETURN jsonb_build_object(
    'invite_id', p_invite_id,
    'status', 'cancelled'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_store_member_invite"("p_invite_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_store_member_role"("p_member_id" "uuid", "p_new_role" "text", "p_reason" "text" DEFAULT NULL::"text", "p_clear_individual_overrides" boolean DEFAULT false, "p_create_occurrence" boolean DEFAULT true) RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "old_role" "text", "new_role" "text", "status" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_old_permissions jsonb;
  v_old_sensitive_actions jsonb;
  v_old_custom_role_id uuid;
  v_old_custom_role_name text;
  v_old_custom_role_base_role text;
  v_should_clear_custom_role boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Membro não informado.';
  END IF;

  IF p_new_role IS NULL OR length(trim(p_new_role)) = 0 THEN
    RAISE EXCEPTION 'Nova função não informada.';
  END IF;

  IF p_new_role NOT IN (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) THEN
    RAISE EXCEPTION 'Função inválida ou não permitida: %', p_new_role;
  END IF;

  SELECT sm.*
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  IF v_member.role = 'owner' THEN
    RAISE EXCEPTION 'Não é permitido alterar a função do proprietário.';
  END IF;

  IF v_member.user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode alterar a sua própria função.';
  END IF;

  IF NOT (
    public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar função de usuários.';
  END IF;

  v_old_permissions := COALESCE(v_member.permissions, '{}'::jsonb);
  v_old_sensitive_actions := COALESCE(v_member.sensitive_actions, '{}'::jsonb);
  v_old_custom_role_id := v_member.custom_role_id;

  IF v_old_custom_role_id IS NOT NULL THEN
    SELECT
      scr.name,
      scr.base_role
    INTO
      v_old_custom_role_name,
      v_old_custom_role_base_role
    FROM public.store_custom_roles scr
    WHERE scr.id = v_old_custom_role_id
      AND scr.store_id = v_member.store_id;

    v_should_clear_custom_role := COALESCE(v_old_custom_role_base_role, '') <> p_new_role;
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  UPDATE public.store_members sm
  SET
    role = p_new_role,
    custom_role_id = CASE
      WHEN v_should_clear_custom_role THEN NULL
      ELSE sm.custom_role_id
    END,
    permissions = CASE
      WHEN p_clear_individual_overrides THEN '{}'::jsonb
      ELSE COALESCE(sm.permissions, '{}'::jsonb)
    END,
    sensitive_actions = CASE
      WHEN p_clear_individual_overrides THEN '{}'::jsonb
      ELSE COALESCE(sm.sensitive_actions, '{}'::jsonb)
    END,
    updated_at = now()
  WHERE sm.id = p_member_id
  RETURNING
    sm.id,
    sm.store_id,
    sm.user_id,
    v_member.role,
    sm.role,
    sm.status,
    sm.permissions,
    sm.sensitive_actions,
    sm.updated_at
  INTO
    member_id,
    store_id,
    user_id,
    old_role,
    new_role,
    status,
    permissions,
    sensitive_actions,
    updated_at;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_member_role_changed',
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'old_role', v_member.role,
      'new_role', p_new_role,
      'reason', p_reason,
      'clear_individual_overrides', p_clear_individual_overrides,
      'old_permissions', v_old_permissions,
      'new_permissions', permissions,
      'old_sensitive_actions', v_old_sensitive_actions,
      'new_sensitive_actions', sensitive_actions,
      'old_custom_role_id', v_old_custom_role_id,
      'old_custom_role_name', v_old_custom_role_name,
      'old_custom_role_base_role', v_old_custom_role_base_role,
      'custom_role_cleared', v_should_clear_custom_role,
      'custom_role_clear_reason',
        CASE
          WHEN v_should_clear_custom_role
            THEN 'A função personalizada foi removida porque sua base não corresponde ao novo papel do usuário.'
          ELSE NULL
        END
    ),
    'success',
    now()
  );

  IF p_create_occurrence THEN
    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_member.store_id,
      p_member_id,
      v_member.user_id,
      'role_change',
      'info',
      'Mudança de função',
      'Função alterada de ' || v_member.role || ' para ' || p_new_role ||
        CASE
          WHEN v_should_clear_custom_role
            THEN '. Função personalizada removida: ' || COALESCE(v_old_custom_role_name, 'não identificada') || '.'
          ELSE '.'
        END ||
        CASE
          WHEN p_reason IS NOT NULL AND length(trim(p_reason)) > 0
            THEN ' Motivo: ' || p_reason
          ELSE ''
        END,
      now(),
      true,
      auth.uid(),
      v_actor_email,
      jsonb_build_object(
        'origin', 'change_store_member_role',
        'old_role', v_member.role,
        'new_role', p_new_role,
        'reason', p_reason,
        'actor_user_id', auth.uid(),
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'target_user_id', v_member.user_id,
        'target_user_name', v_target_name,
        'target_user_email', v_target_email,
        'clear_individual_overrides', p_clear_individual_overrides,
        'old_custom_role_id', v_old_custom_role_id,
        'old_custom_role_name', v_old_custom_role_name,
        'old_custom_role_base_role', v_old_custom_role_base_role,
        'custom_role_cleared', v_should_clear_custom_role
      ),
      now(),
      now()
    );
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."change_store_member_role"("p_member_id" "uuid", "p_new_role" "text", "p_reason" "text", "p_clear_individual_overrides" boolean, "p_create_occurrence" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_voucher_expiry_notifications"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    voucher record;
    prog record;
    days_left integer;
    msg text;
begin
    -- Iterate active vouchers
    for voucher in 
        select v.*, p.warn_voucher_expiry_1, p.warn_voucher_expiry_2, p.warn_voucher_expiry_3, r.title as reward_title
        from public.fidelity_vouchers v
        join public.fidelity_programs p on v.store_id = p.store_id
        join public.fidelity_rewards r on v.reward_id = r.id
        where v.status = 'active' and v.expires_at > now()
    loop
        days_left := extract(day from (voucher.expires_at - now()));
        
        -- Logic to send notification based on days_left matching strict days
        -- Prevents spamming every day. We assume this runs once daily.
        
        if days_left = voucher.warn_voucher_expiry_1 or 
           days_left = voucher.warn_voucher_expiry_2 or 
           days_left = voucher.warn_voucher_expiry_3 then
           
           msg := 'Seu voucher para "' || voucher.reward_title || '" vence em ' || days_left || ' dias! ⏳';
           
           insert into public.customer_notifications (
               customer_id, store_id, title, message, type
           ) values (
               voucher.customer_id, voucher.store_id, 'Voucher expirando', msg, 'warning'
           );
        end if;
    end loop;
end;
$$;


ALTER FUNCTION "public"."check_voucher_expiry_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_expired_reservations"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  delete from stock_reservations where expires_at < now();
  -- Optionally update order status to cancelled if reservation expired
  update orders 
  set status = 'cancelled' 
  where status = 'reserved' 
    and created_at < (now() - interval '15 minutes'); -- Give a bit of buffer
end;
$$;


ALTER FUNCTION "public"."cleanup_expired_reservations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_messages"("p_store_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    deleted_count INT;
BEGIN
    DELETE FROM store_messages
    WHERE store_id = p_store_id AND (expires_at < now() OR expires_at IS NULL);
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_messages"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_confirmed_public_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_reservation record;
  v_movement_id uuid;
  v_consumed_count integer := 0;
  v_active_reservations integer := 0;
  v_cashbook_result jsonb;
BEGIN
  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status,
    o.total,
    o.sales_channel,
    o.fulfillment_type
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  LIMIT 1;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF v_order.status <> 'confirmed' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_confirmed',
      'status', v_order.status
    );
  END IF;

  SELECT COUNT(*)
  INTO v_active_reservations
  FROM public.stock_reservations sr
  WHERE sr.order_id = v_order.id
    AND sr.status = 'active';

  IF v_active_reservations = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'no_active_reservations',
      'order_id', v_order.id,
      'order_code', v_order.order_code,
      'hint', 'Pedido confirmado sem reserva ativa.'
    );
  END IF;

  FOR v_reservation IN
    SELECT
      sr.id,
      sr.store_id,
      sr.product_id,
      sr.location_id,
      sr.quantity,
      p.name AS product_name
    FROM public.stock_reservations sr
    JOIN public.products p ON p.id = sr.product_id
    WHERE sr.order_id = v_order.id
      AND sr.status = 'active'
    ORDER BY p.name
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.inventory_location_balances ilb
      WHERE ilb.store_id = v_reservation.store_id
        AND ilb.product_id = v_reservation.product_id
        AND ilb.location_id = v_reservation.location_id
        AND ilb.on_hand >= v_reservation.quantity
        AND ilb.reserved >= v_reservation.quantity
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'insufficient_reserved_stock',
        'product_id', v_reservation.product_id,
        'product_name', v_reservation.product_name
      );
    END IF;

    UPDATE public.inventory_location_balances ilb
    SET
      on_hand = GREATEST(0, ilb.on_hand - v_reservation.quantity),
      reserved = GREATEST(0, ilb.reserved - v_reservation.quantity),
      updated_at = now()
    WHERE ilb.store_id = v_reservation.store_id
      AND ilb.product_id = v_reservation.product_id
      AND ilb.location_id = v_reservation.location_id;

    UPDATE public.inventory_balances ib
    SET
      on_hand = GREATEST(0, ib.on_hand - v_reservation.quantity),
      reserved = GREATEST(0, ib.reserved - v_reservation.quantity),
      updated_at = now()
    WHERE ib.store_id = v_reservation.store_id
      AND ib.product_id = v_reservation.product_id;

    INSERT INTO public.stock_movements (
      product_id,
      order_id,
      quantity,
      type,
      reason,
      previous_stock,
      new_stock,
      store_id,
      affects_physical,
      source,
      source_id,
      reason_code,
      metadata,
      created_by,
      location_id
    )
    SELECT
      v_reservation.product_id,
      v_order.id,
      (v_reservation.quantity * -1)::integer,
      'exit',
      'Venda concluída pelo pedido ' || v_order.order_code,
      (ilb.on_hand + v_reservation.quantity)::integer,
      ilb.on_hand::integer,
      v_reservation.store_id,
      true,
      'public_order',
      v_order.id,
      'public_order_completed',
      jsonb_build_object(
        'order_code', v_order.order_code,
        'sales_channel', v_order.sales_channel,
        'fulfillment_type', v_order.fulfillment_type,
        'reservation_id', v_reservation.id,
        'location_id', v_reservation.location_id,
        'absolute_quantity', v_reservation.quantity
      ),
      auth.uid(),
      v_reservation.location_id
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_reservation.store_id
      AND ilb.product_id = v_reservation.product_id
      AND ilb.location_id = v_reservation.location_id
    RETURNING id INTO v_movement_id;

    IF v_movement_id IS NULL THEN
      RAISE EXCEPTION 'Falha ao criar stock_movement para o pedido %', v_order.order_code;
    END IF;

    UPDATE public.stock_reservations
    SET
      status = 'consumed',
      consumed_at = now(),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'consumed_at', now(),
        'consumed_by', auth.uid(),
        'consumed_by_function', 'complete_confirmed_public_order',
        'stock_movement_id', v_movement_id
      )
    WHERE id = v_reservation.id;

    v_consumed_count := v_consumed_count + 1;
  END LOOP;

  UPDATE public.orders
  SET
    status = 'completed',
    completed_at = now(),
    commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb) || jsonb_build_object(
      'completed_at', now(),
      'completed_by', auth.uid(),
      'completed_by_source', 'complete_confirmed_public_order'
    ),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'completed_by_function', 'complete_confirmed_public_order'
    )
  WHERE id = v_order.id;

  -- Lançamento financeiro automático.
  SELECT public.create_cashbook_entry_from_order(v_order.id)
  INTO v_cashbook_result;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'order_code', v_order.order_code,
    'status', 'completed',
    'reservations_consumed', v_consumed_count,
    'total', v_order.total,
    'cashbook', v_cashbook_result
  );
END;
$$;


ALTER FUNCTION "public"."complete_confirmed_public_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_my_store_member_onboarding"("p_store_id" "uuid", "p_internal_alias" "text", "p_member_email" "text" DEFAULT NULL::"text", "p_member_phone" "text" DEFAULT NULL::"text", "p_member_mobile_phone" "text" DEFAULT NULL::"text", "p_member_whatsapp_phone" "text" DEFAULT NULL::"text", "p_member_zip_code" "text" DEFAULT NULL::"text", "p_member_address" "text" DEFAULT NULL::"text", "p_member_address_number" "text" DEFAULT NULL::"text", "p_member_complement" "text" DEFAULT NULL::"text", "p_member_district" "text" DEFAULT NULL::"text", "p_member_city" "text" DEFAULT NULL::"text", "p_member_state" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "role" "text", "status" "text", "internal_alias" "text", "member_email" "text", "member_phone" "text", "member_mobile_phone" "text", "member_whatsapp_phone" "text", "member_zip_code" "text", "member_address" "text", "member_address_number" "text", "member_complement" "text", "member_district" "text", "member_city" "text", "member_state" "text", "started_at" timestamp with time zone, "onboarding_required" boolean, "onboarding_completed_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_was_completed boolean := false;
  v_occurrence_id uuid;
  v_final_alias text;
  v_final_contact text;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  v_final_alias := NULLIF(trim(COALESCE(p_internal_alias, '')), '');

  IF v_final_alias IS NULL THEN
    RAISE EXCEPTION 'Informe o apelido/nome de uso nesta loja.';
  END IF;

  v_final_contact := COALESCE(
    NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''),
    NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''),
    NULLIF(trim(COALESCE(p_member_phone, '')), '')
  );

  IF v_final_contact IS NULL THEN
    RAISE EXCEPTION 'Informe ao menos um telefone, celular ou WhatsApp.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  v_was_completed := v_member.onboarding_completed_at IS NOT NULL;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_user_id) AS identity_row;

  UPDATE public.store_members sm
  SET
    internal_alias = v_final_alias,
    member_email = NULLIF(trim(COALESCE(p_member_email, '')), ''),
    member_phone = NULLIF(trim(COALESCE(p_member_phone, '')), ''),
    member_mobile_phone = NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''),
    member_whatsapp_phone = NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''),
    member_zip_code = NULLIF(trim(COALESCE(p_member_zip_code, '')), ''),
    member_address = NULLIF(trim(COALESCE(p_member_address, '')), ''),
    member_address_number = NULLIF(trim(COALESCE(p_member_address_number, '')), ''),
    member_complement = NULLIF(trim(COALESCE(p_member_complement, '')), ''),
    member_district = NULLIF(trim(COALESCE(p_member_district, '')), ''),
    member_city = NULLIF(trim(COALESCE(p_member_city, '')), ''),
    member_state = NULLIF(trim(COALESCE(p_member_state, '')), ''),
    started_at = COALESCE(sm.started_at, now()),
    onboarding_required = false,
    onboarding_completed_at = COALESCE(sm.onboarding_completed_at, now()),
    updated_at = now()
  WHERE sm.id = v_member.id
  RETURNING *
  INTO v_member;

  IF NOT v_was_completed THEN
    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_member.store_id,
      v_member.id,
      v_member.user_id,
      'admission',
      'critical',
      'Admissão / início de acesso',
      'Primeiro acesso concluído e dados básicos cadastrados.',
      COALESCE(v_member.started_at, now()),
      true,
      v_user_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'complete_my_store_member_onboarding',
        'event_type', 'first_access_completed',
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'internal_alias', v_member.internal_alias
      ),
      now(),
      now()
    )
    RETURNING id
    INTO v_occurrence_id;

    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_name,
      user_email,
      action,
      details,
      outcome,
      created_at
    )
    VALUES (
      v_member.store_id,
      v_user_id,
      v_actor_name,
      v_actor_email,
      'store_member_onboarding_completed',
      jsonb_build_object(
        'member_id', v_member.id,
        'target_user_id', v_member.user_id,
        'occurrence_id', v_occurrence_id,
        'internal_alias', v_member.internal_alias
      ),
      'success',
      now()
    );
  ELSE
    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_name,
      user_email,
      action,
      details,
      outcome,
      created_at
    )
    VALUES (
      v_member.store_id,
      v_user_id,
      v_actor_name,
      v_actor_email,
      'store_member_profile_updated_by_self',
      jsonb_build_object(
        'member_id', v_member.id,
        'target_user_id', v_member.user_id,
        'internal_alias', v_member.internal_alias
      ),
      'success',
      now()
    );
  END IF;

  RETURN QUERY
  SELECT
    v_member.id,
    v_member.store_id,
    v_member.user_id,
    v_member.role,
    v_member.status,
    v_member.internal_alias,
    v_member.member_email,
    v_member.member_phone,
    v_member.member_mobile_phone,
    v_member.member_whatsapp_phone,
    v_member.member_zip_code,
    v_member.member_address,
    v_member.member_address_number,
    v_member.member_complement,
    v_member.member_district,
    v_member.member_city,
    v_member.member_state,
    v_member.started_at,
    v_member.onboarding_required,
    v_member.onboarding_completed_at,
    v_member.updated_at;
END;
$$;


ALTER FUNCTION "public"."complete_my_store_member_onboarding"("p_store_id" "uuid", "p_internal_alias" "text", "p_member_email" "text", "p_member_phone" "text", "p_member_mobile_phone" "text", "p_member_whatsapp_phone" "text", "p_member_zip_code" "text", "p_member_address" "text", "p_member_address_number" "text", "p_member_complement" "text", "p_member_district" "text", "p_member_city" "text", "p_member_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Update status to completed
    UPDATE orders 
    SET status = 'completed' 
    WHERE id = p_order_id;
END;
$$;


ALTER FUNCTION "public"."complete_order"("p_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_order"("p_order_id" "uuid") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC comercial/pedido. Revisar junto com correção da área Comercial.';



CREATE OR REPLACE FUNCTION "public"."confirm_order_payment"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_order_id',
      'message', 'Pedido não informado.'
    );
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status,
    o.customer_id,
    o.customer_name,
    o.customer_phone,
    o.total,
    o.payment_method,
    o.payment_method_code,
    o.confirmed_at,
    o.commercial_metadata,
    o.metadata
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_found',
      'message', 'Pedido não encontrado.'
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'message', 'Acesso negado.'
      );
    END IF;
  END IF;

  IF v_order.status::text = 'completed' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_completed',
      'status', 'completed',
      'order_id', v_order.id,
      'order_code', v_order.order_code
    );
  END IF;

  IF v_order.status::text = 'cancelled' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_cancelled',
      'message', 'Pedido cancelado não pode ser aceito.'
    );
  END IF;

  IF v_order.status::text NOT IN ('reserved', 'confirmed') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_status',
      'message', 'Este pedido não está em um status que permita confirmação.',
      'current_status', v_order.status::text
    );
  END IF;

  /*
    Aqui NÃO mexemos em products.stock_quantity.
    Pedido público reservado mantém reserva ativa.
    Baixa física só na conclusão/entrega via complete_confirmed_public_order.
  */
  UPDATE public.orders
  SET
    status = 'confirmed',
    confirmed_at = COALESCE(confirmed_at, now()),
    commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'confirmed_at', COALESCE(confirmed_at, now()),
        'confirmed_by', auth.uid(),
        'confirmed_by_source', 'confirm_order_payment',
        'accepted_for_preparation_at', now()
      ),
    metadata = COALESCE(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'last_status_update_function', 'confirm_order_payment'
      )
  WHERE id = v_order.id;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'order_code', v_order.order_code,
    'status', 'confirmed',
    'message', 'Pedido aceito e enviado para preparação.'
  );
END;
$$;


ALTER FUNCTION "public"."confirm_order_payment"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_order_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT *
    FROM public.stock_reservations
    WHERE store_id = p_store_id
      AND order_id = p_order_id
      AND status = 'active'
    ORDER BY created_at
  LOOP
    PERFORM public.apply_stock_movement_delta(
      p_store_id,
      r.product_id,
      'confirmation',
      -r.quantity,
      true,
      'order',
      p_order_id,
      'confirm',
      '{}'::jsonb,
      p_created_by
    );

    UPDATE public.stock_reservations
    SET status = 'consumed',
        consumed_at = now()
    WHERE id = r.id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."confirm_order_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_purchase_document"("p_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  v_doc record;
  v_item record;
  v_total numeric := 0;
  v_existing_count integer;
  v_items_count integer := 0;
  v_total_quantity numeric := 0;
BEGIN
  SELECT
    pd.id,
    pd.store_id,
    pd.supplier_id,
    pd.invoice_number,
    pd.notes,
    pd.status
  INTO v_doc
  FROM public.purchase_documents pd
  WHERE pd.id = p_document_id
  FOR UPDATE;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Documento não encontrado';
  END IF;

  IF NOT public.user_can_purchase_action(v_doc.store_id, 'confirm') THEN
    RAISE EXCEPTION 'Sem permissão para confirmar compras nesta loja.';
  END IF;

  IF v_doc.status = 'confirmed' THEN
    RAISE EXCEPTION 'Apenas documentos em rascunho podem ser confirmados';
  END IF;

  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'Documento inválido para confirmação';
  END IF;

  SELECT count(*)
  INTO v_existing_count
  FROM public.stock_movements sm
  WHERE sm.metadata->>'purchase_document_id' = p_document_id::text
     OR sm.source_id = p_document_id;

  IF v_existing_count > 0 THEN
    RAISE EXCEPTION 'Este documento já possui movimentos lançados no estoque';
  END IF;

  FOR v_item IN
    SELECT
      pdi.id,
      pdi.purchase_document_id,
      pdi.product_id,
      pdi.quantity,
      pdi.unit_cost,
      COALESCE(pdi.total_cost, pdi.quantity * pdi.unit_cost) AS total_cost
    FROM public.purchase_document_items pdi
    WHERE pdi.purchase_document_id = p_document_id
      AND pdi.store_id = v_doc.store_id
  LOOP
    v_total := v_total + COALESCE(v_item.total_cost, 0);
    v_items_count := v_items_count + 1;
    v_total_quantity := v_total_quantity + COALESCE(v_item.quantity, 0);

    PERFORM public.apply_stock_movement_delta(
      v_doc.store_id,
      v_item.product_id,
      'entry'::stock_movement_type,
      v_item.quantity::numeric,
      true,
      COALESCE(v_doc.notes, 'Entrada por documento'),
      NULL::uuid,
      'purchase_document',
      jsonb_build_object(
        'purchase_document_id', p_document_id,
        'invoice_number', v_doc.invoice_number,
        'unit_cost', v_item.unit_cost,
        'total_cost', v_item.total_cost,
        'origin', 'purchase_document'
      ),
      NULL::uuid
    );

    UPDATE public.stock_movements sm
    SET
      supplier_id = v_doc.supplier_id,
      source_id = p_document_id,
      metadata = COALESCE(sm.metadata, '{}'::jsonb) || jsonb_build_object(
        'purchase_document_id', p_document_id,
        'invoice_number', v_doc.invoice_number,
        'unit_cost', v_item.unit_cost,
        'total_cost', v_item.total_cost,
        'origin', 'purchase_document'
      )
    WHERE sm.id = (
      SELECT sm2.id
      FROM public.stock_movements sm2
      WHERE sm2.store_id = v_doc.store_id
        AND sm2.product_id = v_item.product_id
        AND sm2.type = 'entry'::stock_movement_type
        AND sm2.source = 'purchase_document'
        AND sm2.source_id IS NULL
      ORDER BY sm2.created_at DESC
      LIMIT 1
    );
  END LOOP;

  UPDATE public.purchase_documents
  SET
    total_amount = v_total,
    status = 'confirmed'
  WHERE id = p_document_id
    AND store_id = v_doc.store_id;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_doc.store_id,
    p_entity_type := 'purchase_document',
    p_entity_id := p_document_id,
    p_event_type := 'purchase_document_confirmed',
    p_title := 'Compra confirmada',
    p_description := 'Documento de compra confirmado' ||
      CASE
        WHEN v_doc.invoice_number IS NOT NULL THEN ': ' || v_doc.invoice_number
        ELSE '.'
      END,
    p_severity := 'success',
    p_status := 'done',
    p_channel := 'system',
    p_source := 'confirm_purchase_document',
    p_source_id := p_document_id,
    p_old_data := jsonb_build_object(
      'status', v_doc.status
    ),
    p_new_data := jsonb_build_object(
      'status', 'confirmed',
      'total_amount', v_total,
      'items_count', v_items_count,
      'total_quantity', v_total_quantity,
      'invoice_number', v_doc.invoice_number
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-C',
      'origin', 'purchase_document_confirmation'
    ),
    p_related_supplier_id := v_doc.supplier_id,
    p_related_purchase_document_id := p_document_id
  );
END;
$$;


ALTER FUNCTION "public"."confirm_purchase_document"("p_document_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_purchase_document"("p_document_id" "uuid") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC operacional para confirmar documento de compra. Deve permanecer autenticada até revisão do fluxo de compras.';



CREATE OR REPLACE FUNCTION "public"."confirm_reserved_public_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
BEGIN
  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.status,
    o.total
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  LIMIT 1;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_found'
    );
  END IF;

  -- Segurança para chamadas reais via API/JWT.
  -- No SQL Editor, auth.role() costuma não ser anon/authenticated.
  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_order.store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied'
      );
    END IF;
  END IF;

  IF v_order.status <> 'reserved' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'order_not_reserved',
      'status', v_order.status
    );
  END IF;

  UPDATE public.orders
  SET
    status = 'confirmed',
    confirmed_at = now(),
    commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb) || jsonb_build_object(
      'confirmed_at', now(),
      'confirmed_by', auth.uid(),
      'confirmed_by_source', 'confirm_reserved_public_order'
    )
  WHERE id = v_order.id;

  RETURN jsonb_build_object(
    'ok', true,
    'order_id', v_order.id,
    'order_code', v_order.order_code,
    'status', 'confirmed',
    'total', v_order.total
  );
END;
$$;


ALTER FUNCTION "public"."confirm_reserved_public_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_reserved_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT * FROM public.stock_reservations
    WHERE store_id = p_store_id
      AND order_id = p_order_id
      AND status = 'active'
  LOOP
    -- baixa físico
    PERFORM public.apply_stock_movement_delta(
      p_store_id,
      r.product_id,
      'confirmation',
      -r.quantity,
      true,
      'order',
      p_order_id,
      'confirm',
      '{}'::jsonb,
      p_created_by
    );

    -- encerra reserva
    UPDATE public.stock_reservations
    SET status = 'consumed', consumed_at = now()
    WHERE id = r.id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."confirm_reserved_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_purchase_quotation_to_draft"("p_quotation_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("purchase_document_id" "uuid", "quotation_id" "uuid", "quotation_code" "text", "supplier_id" "uuid", "supplier_name" "text", "status" "text", "items_count" integer, "total_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quotation record;
  v_document_id uuid;
  v_item record;
  v_items_count integer := 0;
  v_total_amount numeric := 0;
BEGIN
  SELECT
    q.id,
    q.store_id,
    q.supplier_id,
    q.quotation_code,
    q.status,
    q.converted_purchase_document_id,
    q.sent_channel,
    q.responsible_name,
    s.name AS supplier_name
  INTO v_quotation
  FROM public.purchase_quotations q
  JOIN public.suppliers s
    ON s.id = q.supplier_id
   AND s.store_id = q.store_id
  WHERE q.id = p_quotation_id
  FOR UPDATE;

  IF v_quotation.id IS NULL THEN
    RAISE EXCEPTION 'Cotação não encontrada.';
  END IF;

  IF NOT public.user_can_purchase_action(v_quotation.store_id, 'create') THEN
    RAISE EXCEPTION 'Sem permissão para converter cotação em compra nesta loja.';
  END IF;

  IF v_quotation.converted_purchase_document_id IS NOT NULL THEN
    RAISE EXCEPTION 'Esta cotação já foi convertida em compra.';
  END IF;

  IF v_quotation.status = 'converted' THEN
    RAISE EXCEPTION 'Esta cotação já está convertida e não pode ser convertida novamente.';
  END IF;

  IF v_quotation.status <> 'approved' THEN
    RAISE EXCEPTION 'Somente cotações aprovadas podem ser convertidas em compra.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.purchase_quotation_items qi
    WHERE qi.quotation_id = p_quotation_id
      AND qi.store_id = v_quotation.store_id
      AND COALESCE(qi.approved_qty, qi.requested_qty) > 0
  ) THEN
    RAISE EXCEPTION 'Cotação sem itens aprovados para conversão.';
  END IF;

  INSERT INTO public.purchase_documents (
    store_id,
    supplier_id,
    invoice_number,
    issue_date,
    total_amount,
    notes,
    status
  )
  VALUES (
    v_quotation.store_id,
    v_quotation.supplier_id,
    NULL,
    CURRENT_DATE,
    0,
    COALESCE(
      NULLIF(p_notes, ''),
      'Rascunho criado a partir da cotação ' || v_quotation.quotation_code || '.'
    ),
    'draft'
  )
  RETURNING id INTO v_document_id;

  FOR v_item IN
    SELECT
      qi.product_id,
      COALESCE(qi.approved_qty, qi.requested_qty) AS quantity,
      COALESCE(qi.quoted_unit_cost, qi.reference_unit_cost, 0) AS unit_cost
    FROM public.purchase_quotation_items qi
    WHERE qi.quotation_id = p_quotation_id
      AND qi.store_id = v_quotation.store_id
      AND COALESCE(qi.approved_qty, qi.requested_qty) > 0
  LOOP
    INSERT INTO public.purchase_document_items (
      purchase_document_id,
      product_id,
      quantity,
      unit_cost,
      store_id
    )
    VALUES (
      v_document_id,
      v_item.product_id,
      v_item.quantity,
      v_item.unit_cost,
      v_quotation.store_id
    );

    v_items_count := v_items_count + 1;
    v_total_amount := v_total_amount + (v_item.quantity * v_item.unit_cost);
  END LOOP;

  UPDATE public.purchase_documents pd
  SET total_amount = v_total_amount
  WHERE pd.id = v_document_id;

  UPDATE public.purchase_quotations q
  SET
    status = 'converted',
    converted_purchase_document_id = v_document_id,
    updated_at = now()
  WHERE q.id = p_quotation_id;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_quotation.store_id,
    p_entity_type := 'purchase_quotation',
    p_entity_id := p_quotation_id,
    p_event_type := 'quotation_converted_to_purchase_document',
    p_title := 'Cotação convertida em compra',
    p_description := 'Cotação ' || v_quotation.quotation_code || ' convertida em rascunho de compra.',
    p_severity := 'success',
    p_status := 'done',
    p_responsible_name := v_quotation.responsible_name,
    p_channel := COALESCE(v_quotation.sent_channel, 'system'),
    p_source := 'convert_purchase_quotation_to_draft',
    p_source_id := p_quotation_id,
    p_old_data := jsonb_build_object(
      'status', v_quotation.status,
      'converted_purchase_document_id', v_quotation.converted_purchase_document_id
    ),
    p_new_data := jsonb_build_object(
      'status', 'converted',
      'purchase_document_id', v_document_id,
      'items_count', v_items_count,
      'total_amount', v_total_amount
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-B',
      'quotation_code', v_quotation.quotation_code,
      'supplier_name', v_quotation.supplier_name
    ),
    p_related_supplier_id := v_quotation.supplier_id,
    p_related_purchase_quotation_id := p_quotation_id,
    p_related_purchase_document_id := v_document_id
  );

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_quotation.store_id,
    p_entity_type := 'purchase_document',
    p_entity_id := v_document_id,
    p_event_type := 'purchase_document_created_from_quotation',
    p_title := 'Rascunho de compra criado pela cotação',
    p_description := 'Rascunho de compra criado a partir da cotação ' || v_quotation.quotation_code || '.',
    p_severity := 'info',
    p_status := 'done',
    p_responsible_name := v_quotation.responsible_name,
    p_channel := COALESCE(v_quotation.sent_channel, 'system'),
    p_source := 'convert_purchase_quotation_to_draft',
    p_source_id := v_document_id,
    p_new_data := jsonb_build_object(
      'purchase_document_id', v_document_id,
      'quotation_id', p_quotation_id,
      'quotation_code', v_quotation.quotation_code,
      'items_count', v_items_count,
      'total_amount', v_total_amount,
      'status', 'draft',
      'supplier_name', v_quotation.supplier_name
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-B',
      'origin', 'purchase_quotation_conversion',
      'supplier_name', v_quotation.supplier_name,
      'quotation_code', v_quotation.quotation_code
    ),
    p_related_supplier_id := v_quotation.supplier_id,
    p_related_purchase_quotation_id := p_quotation_id,
    p_related_purchase_document_id := v_document_id
  );

  RETURN QUERY
  SELECT
    v_document_id,
    v_quotation.id,
    v_quotation.quotation_code,
    v_quotation.supplier_id,
    v_quotation.supplier_name,
    'draft'::text,
    v_items_count,
    v_total_amount;
END;
$$;


ALTER FUNCTION "public"."convert_purchase_quotation_to_draft"("p_quotation_id" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_purchase_quotation_to_draft"("p_quotation_id" "uuid", "p_notes" "text") IS 'Converte uma cotação de compra persistida em documento de compra rascunho.';



CREATE OR REPLACE FUNCTION "public"."create_admin_customer_safe"("p_store_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text" DEFAULT NULL::"text", "p_cpf" "text" DEFAULT NULL::"text", "p_birth_date" "date" DEFAULT NULL::"date", "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_internal_notes" "text" DEFAULT NULL::"text", "p_marketing_consent" boolean DEFAULT false, "p_loyalty_opt_in" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_phone text;
  v_customer_id uuid;
begin
  if p_store_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_store_id');
  end if;

  if coalesce(auth.role(), '') in ('anon', 'authenticated') then
    if auth.uid() is null
       or not (
         public.app_is_store_owner(p_store_id)
         or public.user_has_store_permission(p_store_id, 'customers.manage')
       ) then
      return jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'message', 'Você não tem permissão para criar clientes.'
      );
    end if;
  end if;

  v_phone := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');

  if length(v_phone) < 8 then
    return jsonb_build_object(
      'ok', false,
      'error', 'invalid_phone',
      'message', 'Informe um telefone válido.'
    );
  end if;

  if exists (
    select 1
    from public.customers c
    where c.store_id = p_store_id
      and c.phone = v_phone
      and c.status <> 'deleted_requested'
  ) then
    return jsonb_build_object(
      'ok', false,
      'error', 'customer_phone_already_exists',
      'message', 'Já existe um cliente com este telefone.'
    );
  end if;

  insert into public.customers (
    store_id,
    full_name,
    phone,
    email,
    cpf,
    birth_date,
    is_whatsapp,
    contact_preference,
    marketing_consent,
    loyalty_opt_in,
    tags,
    internal_notes,
    source,
    data_ownership,
    editable_by_store,
    customer_metadata
  )
  values (
    p_store_id,
    nullif(trim(coalesce(p_full_name, '')), ''),
    v_phone,
    nullif(trim(coalesce(p_email, '')), ''),
    nullif(regexp_replace(coalesce(p_cpf, ''), '\D', '', 'g'), ''),
    p_birth_date,
    true,
    'whatsapp',
    coalesce(p_marketing_consent, false),
    coalesce(p_loyalty_opt_in, true),
    coalesce(p_tags, '{}'),
    p_internal_notes,
    'admin',
    'store_managed',
    true,
    jsonb_build_object(
      'created_by', auth.uid(),
      'created_by_source', 'create_admin_customer_safe',
      'created_at', now()
    )
  )
  returning id into v_customer_id;

  return jsonb_build_object(
    'ok', true,
    'customer_id', v_customer_id
  );
end;
$$;


ALTER FUNCTION "public"."create_admin_customer_safe"("p_store_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_cpf" "text", "p_birth_date" "date", "p_tags" "text"[], "p_internal_notes" "text", "p_marketing_consent" boolean, "p_loyalty_opt_in" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_cashbook_entry"("p_store_id" "uuid", "p_type" "text", "p_direction" "text", "p_amount" numeric, "p_description" "text", "p_payment_method_code" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entry_id uuid;
  v_entry_code text;
  v_payment_method record;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF p_type NOT IN ('sale', 'manual_income', 'manual_expense', 'refund', 'adjustment', 'transfer', 'other') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_type');
  END IF;

  IF p_direction NOT IN ('in', 'out') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_direction');
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_amount');
  END IF;

  IF p_description IS NULL OR length(trim(p_description)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_description');
  END IF;

  IF p_payment_method_code IS NOT NULL THEN
    SELECT
      pm.code,
      pm.name
    INTO v_payment_method
    FROM public.store_payment_methods pm
    WHERE pm.store_id = p_store_id
      AND pm.code = p_payment_method_code
      AND pm.active = true
    LIMIT 1;
  END IF;

  v_entry_code := public.generate_cashbook_entry_code();

  INSERT INTO public.cashbook_entries (
    store_id,
    entry_code,
    entry_date,
    occurred_at,
    type,
    direction,
    amount,
    description,
    notes,
    payment_method,
    payment_method_code,
    source,
    status,
    affects_balance,
    metadata,
    created_by
  )
  VALUES (
    p_store_id,
    v_entry_code,
    COALESCE(p_occurred_at::date, CURRENT_DATE),
    COALESCE(p_occurred_at, now()),
    p_type,
    p_direction,
    p_amount,
    trim(p_description),
    NULLIF(trim(COALESCE(p_notes, '')), ''),
    v_payment_method.name,
    p_payment_method_code,
    'manual',
    'confirmed',
    true,
    COALESCE(p_metadata, '{}'::jsonb),
    auth.uid()
  )
  RETURNING id INTO v_entry_id;

  RETURN jsonb_build_object(
    'ok', true,
    'entry', jsonb_build_object(
      'id', v_entry_id,
      'entry_code', v_entry_code,
      'type', p_type,
      'direction', p_direction,
      'amount', p_amount,
      'payment_method_code', p_payment_method_code
    )
  );
END;
$$;


ALTER FUNCTION "public"."create_cashbook_entry"("p_store_id" "uuid", "p_type" "text", "p_direction" "text", "p_amount" numeric, "p_description" "text", "p_payment_method_code" "text", "p_notes" "text", "p_occurred_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_cashbook_entry_from_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_existing_id uuid;
  v_entry_id uuid;
  v_entry_code text;
  v_payment_name text;
  v_affects_cashbook boolean := true;
BEGIN
  SELECT
    o.id,
    o.store_id,
    o.order_code,
    o.customer_id,
    o.customer_name,
    o.total,
    o.status,
    o.payment_method,
    o.payment_method_code,
    o.payment_metadata,
    o.sales_channel,
    o.fulfillment_type,
    o.completed_at
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  LIMIT 1;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF v_order.status <> 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_completed', 'status', v_order.status);
  END IF;

  SELECT id
  INTO v_existing_id
  FROM public.cashbook_entries
  WHERE order_id = v_order.id
    AND source = 'order'
    AND type = 'sale'
    AND status = 'confirmed'
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_exists', true,
      'entry_id', v_existing_id
    );
  END IF;

  v_payment_name := COALESCE(v_order.payment_metadata->>'name', v_order.payment_method_code, v_order.payment_method::text);
  v_affects_cashbook := COALESCE((v_order.payment_metadata->>'affects_cashbook')::boolean, true);

  IF v_affects_cashbook = false THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'payment_method_does_not_affect_cashbook'
    );
  END IF;

  v_entry_code := public.generate_cashbook_entry_code();

  INSERT INTO public.cashbook_entries (
    store_id,
    entry_code,
    entry_date,
    occurred_at,
    type,
    direction,
    amount,
    description,
    payment_method,
    payment_method_code,
    source,
    source_id,
    order_id,
    customer_id,
    status,
    affects_balance,
    metadata,
    created_by
  )
  VALUES (
    v_order.store_id,
    v_entry_code,
    COALESCE(v_order.completed_at::date, CURRENT_DATE),
    COALESCE(v_order.completed_at, now()),
    'sale',
    'in',
    v_order.total,
    'Venda concluída pelo pedido ' || v_order.order_code,
    v_payment_name,
    COALESCE(v_order.payment_method_code, v_order.payment_method::text),
    'order',
    v_order.id,
    v_order.id,
    v_order.customer_id,
    'confirmed',
    true,
    jsonb_build_object(
      'order_code', v_order.order_code,
      'sales_channel', v_order.sales_channel,
      'fulfillment_type', v_order.fulfillment_type,
      'customer_name', v_order.customer_name,
      'payment_metadata', COALESCE(v_order.payment_metadata, '{}'::jsonb)
    ),
    auth.uid()
  )
  RETURNING id INTO v_entry_id;

  RETURN jsonb_build_object(
    'ok', true,
    'entry', jsonb_build_object(
      'id', v_entry_id,
      'entry_code', v_entry_code,
      'amount', v_order.total,
      'payment_method_code', COALESCE(v_order.payment_method_code, v_order.payment_method::text)
    )
  );
END;
$$;


ALTER FUNCTION "public"."create_cashbook_entry_from_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_manual_stock_adjustment"("p_product_id" "uuid", "p_location_id" "uuid", "p_adjustment_kind" "text", "p_quantity" numeric, "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("movement_id" "uuid", "product_id" "uuid", "location_id" "uuid", "movement_type" "public"."stock_movement_type", "quantity" numeric, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_movement_type public.stock_movement_type;
  v_quantity numeric;
  v_reason text;
  v_movement_id uuid;

  v_on_hand_before numeric := 0;
  v_on_hand_after numeric := 0;
  v_reserved numeric := 0;
  v_available numeric := 0;

  v_has_balance boolean := false;
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'Informe uma quantidade maior que zero.';
  END IF;

  SELECT p.store_id
    INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao produto informado.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stock_locations sl
    WHERE sl.id = p_location_id
      AND sl.store_id = v_store_id
      AND sl.active = true
  ) THEN
    RAISE EXCEPTION 'Local de estoque inválido ou inativo.';
  END IF;

  CASE p_adjustment_kind
    WHEN 'manual_entry' THEN
      v_movement_type := 'entry';
      v_quantity := abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Entrada por correção manual');

    WHEN 'manual_exit' THEN
      v_movement_type := 'exit';
      v_quantity := -abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Saída por correção manual');

    WHEN 'damage' THEN
      v_movement_type := 'clearance';
      v_quantity := -abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Baixa por avaria');

    WHEN 'expired' THEN
      v_movement_type := 'clearance';
      v_quantity := -abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Baixa por vencimento');

    WHEN 'breakage' THEN
      v_movement_type := 'clearance';
      v_quantity := -abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Baixa por quebra');

    WHEN 'loss' THEN
      v_movement_type := 'clearance';
      v_quantity := -abs(p_quantity);
      v_reason := COALESCE(NULLIF(p_reason, ''), 'Baixa por perda');

    ELSE
      RAISE EXCEPTION 'Tipo de ajuste inválido.';
  END CASE;

  SELECT
    true,
    COALESCE(ilb.on_hand, 0),
    COALESCE(ilb.reserved, 0)
  INTO
    v_has_balance,
    v_on_hand_before,
    v_reserved
  FROM public.inventory_location_balances ilb
  WHERE ilb.store_id = v_store_id
    AND ilb.product_id = p_product_id
    AND ilb.location_id = p_location_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_has_balance := false;
    v_on_hand_before := 0;
    v_reserved := 0;
  END IF;

  v_available := v_on_hand_before - v_reserved;

  IF v_quantity < 0 AND v_available < abs(v_quantity) THEN
    RAISE EXCEPTION 'Saldo insuficiente no local selecionado. Disponível: %, solicitado: %.',
      v_available,
      abs(v_quantity);
  END IF;

  v_on_hand_after := v_on_hand_before + v_quantity;

  IF v_on_hand_after < 0 THEN
    RAISE EXCEPTION 'O ajuste deixaria o estoque físico negativo.';
  END IF;

  IF v_has_balance THEN
    UPDATE public.inventory_location_balances ilb
    SET
      on_hand = v_on_hand_after,
      updated_at = now()
    WHERE ilb.store_id = v_store_id
      AND ilb.product_id = p_product_id
      AND ilb.location_id = p_location_id;
  ELSE
    INSERT INTO public.inventory_location_balances (
      store_id,
      product_id,
      location_id,
      on_hand,
      reserved
    )
    VALUES (
      v_store_id,
      p_product_id,
      p_location_id,
      v_on_hand_after,
      0
    );
  END IF;

  INSERT INTO public.stock_movements (
    store_id,
    product_id,
    location_id,
    type,
    quantity,
    previous_stock,
    new_stock,
    reason,
    source,
    source_id,
    affects_physical,
    created_by,
    metadata
  )
  VALUES (
    v_store_id,
    p_product_id,
    p_location_id,
    v_movement_type,
    v_quantity::integer,
    v_on_hand_before::integer,
    v_on_hand_after::integer,
    v_reason,
    'manual_adjustment',
    NULL,
    true,
    auth.uid(),
    jsonb_build_object(
      'adjustment_kind', p_adjustment_kind,
      'notes', p_notes,
      'created_from', 'stock_movements_page',
      'location_id', p_location_id,
      'on_hand_before', v_on_hand_before,
      'on_hand_after', v_on_hand_after,
      'reserved', v_reserved,
      'available_before', v_available
    )
  )
  RETURNING id INTO v_movement_id;

  RETURN QUERY
  SELECT
    v_movement_id,
    p_product_id,
    p_location_id,
    v_movement_type,
    v_quantity,
    'Ajuste de estoque registrado com sucesso.'::text;
END;
$$;


ALTER FUNCTION "public"."create_manual_stock_adjustment"("p_product_id" "uuid", "p_location_id" "uuid", "p_adjustment_kind" "text", "p_quantity" numeric, "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_manual_stock_adjustment"("p_product_id" "uuid", "p_location_id" "uuid", "p_adjustment_kind" "text", "p_quantity" numeric, "p_reason" "text", "p_notes" "text") IS 'Registra ajuste manual de estoque por local, atualizando inventory_location_balances.on_hand/reserved e gravando histórico em stock_movements.';



CREATE OR REPLACE FUNCTION "public"."create_my_profile_change_request"("p_store_id" "uuid", "p_request_type" "text", "p_requested_changes" "jsonb", "p_reason" "text", "p_sensitive" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "current_snapshot" "jsonb", "reason" "text", "sensitive" boolean, "visible_to_member" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member public.store_members%ROWTYPE;
  v_actor_email text;
  v_profile public.profiles%ROWTYPE;
  v_snapshot jsonb;
  v_request_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF p_request_type NOT IN (
    'name_change',
    'cpf_change',
    'birthdate_change',
    'identity_change',
    'contact_update',
    'address_update',
    'avatar_update',
    'additional_info_update',
    'additional_info_remove',
    'third_party_update',
    'other'
  ) THEN
    RAISE EXCEPTION 'Tipo de solicitação inválido.';
  END IF;

  IF length(trim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'Informe um motivo com pelo menos 5 caracteres.';
  END IF;

  IF jsonb_typeof(COALESCE(p_requested_changes, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'As alterações solicitadas devem ser enviadas como objeto JSON.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  SELECT *
  INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_user_id;

  SELECT au.email::text
  INTO v_actor_email
  FROM auth.users au
  WHERE au.id = v_user_id;

  v_snapshot := jsonb_build_object(
    'profile', jsonb_build_object(
      'name', v_profile.name,
      'cpf', v_profile.cpf,
      'birthdate', v_profile.birthdata,
      'avatar_url', v_profile.avatar_url
    ),
    'member', jsonb_build_object(
      'internal_alias', v_member.internal_alias,
      'member_email', v_member.member_email,
      'member_phone', v_member.member_phone,
      'member_mobile_phone', v_member.member_mobile_phone,
      'member_whatsapp_phone', v_member.member_whatsapp_phone,
      'member_avatar_url', v_member.member_avatar_url,
      'member_zip_code', v_member.member_zip_code,
      'member_address', v_member.member_address,
      'member_address_number', v_member.member_address_number,
      'member_complement', v_member.member_complement,
      'member_district', v_member.member_district,
      'member_city', v_member.member_city,
      'member_state', v_member.member_state,
      'member_additional_info', COALESCE(v_member.member_additional_info, '[]'::jsonb)
    )
  );

  INSERT INTO public.store_member_profile_change_requests (
    store_id,
    member_id,
    user_id,
    requested_by,
    requested_by_email,
    request_type,
    status,
    requested_changes,
    current_snapshot,
    reason,
    visible_to_member,
    sensitive,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_member.store_id,
    v_member.id,
    v_member.user_id,
    v_user_id,
    v_actor_email,
    p_request_type,
    'pending',
    COALESCE(p_requested_changes, '{}'::jsonb),
    v_snapshot,
    trim(p_reason),
    true,
    COALESCE(p_sensitive, false),
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'origin', 'create_my_profile_change_request'
    ),
    now(),
    now()
  )
  RETURNING id
  INTO v_request_id;

  INSERT INTO public.store_member_occurrences (
    store_id,
    member_id,
    user_id,
    occurrence_type,
    severity,
    title,
    description,
    occurred_at,
    visible_to_member,
    created_by,
    created_by_email,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_member.store_id,
    v_member.id,
    v_member.user_id,
    'note',
    CASE WHEN COALESCE(p_sensitive, false) THEN 'high' ELSE 'info' END,
    'Solicitação cadastral criada',
    'O usuário criou uma solicitação de alteração cadastral.',
    now(),
    true,
    v_user_id,
    v_actor_email,
    jsonb_build_object(
      'origin', 'create_my_profile_change_request',
      'request_id', v_request_id,
      'request_type', p_request_type
    ),
    now(),
    now()
  );

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.requested_changes,
    r.current_snapshot,
    r.reason,
    r.sensitive,
    r.visible_to_member,
    r.created_at
  FROM public.store_member_profile_change_requests r
  WHERE r.id = v_request_id;
END;
$$;


ALTER FUNCTION "public"."create_my_profile_change_request"("p_store_id" "uuid", "p_request_type" "text", "p_requested_changes" "jsonb", "p_reason" "text", "p_sensitive" boolean, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_my_profile_change_request_v2"("p_member_id" "uuid", "p_request_type" "text", "p_requested_changes" "jsonb", "p_reason" "text", "p_sensitive" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "current_snapshot" "jsonb", "reason" "text", "sensitive" boolean, "visible_to_member" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
