      'internal_alias', v_member.internal_alias,
      'member_email', v_member.member_email,
      'member_phone', v_member.member_phone,
      'member_mobile_phone', v_member.member_mobile_phone,
      'member_whatsapp_phone', v_member.member_whatsapp_phone,
      'member_avatar_url', v_member.member_avatar_url,
      'member_zip_code', v_member.member_zip_code,
      'member_address', v_member.member_address,
      'member_address_number', v_member.member_address_number,
      'member_complement', v_member.member_complement,
      'member_district', v_member.member_district,
      'member_city', v_member.member_city,
      'member_state', v_member.member_state,
      'member_additional_info', COALESCE(v_member.member_additional_info, '[]'::jsonb)
    )
  );

  INSERT INTO public.store_member_profile_change_requests (
    store_id,
    member_id,
    user_id,
    requested_by,
    requested_by_email,
    request_type,
    status,
    requested_changes,
