    'pending',
    COALESCE(p_requested_changes, '{}'::jsonb),
    v_snapshot,
    trim(p_reason),
    true,
    COALESCE(p_sensitive, false),
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'origin', 'create_my_profile_change_request_v2',
      'resolved_store_id', v_member.store_id,
      'resolved_member_id', v_member.id
    ),
    now(),
