CREATE OR REPLACE FUNCTION "public"."create_operational_timeline_event"("p_store_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT 'info'::"text", "p_status" "text" DEFAULT 'done'::"text", "p_actor_user_id" "uuid" DEFAULT "auth"."uid"(), "p_actor_email" "text" DEFAULT NULL::"text", "p_responsible_name" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT 'system'::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_source" "text" DEFAULT 'system'::"text", "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_old_data" "jsonb" DEFAULT '{}'::"jsonb", "p_new_data" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_related_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_related_product_id" "uuid" DEFAULT NULL::"uuid", "p_related_purchase_quotation_id" "uuid" DEFAULT NULL::"uuid", "p_related_purchase_document_id" "uuid" DEFAULT NULL::"uuid", "p_related_stock_transfer_id" "uuid" DEFAULT NULL::"uuid", "p_related_stock_movement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_event_id uuid;
  v_auth_uid uuid := auth.uid();
BEGIN
  -- Chamadas autenticadas devem respeitar o mesmo padrão das RPCs operacionais.
  -- Chamadas internas/service-role podem não ter auth.uid().
  IF v_auth_uid IS NOT NULL THEN
    IF NOT public.is_store_member(p_store_id)
    AND NOT EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = v_auth_uid
        AND p.is_admin = true
    ) THEN
      RAISE EXCEPTION 'Usuário não autorizado para registrar evento nesta loja.';
    END IF;
  END IF;

  INSERT INTO public.operational_timeline_events (
    store_id,
    entity_type,
    entity_id,
    event_type,
    title,
    description,
    severity,
    status,
    actor_user_id,
    actor_email,
    responsible_name,
    channel,
    occurred_at,
    source,
    source_id,
    old_data,
    new_data,
    metadata,
    related_supplier_id,
    related_product_id,
    related_purchase_quotation_id,
    related_purchase_document_id,
    related_stock_transfer_id,
    related_stock_movement_id
  )
  VALUES (
    p_store_id,
    p_entity_type,
    p_entity_id,
    p_event_type,
    p_title,
    p_description,
    COALESCE(p_severity, 'info'),
    COALESCE(p_status, 'done'),
    p_actor_user_id,
    p_actor_email,
    p_responsible_name,
    p_channel,
    COALESCE(p_occurred_at, now()),
    COALESCE(p_source, 'system'),
    p_source_id,
    COALESCE(p_old_data, '{}'::jsonb),
    COALESCE(p_new_data, '{}'::jsonb),
    COALESCE(p_metadata, '{}'::jsonb),
    p_related_supplier_id,
    p_related_product_id,
    p_related_purchase_quotation_id,
    p_related_purchase_document_id,
    p_related_stock_transfer_id,
    p_related_stock_movement_id
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."create_operational_timeline_event"("p_store_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text", "p_severity" "text", "p_status" "text", "p_actor_user_id" "uuid", "p_actor_email" "text", "p_responsible_name" "text", "p_channel" "text", "p_occurred_at" timestamp with time zone, "p_source" "text", "p_source_id" "uuid", "p_old_data" "jsonb", "p_new_data" "jsonb", "p_metadata" "jsonb", "p_related_supplier_id" "uuid", "p_related_product_id" "uuid", "p_related_purchase_quotation_id" "uuid", "p_related_purchase_document_id" "uuid", "p_related_stock_transfer_id" "uuid", "p_related_stock_movement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_order_with_reservation"("p_store_id" "uuid", "p_customer_name" "text", "p_customer_phone" "text", "p_items" "jsonb", "p_payment_method" "text", "p_total" numeric, "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_quantity integer;
  v_unit_price numeric;
  v_order_status text := 'reserved';
  v_reservation_listing_duration integer;
  v_expires_at timestamptz;
  v_config jsonb;
  v_phone text;
  v_items_count integer;
  v_current_stock integer;
BEGIN
  v_phone := regexp_replace(coalesce(p_customer_phone, ''), '\D', '', 'g');

  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Loja não informada');
  END IF;

  SELECT s.config
    INTO v_config
  FROM public.stores s
  WHERE s.id = p_store_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Loja inválida');
  END IF;

  IF length(trim(coalesce(p_customer_name, ''))) < 2 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Nome do cliente inválido');
  END IF;

  IF length(v_phone) < 10 OR length(v_phone) > 14 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Telefone inválido');
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Itens inválidos');
  END IF;

  SELECT jsonb_array_length(p_items)
    INTO v_items_count;

  IF v_items_count <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Carrinho vazio');
  END IF;

  IF v_items_count > 50 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Quantidade de itens excede o limite');
  END IF;

  v_reservation_listing_duration := COALESCE(
    NULLIF(v_config ->> 'timer_duration_minutes', '')::integer,
    10
  );

  v_reservation_listing_duration := greatest(
    1,
    least(v_reservation_listing_duration, 120)
  );

  v_expires_at := now() + (v_reservation_listing_duration || ' minutes')::interval;

  INSERT INTO public.orders (
    store_id,
    customer_name,
    customer_phone,
    status,
    payment_method,
    total,
    notes,
    metadata
  )
  VALUES (
    p_store_id,
    trim(p_customer_name),
    v_phone,
    v_order_status,
    coalesce(p_payment_method, 'pending'),
    coalesce(p_total, 0),
    p_notes,
    COALESCE(p_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'origin', 'create_order_with_reservation',
        'items_count', v_items_count
      )
  )
  RETURNING id INTO v_order_id;

  FOR v_item IN
    SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := COALESCE(
      NULLIF(v_item ->> 'product_id', '')::uuid,
      NULLIF(v_item ->> 'id', '')::uuid
    );

    v_quantity := COALESCE(
      NULLIF(v_item ->> 'quantity', '')::integer,
      0
    );

    v_unit_price := COALESCE(
      NULLIF(v_item ->> 'unit_price', '')::numeric,
      NULLIF(v_item ->> 'price', '')::numeric,
      0
    );

    IF v_product_id IS NULL THEN
      RAISE EXCEPTION 'Produto inválido';
    END IF;

    IF v_quantity <= 0 OR v_quantity > 999 THEN
      RAISE EXCEPTION 'Quantidade inválida';
    END IF;

    IF v_unit_price < 0 THEN
      RAISE EXCEPTION 'Preço inválido';
    END IF;

    SELECT COALESCE(p.physical_stock, 0)
      INTO v_current_stock
    FROM public.products p
    WHERE p.id = v_product_id
      AND p.store_id = p_store_id
      AND COALESCE(p.active, true) = true
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto não encontrado ou indisponível';
    END IF;

    IF v_current_stock < v_quantity THEN
      RAISE EXCEPTION 'Estoque insuficiente para o produto %', v_product_id;
    END IF;

    UPDATE public.products
    SET
      physical_stock = physical_stock - v_quantity,
      sales_count = COALESCE(sales_count, 0) + v_quantity,
      last_sale_at = now()
    WHERE id = v_product_id
      AND store_id = p_store_id;

    INSERT INTO public.order_items (
      order_id,
      product_id,
      quantity,
      unit_price
    )
    VALUES (
      v_order_id,
      v_product_id,
      v_quantity,
      v_unit_price
    );

    INSERT INTO public.stock_reservations (
      store_id,
      product_id,
      order_id,
      quantity,
      expires_at
    )
    VALUES (
      p_store_id,
      v_product_id,
      v_order_id,
      v_quantity,
      v_expires_at
    );
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'expires_at', v_expires_at
  );

EXCEPTION WHEN OTHERS THEN
  IF v_order_id IS NOT NULL THEN
    DELETE FROM public.orders
    WHERE id = v_order_id;
  END IF;

  RETURN jsonb_build_object(
    'success', false,
    'message', SQLERRM
  );
END;
$$;


ALTER FUNCTION "public"."create_order_with_reservation"("p_store_id" "uuid", "p_customer_name" "text", "p_customer_phone" "text", "p_items" "jsonb", "p_payment_method" "text", "p_total" numeric, "p_notes" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_order_with_reservation"("p_store_id" "uuid", "p_customer_name" "text", "p_customer_phone" "text", "p_items" "jsonb", "p_payment_method" "text", "p_total" numeric, "p_notes" "text", "p_metadata" "jsonb") IS 'EXCEÇÃO TEMPORÁRIA 6.4: função pública de pedido com reserva. Usa lógica legada de estoque/pedido e deve ser reescrita na revisão da área Comercial.';



CREATE OR REPLACE FUNCTION "public"."create_public_order_by_slug"("p_slug" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_fulfillment_type" "text", "p_sales_channel" "text", "p_items" "jsonb", "p_delivery_address" "jsonb" DEFAULT '{}'::"jsonb", "p_table_code" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_payment_method_code" "text" DEFAULT 'pending'::"text", "p_delivery_method_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_store record;
  v_store_id uuid;
  v_location_id uuid;
  v_customer_id uuid;
  v_customer_phone text;
  v_customer_name text;
  v_order_id uuid;
  v_order_code text;
  v_public_order_token text;

  v_subtotal numeric := 0;
  v_delivery_fee numeric := 0;
  v_total numeric := 0;
  v_minimum_order_value numeric := 0;

  v_reservation_minutes integer := 10;
  v_expires_at timestamp with time zone;

  v_item record;
  v_product record;
  v_qty numeric;
  v_line_total numeric;
  v_updated_balance_id uuid;
  v_items_count integer := 0;

  v_whatsapp_digits text;
  v_whatsapp_message text;
  v_whatsapp_url text;

  v_payment_method record;
  v_payment_method_enum payment_method;

  v_delivery_method record;
  v_effective_delivery_method_code text;
  v_effective_fulfillment_type text;
BEGIN
  -- =======================================================
  -- 1. Validações básicas
  -- =======================================================

  IF p_slug IS NULL OR length(trim(p_slug)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_slug');
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'empty_cart');
  END IF;

  IF p_sales_channel IS NULL OR p_sales_channel NOT IN ('whatsapp', 'public_store', 'qr_table', 'direct', 'phone', 'in_person', 'other') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_sales_channel');
  END IF;

  v_customer_phone := regexp_replace(COALESCE(p_customer_phone, ''), '\D', '', 'g');
  v_customer_name := nullif(trim(COALESCE(p_customer_name, '')), '');

  IF length(v_customer_phone) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_customer_phone');
  END IF;

  -- =======================================================
  -- 2. Loja pública habilitada
  -- =======================================================

  SELECT
    s.*,
    regexp_replace(
      COALESCE(
        s.contacts->>'whatsapp_business',
        s.contacts->>'whatsapp',
        s.phone_number,
        ''
      ),
      '\D',
      '',
      'g'
    ) AS whatsapp_digits
  INTO v_store
  FROM public.stores s
  WHERE s.slug = lower(trim(p_slug))
    AND s.public_store_enabled = true
  LIMIT 1;

  IF v_store.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_not_found_or_disabled');
  END IF;

  v_store_id := v_store.id;
  v_reservation_minutes := COALESCE(v_store.reservation_time_minutes, 10);
  v_whatsapp_digits := COALESCE(v_store.whatsapp_digits, '');

  -- =======================================================
  -- 3. Canal de venda ativo e público
  -- =======================================================

  IF NOT EXISTS (
    SELECT 1
    FROM public.store_sales_channels sc
    WHERE sc.store_id = v_store_id
      AND sc.code = p_sales_channel
      AND sc.active = true
      AND sc.public_enabled = true
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sales_channel_disabled');
  END IF;

  -- =======================================================
  -- 4. Forma de entrega ativa e pública
  -- =======================================================

  v_effective_delivery_method_code :=
    COALESCE(
      NULLIF(trim(COALESCE(p_delivery_method_code, '')), ''),
      CASE
        WHEN p_fulfillment_type = 'delivery' THEN 'local_delivery'
        WHEN p_fulfillment_type = 'qr_table' THEN 'qr_table'
        WHEN p_fulfillment_type = 'dine_in' THEN 'dine_in'
        ELSE 'pickup'
      END
    );

  SELECT
    dm.code,
    dm.name,
    dm.fulfillment_type,
    dm.requires_address,
    dm.requires_table,
    dm.minimum_order_value,
    dm.delivery_fee,
    dm.estimated_minutes_min,
    dm.estimated_minutes_max
  INTO v_delivery_method
  FROM public.store_delivery_methods dm
  WHERE dm.store_id = v_store_id
    AND dm.code = v_effective_delivery_method_code
    AND dm.active = true
    AND dm.public_enabled = true
  LIMIT 1;

  IF v_delivery_method.code IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'delivery_method_disabled'
    );
  END IF;

  v_effective_fulfillment_type := v_delivery_method.fulfillment_type;
  v_delivery_fee := COALESCE(v_delivery_method.delivery_fee, 0);
  v_minimum_order_value := COALESCE(v_delivery_method.minimum_order_value, 0);

  IF v_delivery_method.requires_address = true
     AND (p_delivery_address IS NULL OR p_delivery_address = '{}'::jsonb) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'delivery_address_required');
  END IF;

  IF v_delivery_method.requires_table = true
     AND (p_table_code IS NULL OR length(trim(p_table_code)) = 0) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_code_required');
  END IF;

  -- =======================================================
  -- 5. Forma de pagamento ativa e pública
  -- =======================================================

  SELECT
    pm.code,
    pm.name,
    pm.requires_proof,
    pm.requires_change_for,
    pm.affects_cashbook
  INTO v_payment_method
  FROM public.store_payment_methods pm
  WHERE pm.store_id = v_store_id
    AND pm.code = COALESCE(NULLIF(trim(p_payment_method_code), ''), 'pending')
    AND pm.active = true
    AND pm.public_enabled = true
  LIMIT 1;

  IF v_payment_method.code IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'payment_method_disabled'
    );
  END IF;

  v_payment_method_enum :=
    CASE
      WHEN v_payment_method.code = 'cash' THEN 'cash'::payment_method
      WHEN v_payment_method.code = 'pix' THEN 'pix'::payment_method
      WHEN v_payment_method.code IN ('debit_card', 'credit_card') THEN 'card'::payment_method
      ELSE 'pending'::payment_method
    END;

  -- =======================================================
  -- 6. Local de venda/reserva
  -- =======================================================

  SELECT COALESCE(
    v_store.public_sales_location_id,
    (
      SELECT sl.id
      FROM public.stock_locations sl
      WHERE sl.store_id = v_store_id
        AND sl.active = true
        AND sl.allow_sales = true
      ORDER BY sl.is_default DESC, sl.sort_order, sl.name
      LIMIT 1
    ),
    (
      SELECT sl.id
      FROM public.stock_locations sl
      WHERE sl.store_id = v_store_id
        AND sl.active = true
        AND sl.is_default = true
      ORDER BY sl.sort_order, sl.name
      LIMIT 1
    )
  )
  INTO v_location_id;

  IF v_location_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sales_location_not_configured');
  END IF;

  -- =======================================================
  -- 7. Cliente: cria ou reaproveita por loja + telefone
  -- =======================================================

  SELECT c.id
  INTO v_customer_id
  FROM public.customers c
  WHERE c.store_id = v_store_id
    AND c.phone = v_customer_phone
  ORDER BY c.created_at DESC
  LIMIT 1;

  IF v_customer_id IS NULL THEN
    INSERT INTO public.customers (
      store_id,
      phone,
      full_name,
      is_whatsapp,
      contact_preference,
      marketing_consent,
      loyalty_opt_in,
      status,
      last_login
    )
    VALUES (
      v_store_id,
      v_customer_phone,
      v_customer_name,
      true,
      'whatsapp',
      false,
      false,
      'active',
      now()
    )
    RETURNING id INTO v_customer_id;
  ELSE
    UPDATE public.customers
    SET
      full_name = COALESCE(v_customer_name, full_name),
      is_whatsapp = true,
      contact_preference = COALESCE(contact_preference, 'whatsapp'),
      last_login = now()
    WHERE id = v_customer_id;
  END IF;

  -- =======================================================
  -- 8. Validar itens e calcular subtotal no servidor
  -- =======================================================

  FOR v_item IN
    SELECT
      (item->>'product_id')::uuid AS product_id,
      COALESCE((item->>'quantity')::numeric, 0) AS quantity
    FROM jsonb_array_elements(p_items) AS item
  LOOP
    v_qty := v_item.quantity;

    IF v_item.product_id IS NULL OR v_qty <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_cart_item');
    END IF;

    SELECT
      p.id,
      p.name,
      p.description,
      p.price,
      p.images,
      p.category_id,
      p.active,
      p.discontinued,
      p.is_discontinued,
      c.name AS category_name
    INTO v_product
    FROM public.products p
    LEFT JOIN public.categories c ON c.id = p.category_id
    WHERE p.id = v_item.product_id
      AND p.store_id = v_store_id
      AND p.active = true
      AND COALESCE(p.discontinued, false) = false
      AND COALESCE(p.is_discontinued, false) = false
      AND (
        p.category_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.categories cx
          WHERE cx.id = p.category_id
            AND cx.store_id = v_store_id
            AND cx.active = true
        )
      )
    LIMIT 1;

    IF v_product.id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'product_unavailable',
        'product_id', v_item.product_id
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.inventory_location_balances ilb
      WHERE ilb.store_id = v_store_id
        AND ilb.location_id = v_location_id
        AND ilb.product_id = v_product.id
        AND (ilb.on_hand - ilb.reserved) >= v_qty
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'insufficient_stock',
        'product_id', v_product.id,
        'product_name', v_product.name
      );
    END IF;

    v_line_total := v_qty * COALESCE(v_product.price, 0);
    v_subtotal := v_subtotal + v_line_total;
    v_items_count := v_items_count + 1;
  END LOOP;

  IF v_items_count = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'empty_cart');
  END IF;

  -- Pedido mínimo por método de entrega.
  -- Retirada vem com mínimo 0; entrega local vem com mínimo configurável.
  IF v_minimum_order_value > 0
     AND v_subtotal < v_minimum_order_value THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'minimum_order_not_reached',
      'minimum_order_value', v_minimum_order_value,
      'current_total', v_subtotal,
      'delivery_method_code', v_delivery_method.code
    );
  END IF;

  v_total := v_subtotal + v_delivery_fee;

  -- =======================================================
  -- 9. Criar pedido
  -- =======================================================

  v_order_code := public.generate_public_order_code();
  v_public_order_token := encode(extensions.gen_random_bytes(24), 'hex');
  v_expires_at := now() + make_interval(mins => v_reservation_minutes);

  INSERT INTO public.orders (
    store_id,
    user_id,
    customer_id,
    customer_name,
    customer_phone,
    status,
    subtotal,
    delivery_fee,
    total,
    sales_channel,
    fulfillment_type,
    delivery_method_code,
    delivery_metadata,
    payment_method,
    payment_method_code,
    payment_metadata,
    delivery_address,
    delivery_address_snapshot,
    table_code,
    notes,
    order_code,
    public_order_token,
    expires_at,
    customer_snapshot,
    commercial_metadata,
    metadata
  )
  VALUES (
    v_store_id,
    NULL,
    v_customer_id,
    v_customer_name,
    v_customer_phone,
    'reserved',
    v_subtotal,
    v_delivery_fee,
    v_total,
    p_sales_channel,
    v_effective_fulfillment_type,
    v_delivery_method.code,
    jsonb_build_object(
      'code', v_delivery_method.code,
      'name', v_delivery_method.name,
      'fulfillment_type', v_delivery_method.fulfillment_type,
      'requires_address', v_delivery_method.requires_address,
      'requires_table', v_delivery_method.requires_table,
      'minimum_order_value', v_delivery_method.minimum_order_value,
      'delivery_fee', v_delivery_method.delivery_fee,
      'estimated_minutes_min', v_delivery_method.estimated_minutes_min,
      'estimated_minutes_max', v_delivery_method.estimated_minutes_max
    ),
    v_payment_method_enum,
    v_payment_method.code,
    jsonb_build_object(
      'code', v_payment_method.code,
      'name', v_payment_method.name,
      'requires_proof', v_payment_method.requires_proof,
      'requires_change_for', v_payment_method.requires_change_for,
      'affects_cashbook', v_payment_method.affects_cashbook
    ),
    CASE
      WHEN v_delivery_method.requires_address = true THEN p_delivery_address::text
      ELSE NULL
    END,
    COALESCE(p_delivery_address, '{}'::jsonb),
    NULLIF(trim(COALESCE(p_table_code, '')), ''),
    NULLIF(trim(COALESCE(p_notes, '')), ''),
    v_order_code,
    v_public_order_token,
    v_expires_at,
    jsonb_build_object(
      'customer_id', v_customer_id,
      'name', v_customer_name,
      'phone', v_customer_phone,
      'source', 'public_order_rpc'
    ),
    jsonb_build_object(
      'slug', p_slug,
      'sales_channel', p_sales_channel,
      'fulfillment_type', v_effective_fulfillment_type,
      'delivery_method_code', v_delivery_method.code,
      'delivery_method_name', v_delivery_method.name,
      'location_id', v_location_id,
      'payment_method_code', v_payment_method.code,
      'payment_method_name', v_payment_method.name,
      'created_by', 'public_order_rpc'
    ),
    jsonb_build_object(
      'source', 'public_order_rpc',
      'reservation_minutes', v_reservation_minutes
    )
  )
  RETURNING id INTO v_order_id;

  -- =======================================================
  -- 10. Inserir itens e reservar estoque
  -- =======================================================

  FOR v_item IN
    SELECT
      (item->>'product_id')::uuid AS product_id,
      COALESCE((item->>'quantity')::numeric, 0) AS quantity
    FROM jsonb_array_elements(p_items) AS item
  LOOP
    v_qty := v_item.quantity;

    SELECT
      p.id,
      p.name,
      p.description,
      p.price,
      p.images,
      p.category_id,
      c.name AS category_name
    INTO v_product
    FROM public.products p
    LEFT JOIN public.categories c ON c.id = p.category_id
    WHERE p.id = v_item.product_id
      AND p.store_id = v_store_id
    LIMIT 1;

    v_line_total := v_qty * COALESCE(v_product.price, 0);

    UPDATE public.inventory_location_balances ilb
    SET
      reserved = ilb.reserved + v_qty,
      updated_at = now()
    WHERE ilb.store_id = v_store_id
      AND ilb.location_id = v_location_id
      AND ilb.product_id = v_product.id
      AND (ilb.on_hand - ilb.reserved) >= v_qty
    RETURNING ilb.id INTO v_updated_balance_id;

    IF v_updated_balance_id IS NULL THEN
      RAISE EXCEPTION 'Estoque insuficiente para o produto %', v_product.name;
    END IF;

    UPDATE public.inventory_balances ib
    SET
      reserved = ib.reserved + v_qty,
      updated_at = now()
    WHERE ib.store_id = v_store_id
      AND ib.product_id = v_product.id;

    INSERT INTO public.order_items (
      order_id,
      store_id,
      product_id,
      quantity,
      unit_price,
      discount,
      product_snapshot,
      commercial_metadata
    )
    VALUES (
      v_order_id,
      v_store_id,
      v_product.id,
      v_qty::integer,
      COALESCE(v_product.price, 0),
      0,
      jsonb_build_object(
        'product_id', v_product.id,
        'name', v_product.name,
        'description', v_product.description,
        'price', v_product.price,
        'images', COALESCE(to_jsonb(v_product.images), '[]'::jsonb),
        'category_id', v_product.category_id,
        'category_name', v_product.category_name
      ),
      jsonb_build_object(
        'line_total', v_line_total,
        'location_id', v_location_id,
        'reserved_until', v_expires_at
      )
    );

    INSERT INTO public.stock_reservations (
      order_id,
      store_id,
      product_id,
      quantity,
      expires_at,
      status,
      location_id,
      sales_channel,
      metadata
    )
    VALUES (
      v_order_id,
      v_store_id,
      v_product.id,
      v_qty::integer,
      v_expires_at,
      'active',
      v_location_id,
      p_sales_channel,
      jsonb_build_object(
        'order_code', v_order_code,
        'source', 'public_order_rpc',
        'fulfillment_type', v_effective_fulfillment_type,
        'delivery_method_code', v_delivery_method.code,
        'payment_method_code', v_payment_method.code
      )
    );
  END LOOP;

  -- =======================================================
  -- 11. WhatsApp de fechamento
  -- =======================================================

  v_whatsapp_message := concat(
    'Olá! Novo pedido pelo cardápio online da ', v_store.name, E'.\n\n',
    'Pedido: ', v_order_code, E'\n',
    'Subtotal: R$ ', replace(to_char(v_subtotal, 'FM999999990.00'), '.', ','), E'\n',
    CASE
      WHEN v_delivery_fee > 0 THEN concat('Taxa de entrega: R$ ', replace(to_char(v_delivery_fee, 'FM999999990.00'), '.', ','), E'\n')
      ELSE ''
    END,
    'Total: R$ ', replace(to_char(v_total, 'FM999999990.00'), '.', ','), E'\n',
    'Entrega/Retirada: ', COALESCE(v_delivery_method.name, v_effective_fulfillment_type), E'\n',
    'Pagamento: ', COALESCE(v_payment_method.name, 'A combinar'), E'\n',
    CASE
      WHEN p_table_code IS NOT NULL THEN concat('Mesa/comanda: ', p_table_code, E'\n')
      ELSE ''
    END,
    E'\n',
    'Cliente: ', COALESCE(v_customer_name, 'Não informado'), E'\n',
    'Telefone: ', v_customer_phone, E'\n\n',
    'Por favor, confirme meu pedido.'
  );

  IF length(v_whatsapp_digits) >= 10 THEN
    v_whatsapp_url := concat(
      'https://wa.me/',
      CASE
        WHEN v_whatsapp_digits LIKE '55%' THEN v_whatsapp_digits
        ELSE concat('55', v_whatsapp_digits)
      END,
      '?text=',
      replace(replace(replace(v_whatsapp_message, E'\n', '%0A'), ' ', '%20'), '#', '%23')
    );
  ELSE
    v_whatsapp_url := NULL;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'order', jsonb_build_object(
      'id', v_order_id,
      'order_code', v_order_code,
      'subtotal', v_subtotal,
      'delivery_fee', v_delivery_fee,
      'total', v_total,
      'status', 'reserved',
      'sales_channel', p_sales_channel,
      'fulfillment_type', v_effective_fulfillment_type,
      'delivery_method_code', v_delivery_method.code,
      'delivery_method_name', v_delivery_method.name,
      'payment_method', v_payment_method_enum::text,
      'payment_method_code', v_payment_method.code,
      'payment_method_name', v_payment_method.name,
      'expires_at', v_expires_at,
      'reservation_minutes', v_reservation_minutes,
      'public_order_token', v_public_order_token
    ),
    'whatsapp', jsonb_build_object(
      'digits', v_whatsapp_digits,
      'message', v_whatsapp_message,
      'url', v_whatsapp_url
    )
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'unexpected_error',
      'message', SQLERRM
    );
END;
$_$;


ALTER FUNCTION "public"."create_public_order_by_slug"("p_slug" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_fulfillment_type" "text", "p_sales_channel" "text", "p_items" "jsonb", "p_delivery_address" "jsonb", "p_table_code" "text", "p_notes" "text", "p_payment_method_code" "text", "p_delivery_method_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_purchase_document_draft_batch"("p_supplier_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("purchase_document_id" "uuid", "supplier_id" "uuid", "supplier_name" "text", "status" "text", "items_count" integer, "total_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier public.suppliers%ROWTYPE;
  v_document_id uuid;
  v_document_code text;
  v_item record;
  v_items_count integer := 0;
  v_total_amount numeric := 0;
  v_product_store_id uuid;
  v_quantity numeric;
  v_unit_cost numeric;
  v_notes text;
BEGIN
  IF p_supplier_id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não informado.';
  END IF;

  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0
  THEN
    RAISE EXCEPTION 'Informe ao menos um item para criar o rascunho de compra.';
  END IF;

  SELECT *
  INTO v_supplier
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fornecedor não encontrado.';
  END IF;

  IF NOT public.user_can_purchase_action(v_supplier.store_id, 'create') THEN
    RAISE EXCEPTION 'Sem permissão para criar compras nesta loja.';
  END IF;

  IF COALESCE(v_supplier.active, true) = false THEN
    RAISE EXCEPTION 'Fornecedor inativo. Não é possível criar compra.';
  END IF;

  IF COALESCE(v_supplier.blocked, false) = true THEN
    RAISE EXCEPTION 'Fornecedor bloqueado. Revise o cadastro antes de criar compra.';
  END IF;

  IF lower(COALESCE(v_supplier.homologation_status, 'not_evaluated')) IN (
    'rejected',
    'reproved',
    'reprovado',
    'blocked',
    'bloqueado'
  ) THEN
    RAISE EXCEPTION 'Fornecedor reprovado ou bloqueado na homologação. Revise o cadastro antes de criar compra.';
  END IF;

  v_notes := COALESCE(
    NULLIF(trim(COALESCE(p_notes, '')), ''),
    'Rascunho manual de compra.'
  );

  v_document_code := public.generate_purchase_document_code(v_supplier.store_id);

  INSERT INTO public.purchase_documents (
    store_id,
    supplier_id,
    document_code,
    invoice_number,
    issue_date,
    total_amount,
    notes,
    status
  )
  VALUES (
    v_supplier.store_id,
    v_supplier.id,
    v_document_code,
    NULL,
    CURRENT_DATE,
    0,
    v_notes,
    'draft'
  )
  RETURNING id
  INTO v_document_id;

  FOR v_item IN
    SELECT *
    FROM jsonb_to_recordset(p_items) AS x(
      product_id uuid,
      quantity numeric,
      unit_cost numeric,
      notes text
    )
  LOOP
    IF v_item.product_id IS NULL THEN
      RAISE EXCEPTION 'Item sem produto informado.';
    END IF;

    v_quantity := COALESCE(v_item.quantity, 0);
    v_unit_cost := COALESCE(v_item.unit_cost, 0);

    IF v_quantity <= 0 THEN
      RAISE EXCEPTION 'Produto % possui quantidade inválida.', v_item.product_id;
    END IF;

    IF v_unit_cost < 0 THEN
      RAISE EXCEPTION 'Produto % possui custo inválido.', v_item.product_id;
    END IF;

    SELECT p.store_id
    INTO v_product_store_id
    FROM public.products p
    WHERE p.id = v_item.product_id
      AND p.store_id = v_supplier.store_id
      AND COALESCE(p.active, true) = true;

    IF v_product_store_id IS NULL THEN
      RAISE EXCEPTION 'Produto % não encontrado, inativo ou fora da loja do fornecedor.', v_item.product_id;
    END IF;

    INSERT INTO public.purchase_document_items (
      purchase_document_id,
      product_id,
      quantity,
      unit_cost,
      store_id
    )
    VALUES (
      v_document_id,
      v_item.product_id,
      v_quantity,
      v_unit_cost,
      v_supplier.store_id
    );

    v_items_count := v_items_count + 1;
    v_total_amount := v_total_amount + (v_quantity * v_unit_cost);
  END LOOP;

  IF v_items_count = 0 THEN
    RAISE EXCEPTION 'Nenhum item válido foi informado.';
  END IF;

  UPDATE public.purchase_documents pd
  SET total_amount = v_total_amount
  WHERE pd.id = v_document_id;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_supplier.store_id,
    p_entity_type := 'purchase_document',
    p_entity_id := v_document_id,
    p_event_type := 'purchase_document_created',
    p_title := 'Compra criada',
    p_description := 'Rascunho manual de compra criado para o fornecedor ' || v_supplier.name || '.',
    p_severity := 'info',
    p_status := 'done',
    p_channel := 'manual',
    p_source := 'create_purchase_document_draft_batch',
    p_source_id := v_document_id,
    p_new_data := jsonb_build_object(
      'purchase_document_id', v_document_id,
      'document_code', v_document_code,
      'supplier_id', v_supplier.id,
      'supplier_name', v_supplier.name,
      'status', 'draft',
      'items_count', v_items_count,
      'total_amount', v_total_amount,
      'notes', v_notes
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-B',
      'origin', 'manual_purchase_document_draft',
      'document_code', v_document_code,
      'supplier_name', v_supplier.name
    ),
    p_related_supplier_id := v_supplier.id,
    p_related_purchase_document_id := v_document_id
  );

  RETURN QUERY
  SELECT
    pd.id AS purchase_document_id,
    s.id AS supplier_id,
    s.name AS supplier_name,
    pd.status,
    v_items_count AS items_count,
    pd.total_amount
  FROM public.purchase_documents pd
  JOIN public.suppliers s
    ON s.id = pd.supplier_id
   AND s.store_id = pd.store_id
  WHERE pd.id = v_document_id;
END;
$$;


ALTER FUNCTION "public"."create_purchase_document_draft_batch"("p_supplier_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_purchase_document_draft_batch"("p_supplier_id" "uuid", "p_items" "jsonb", "p_notes" "text") IS 'FASE 6.5C: cria rascunho de compra apenas para fornecedores elegíveis: ativos, não bloqueados e não reprovados.';



CREATE OR REPLACE FUNCTION "public"."create_purchase_quotation"("p_supplier_id" "uuid", "p_items" "jsonb", "p_message_subject" "text" DEFAULT NULL::"text", "p_message_body" "text" DEFAULT NULL::"text", "p_sent_channel" "text" DEFAULT NULL::"text", "p_responsible_name" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("quotation_id" "uuid", "quotation_code" "text", "status" "text", "items_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier record;
  v_store_id uuid;
  v_quotation_id uuid;
  v_quotation_code text;
  v_item jsonb;
  v_items_count integer := 0;
BEGIN
  IF p_supplier_id IS NULL THEN
    RAISE EXCEPTION 'Informe o fornecedor da cotação.';
  END IF;

  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0
  THEN
    RAISE EXCEPTION 'Informe ao menos um item para a cotação.';
  END IF;

  SELECT
    s.id,
    s.store_id,
    s.name,
    COALESCE(s.active, false) AS active,
    COALESCE(s.blocked, false) AS blocked,
    COALESCE(s.homologation_status, 'not_evaluated') AS homologation_status
  INTO v_supplier
  FROM public.suppliers s
  WHERE s.id = p_supplier_id;

  IF v_supplier.id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado.';
  END IF;

  v_store_id := v_supplier.store_id;

  IF NOT public.user_can_purchase_action(v_store_id, 'create') THEN
    RAISE EXCEPTION 'Sem permissão para criar cotações nesta loja.';
  END IF;

  IF v_supplier.active IS NOT TRUE THEN
    RAISE EXCEPTION 'Fornecedor inativo não pode receber cotação.';
  END IF;

  IF v_supplier.blocked IS TRUE THEN
    RAISE EXCEPTION 'Fornecedor bloqueado não pode receber cotação.';
  END IF;

  IF v_supplier.homologation_status <> 'approved' THEN
    RAISE EXCEPTION 'Fornecedor precisa estar aprovado para receber cotação.';
  END IF;

  v_quotation_code :=
    'COT-' ||
    to_char(timezone('America/Sao_Paulo', now()), 'YYYYMMDD-HH24MISS') ||
    '-' ||
    lpad((floor(random() * 1000))::int::text, 3, '0');

  INSERT INTO public.purchase_quotations (
    store_id,
    supplier_id,
    quotation_code,
    status,
    sent_channel,
    responsible_name,
    message_subject,
    message_body,
    notes,
    metadata,
    created_by
  )
  VALUES (
    v_store_id,
    p_supplier_id,
    v_quotation_code,
    'draft',
    p_sent_channel,
    p_responsible_name,
    p_message_subject,
    p_message_body,
    p_notes,
    jsonb_build_object(
      'created_from', 'purchase_suggestions',
      'supplier_name', v_supplier.name
    ),
    auth.uid()
  )
  RETURNING id INTO v_quotation_id;

  FOR v_item IN
    SELECT value
    FROM jsonb_array_elements(p_items)
  LOOP
    IF (v_item->>'product_id') IS NULL THEN
      RAISE EXCEPTION 'Item da cotação sem produto.';
    END IF;

    IF COALESCE((v_item->>'quantity')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'Quantidade inválida em item da cotação.';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.products p
      WHERE p.id = (v_item->>'product_id')::uuid
        AND p.store_id = v_store_id
    ) THEN
      RAISE EXCEPTION 'Produto da cotação não pertence à loja.';
    END IF;

    INSERT INTO public.purchase_quotation_items (
      quotation_id,
      store_id,
      product_id,
      requested_qty,
      reference_unit_cost,
      quoted_unit_cost,
      approved_qty,
      notes
    )
    VALUES (
      v_quotation_id,
      v_store_id,
      (v_item->>'product_id')::uuid,
      (v_item->>'quantity')::numeric,
      NULLIF(v_item->>'unit_cost', '')::numeric,
      NULL,
      (v_item->>'quantity')::numeric,
      NULLIF(v_item->>'notes', '')
    );

    v_items_count := v_items_count + 1;
  END LOOP;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_store_id,
    p_entity_type := 'purchase_quotation',
    p_entity_id := v_quotation_id,
    p_event_type := 'quotation_created',
    p_title := 'Cotação criada',
    p_description := 'Cotação ' || v_quotation_code || ' criada para o fornecedor ' || v_supplier.name || '.',
    p_severity := 'info',
    p_status := 'done',
    p_responsible_name := NULLIF(p_responsible_name, ''),
    p_channel := COALESCE(NULLIF(p_sent_channel, ''), 'system'),
    p_source := 'create_purchase_quotation',
    p_source_id := v_quotation_id,
    p_new_data := jsonb_build_object(
      'quotation_id', v_quotation_id,
      'quotation_code', v_quotation_code,
      'status', 'draft',
      'supplier_id', p_supplier_id,
      'supplier_name', v_supplier.name,
      'items_count', v_items_count,
      'sent_channel', p_sent_channel,
      'responsible_name', p_responsible_name
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-B-FIX',
      'items_count', v_items_count
    ),
    p_related_supplier_id := p_supplier_id,
    p_related_purchase_quotation_id := v_quotation_id
  );

  IF NULLIF(p_sent_channel, '') IS NOT NULL
     AND p_sent_channel NOT IN ('manual', 'system') THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_store_id,
      p_entity_type := 'purchase_quotation',
      p_entity_id := v_quotation_id,
      p_event_type := 'quotation_channel_defined',
      p_title := 'Canal da cotação definido',
      p_description := 'Canal definido para a cotação ' || v_quotation_code || ': ' || p_sent_channel || '.',
      p_severity := 'info',
      p_status := 'done',
      p_responsible_name := NULLIF(p_responsible_name, ''),
      p_channel := p_sent_channel,
      p_source := 'create_purchase_quotation',
      p_source_id := v_quotation_id,
      p_new_data := jsonb_build_object(
        'sent_channel', p_sent_channel,
        'quotation_code', v_quotation_code
      ),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-B-FIX',
        'reason', 'channel_defined_on_creation'
      ),
      p_related_supplier_id := p_supplier_id,
      p_related_purchase_quotation_id := v_quotation_id
    );
  END IF;

  RETURN QUERY
  SELECT
    v_quotation_id,
    v_quotation_code,
    'draft'::text,
    v_items_count;
END;
$$;


ALTER FUNCTION "public"."create_purchase_quotation"("p_supplier_id" "uuid", "p_items" "jsonb", "p_message_subject" "text", "p_message_body" "text", "p_sent_channel" "text", "p_responsible_name" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_purchase_quotation"("p_supplier_id" "uuid", "p_items" "jsonb", "p_message_subject" "text", "p_message_body" "text", "p_sent_channel" "text", "p_responsible_name" "text", "p_notes" "text") IS 'Cria uma cotação de compra persistida a partir de itens selecionados nas sugestões ou fluxo manual.';



CREATE OR REPLACE FUNCTION "public"."create_stock_transfer"("p_store_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_requested_by" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."stock_transfers"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer public.stock_transfers;
begin
    if p_store_id is null then
        raise exception 'p_store_id é obrigatório' using errcode = '23514';
    end if;

    if p_source_location_id is null or p_destination_location_id is null then
        raise exception 'Origem e destino são obrigatórios' using errcode = '23514';
    end if;

    if p_source_location_id = p_destination_location_id then
        raise exception 'Origem e destino não podem ser iguais' using errcode = '23514';
    end if;

    if not public.stock_location_belongs_to_store(p_source_location_id, p_store_id) then
        raise exception 'Local de origem não pertence à store' using errcode = '23514';
    end if;

    if not public.stock_location_belongs_to_store(p_destination_location_id, p_store_id) then
        raise exception 'Local de destino não pertence à store' using errcode = '23514';
    end if;

    insert into public.stock_transfers (
        store_id,
        source_store_id,
        destination_store_id,
        source_location_id,
        destination_location_id,
        status,
        transfer_code,
        requested_by,
        requested_at,
        notes,
        metadata
    )
    values (
        p_store_id,
        p_store_id,
        p_store_id,
        p_source_location_id,
        p_destination_location_id,
        'draft',
        public.generate_stock_transfer_code(p_store_id),
        p_requested_by,
        now(),
        p_notes,
        coalesce(p_metadata, '{}'::jsonb)
    )
    returning * into v_transfer;

    return v_transfer;
end;
$$;


ALTER FUNCTION "public"."create_stock_transfer"("p_store_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_notes" "text", "p_requested_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_stock_transfer"("p_store_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_notes" "text", "p_requested_by" "uuid", "p_metadata" "jsonb") IS 'Cria cabeçalho de transferência interna entre locais da mesma store.';



CREATE OR REPLACE FUNCTION "public"."create_stock_transfer_draft_batch"("p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("transfer_id" "uuid", "transfer_code" "text", "status" "text", "items_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_destination_store_id uuid;
  v_transfer_id uuid;
  v_transfer_code text;
  v_items_count integer;
BEGIN
  IF p_source_location_id IS NULL
    OR p_destination_location_id IS NULL
    OR p_source_location_id = p_destination_location_id
  THEN
    RAISE EXCEPTION 'Origem e destino inválidos.';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos um item para a transferência.';
  END IF;

  SELECT sl.store_id
  INTO v_store_id
  FROM public.stock_locations sl
  WHERE sl.id = p_source_location_id
    AND sl.active = true
  LIMIT 1;

  SELECT sl.store_id
  INTO v_destination_store_id
  FROM public.stock_locations sl
  WHERE sl.id = p_destination_location_id
    AND sl.active = true
  LIMIT 1;

  IF v_store_id IS NULL OR v_destination_store_id IS NULL THEN
    RAISE EXCEPTION 'Origem ou destino inválido/inativo.';
  END IF;

  IF v_store_id <> v_destination_store_id THEN
    RAISE EXCEPTION 'Origem e destino precisam pertencer à mesma loja.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  -- Validação dos itens.
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_items) AS item(product_id uuid, quantity numeric)
    LEFT JOIN public.products p
      ON p.id = item.product_id
     AND p.store_id = v_store_id
    WHERE p.id IS NULL
       OR COALESCE(item.quantity, 0) <= 0
  ) THEN
    RAISE EXCEPTION 'Há item inválido ou produto fora da loja.';
  END IF;

  v_transfer_code :=
    'TRF-' ||
    to_char(timezone('America/Sao_Paulo', now()), 'YYYYMMDD-HH24MISS') ||
    '-' ||
    lpad(floor(random() * 1000)::int::text, 3, '0');

  INSERT INTO public.stock_transfers (
    store_id,
    source_store_id,
    destination_store_id,
    source_location_id,
    destination_location_id,
    status,
    transfer_code,
    requested_by,
    requested_at,
    notes,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_store_id,
    v_store_id,
    v_store_id,
    p_source_location_id,
    p_destination_location_id,
    'draft'::public.stock_transfer_status,
    v_transfer_code,
    auth.uid(),
    now(),
    COALESCE(
      p_notes,
      'Rascunho em lote criado a partir de sugestões gerenciais de transferência.'
    ),
    jsonb_build_object(
      'origin', 'inventory_management_batch_suggestion',
      'source_location_id', p_source_location_id,
      'destination_location_id', p_destination_location_id,
      'items', p_items
    ),
    now(),
    now()
  )
  RETURNING
    stock_transfers.id,
    stock_transfers.transfer_code
  INTO
    v_transfer_id,
    v_transfer_code;

  INSERT INTO public.stock_transfer_items (
    transfer_id,
    store_id,
    product_id,
    variant_id,
    requested_qty,
    shipped_qty,
    received_qty,
    divergence_qty,
    notes,
    metadata,
    created_at,
    updated_at
  )
  SELECT
    v_transfer_id,
    v_store_id,
    item.product_id,
    NULL,
    item.quantity,
    0,
    0,
    0,
    'Item adicionado a partir de sugestão gerencial em lote.',
    jsonb_build_object(
      'origin', 'inventory_management_batch_suggestion',
      'suggested_qty', item.quantity
    ),
    now(),
    now()
  FROM jsonb_to_recordset(p_items) AS item(product_id uuid, quantity numeric);

  SELECT COUNT(*)
  INTO v_items_count
  FROM public.stock_transfer_items sti
  WHERE sti.transfer_id = v_transfer_id;

  RETURN QUERY
  SELECT
    v_transfer_id AS transfer_id,
    v_transfer_code AS transfer_code,
    'draft'::text AS status,
    v_items_count AS items_count;
END;
$$;


ALTER FUNCTION "public"."create_stock_transfer_draft_batch"("p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_stock_transfer_draft_batch"("p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_items" "jsonb", "p_notes" "text") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC gerencial para criação de rascunho de transferência em lote a partir de sugestões.';



CREATE OR REPLACE FUNCTION "public"."create_stock_transfer_draft_from_suggestion"("p_product_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_quantity" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("transfer_id" "uuid", "transfer_code" "text", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_product_name text;
  v_source_store_id uuid;
  v_destination_store_id uuid;
  v_transfer_id uuid;
  v_transfer_code text;
BEGIN
  IF p_product_id IS NULL
    OR p_source_location_id IS NULL
    OR p_destination_location_id IS NULL
    OR COALESCE(p_quantity, 0) <= 0
  THEN
    RAISE EXCEPTION 'Parâmetros inválidos para criação da transferência.';
  END IF;

  IF p_source_location_id = p_destination_location_id THEN
    RAISE EXCEPTION 'Origem e destino não podem ser o mesmo local.';
  END IF;

  SELECT
    p.store_id,
    p.name
  INTO
    v_store_id,
    v_product_name
  FROM public.products p
  WHERE p.id = p_product_id
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja do produto informado.';
  END IF;

  SELECT sl.store_id
  INTO v_source_store_id
  FROM public.stock_locations sl
  WHERE sl.id = p_source_location_id
    AND sl.active = true
  LIMIT 1;

  SELECT sl.store_id
  INTO v_destination_store_id
  FROM public.stock_locations sl
  WHERE sl.id = p_destination_location_id
    AND sl.active = true
  LIMIT 1;

  IF v_source_store_id IS NULL OR v_destination_store_id IS NULL THEN
    RAISE EXCEPTION 'Origem ou destino inválido/inativo.';
  END IF;

  IF v_source_store_id <> v_store_id OR v_destination_store_id <> v_store_id THEN
    RAISE EXCEPTION 'Origem, destino e produto precisam pertencer à mesma loja.';
  END IF;

  v_transfer_code :=
    'TRF-' ||
    to_char(timezone('America/Sao_Paulo', now()), 'YYYYMMDD-HH24MISS') ||
    '-' ||
    lpad(floor(random() * 1000)::int::text, 3, '0');

  INSERT INTO public.stock_transfers (
    store_id,
    source_store_id,
    destination_store_id,
    source_location_id,
    destination_location_id,
    status,
    transfer_code,
    requested_by,
    requested_at,
    notes,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_store_id,
    v_store_id,
    v_store_id,
    p_source_location_id,
    p_destination_location_id,
    'draft'::public.stock_transfer_status,
    v_transfer_code,
    auth.uid(),
    now(),
    COALESCE(
      p_notes,
      'Rascunho criado a partir de sugestão gerencial de transferência.'
    ),
    jsonb_build_object(
      'origin', 'inventory_management_suggestion',
      'product_id', p_product_id,
      'product_name', v_product_name,
      'source_location_id', p_source_location_id,
      'destination_location_id', p_destination_location_id,
      'suggested_qty', p_quantity
    ),
    now(),
    now()
  )
  RETURNING
    stock_transfers.id,
    stock_transfers.transfer_code
  INTO
    v_transfer_id,
    v_transfer_code;

  INSERT INTO public.stock_transfer_items (
    transfer_id,
    store_id,
    product_id,
    variant_id,
    requested_qty,
    shipped_qty,
    received_qty,
    divergence_qty,
    notes,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_transfer_id,
    v_store_id,
    p_product_id,
    NULL,
    p_quantity,
    0,
    0,
    0,
    'Item adicionado a partir de sugestão gerencial.',
    jsonb_build_object(
      'origin', 'inventory_management_suggestion',
      'suggested_qty', p_quantity
    ),
    now(),
    now()
  );

  RETURN QUERY
  SELECT
    v_transfer_id AS transfer_id,
    v_transfer_code AS transfer_code,
    'draft'::text AS status;
END;
$$;


ALTER FUNCTION "public"."create_stock_transfer_draft_from_suggestion"("p_product_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_quantity" numeric, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_stock_transfer_draft_from_suggestion"("p_product_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid", "p_quantity" numeric, "p_notes" "text") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC gerencial para criar rascunho de transferência a partir de sugestão individual.';



CREATE OR REPLACE FUNCTION "public"."create_store_custom_role"("p_store_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_base_role" "text" DEFAULT 'staff'::"text", "p_permissions" "jsonb" DEFAULT NULL::"jsonb", "p_sensitive_actions" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("id" "uuid", "store_id" "uuid", "name" "text", "description" "text", "base_role" "text", "active" boolean, "permissions" "jsonb", "sensitive_actions" "jsonb", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_actor_name text;
  v_actor_email text;
  v_permissions jsonb := '{}'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'Nome da função não informado.';
  end if;

  if p_base_role not in (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) then
    raise exception 'Papel base inválido: %', p_base_role;
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.user_has_store_permission(p_store_id, 'security.custom_roles.manage')
  ) then
    raise exception 'Sem permissão para criar funções personalizadas.';
  end if;

  /*
    Se o front enviar p_permissions, usamos o enviado.
    Se vier null, copiamos o template atual do papel base.
  */
  if p_permissions is not null then
    v_permissions := coalesce(p_permissions, '{}'::jsonb);
  else
    select coalesce(
      jsonb_object_agg(t.permission_code, t.allowed),
      '{}'::jsonb
    )
    into v_permissions
    from public.store_role_permission_templates t
    where t.store_id = p_store_id
      and t.role = p_base_role;
  end if;

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_actor_name,
    v_actor_email
  from public.get_user_display_identity(auth.uid()) as identity_row;

  return query
  insert into public.store_custom_roles (
    store_id,
    name,
    description,
    base_role,
    active,
    permissions,
    sensitive_actions,
    created_by,
    created_at,
    updated_at
  )
  values (
    p_store_id,
    trim(p_name),
    nullif(trim(coalesce(p_description, '')), ''),
    p_base_role,
    true,
    v_permissions,
    coalesce(p_sensitive_actions, '{}'::jsonb),
    auth.uid(),
    now(),
    now()
  )
  returning
    store_custom_roles.id,
    store_custom_roles.store_id,
    store_custom_roles.name,
    store_custom_roles.description,
    store_custom_roles.base_role,
    store_custom_roles.active,
    store_custom_roles.permissions,
    store_custom_roles.sensitive_actions,
    store_custom_roles.created_by,
    store_custom_roles.created_at,
    store_custom_roles.updated_at;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  values (
    p_store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_custom_role_created',
    jsonb_build_object(
      'name', trim(p_name),
      'base_role', p_base_role,
      'permissions_source',
        case when p_permissions is null then 'base_role_template' else 'manual_payload' end,
      'permissions', v_permissions,
      'sensitive_actions', coalesce(p_sensitive_actions, '{}'::jsonb)
    ),
    'success',
    now()
  );
end;
$$;


ALTER FUNCTION "public"."create_store_custom_role"("p_store_id" "uuid", "p_name" "text", "p_description" "text", "p_base_role" "text", "p_permissions" "jsonb", "p_sensitive_actions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_store_member_invite"("p_store_id" "uuid", "p_email" "text", "p_role" "text" DEFAULT 'staff'::"text", "p_permissions" "jsonb" DEFAULT '{}'::"jsonb", "p_sensitive_actions" "jsonb" DEFAULT '{}'::"jsonb", "p_expires_in_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_email text;
  v_actor_email text;
  v_existing_user_id uuid;
  v_existing_member_id uuid;
  v_invite_id uuid;
  v_expires_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_email IS NULL OR btrim(p_email) = '' THEN
    RAISE EXCEPTION 'E-mail do usuário é obrigatório.';
  END IF;

  v_email := lower(btrim(p_email));

  IF p_role NOT IN (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'viewer',
    'staff'
  ) THEN
    RAISE EXCEPTION 'Papel inválido para convite: %', p_role;
  END IF;

  IF p_expires_in_days IS NULL OR p_expires_in_days < 1 OR p_expires_in_days > 30 THEN
    RAISE EXCEPTION 'Validade do convite deve estar entre 1 e 30 dias.';
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.manage')
  ) THEN
    RAISE EXCEPTION 'Você não tem permissão para convidar usuários.';
  END IF;

  SELECT email::text
  INTO v_actor_email
  FROM auth.users
  WHERE id = auth.uid();

  SELECT au.id
  INTO v_existing_user_id
  FROM auth.users au
  WHERE lower(au.email::text) = v_email
  LIMIT 1;

  IF v_existing_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode convidar seu próprio e-mail.';
  END IF;

  IF v_existing_user_id IS NOT NULL THEN
    SELECT sm.id
    INTO v_existing_member_id
    FROM public.store_members sm
    WHERE sm.store_id = p_store_id
      AND sm.user_id = v_existing_user_id
      AND sm.status = 'active'
    LIMIT 1;

    IF v_existing_member_id IS NOT NULL THEN
      RAISE EXCEPTION 'Este usuário já é membro ativo desta loja.';
    END IF;
  END IF;

  v_expires_at := now() + make_interval(days => p_expires_in_days);

  INSERT INTO public.store_member_invites (
    store_id,
    email,
    role,
    status,
    invited_by,
    invited_by_email,
    invited_at,
    expires_at,
    permissions,
    sensitive_actions,
    metadata
  )
  VALUES (
    p_store_id,
    v_email,
    p_role,
    'pending',
    auth.uid(),
    v_actor_email,
    now(),
    v_expires_at,
    COALESCE(p_permissions, '{}'::jsonb),
    COALESCE(p_sensitive_actions, '{}'::jsonb),
    jsonb_build_object(
      'target_user_exists_in_auth', v_existing_user_id IS NOT NULL,
      'target_user_id', v_existing_user_id
    )
  )
  ON CONFLICT (store_id, normalized_email)
  WHERE status = 'pending'
  DO UPDATE SET
    role = EXCLUDED.role,
    invited_by = EXCLUDED.invited_by,
    invited_by_email = EXCLUDED.invited_by_email,
    invited_at = now(),
    expires_at = EXCLUDED.expires_at,
    permissions = EXCLUDED.permissions,
    sensitive_actions = EXCLUDED.sensitive_actions,
    metadata = EXCLUDED.metadata,
    updated_at = now()
  RETURNING id
  INTO v_invite_id;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    p_store_id,
    auth.uid(),
    v_actor_email,
    'store_member_invite_created',
    jsonb_build_object(
      'invite_id', v_invite_id,
      'target_email', v_email,
      'target_user_exists_in_auth', v_existing_user_id IS NOT NULL,
      'target_user_id', v_existing_user_id,
      'role', p_role,
      'expires_at', v_expires_at
    ),
    'success',
    now()
  );

  RETURN jsonb_build_object(
    'mode', 'pending_invite',
    'invite_id', v_invite_id,
    'store_id', p_store_id,
    'email', v_email,
    'role', p_role,
    'status', 'pending',
    'expires_at', v_expires_at,
    'target_user_exists_in_auth', v_existing_user_id IS NOT NULL
  );
END;
$$;


ALTER FUNCTION "public"."create_store_member_invite"("p_store_id" "uuid", "p_email" "text", "p_role" "text", "p_permissions" "jsonb", "p_sensitive_actions" "jsonb", "p_expires_in_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_store_member_occurrence_v2"("p_member_id" "uuid", "p_occurrence_type" "text", "p_severity" "text" DEFAULT 'info'::"text", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_visible_to_member" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("occurrence_id" "uuid", "member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "occurrence_type" "text", "severity" "text", "title" "text", "description" "text", "occurred_at" timestamp with time zone, "visible_to_member" boolean, "member_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;

  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;

  v_old_status text;
  v_old_role text;
  v_old_custom_role_id uuid;

  v_new_role text;
  v_new_custom_role_id uuid;
  v_new_custom_role_base_role text;
  v_clear_individual_overrides boolean := false;

  v_final_title text;
  v_final_description text;
  v_effective_occurred_at timestamp with time zone;
  v_occurrence_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Membro não informado.';
  END IF;

  IF p_occurrence_type IS NULL OR length(trim(p_occurrence_type)) = 0 THEN
    RAISE EXCEPTION 'Tipo de ocorrência não informado.';
  END IF;

  IF p_occurrence_type NOT IN (
    'admission',
    'suspension',
    'note',
    'warning',
    'praise',
    'training',
    'incident',
    'role_change',
    'absence',
    'exit',
    'other'
  ) THEN
    RAISE EXCEPTION 'Tipo de ocorrência inválido: %', p_occurrence_type;
  END IF;

  IF p_severity NOT IN ('info', 'low', 'medium', 'high', 'critical') THEN
    RAISE EXCEPTION 'Severidade inválida: %', p_severity;
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members
  WHERE id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  IF NOT (
    public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para registrar ocorrência de usuário.';
  END IF;

  v_final_description := COALESCE(NULLIF(trim(p_description), ''), '');

  IF p_occurrence_type IN ('admission', 'suspension', 'exit')
     AND length(v_final_description) = 0 THEN
    RAISE EXCEPTION 'Informe o motivo/descrição para esta ocorrência.';
  END IF;

  IF p_occurrence_type IN ('suspension', 'exit') THEN
    IF v_member.user_id = auth.uid() THEN
      RAISE EXCEPTION 'Você não pode suspender ou desligar seu próprio usuário por esta rotina.';
    END IF;

    IF v_member.role = 'owner' THEN
      RAISE EXCEPTION 'Não é permitido suspender ou desligar o proprietário principal por esta rotina.';
    END IF;
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  v_old_status := v_member.status;
  v_old_role := v_member.role;
  v_old_custom_role_id := v_member.custom_role_id;

  v_effective_occurred_at := COALESCE(p_occurred_at, now());

  v_final_title := COALESCE(
    NULLIF(trim(p_title), ''),
    CASE
      WHEN p_occurrence_type = 'admission' THEN 'Admissão / início de acesso'
      WHEN p_occurrence_type = 'suspension' THEN 'Suspensão temporária de acesso'
      WHEN p_occurrence_type = 'exit' THEN 'Desligamento do usuário'
      WHEN p_occurrence_type = 'role_change' THEN 'Alteração de função'
      WHEN p_occurrence_type = 'absence' THEN 'Ausência'
      WHEN p_occurrence_type = 'incident' THEN 'Incidente'
      WHEN p_occurrence_type = 'training' THEN 'Treinamento'
      WHEN p_occurrence_type = 'warning' THEN 'Advertência'
      WHEN p_occurrence_type = 'praise' THEN 'Elogio'
      WHEN p_occurrence_type = 'note' THEN 'Observação'
      ELSE 'Ocorrência do usuário'
    END
  );

  IF p_occurrence_type IN ('admission', 'role_change') THEN
    v_new_role := NULLIF(trim(COALESCE(p_metadata->>'new_role', '')), '');

    IF v_new_role IS NOT NULL
       AND v_new_role NOT IN (
        'admin',
        'manager',
        'stock_operator',
        'cashier',
        'sales',
        'staff',
        'viewer'
       ) THEN
      RAISE EXCEPTION 'Papel informado é inválido: %', v_new_role;
    END IF;

    IF p_metadata ? 'new_custom_role_id'
       AND NULLIF(trim(COALESCE(p_metadata->>'new_custom_role_id', '')), '') IS NOT NULL THEN
      v_new_custom_role_id := (p_metadata->>'new_custom_role_id')::uuid;

      SELECT scr.base_role
      INTO v_new_custom_role_base_role
      FROM public.store_custom_roles scr
      WHERE scr.id = v_new_custom_role_id
        AND scr.store_id = v_member.store_id
        AND scr.active = true;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Função personalizada não encontrada ou inativa.';
      END IF;

      IF COALESCE(v_new_role, v_member.role) <> v_new_custom_role_base_role THEN
        RAISE EXCEPTION 'A função personalizada selecionada não é compatível com o papel informado.';
      END IF;
    ELSE
      v_new_custom_role_id := NULL;
    END IF;

    v_clear_individual_overrides :=
      COALESCE((p_metadata->>'clear_individual_overrides')::boolean, false);
  END IF;

  INSERT INTO public.store_member_occurrences (
    store_id,
    member_id,
    user_id,
    occurrence_type,
    severity,
    title,
    description,
    occurred_at,
    visible_to_member,
    created_by,
    created_by_email,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_member.store_id,
    p_member_id,
    v_member.user_id,
    p_occurrence_type,
    p_severity,
    v_final_title,
    v_final_description,
    v_effective_occurred_at,
    COALESCE(p_visible_to_member, false),
    auth.uid(),
    v_actor_email,
    COALESCE(p_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'target_user_name', v_target_name,
        'target_user_email', v_target_email,
        'old_status', v_old_status,
        'old_role', v_old_role,
        'old_custom_role_id', v_old_custom_role_id,
        'effective_occurred_at', v_effective_occurred_at,
        'origin', 'create_store_member_occurrence_v2'
      ),
    now(),
    now()
  )
  RETURNING id
  INTO v_occurrence_id;

  IF p_occurrence_type = 'admission' THEN
    UPDATE public.store_members sm
    SET
      status = 'active',
      role = COALESCE(v_new_role, sm.role),
      custom_role_id = CASE
        WHEN p_metadata ? 'new_custom_role_id' THEN v_new_custom_role_id
        ELSE sm.custom_role_id
      END,
      permissions = CASE
        WHEN v_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.permissions, '{}'::jsonb)
      END,
      sensitive_actions = CASE
        WHEN v_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.sensitive_actions, '{}'::jsonb)
      END,
      started_at = v_effective_occurred_at,
      ended_at = NULL,
      exit_reason = NULL,
      status_reason = v_final_description,
      updated_at = now()
    WHERE sm.id = p_member_id;

  ELSIF p_occurrence_type = 'suspension' THEN
    UPDATE public.store_members sm
    SET
      status = 'suspended',
      status_reason = v_final_description,
      updated_at = now()
    WHERE sm.id = p_member_id;

  ELSIF p_occurrence_type = 'exit' THEN
    UPDATE public.store_members sm
    SET
      status = 'inactive',
      ended_at = v_effective_occurred_at,
      exit_reason = v_final_description,
      status_reason = v_final_description,
      updated_at = now()
    WHERE sm.id = p_member_id;

  ELSIF p_occurrence_type = 'role_change' THEN
    UPDATE public.store_members sm
    SET
      role = COALESCE(v_new_role, sm.role),
      custom_role_id = CASE
        WHEN p_metadata ? 'new_custom_role_id' THEN v_new_custom_role_id
        ELSE sm.custom_role_id
      END,
      permissions = CASE
        WHEN v_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.permissions, '{}'::jsonb)
      END,
      sensitive_actions = CASE
        WHEN v_clear_individual_overrides THEN '{}'::jsonb
        ELSE COALESCE(sm.sensitive_actions, '{}'::jsonb)
      END,
      status_reason = v_final_description,
      updated_at = now()
    WHERE sm.id = p_member_id;
  END IF;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    CASE
      WHEN p_occurrence_type = 'admission' THEN 'store_member_admission_registered'
      WHEN p_occurrence_type = 'suspension' THEN 'store_member_suspension_registered'
      WHEN p_occurrence_type = 'exit' THEN 'store_member_exit_registered'
      WHEN p_occurrence_type = 'role_change' THEN 'store_member_role_changed_by_occurrence'
      ELSE 'store_member_occurrence_created'
    END,
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'old_status', v_old_status,
      'new_status',
        CASE
          WHEN p_occurrence_type = 'admission' THEN 'active'
          WHEN p_occurrence_type = 'suspension' THEN 'suspended'
          WHEN p_occurrence_type = 'exit' THEN 'inactive'
          ELSE v_old_status
        END,
      'old_role', v_old_role,
      'new_role', COALESCE(v_new_role, v_old_role),
      'old_custom_role_id', v_old_custom_role_id,
      'new_custom_role_id',
        CASE
          WHEN p_occurrence_type IN ('admission', 'role_change') AND p_metadata ? 'new_custom_role_id'
            THEN v_new_custom_role_id
          ELSE v_old_custom_role_id
        END,
      'occurrence_id', v_occurrence_id,
      'occurrence_type', p_occurrence_type,
      'severity', p_severity,
      'title', v_final_title,
      'description', v_final_description,
      'occurred_at', v_effective_occurred_at
    ),
    'success',
    now()
  );

  RETURN QUERY
  SELECT
    smo.id AS occurrence_id,
    smo.member_id,
    smo.store_id,
    smo.user_id,
    smo.occurrence_type,
    smo.severity,
    smo.title,
    smo.description,
    smo.occurred_at,
    smo.visible_to_member,
    sm.status AS member_status,
    smo.created_at
  FROM public.store_member_occurrences smo
  JOIN public.store_members sm
    ON sm.id = smo.member_id
  WHERE smo.id = v_occurrence_id;
END;
$$;


ALTER FUNCTION "public"."create_store_member_occurrence_v2"("p_member_id" "uuid", "p_occurrence_type" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_occurred_at" timestamp with time zone, "p_visible_to_member" boolean, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_supplier_contact"("p_supplier_id" "uuid", "p_name" "text", "p_department" "text" DEFAULT 'commercial'::"text", "p_role" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_whatsapp" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_is_primary" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "name" "text", "department" "text", "is_primary" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_contact_id uuid;
BEGIN
  IF p_supplier_id IS NULL OR NULLIF(trim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Fornecedor e nome do contato são obrigatórios.';
  END IF;

  SELECT s.store_id
  INTO v_store_id
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
    AND public.is_store_member(s.store_id)
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado ou sem permissão.';
  END IF;

  IF p_is_primary THEN
    UPDATE public.supplier_contacts sc
    SET
      is_primary = false,
      updated_at = now()
    WHERE sc.store_id = v_store_id
      AND sc.supplier_id = p_supplier_id
      AND sc.department = COALESCE(p_department, 'commercial')
      AND sc.active = true;
  END IF;

  INSERT INTO public.supplier_contacts (
    store_id,
    supplier_id,
    name,
    department,
    role,
    phone,
    whatsapp,
    email,
    notes,
    is_primary,
    active,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_store_id,
    p_supplier_id,
    trim(p_name),
    COALESCE(p_department, 'commercial'),
    NULLIF(trim(COALESCE(p_role, '')), ''),
    NULLIF(trim(COALESCE(p_phone, '')), ''),
    NULLIF(trim(COALESCE(p_whatsapp, '')), ''),
    NULLIF(trim(COALESCE(p_email, '')), ''),
    NULLIF(trim(COALESCE(p_notes, '')), ''),
    COALESCE(p_is_primary, false),
    true,
    '{}'::jsonb,
    now(),
    now()
  )
  RETURNING supplier_contacts.id
  INTO v_contact_id;

  RETURN QUERY
  SELECT
    sc.id,
    sc.store_id,
    sc.supplier_id,
    sc.name,
    sc.department,
    sc.is_primary
  FROM public.supplier_contacts sc
  WHERE sc.id = v_contact_id;
END;
$$;


ALTER FUNCTION "public"."create_supplier_contact"("p_supplier_id" "uuid", "p_name" "text", "p_department" "text", "p_role" "text", "p_phone" "text", "p_whatsapp" "text", "p_email" "text", "p_notes" "text", "p_is_primary" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_supplier_relationship_event"("p_supplier_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT 'info'::"text", "p_status" "text" DEFAULT 'open'::"text", "p_related_purchase_document_id" "uuid" DEFAULT NULL::"uuid", "p_related_product_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "event_type" "text", "title" "text", "severity" "text", "status" "text", "event_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_event_id uuid;
BEGIN
  IF p_supplier_id IS NULL OR NULLIF(trim(p_title), '') IS NULL THEN
    RAISE EXCEPTION 'Fornecedor e título são obrigatórios.';
  END IF;

  SELECT s.store_id
  INTO v_store_id
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
    AND public.is_store_member(s.store_id)
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado ou sem permissão.';
  END IF;

  INSERT INTO public.supplier_relationship_events (
    store_id,
    supplier_id,
    event_type,
    title,
    description,
    event_at,
    severity,
    status,
    related_purchase_document_id,
    related_product_id,
    created_by,
    created_by_email,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_store_id,
    p_supplier_id,
    COALESCE(p_event_type, 'note'),
    trim(p_title),
    NULLIF(trim(COALESCE(p_description, '')), ''),
    now(),
    COALESCE(p_severity, 'info'),
    COALESCE(p_status, 'open'),
    p_related_purchase_document_id,
    p_related_product_id,
    auth.uid(),
    auth.email(),
    COALESCE(p_metadata, '{}'::jsonb),
    now(),
    now()
  )
  RETURNING supplier_relationship_events.id
  INTO v_event_id;

  UPDATE public.suppliers s
  SET
    last_contact_at = now(),
    updated_at = now()
  WHERE s.id = p_supplier_id
    AND s.store_id = v_store_id;

  RETURN QUERY
  SELECT
    sre.id,
    sre.store_id,
    sre.supplier_id,
    sre.event_type,
    sre.title,
    sre.severity,
    sre.status,
    sre.event_at
  FROM public.supplier_relationship_events sre
  WHERE sre.id = v_event_id;
END;
$$;


ALTER FUNCTION "public"."create_supplier_relationship_event"("p_supplier_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text", "p_severity" "text", "p_status" "text", "p_related_purchase_document_id" "uuid", "p_related_product_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_login_with_password"("p_phone" "text", "p_password" "text", "p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_phone text;
  v_customer public.customers%rowtype;
  v_customer_json jsonb;
BEGIN
  v_phone := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');

  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('customer', null);
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stores s
    WHERE s.id = p_store_id
      AND s.public_store_enabled = true
  ) THEN
    RETURN jsonb_build_object('customer', null);
  END IF;

  IF length(v_phone) < 10 OR length(v_phone) > 14 THEN
    RETURN jsonb_build_object('customer', null);
  END IF;

  IF length(coalesce(p_password, '')) < 4 THEN
    RETURN jsonb_build_object('customer', null);
  END IF;

  SELECT c.*
    INTO v_customer
  FROM public.customers c
  WHERE c.phone = v_phone
    AND c.store_id = p_store_id
    AND COALESCE(c.status, 'active') = 'active'
    AND c.password_hash IS NOT NULL
    AND c.password_hash = crypt(p_password, c.password_hash)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('customer', null);
  END IF;

  v_customer_json := jsonb_build_object(
    'id', v_customer.id,
    'store_id', v_customer.store_id,
    'full_name', v_customer.full_name,
    'phone', v_customer.phone,
    'is_whatsapp', COALESCE(v_customer.is_whatsapp, false),
    'contact_preference', v_customer.contact_preference,
    'loyalty_points', COALESCE(v_customer.loyalty_points, 0),
    'loyalty_tier', COALESCE(v_customer.loyalty_tier, 'Bronze'),
    'current_tier_id', v_customer.current_tier_id,
    'loyalty_opt_in', COALESCE(v_customer.loyalty_opt_in, false),
    'status', COALESCE(v_customer.status, 'active')
  );

  RETURN jsonb_build_object('customer', v_customer_json);
END;
$$;


ALTER FUNCTION "public"."customer_login_with_password"("p_phone" "text", "p_password" "text", "p_store_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."customer_login_with_password"("p_phone" "text", "p_password" "text", "p_store_id" "uuid") IS 'EXCEÇÃO INTENCIONAL 6.4: função pública para login de cliente por telefone/senha. Revisar para não expor dados sensíveis do customer.';



CREATE OR REPLACE FUNCTION "public"."decline_my_store_member_invite"("p_invite_id" "uuid", "p_reason" "text" DEFAULT 'Recusado pelo convidado'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_email text;
  v_invite public.store_member_invites%ROWTYPE;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT au.email::text
  INTO v_email
  FROM auth.users au
  WHERE au.id = v_user_id;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'E-mail do usuário autenticado não encontrado.';
  END IF;

  SELECT *
  INTO v_invite
  FROM public.store_member_invites
  WHERE id = p_invite_id
    AND normalized_email = lower(btrim(v_email))
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Convite pendente não encontrado para este usuário.';
  END IF;

  IF v_invite.expires_at < now() THEN
    UPDATE public.store_member_invites
    SET
      status = 'expired',
      updated_at = now()
    WHERE id = v_invite.id;

    RAISE EXCEPTION 'Convite expirado.';
  END IF;

  UPDATE public.store_member_invites
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = v_user_id,
    cancel_reason = COALESCE(p_reason, 'Recusado pelo convidado'),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'declined_by_invitee', true,
      'declined_at', now()
    ),
    updated_at = now()
  WHERE id = v_invite.id;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_invite.store_id,
    v_user_id,
    v_email,
    'store_member_invite_declined',
    jsonb_build_object(
      'invite_id', v_invite.id,
      'target_email', v_invite.email,
      'role', v_invite.role,
      'reason', p_reason
    ),
    'success',
    now()
  );

  RETURN jsonb_build_object(
    'invite_id', v_invite.id,
    'store_id', v_invite.store_id,
    'email', v_invite.email,
    'status', 'declined'
  );
END;
$$;


ALTER FUNCTION "public"."decline_my_store_member_invite"("p_invite_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_purchase_document_draft"("p_document_id" "uuid") RETURNS TABLE("purchase_document_id" "uuid", "restored_quotation_id" "uuid", "restored_quotation_status" "text", "deleted_items" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_doc record;
  v_quote record;
  v_restored_status text;
  v_deleted_items integer := 0;
  v_existing_movements integer := 0;
  v_existing_applications integer := 0;
BEGIN
  IF p_document_id IS NULL THEN
    RAISE EXCEPTION 'Documento de compra não informado.';
  END IF;

  SELECT
    pd.id,
    pd.store_id,
    pd.supplier_id,
    pd.invoice_number,
    pd.issue_date,
    pd.total_amount,
    pd.notes,
    pd.status
  INTO v_doc
  FROM public.purchase_documents pd
  WHERE pd.id = p_document_id
  FOR UPDATE;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Documento de compra não encontrado.';
  END IF;

  IF NOT (
    public.user_can_purchase_action(v_doc.store_id, 'create')
    OR public.user_can_purchase_action(v_doc.store_id, 'cancel')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para excluir rascunhos de compra nesta loja.';
  END IF;

  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'Somente rascunhos de compra podem ser excluídos por esta operação.';
  END IF;

  SELECT COUNT(*)
  INTO v_existing_movements
  FROM public.stock_movements sm
  WHERE sm.source_id = p_document_id
     OR sm.metadata->>'purchase_document_id' = p_document_id::text;

  IF v_existing_movements > 0 THEN
    RAISE EXCEPTION 'Este documento possui movimentações de estoque e não pode ser excluído como rascunho.';
  END IF;

  SELECT COUNT(*)
  INTO v_existing_applications
  FROM public.purchase_document_location_applications pdla
  WHERE pdla.purchase_document_id = p_document_id;

  IF v_existing_applications > 0 THEN
    RAISE EXCEPTION 'Este documento já foi aplicado a local de estoque e não pode ser excluído como rascunho.';
  END IF;

  SELECT
    q.id,
    q.store_id,
    q.quotation_code,
    q.status,
    q.sent_channel,
    q.responsible_name,
    q.converted_purchase_document_id
  INTO v_quote
  FROM public.purchase_quotations q
  WHERE q.converted_purchase_document_id = p_document_id
    AND q.store_id = v_doc.store_id
  FOR UPDATE;

  IF v_quote.id IS NOT NULL THEN
    SELECT
      COALESCE(
        (
          SELECT NULLIF(e.old_data->>'status', '')
          FROM public.operational_timeline_events e
          WHERE e.event_type = 'quotation_converted_to_purchase_document'
            AND e.related_purchase_document_id = p_document_id
          ORDER BY e.occurred_at DESC
          LIMIT 1
        ),
        'approved'
      )
    INTO v_restored_status;

    IF v_restored_status NOT IN ('draft', 'sent', 'answered', 'approved', 'rejected', 'cancelled') THEN
      v_restored_status := 'approved';
    END IF;

    UPDATE public.purchase_quotations q
    SET
      status = v_restored_status,
      converted_purchase_document_id = NULL,
      updated_at = now()
    WHERE q.id = v_quote.id
      AND q.store_id = v_doc.store_id;
  END IF;

  DELETE FROM public.purchase_document_items pdi
  WHERE pdi.purchase_document_id = p_document_id
    AND pdi.store_id = v_doc.store_id;

  GET DIAGNOSTICS v_deleted_items = ROW_COUNT;

  PERFORM public.create_operational_timeline_event(
    p_store_id := v_doc.store_id,
    p_entity_type := 'purchase_document',
    p_entity_id := p_document_id,
    p_event_type := 'purchase_document_draft_deleted',
    p_title := 'Rascunho de compra excluído',
    p_description := 'Rascunho de compra excluído' ||
      CASE
        WHEN v_quote.id IS NOT NULL THEN ' e vínculo com a cotação restaurado.'
        ELSE '.'
      END,
    p_severity := 'warning',
    p_status := 'archived',
    p_channel := 'manual',
    p_source := 'delete_purchase_document_draft',
    p_source_id := p_document_id,
    p_old_data := jsonb_build_object(
      'purchase_document_id', p_document_id,
      'status', v_doc.status,
      'invoice_number', v_doc.invoice_number,
      'issue_date', v_doc.issue_date,
      'total_amount', v_doc.total_amount,
      'notes', v_doc.notes,
      'linked_quotation_id', v_quote.id,
      'linked_quotation_code', v_quote.quotation_code,
      'quotation_status_before', v_quote.status
    ),
    p_new_data := jsonb_build_object(
      'deleted', true,
      'deleted_items', v_deleted_items,
      'restored_quotation_id', v_quote.id,
      'restored_quotation_status', v_restored_status
    ),
    p_metadata := jsonb_build_object(
      'phase', '9.3C.6-C',
      'origin', 'purchase_document_draft_delete',
      'quotation_code', v_quote.quotation_code
    ),
    p_related_supplier_id := v_doc.supplier_id,
    p_related_purchase_quotation_id := v_quote.id,
    p_related_purchase_document_id := NULL
  );

  IF v_quote.id IS NOT NULL THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_doc.store_id,
      p_entity_type := 'purchase_quotation',
      p_entity_id := v_quote.id,
      p_event_type := 'quotation_linked_purchase_cancelled',
      p_title := 'Compra vinculada cancelada',
      p_description := 'A compra vinculada à cotação ' || v_quote.quotation_code || ' foi excluída e a cotação voltou para ' || v_restored_status || '.',
      p_severity := 'warning',
      p_status := 'done',
      p_responsible_name := v_quote.responsible_name,
      p_channel := COALESCE(v_quote.sent_channel, 'manual'),
      p_source := 'delete_purchase_document_draft',
      p_source_id := p_document_id,
      p_old_data := jsonb_build_object(
        'quotation_status', v_quote.status,
        'converted_purchase_document_id', p_document_id,
        'purchase_document_status', v_doc.status,
        'purchase_document_total_amount', v_doc.total_amount
      ),
      p_new_data := jsonb_build_object(
        'quotation_status', v_restored_status,
        'converted_purchase_document_id', NULL,
        'linked_purchase_deleted', true,
        'deleted_purchase_document_id', p_document_id,
        'deleted_items', v_deleted_items
      ),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-C',
        'origin', 'linked_purchase_delete',
        'quotation_code', v_quote.quotation_code
      ),
      p_related_supplier_id := v_doc.supplier_id,
      p_related_purchase_quotation_id := v_quote.id,
      p_related_purchase_document_id := NULL
    );
  END IF;

  DELETE FROM public.purchase_documents pd
  WHERE pd.id = p_document_id
    AND pd.store_id = v_doc.store_id;

  RETURN QUERY
  SELECT
    p_document_id,
    v_quote.id,
    v_restored_status,
    v_deleted_items;
END;
$$;


ALTER FUNCTION "public"."delete_purchase_document_draft"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_purchase_document_supplier_eligibility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier record;
BEGIN
  -- Permite cancelamento/histórico sem travar manutenção.
  IF COALESCE(NEW.status, 'draft') = 'cancelled' THEN
    RETURN NEW;
  END IF;

  IF NEW.supplier_id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não informado no documento de compra.';
  END IF;

  SELECT
    s.id,
    s.name,
    s.store_id,
    COALESCE(s.active, true) AS active,
    COALESCE(s.blocked, false) AS blocked,
    lower(COALESCE(s.homologation_status, 'not_evaluated')) AS homologation_status
  INTO v_supplier
  FROM public.suppliers s
  WHERE s.id = NEW.supplier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fornecedor do documento de compra não encontrado.';
  END IF;

  IF v_supplier.store_id IS DISTINCT FROM NEW.store_id THEN
    RAISE EXCEPTION 'Fornecedor pertence a outra loja.';
  END IF;

  IF v_supplier.active = false THEN
    RAISE EXCEPTION 'Fornecedor inativo. Não é possível criar ou manter compra ativa para este fornecedor.';
  END IF;

  IF v_supplier.blocked = true THEN
    RAISE EXCEPTION 'Fornecedor bloqueado. Não é possível criar ou manter compra ativa para este fornecedor.';
  END IF;

  IF v_supplier.homologation_status IN (
    'rejected',
    'reproved',
    'reprovado',
    'blocked',
    'bloqueado'
  ) THEN
    RAISE EXCEPTION 'Fornecedor reprovado ou bloqueado na homologação. Não é possível criar compra para este fornecedor.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_purchase_document_supplier_eligibility"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_purchase_document_supplier_eligibility"() IS 'FASE 6.5C: trava interna para impedir documentos de compra ativos com fornecedor inativo, bloqueado ou reprovado.';



CREATE OR REPLACE FUNCTION "public"."ensure_inventory_location_balance"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inventory_location_balances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_row public.inventory_location_balances;
begin
    insert into public.inventory_location_balances (
        store_id,
        location_id,
        product_id,
        variant_id,
        on_hand,
        reserved,
        updated_at
    )
    values (
        p_store_id,
        p_location_id,
        p_product_id,
        p_variant_id,
        0,
        0,
        now()
    )
    on conflict (
        store_id,
        location_id,
        product_id,
        coalesce(variant_id, '00000000-0000-0000-0000-000000000000'::uuid)
    )
    do update
       set updated_at = public.inventory_location_balances.updated_at
    returning *
      into v_row;

    return v_row;
end;
$$;


ALTER FUNCTION "public"."ensure_inventory_location_balance"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_inventory_location_balance"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid") IS 'Garante a existência do saldo por local para store/produto/variante.';



CREATE OR REPLACE FUNCTION "public"."ensure_product_stock_location_rules"("p_store_id" "uuid", "p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product record;
  v_locations_count integer := 0;
  v_percent numeric := 0;
  v_inserted integer := 0;
BEGIN
  IF p_store_id IS NULL OR p_product_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_parameters');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT
    p.id,
    p.store_id,
    COALESCE(p.min_stock, 0) AS min_stock,
    COALESCE(p.max_stock, 0) AS max_stock
  INTO v_product
  FROM public.products p
  WHERE p.id = p_product_id
    AND p.store_id = p_store_id;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'product_not_found');
  END IF;

  SELECT COUNT(*)::integer
  INTO v_locations_count
  FROM public.stock_locations sl
  WHERE sl.store_id = p_store_id
    AND sl.active = true
    AND (
      sl.allow_sales = true
      OR sl.allow_reservations = true
      OR sl.is_default = true
    );

  IF v_locations_count <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_active_locations');
  END IF;

  v_percent := round((100.0 / v_locations_count)::numeric, 2);

  INSERT INTO public.product_stock_location_rules (
    store_id,
    product_id,
    location_id,
    min_percent,
    max_percent,
    min_stock,
    max_stock,
    use_percentage,
    active
  )
  SELECT
    p_store_id,
    p_product_id,
    sl.id,
    v_percent,
    v_percent,
    round((COALESCE(v_product.min_stock, 0) * v_percent / 100.0)::numeric, 2),
    round((COALESCE(v_product.max_stock, 0) * v_percent / 100.0)::numeric, 2),
    true,
    true
  FROM public.stock_locations sl
  WHERE sl.store_id = p_store_id
    AND sl.active = true
    AND (
      sl.allow_sales = true
      OR sl.allow_reservations = true
      OR sl.is_default = true
    )
  ON CONFLICT (store_id, product_id, location_id)
  DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'product_id', p_product_id,
    'locations_count', v_locations_count,
    'inserted', v_inserted,
    'default_percent', v_percent
  );
END;
$$;


ALTER FUNCTION "public"."ensure_product_stock_location_rules"("p_store_id" "uuid", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_single_default_stock_location"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    if new.is_default then
        update public.stock_locations
           set is_default = false,
               updated_at = now()
         where store_id = new.store_id
           and id <> new.id
           and is_default = true;
    end if;

    return new;
end;
$$;


