CREATE OR REPLACE FUNCTION "public"."expire_public_order_reservations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order record;
  v_reservation record;
  v_orders_expired integer := 0;
  v_reservations_expired integer := 0;
BEGIN
  FOR v_order IN
    SELECT
      o.id,
      o.store_id,
      o.order_code
    FROM public.orders o
    WHERE o.status = 'reserved'
      AND o.expires_at IS NOT NULL
      AND o.expires_at <= now()
    ORDER BY o.expires_at ASC
  LOOP
    FOR v_reservation IN
      SELECT
        sr.id,
        sr.store_id,
        sr.product_id,
        sr.location_id,
        sr.quantity
      FROM public.stock_reservations sr
      WHERE sr.order_id = v_order.id
        AND sr.status = 'active'
    LOOP
      UPDATE public.inventory_location_balances ilb
      SET
        reserved = GREATEST(0, ilb.reserved - v_reservation.quantity),
        updated_at = now()
      WHERE ilb.store_id = v_reservation.store_id
        AND ilb.product_id = v_reservation.product_id
        AND ilb.location_id = v_reservation.location_id;

      UPDATE public.inventory_balances ib
      SET
        reserved = GREATEST(0, ib.reserved - v_reservation.quantity),
        updated_at = now()
      WHERE ib.store_id = v_reservation.store_id
        AND ib.product_id = v_reservation.product_id;

      UPDATE public.stock_reservations
      SET
        status = 'expired',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'expired_at', now(),
          'expired_by', 'expire_public_order_reservations'
        )
      WHERE id = v_reservation.id;

      v_reservations_expired := v_reservations_expired + 1;
    END LOOP;

    UPDATE public.orders
    SET
      status = 'cancelled',
      commercial_metadata = COALESCE(commercial_metadata, '{}'::jsonb) || jsonb_build_object(
        'cancelled_reason', 'reservation_expired',
        'cancelled_at', now(),
        'cancelled_by', 'expire_public_order_reservations'
      ),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'reservation_expired_at', now()
      )
    WHERE id = v_order.id;

    v_orders_expired := v_orders_expired + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'orders_expired', v_orders_expired,
    'reservations_expired', v_reservations_expired
  );
END;
$$;


ALTER FUNCTION "public"."expire_public_order_reservations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_reservation"("p_order_id" "uuid", "p_minutes" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order record;
  v_minutes integer;
  v_updated_count integer := 0;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'Pedido não informado.';
  END IF;

  v_minutes := COALESCE(p_minutes, 0);

  IF v_minutes < 1 OR v_minutes > 120 THEN
    RAISE EXCEPTION 'Tempo de prorrogação inválido. Informe entre 1 e 120 minutos.';
  END IF;

  SELECT
    o.id,
    o.store_id,
    o.status,
    o.order_code
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  LIMIT 1;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Pedido não encontrado.';
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Usuário não autenticado.';
    END IF;

    IF NOT public.is_store_member(v_order.store_id) THEN
      RAISE EXCEPTION 'Acesso negado ao pedido informado.';
    END IF;
  END IF;

  IF v_order.status::text NOT IN ('reserved', 'confirmed') THEN
    RAISE EXCEPTION 'Apenas pedidos reservados ou confirmados podem ter reserva prorrogada. Status atual: %.', v_order.status;
  END IF;

  UPDATE public.stock_reservations sr
  SET
    expires_at = GREATEST(sr.expires_at, now()) + (v_minutes || ' minutes')::interval,
    metadata = COALESCE(sr.metadata, '{}'::jsonb) || jsonb_build_object(
      'extended_at', now(),
      'extended_by', auth.uid(),
      'extended_minutes', v_minutes,
      'extended_by_function', 'extend_reservation'
    )
  WHERE sr.order_id = v_order.id
    AND sr.store_id = v_order.store_id
    AND sr.status = 'active';

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  IF v_updated_count <= 0 THEN
    RAISE EXCEPTION 'Reserva ativa não encontrada para o pedido informado.';
  END IF;
END;
$$;


ALTER FUNCTION "public"."extend_reservation"("p_order_id" "uuid", "p_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."extend_reservation"("p_order_id" "uuid", "p_minutes" integer) IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC comercial de extensão de reserva. Revisar junto com fluxo de pedidos/reservas.';



