CREATE OR REPLACE FUNCTION "public"."generate_purchase_document_code"("p_store_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code text;
  v_attempt integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada para gerar código da compra.';
  END IF;

  IF NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja.';
  END IF;

  LOOP
    v_attempt := v_attempt + 1;

    v_code :=
      'ENT-' ||
      to_char(timezone('America/Sao_Paulo', now()), 'YYYYMMDD-HH24MISS') ||
      '-' ||
      lpad(floor(random() * 1000)::int::text, 3, '0');

    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM public.purchase_documents pd
      WHERE pd.store_id = p_store_id
        AND pd.document_code = v_code
    );

    IF v_attempt >= 10 THEN
      RAISE EXCEPTION 'Não foi possível gerar código único para a compra.';
    END IF;
  END LOOP;

  RETURN v_code;
END;
$$;


