CREATE OR REPLACE FUNCTION "public"."get_admin_customers_safe"("p_store_id" "uuid", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_customers jsonb;
begin
  if p_store_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'missing_store_id',
      'customers', '[]'::jsonb
    );
  end if;

  if coalesce(auth.role(), '') in ('anon', 'authenticated') then
    if auth.uid() is null
       or not (
         public.app_is_store_owner(p_store_id)
         or public.user_has_store_permission(p_store_id, 'customers.view')
         or public.user_has_store_permission(p_store_id, 'customers.manage')
       ) then
      return jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'customers', '[]'::jsonb
      );
    end if;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'store_id', q.store_id,
        'full_name', q.full_name,
        'phone', q.phone,
        'email', q.email,
        'cpf', q.cpf,
        'birth_date', q.birth_date,
        'status', q.status,
        'source', q.source,
        'data_ownership', q.data_ownership,
        'editable_by_store', q.editable_by_store,
        'is_whatsapp', q.is_whatsapp,
        'contact_preference', q.contact_preference,
        'marketing_consent', q.marketing_consent,
        'loyalty_opt_in', q.loyalty_opt_in,
        'loyalty_points', q.loyalty_points,
        'loyalty_tier', q.loyalty_tier,
        'current_tier_id', q.current_tier_id,
        'current_tier_name', q.current_tier_name,
        'tags', q.tags,
        'internal_notes', q.internal_notes,
        'created_at', q.created_at,
        'last_login', q.last_login,
        'last_point_activity_at', q.last_point_activity_at,
        'last_order_at', q.last_order_at,
        'total_orders', q.total_orders,
        'total_spent', q.total_spent
      )
      order by q.created_at desc
    ),
    '[]'::jsonb
  )
  into v_customers
  from (
    select
      c.*,
      ft.name as current_tier_name
    from public.customers c
    left join public.fidelity_tiers ft
      on ft.id = c.current_tier_id
    where c.store_id = p_store_id
    order by c.created_at desc
    limit greatest(1, least(coalesce(p_limit, 500), 1000))
  ) q;

  return jsonb_build_object('ok', true, 'customers', v_customers);
end;
$$;


ALTER FUNCTION "public"."get_admin_customers_safe"("p_store_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_loyalty_safe"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_program jsonb;
  v_tiers jsonb;
  v_recent_transactions jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
  END IF;

  SELECT to_jsonb(fp)
  INTO v_program
  FROM public.fidelity_programs fp
  WHERE fp.store_id = p_store_id
  ORDER BY fp.created_at DESC
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(to_jsonb(ft) ORDER BY ft.min_points), '[]'::jsonb)
  INTO v_tiers
  FROM public.fidelity_tiers ft
  WHERE ft.store_id = p_store_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.created_at DESC), '[]'::jsonb)
  INTO v_recent_transactions
  FROM (
    SELECT
      lt.*,
      c.full_name AS customer_name,
      c.phone AS customer_phone
    FROM public.loyalty_transactions lt
    JOIN public.customers c ON c.id = lt.customer_id
    WHERE c.store_id = p_store_id
    ORDER BY lt.created_at DESC
    LIMIT 50
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'program', COALESCE(v_program, 'null'::jsonb),
    'tiers', COALESCE(v_tiers, '[]'::jsonb),
    'recent_transactions', COALESCE(v_recent_transactions, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_admin_loyalty_safe"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_orders_safe"("p_store_id" "uuid", "p_status" "text" DEFAULT 'all'::"text", "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_orders jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id', 'orders', '[]'::jsonb);
  END IF;

  IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'access_denied', 'orders', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.created_at DESC), '[]'::jsonb)
  INTO v_orders
  FROM (
    SELECT
      o.*,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', oi.id,
            'quantity', oi.quantity,
            'unit_price', oi.unit_price,
            'product_id', oi.product_id,
            'product_snapshot', oi.product_snapshot,
            'commercial_metadata', oi.commercial_metadata,
            'product', jsonb_build_object(
              'name', COALESCE(p.name, oi.product_snapshot->>'name'),
              'price', p.price
            )
          )
          ORDER BY oi.id
        )
        FROM public.order_items oi
        LEFT JOIN public.products p ON p.id = oi.product_id
        WHERE oi.order_id = o.id
      ), '[]'::jsonb) AS order_items,
      COALESCE((
        SELECT jsonb_agg(to_jsonb(sr) ORDER BY sr.expires_at)
        FROM public.stock_reservations sr
        WHERE sr.order_id = o.id
      ), '[]'::jsonb) AS stock_reservations
    FROM public.orders o
    WHERE o.store_id = p_store_id
      AND (
        p_status IS NULL
        OR p_status = 'all'
        OR o.status::text = p_status
      )
    ORDER BY o.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 200), 500))
  ) q;

  RETURN jsonb_build_object('ok', true, 'orders', v_orders);
END;
$$;


ALTER FUNCTION "public"."get_admin_orders_safe"("p_store_id" "uuid", "p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_available_stock"("p_product_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_physical INTEGER;
    v_reserved INTEGER;
BEGIN
    -- Get physical stock
    SELECT stock_quantity INTO v_physical FROM products WHERE id = p_product_id;
    
    -- Get active reservations (not expired)
    SELECT COALESCE(SUM(quantity), 0) INTO v_reserved 
    FROM stock_reservations 
    WHERE product_id = p_product_id 
    AND expires_at > NOW();
    
    RETURN COALESCE(v_physical, 0) - v_reserved;
END;
$$;


ALTER FUNCTION "public"."get_available_stock"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_campaign_recipients_safe"("p_store_id" "uuid", "p_campaign_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recipients jsonb;
  v_campaign record;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF p_campaign_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_campaign_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT
    pc.id,
    pc.name,
    pc.channel,
    pc.status
  INTO v_campaign
  FROM public.promotion_campaigns pc
  WHERE pc.id = p_campaign_id
    AND pc.store_id = p_store_id;

  IF v_campaign.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', pcr.id,
        'campaign_id', pcr.campaign_id,
        'customer_id', pcr.customer_id,
        'channel', pcr.channel,
        'recipient_name', pcr.recipient_name,
        'recipient_phone', pcr.recipient_phone,
        'recipient_email', pcr.recipient_email,
        'status', pcr.status,
        'message_preview', pcr.message_preview,
        'sent_at', pcr.sent_at,
        'created_at', pcr.created_at
      )
      ORDER BY pcr.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_recipients
  FROM public.promotion_campaign_recipients pcr
  WHERE pcr.store_id = p_store_id
    AND pcr.campaign_id = p_campaign_id;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign', jsonb_build_object(
      'id', v_campaign.id,
      'name', v_campaign.name,
      'channel', v_campaign.channel,
      'status', v_campaign.status
    ),
    'recipients', v_recipients
  );
END;
$$;


ALTER FUNCTION "public"."get_campaign_recipients_safe"("p_store_id" "uuid", "p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cashbook_entries_safe"("p_store_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entries jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id', 'entries', '[]'::jsonb);
  END IF;

  IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'access_denied', 'entries', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.occurred_at DESC), '[]'::jsonb)
  INTO v_entries
  FROM (
    SELECT
      ce.*,
      o.customer_name AS order_customer_name,
      o.order_code AS order_code
    FROM public.cashbook_entries ce
    LEFT JOIN public.orders o ON o.id = ce.order_id
    WHERE ce.store_id = p_store_id
    ORDER BY ce.occurred_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 500))
  ) q;

  RETURN jsonb_build_object('ok', true, 'entries', v_entries);
END;
$$;


ALTER FUNCTION "public"."get_cashbook_entries_safe"("p_store_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cashbook_summary"("p_store_id" "uuid", "p_start_date" "date" DEFAULT CURRENT_DATE, "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_in numeric := 0;
  v_total_out numeric := 0;
  v_balance numeric := 0;
  v_by_payment jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT
    COALESCE(SUM(amount) FILTER (WHERE direction = 'in' AND status = 'confirmed' AND affects_balance = true), 0),
    COALESCE(SUM(amount) FILTER (WHERE direction = 'out' AND status = 'confirmed' AND affects_balance = true), 0)
  INTO v_total_in, v_total_out
  FROM public.cashbook_entries
  WHERE store_id = p_store_id
    AND entry_date BETWEEN p_start_date AND p_end_date;

  v_balance := v_total_in - v_total_out;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'payment_method_code', payment_method_code,
        'payment_method', payment_method,
        'total_in', total_in,
        'total_out', total_out,
        'balance', total_in - total_out
      )
      ORDER BY payment_method_code
    ),
    '[]'::jsonb
  )
  INTO v_by_payment
  FROM (
    SELECT
      COALESCE(payment_method_code, 'not_informed') AS payment_method_code,
      COALESCE(payment_method, 'Não informado') AS payment_method,
      COALESCE(SUM(amount) FILTER (WHERE direction = 'in' AND status = 'confirmed' AND affects_balance = true), 0) AS total_in,
      COALESCE(SUM(amount) FILTER (WHERE direction = 'out' AND status = 'confirmed' AND affects_balance = true), 0) AS total_out
    FROM public.cashbook_entries
    WHERE store_id = p_store_id
      AND entry_date BETWEEN p_start_date AND p_end_date
    GROUP BY
      COALESCE(payment_method_code, 'not_informed'),
      COALESCE(payment_method, 'Não informado')
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'summary', jsonb_build_object(
      'start_date', p_start_date,
      'end_date', p_end_date,
      'total_in', v_total_in,
      'total_out', v_total_out,
      'balance', v_balance,
      'by_payment_method', v_by_payment
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_cashbook_summary"("p_store_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_commercial_dashboard_safe"("p_store_id" "uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start timestamptz;
  v_end timestamptz;

  v_today_start timestamptz;
  v_today_end timestamptz;

  v_month_start timestamptz;
  v_month_end timestamptz;

  v_summary jsonb;
  v_statuses jsonb;
  v_channels jsonb;
  v_top_products jsonb;
  v_recent_orders jsonb;
  v_cashbook jsonb;
  v_loyalty jsonb;
  v_customers jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_store_id'
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied'
      );
    END IF;
  END IF;

  v_today_start := date_trunc('day', now());
  v_today_end := v_today_start + interval '1 day';

  v_month_start := date_trunc('month', now());
  v_month_end := v_month_start + interval '1 month';

  v_start := COALESCE(p_start_date::timestamptz, v_month_start);
  v_end := COALESCE((p_end_date + 1)::timestamptz, v_month_end);

  SELECT jsonb_build_object(
    'today_sales', COALESCE(SUM(o.total) FILTER (
      WHERE o.status = 'completed'
        AND o.completed_at >= v_today_start
        AND o.completed_at < v_today_end
    ), 0),
    'today_orders', COALESCE(COUNT(*) FILTER (
      WHERE o.created_at >= v_today_start
        AND o.created_at < v_today_end
    ), 0),
    'today_completed_orders', COALESCE(COUNT(*) FILTER (
      WHERE o.status = 'completed'
        AND o.completed_at >= v_today_start
        AND o.completed_at < v_today_end
    ), 0),

    'month_sales', COALESCE(SUM(o.total) FILTER (
      WHERE o.status = 'completed'
        AND o.completed_at >= v_month_start
        AND o.completed_at < v_month_end
    ), 0),
    'month_completed_orders', COALESCE(COUNT(*) FILTER (
      WHERE o.status = 'completed'
        AND o.completed_at >= v_month_start
        AND o.completed_at < v_month_end
    ), 0),

    'period_sales', COALESCE(SUM(o.total) FILTER (
      WHERE o.status = 'completed'
        AND COALESCE(o.completed_at, o.created_at) >= v_start
        AND COALESCE(o.completed_at, o.created_at) < v_end
    ), 0),
    'period_orders', COALESCE(COUNT(*) FILTER (
      WHERE o.created_at >= v_start
        AND o.created_at < v_end
    ), 0),
    'period_completed_orders', COALESCE(COUNT(*) FILTER (
      WHERE o.status = 'completed'
        AND COALESCE(o.completed_at, o.created_at) >= v_start
        AND COALESCE(o.completed_at, o.created_at) < v_end
    ), 0),
    'period_average_ticket', COALESCE(AVG(o.total) FILTER (
      WHERE o.status = 'completed'
        AND COALESCE(o.completed_at, o.created_at) >= v_start
        AND COALESCE(o.completed_at, o.created_at) < v_end
    ), 0)
  )
  INTO v_summary
  FROM public.orders o
  WHERE o.store_id = p_store_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'status', q.status,
        'count', q.count,
        'total', q.total
      )
      ORDER BY q.count DESC
    ),
    '[]'::jsonb
  )
  INTO v_statuses
  FROM (
    SELECT
      o.status::text AS status,
      COUNT(*)::integer AS count,
      COALESCE(SUM(o.total), 0) AS total
    FROM public.orders o
    WHERE o.store_id = p_store_id
      AND o.created_at >= v_start
      AND o.created_at < v_end
    GROUP BY o.status
  ) q;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'sales_channel', q.sales_channel,
        'count', q.count,
        'total', q.total
      )
      ORDER BY q.total DESC
    ),
    '[]'::jsonb
  )
  INTO v_channels
  FROM (
    SELECT
      COALESCE(o.sales_channel, o.commercial_metadata->>'sales_channel', 'unknown') AS sales_channel,
      COUNT(*)::integer AS count,
      COALESCE(SUM(o.total) FILTER (WHERE o.status = 'completed'), 0) AS total
    FROM public.orders o
    WHERE o.store_id = p_store_id
      AND o.created_at >= v_start
      AND o.created_at < v_end
    GROUP BY COALESCE(o.sales_channel, o.commercial_metadata->>'sales_channel', 'unknown')
  ) q;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'product_id', q.product_id,
        'product_name', q.product_name,
        'quantity', q.quantity,
        'total', q.total
      )
      ORDER BY q.quantity DESC, q.total DESC
    ),
    '[]'::jsonb
  )
  INTO v_top_products
  FROM (
    SELECT
      oi.product_id,
      COALESCE(p.name, oi.product_snapshot->>'name', 'Produto') AS product_name,
      COALESCE(SUM(oi.quantity), 0)::numeric AS quantity,
      COALESCE(SUM(oi.quantity * oi.unit_price), 0)::numeric AS total
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    LEFT JOIN public.products p ON p.id = oi.product_id
    WHERE o.store_id = p_store_id
      AND o.status = 'completed'
      AND COALESCE(o.completed_at, o.created_at) >= v_start
      AND COALESCE(o.completed_at, o.created_at) < v_end
    GROUP BY oi.product_id, COALESCE(p.name, oi.product_snapshot->>'name', 'Produto')
    ORDER BY quantity DESC, total DESC
    LIMIT 10
  ) q;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'order_code', q.order_code,
        'customer_name', q.customer_name,
        'customer_phone', q.customer_phone,
        'total', q.total,
        'status', q.status,
        'sales_channel', q.sales_channel,
        'fulfillment_type', q.fulfillment_type,
        'payment_method_code', q.payment_method_code,
        'created_at', q.created_at,
        'confirmed_at', q.confirmed_at,
        'completed_at', q.completed_at
      )
      ORDER BY q.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_recent_orders
  FROM (
    SELECT
      o.id,
      o.order_code,
      o.customer_name,
      o.customer_phone,
      o.total,
      o.status,
      o.sales_channel,
      o.fulfillment_type,
      o.payment_method_code,
      o.created_at,
      o.confirmed_at,
      o.completed_at
    FROM public.orders o
    WHERE o.store_id = p_store_id
    ORDER BY o.created_at DESC
    LIMIT 8
  ) q;

  SELECT jsonb_build_object(
    'period_entries', COALESCE(SUM(ce.amount) FILTER (
      WHERE ce.direction = 'in'
        AND ce.created_at >= v_start
        AND ce.created_at < v_end
    ), 0),
    'period_outputs', COALESCE(SUM(ce.amount) FILTER (
      WHERE ce.direction = 'out'
        AND ce.created_at >= v_start
        AND ce.created_at < v_end
    ), 0),
    'period_balance', COALESCE(SUM(
      CASE
        WHEN ce.direction = 'in' THEN ce.amount
        WHEN ce.direction = 'out' THEN -ce.amount
        ELSE 0
      END
    ) FILTER (
      WHERE ce.created_at >= v_start
        AND ce.created_at < v_end
    ), 0),
    'month_entries', COALESCE(SUM(ce.amount) FILTER (
      WHERE ce.direction = 'in'
        AND ce.created_at >= v_month_start
        AND ce.created_at < v_month_end
    ), 0),
    'month_outputs', COALESCE(SUM(ce.amount) FILTER (
      WHERE ce.direction = 'out'
        AND ce.created_at >= v_month_start
        AND ce.created_at < v_month_end
    ), 0)
  )
  INTO v_cashbook
  FROM public.cashbook_entries ce
  WHERE ce.store_id = p_store_id;

  SELECT jsonb_build_object(
    'period_points_issued', COALESCE(SUM(lt.points) FILTER (
      WHERE lt.points > 0
        AND lt.created_at >= v_start
        AND lt.created_at < v_end
    ), 0),
    'period_transactions', COALESCE(COUNT(*) FILTER (
      WHERE lt.created_at >= v_start
        AND lt.created_at < v_end
    ), 0),
    'active_customers_with_points', COALESCE(COUNT(DISTINCT c.id) FILTER (
      WHERE COALESCE(c.loyalty_points, 0) > 0
    ), 0)
  )
  INTO v_loyalty
  FROM public.customers c
  LEFT JOIN public.loyalty_transactions lt ON lt.customer_id = c.id
  WHERE c.store_id = p_store_id;

  SELECT jsonb_build_object(
    'total_customers', COALESCE(COUNT(*), 0),
    'new_customers_period', COALESCE(COUNT(*) FILTER (
      WHERE c.created_at >= v_start
        AND c.created_at < v_end
    ), 0),
    'customer_owned', COALESCE(COUNT(*) FILTER (
      WHERE c.data_ownership = 'customer_owned'
    ), 0),
    'store_managed', COALESCE(COUNT(*) FILTER (
      WHERE c.data_ownership = 'store_managed'
    ), 0),
    'loyalty_opt_in', COALESCE(COUNT(*) FILTER (
      WHERE COALESCE(c.loyalty_opt_in, false) = true
    ), 0)
  )
  INTO v_customers
  FROM public.customers c
  WHERE c.store_id = p_store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'range', jsonb_build_object(
      'start', v_start,
      'end', v_end,
      'today_start', v_today_start,
      'today_end', v_today_end,
      'month_start', v_month_start,
      'month_end', v_month_end
    ),
    'summary', v_summary,
    'orders_by_status', v_statuses,
    'sales_by_channel', v_channels,
    'top_products', v_top_products,
    'recent_orders', v_recent_orders,
    'cashbook', v_cashbook,
    'loyalty', v_loyalty,
    'customers', v_customers
  );
END;
$$;


ALTER FUNCTION "public"."get_commercial_dashboard_safe"("p_store_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_user_security_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_email text;
  v_profile jsonb;
  v_memberships jsonb;
  v_primary_membership jsonb;
  v_has_pin boolean;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'authenticated', false,
      'user_id', NULL,
      'email', NULL,
      'profile', NULL,
      'memberships', '[]'::jsonb,
      'primary_membership', NULL,
      'has_pin', false,
      'is_global_admin', false
    );
  END IF;

  SELECT au.email::text
  INTO v_email
  FROM auth.users au
  WHERE au.id = v_user_id;

  SELECT jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'phone', p.phone,
    'cpf', p.cpf,
    'city', p.city,
    'is_admin', COALESCE(p.is_admin, false),
    'is_active', COALESCE(p.is_active, true),
    'created_at', p.created_at,
    'updated_at', p.updated_at
  )
  INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_user_id;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_pins up
    WHERE up.user_id = v_user_id
  )
  INTO v_has_pin;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'member_id', sm.id,
        'store_id', sm.store_id,
        'store_name', s.name,
        'store_slug', s.slug,
        'store_logo_url', s.logo_url,
        'role', sm.role,
        'status', sm.status,
        'permissions', sm.permissions,
        'sensitive_actions', sm.sensitive_actions,
        'is_owner', (sm.role = 'owner' OR s.user_id = v_user_id),
        'is_primary_owner', (s.user_id = v_user_id),
        'created_at', sm.created_at,
        'updated_at', sm.updated_at
      )
      ORDER BY
        CASE sm.role
          WHEN 'owner' THEN 1
          WHEN 'admin' THEN 2
          WHEN 'manager' THEN 3
          WHEN 'cashier' THEN 4
          WHEN 'stock_operator' THEN 5
          WHEN 'sales' THEN 6
          WHEN 'staff' THEN 7
          WHEN 'viewer' THEN 8
          ELSE 99
        END,
        s.name
    ),
    '[]'::jsonb
  )
  INTO v_memberships
  FROM public.store_members sm
  JOIN public.stores s ON s.id = sm.store_id
  WHERE sm.user_id = v_user_id
    AND sm.status = 'active';

  SELECT jsonb_build_object(
    'member_id', sm.id,
    'store_id', sm.store_id,
    'store_name', s.name,
    'store_slug', s.slug,
    'store_logo_url', s.logo_url,
    'role', sm.role,
    'status', sm.status,
    'permissions', sm.permissions,
    'sensitive_actions', sm.sensitive_actions,
    'is_owner', (sm.role = 'owner' OR s.user_id = v_user_id),
    'is_primary_owner', (s.user_id = v_user_id),
    'created_at', sm.created_at,
    'updated_at', sm.updated_at
  )
  INTO v_primary_membership
  FROM public.store_members sm
  JOIN public.stores s ON s.id = sm.store_id
  WHERE sm.user_id = v_user_id
    AND sm.status = 'active'
  ORDER BY
    CASE
      WHEN s.user_id = v_user_id THEN 0
      WHEN sm.role = 'owner' THEN 1
      WHEN sm.role = 'admin' THEN 2
      WHEN sm.role = 'manager' THEN 3
      ELSE 9
    END,
    s.created_at
  LIMIT 1;

  RETURN jsonb_build_object(
    'authenticated', true,
    'user_id', v_user_id,
    'email', v_email,
    'profile', COALESCE(v_profile, '{}'::jsonb),
    'memberships', COALESCE(v_memberships, '[]'::jsonb),
    'primary_membership', v_primary_membership,
    'has_pin', COALESCE(v_has_pin, false),
    'is_global_admin', COALESCE((v_profile ->> 'is_admin')::boolean, false)
  );
END;
$$;


ALTER FUNCTION "public"."get_current_user_security_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_user_security_context_v2"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_primary_membership jsonb;
  v_memberships jsonb;
  v_profile jsonb;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'authenticated', false,
      'user_id', NULL,
      'profile', NULL,
      'primary_membership', NULL,
      'memberships', '[]'::jsonb
    );
  END IF;

  SELECT jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'phone', p.phone,
    'mobile_phone', p.mobile_phone,
    'whatsapp_phone', p.whatsapp_phone,
    'avatar_url', p.avatar_url,
    'profile_avatar_url', p.avatar_url,
    'email', au.email
  )
  INTO v_profile
  FROM public.profiles p
  LEFT JOIN auth.users au
    ON au.id = p.id
  WHERE p.id = v_user_id;

  WITH membership_rows AS (
    SELECT
      sm.id AS member_id,
      sm.store_id,
      s.name AS store_name,
      s.slug AS store_slug,
      s.logo_url AS store_logo_url,
      sm.user_id,
      sm.role,
      sm.status,
      sm.status_reason,

      sm.internal_alias,
      sm.member_avatar_url,
      sm.member_email,
      sm.member_phone,
      sm.member_mobile_phone,
      sm.member_whatsapp_phone,

      sm.onboarding_required,
      sm.onboarding_completed_at,

      p.name AS profile_name,
      p.avatar_url AS profile_avatar_url,

      COALESCE(sm.permissions, '{}'::jsonb) AS permissions,
      COALESCE(sm.sensitive_actions, '{}'::jsonb) AS sensitive_actions,
      sm.custom_role_id,
      scr.name AS custom_role_name,
      scr.base_role AS custom_role_base_role,
      COALESCE(scr.permissions, '{}'::jsonb) AS custom_role_permissions,
      COALESCE(scr.sensitive_actions, '{}'::jsonb) AS custom_role_sensitive_actions,
      sm.created_at,
      sm.updated_at,
      sm.last_seen_at,

      CASE
        WHEN sm.role = 'owner' THEN 1
        WHEN sm.role = 'admin' THEN 2
        WHEN sm.role = 'manager' THEN 3
        WHEN sm.role = 'stock_operator' THEN 4
        WHEN sm.role = 'cashier' THEN 5
        WHEN sm.role = 'sales' THEN 6
        WHEN sm.role = 'staff' THEN 7
        WHEN sm.role = 'viewer' THEN 8
        ELSE 99
      END AS role_sort,

      CASE
        WHEN sm.status = 'active' THEN 1
        WHEN sm.status = 'suspended' THEN 2
        ELSE 9
      END AS status_sort
    FROM public.store_members sm
    JOIN public.stores s
      ON s.id = sm.store_id
    LEFT JOIN public.profiles p
      ON p.id = sm.user_id
    LEFT JOIN public.store_custom_roles scr
      ON scr.id = sm.custom_role_id
     AND scr.store_id = sm.store_id
     AND scr.active = true
    WHERE sm.user_id = v_user_id
      AND sm.status IN ('active', 'suspended')
  ),
  membership_json AS (
    SELECT
      jsonb_build_object(
        'member_id', mr.member_id,
        'store_id', mr.store_id,
        'store_name', mr.store_name,
        'store_slug', mr.store_slug,
        'store_logo_url', mr.store_logo_url,
        'user_id', mr.user_id,
        'role', mr.role,
        'status', mr.status,
        'status_reason', mr.status_reason,

        'internal_alias', mr.internal_alias,
        'member_avatar_url', mr.member_avatar_url,
        'member_email', mr.member_email,
        'member_phone', mr.member_phone,
        'member_mobile_phone', mr.member_mobile_phone,
        'member_whatsapp_phone', mr.member_whatsapp_phone,

        'onboarding_required', COALESCE(mr.onboarding_required, true),
        'onboarding_completed_at', mr.onboarding_completed_at,

        'profile_name', mr.profile_name,
        'profile_avatar_url', mr.profile_avatar_url,
        'avatar_url', COALESCE(mr.member_avatar_url, mr.profile_avatar_url),

        'permissions', mr.permissions,
        'sensitive_actions', mr.sensitive_actions,
        'custom_role_id', mr.custom_role_id,
        'custom_role_name', mr.custom_role_name,
        'custom_role_base_role', mr.custom_role_base_role,
        'custom_role_permissions', mr.custom_role_permissions,
        'custom_role_sensitive_actions', mr.custom_role_sensitive_actions,
        'created_at', mr.created_at,
        'updated_at', mr.updated_at,
        'last_seen_at', mr.last_seen_at,

        'is_owner', (mr.role = 'owner'),
        'is_primary_owner', false,

        'access_blocked', (mr.status = 'suspended'),
        'access_message',
          CASE
            WHEN mr.status = 'suspended'
              THEN COALESCE(
                NULLIF(trim(mr.status_reason), ''),
                'Seu acesso a esta loja está suspenso. Procure o responsável pela empresa.'
              )
            ELSE NULL
          END
      ) AS item,
      mr.role_sort,
      mr.status_sort,
      mr.created_at,
      mr.status
    FROM membership_rows mr
  ),
  aggregated AS (
    SELECT
      COALESCE(
        jsonb_agg(item ORDER BY status_sort, role_sort, created_at),
        '[]'::jsonb
      ) AS all_memberships
    FROM membership_json
  ),
  primary_row AS (
    SELECT item AS primary_membership
    FROM membership_json
    WHERE status = 'active'
    ORDER BY role_sort, created_at
    LIMIT 1
  )
  SELECT
    aggregated.all_memberships,
    primary_row.primary_membership
  INTO
    v_memberships,
    v_primary_membership
  FROM aggregated
  LEFT JOIN primary_row ON true;

  RETURN jsonb_build_object(
    'authenticated', true,
    'user_id', v_user_id,
    'profile', v_profile,
    'primary_membership', v_primary_membership,
    'memberships', COALESCE(v_memberships, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_current_user_security_context_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_user_store_permissions_v2"("p_store_id" "uuid") RETURNS TABLE("permission_code" "text", "role_allowed" boolean, "custom_role_override" boolean, "individual_override" boolean, "effective_allowed" boolean, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_member_id uuid;
  v_member_role text;
  v_member_permissions jsonb;
  v_custom_role_permissions jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  select
    sm.id,
    sm.role,
    coalesce(sm.permissions, '{}'::jsonb),
    coalesce(scr.permissions, '{}'::jsonb)
  into
    v_member_id,
    v_member_role,
    v_member_permissions,
    v_custom_role_permissions
  from public.store_members sm
  left join public.store_custom_roles scr
    on scr.id = sm.custom_role_id
   and scr.store_id = sm.store_id
   and scr.active = true
  where sm.store_id = p_store_id
    and sm.user_id = auth.uid()
    and sm.status = 'active'
  order by
    case when sm.role = 'owner' then 0 else 1 end,
    case when scr.id is not null then 0 else 1 end,
    sm.updated_at desc nulls last,
    sm.created_at desc nulls last
  limit 1;

  if v_member_id is null then
    raise exception 'Usuário não possui vínculo ativo com esta loja.';
  end if;

  return query
  with catalog as (
    select
      c.permission_key
    from public.store_permission_catalog c
    where c.active = true
  ),
  role_permissions as (
    select
      srpt.permission_code,
      coalesce(srpt.allowed, false) as allowed
    from public.store_role_permission_templates srpt
    where srpt.store_id = p_store_id
      and srpt.role = v_member_role
  ),
  resolved as (
    select
      c.permission_key as permission_code,

      case
        when v_member_role = 'owner' then true
        else coalesce(rp.allowed, false)
      end as role_allowed,

      case
        when v_custom_role_permissions ? c.permission_key
          then (v_custom_role_permissions ->> c.permission_key)::boolean
        else null
      end as custom_role_override,

      case
        when v_member_permissions ? c.permission_key
          then (v_member_permissions ->> c.permission_key)::boolean
        else null
      end as individual_override
    from catalog c
    left join role_permissions rp
      on rp.permission_code = c.permission_key
  )
  select
    r.permission_code,
    r.role_allowed,
    r.custom_role_override,
    r.individual_override,
    coalesce(
      r.individual_override,
      r.custom_role_override,
      r.role_allowed,
      false
    ) as effective_allowed,
    case
      when r.individual_override is not null then 'member_override'
      when r.custom_role_override is not null then 'custom_role'
      when v_member_role = 'owner' then 'owner'
      when r.role_allowed is true then 'role'
      else 'default'
    end as source
  from resolved r
  order by r.permission_code;
end;
$$;


ALTER FUNCTION "public"."get_current_user_store_permissions_v2"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_360_safe"("p_store_id" "uuid", "p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_customer jsonb;
  v_orders jsonb;
  v_loyalty_transactions jsonb;
  v_addresses jsonb;
  v_consents jsonb;
begin
  if p_store_id is null or p_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_parameters');
  end if;

  if coalesce(auth.role(), '') in ('anon', 'authenticated') then
    if auth.uid() is null
       or not (
         public.app_is_store_owner(p_store_id)
         or public.user_has_store_permission(p_store_id, 'customers.view')
         or public.user_has_store_permission(p_store_id, 'customers.manage')
       ) then
      return jsonb_build_object(
        'ok', false,
        'error', 'access_denied'
      );
    end if;
  end if;

  select to_jsonb(q)
  into v_customer
  from (
    select
      c.*,
      ft.name as current_tier_name,
      ft.color as current_tier_color,
      ft.min_points as current_tier_min_points
    from public.customers c
    left join public.fidelity_tiers ft
      on ft.id = c.current_tier_id
    where c.id = p_customer_id
      and c.store_id = p_store_id
  ) q;

  if v_customer is null then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'order_code', o.order_code,
        'status', o.status,
        'total', o.total,
        'sales_channel', o.sales_channel,
        'fulfillment_type', o.fulfillment_type,
        'payment_method_code', o.payment_method_code,
        'delivery_method_code', o.delivery_method_code,
        'created_at', o.created_at,
        'confirmed_at', o.confirmed_at,
        'completed_at', o.completed_at
      )
      order by o.created_at desc
    ),
    '[]'::jsonb
  )
  into v_orders
  from public.orders o
  where o.customer_id = p_customer_id
    and o.store_id = p_store_id
  limit 50;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', lt.id,
        'type', lt.type,
        'points', lt.points,
        'description', lt.description,
        'order_id', lt.order_id,
        'created_at', lt.created_at
      )
      order by lt.created_at desc
    ),
    '[]'::jsonb
  )
  into v_loyalty_transactions
  from public.loyalty_transactions lt
  where lt.customer_id = p_customer_id
  limit 50;

  select coalesce(jsonb_agg(to_jsonb(ca) order by ca.created_at desc), '[]'::jsonb)
  into v_addresses
  from public.customer_addresses ca
  where ca.customer_id = p_customer_id;

  select coalesce(jsonb_agg(to_jsonb(cl) order by cl.created_at desc), '[]'::jsonb)
  into v_consents
  from public.customer_consent_logs cl
  where cl.customer_id = p_customer_id;

  return jsonb_build_object(
    'ok', true,
    'customer', v_customer,
    'orders', v_orders,
    'loyalty_transactions', v_loyalty_transactions,
    'addresses', v_addresses,
    'consents', v_consents
  );
end;
$$;


ALTER FUNCTION "public"."get_customer_360_safe"("p_store_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_orders_summary"("p_store_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_orders_count integer := 0;
  v_total_sales numeric := 0;
  v_completed_count integer := 0;
  v_reserved_count integer := 0;
  v_cancelled_count integer := 0;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(total), 0),
    COUNT(*) FILTER (WHERE status = 'completed')::integer,
    COUNT(*) FILTER (WHERE status = 'reserved')::integer,
    COUNT(*) FILTER (WHERE status = 'cancelled')::integer
  INTO
    v_orders_count,
    v_total_sales,
    v_completed_count,
    v_reserved_count,
    v_cancelled_count
  FROM public.orders
  WHERE store_id = p_store_id
    AND created_at >= p_start_at
    AND created_at < p_end_at;

  RETURN jsonb_build_object(
    'ok', true,
    'summary', jsonb_build_object(
      'orders_count', v_orders_count,
      'total_sales', v_total_sales,
      'completed_count', v_completed_count,
      'reserved_count', v_reserved_count,
      'cancelled_count', v_cancelled_count
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_dashboard_orders_summary"("p_store_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_recent_orders"("p_store_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_orders jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id', 'orders', '[]'::jsonb);
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied', 'orders', '[]'::jsonb);
    END IF;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'order_code', q.order_code,
        'total', q.total,
        'created_at', q.created_at,
        'status', q.status,
        'customer_name', q.customer_name,
        'customer_phone', q.customer_phone
      )
      ORDER BY q.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_orders
  FROM (
    SELECT
      o.id,
      o.order_code,
      o.total,
      o.created_at,
      o.status::text AS status,
      o.customer_name,
      o.customer_phone
    FROM public.orders o
    WHERE o.store_id = p_store_id
    ORDER BY o.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 5), 20))
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'orders', v_orders
  );
END;
$$;


ALTER FUNCTION "public"."get_dashboard_recent_orders"("p_store_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_default_admin_landing_path_v3"("p_store_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if public.app_is_store_owner(p_store_id) then
    return '/admin';
  end if;

  if public.user_has_store_permission(p_store_id, 'dashboard.view') then
    return '/admin';
  end if;

  if public.user_has_store_permission(p_store_id, 'commercial.view') then
    return '/admin/commercial-dashboard';
  end if;

  if public.user_has_store_permission(p_store_id, 'orders.view') then
    return '/admin/orders';
  end if;

  if public.user_has_store_permission(p_store_id, 'products.view') then
    return '/admin/products';
  end if;

  if public.user_has_store_permission(p_store_id, 'stock.view') then
    return '/admin/stock';
  end if;

  if public.user_has_store_permission(p_store_id, 'customers.view') then
    return '/admin/customers';
  end if;

  if public.user_has_store_permission(p_store_id, 'cashbook.view') then
    return '/admin/cashbook';
  end if;

  if public.user_has_store_permission(p_store_id, 'settings.view')
     and public.user_has_store_permission(p_store_id, 'settings.store.view') then
    return '/admin/settings?tab=store';
  end if;

  return '/admin/my-profile';
end;
$$;


ALTER FUNCTION "public"."get_default_admin_landing_path_v3"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_default_stock_location_id"("p_store_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_location_id uuid;
begin
    select sl.id
      into v_location_id
      from public.stock_locations sl
     where sl.store_id = p_store_id
       and sl.is_default = true
       and sl.active = true
     order by sl.created_at asc
     limit 1;

    if v_location_id is null then
        raise exception 'Nenhum local de estoque default ativo encontrado para a loja %', p_store_id
            using errcode = 'P0001';
    end if;

    return v_location_id;
end;
$$;


ALTER FUNCTION "public"."get_default_stock_location_id"("p_store_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_default_stock_location_id"("p_store_id" "uuid") IS 'Retorna o location_id default ativo da store.';



CREATE OR REPLACE FUNCTION "public"."get_effective_store_member_permissions_v2"("p_store_id" "uuid", "p_member_id" "uuid") RETURNS TABLE("permission_code" "text", "role_allowed" boolean, "custom_role_override" boolean, "individual_override" boolean, "effective_allowed" boolean, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_member_role text;
  v_member_permissions jsonb;
  v_custom_role_permissions jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if p_member_id is null then
    raise exception 'Membro não informado.';
  end if;

  if not public.can_access_security_section(p_store_id, 'user_permissions', false) then
    raise exception 'Você não tem permissão para visualizar permissões por usuário.';
  end if;

  select
    sm.role,
    coalesce(sm.permissions, '{}'::jsonb),
    coalesce(scr.permissions, '{}'::jsonb)
  into
    v_member_role,
    v_member_permissions,
    v_custom_role_permissions
  from public.store_members sm
  left join public.store_custom_roles scr
    on scr.id = sm.custom_role_id
   and scr.store_id = sm.store_id
   and scr.active = true
  where sm.id = p_member_id
    and sm.store_id = p_store_id
  limit 1;

  if v_member_role is null then
    raise exception 'Membro não encontrado nesta loja.';
  end if;

  return query
  with catalog as (
    select c.permission_key
    from public.store_permission_catalog c
    where c.active = true
  ),
  role_permissions as (
    select
      srpt.permission_code,
      coalesce(srpt.allowed, false) as allowed
    from public.store_role_permission_templates srpt
    where srpt.store_id = p_store_id
      and srpt.role = v_member_role
  ),
  resolved as (
    select
      c.permission_key as permission_code,

      coalesce(rp.allowed, false) as role_allowed,

      case
        when v_custom_role_permissions ? c.permission_key
          then (v_custom_role_permissions ->> c.permission_key)::boolean
        else null
      end as custom_role_override,

      case
        when v_member_permissions ? c.permission_key
          then (v_member_permissions ->> c.permission_key)::boolean
        else null
      end as individual_override
    from catalog c
    left join role_permissions rp
      on rp.permission_code = c.permission_key
  )
  select
    r.permission_code,
    r.role_allowed,
    r.custom_role_override,
    r.individual_override,
    coalesce(
      r.individual_override,
      r.custom_role_override,
      r.role_allowed,
      false
    ) as effective_allowed,
    case
      when r.individual_override is not null then 'member_override'
      when r.custom_role_override is not null then 'custom_role'
      when r.role_allowed is not null then 'role'
      else 'default'
    end as source
  from resolved r
  order by r.permission_code;
end;
$$;


ALTER FUNCTION "public"."get_effective_store_member_permissions_v2"("p_store_id" "uuid", "p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_store_permissions"("p_store_id" "uuid") RETURNS TABLE("permission_code" "text", "module" "text", "action" "text", "label" "text", "description" "text", "risk_level" "text", "allowed" boolean, "source" "text", "role" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_role text;
    v_member_permissions jsonb;
    v_custom_role_permissions jsonb;
    v_is_owner boolean;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN;
    END IF;

    SELECT
        sm.role,
        COALESCE(sm.permissions, '{}'::jsonb),
        COALESCE(scr.permissions, '{}'::jsonb),
        (sm.role = 'owner')
    INTO
        v_role,
        v_member_permissions,
        v_custom_role_permissions,
        v_is_owner
    FROM public.store_members sm
    LEFT JOIN public.store_custom_roles scr
        ON scr.id = sm.custom_role_id
       AND scr.store_id = sm.store_id
       AND scr.active = true
    WHERE sm.store_id = p_store_id
      AND sm.user_id = auth.uid()
      AND sm.status = 'active'
    ORDER BY
        CASE sm.role
            WHEN 'owner' THEN 1
            WHEN 'admin' THEN 2
            WHEN 'manager' THEN 3
            WHEN 'stock_operator' THEN 4
            WHEN 'cashier' THEN 5
            WHEN 'sales' THEN 6
            WHEN 'staff' THEN 7
            WHEN 'viewer' THEN 8
            ELSE 99
        END
    LIMIT 1;

    IF v_role IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        c.code AS permission_code,
        c.module,
        c.action,
        c.label,
        c.description,
        c.risk_level,
        CASE
            WHEN v_is_owner THEN true
            WHEN COALESCE((v_member_permissions ->> 'all')::boolean, false) THEN true
            WHEN v_member_permissions ? c.code THEN COALESCE((v_member_permissions ->> c.code)::boolean, false)
            WHEN v_custom_role_permissions ? c.code THEN COALESCE((v_custom_role_permissions ->> c.code)::boolean, false)
            ELSE COALESCE(t.allowed, false)
        END AS allowed,
        CASE
            WHEN v_is_owner THEN 'owner'
            WHEN COALESCE((v_member_permissions ->> 'all')::boolean, false) THEN 'member_override_all'
            WHEN v_member_permissions ? c.code THEN 'member_override'
            WHEN v_custom_role_permissions ? c.code THEN 'custom_role_override'
            WHEN t.source IS NOT NULL THEN t.source
            ELSE 'default_denied'
        END AS source,
        v_role AS role
    FROM public.security_permission_catalog c
    LEFT JOIN public.store_role_permission_templates t
        ON t.store_id = p_store_id
       AND t.role = v_role
       AND t.permission_code = c.code
    WHERE c.active = true
    ORDER BY c.sort_order, c.code;
END;
$$;


ALTER FUNCTION "public"."get_effective_store_permissions"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_balance_for_update"("p_store_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inventory_balances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_row public.inventory_balances;
begin
    insert into public.inventory_balances (
        store_id,
        product_id,
        variant_id,
        on_hand,
        reserved,
        updated_at
    )
    values (
        p_store_id,
        p_product_id,
        p_variant_id,
        0,
        0,
        now()
    )
    on conflict (
        store_id,
        product_id,
        coalesce(variant_id, '00000000-0000-0000-0000-000000000000'::uuid)
    )
    do nothing;

    select *
      into v_row
      from public.inventory_balances ib
     where ib.store_id = p_store_id
       and ib.product_id = p_product_id
       and (
            (p_variant_id is null and ib.variant_id is null)
            or ib.variant_id = p_variant_id
       )
     for update;

    if v_row.id is null then
        raise exception 'Não foi possível obter saldo consolidado para store %, product %, variant %',
            p_store_id, p_product_id, p_variant_id
            using errcode = 'P0001';
    end if;

    return v_row;
end;
$$;


ALTER FUNCTION "public"."get_inventory_balance_for_update"("p_store_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_criticality_summary"("p_store_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("store_id" "uuid", "total_products" bigint, "global_stockout" bigint, "global_critical" bigint, "global_attention" bigint, "global_excess" bigint, "products_with_location_stockout" bigint, "products_with_location_critical" bigint, "recommended_buy" bigint, "recommended_transfer" bigint, "recommended_monitor" bigint, "recommended_review_excess" bigint, "recommended_ok" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  SELECT
    g.store_id,

    COUNT(*)::bigint AS total_products,

    COUNT(*) FILTER (
      WHERE g.global_status = 'global_stockout'
    )::bigint AS global_stockout,

    COUNT(*) FILTER (
      WHERE g.global_status = 'global_critical'
    )::bigint AS global_critical,

    COUNT(*) FILTER (
      WHERE g.global_status = 'global_attention'
    )::bigint AS global_attention,

    COUNT(*) FILTER (
      WHERE g.global_status = 'global_excess'
    )::bigint AS global_excess,

    COUNT(*) FILTER (
      WHERE g.location_stockout_count > 0
    )::bigint AS products_with_location_stockout,

    COUNT(*) FILTER (
      WHERE g.location_critical_count > 0
    )::bigint AS products_with_location_critical,

    COUNT(*) FILTER (
      WHERE g.recommended_action = 'buy'
    )::bigint AS recommended_buy,

    COUNT(*) FILTER (
      WHERE g.recommended_action = 'transfer'
    )::bigint AS recommended_transfer,

    COUNT(*) FILTER (
      WHERE g.recommended_action = 'monitor'
    )::bigint AS recommended_monitor,

    COUNT(*) FILTER (
      WHERE g.recommended_action = 'review_excess'
    )::bigint AS recommended_review_excess,

    COUNT(*) FILTER (
      WHERE g.recommended_action = 'ok'
    )::bigint AS recommended_ok

  FROM public.get_inventory_management_products(p_store_id, NULL, 1000) g
  GROUP BY g.store_id;
END;
$$;


