CREATE OR REPLACE FUNCTION "public"."get_inventory_location_balance_for_update"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inventory_location_balances"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_row public.inventory_location_balances;
begin
    perform public.ensure_inventory_location_balance(
        p_store_id,
        p_location_id,
        p_product_id,
        p_variant_id
    );

    select *
      into v_row
      from public.inventory_location_balances ilb
     where ilb.store_id = p_store_id
       and ilb.location_id = p_location_id
       and ilb.product_id = p_product_id
       and (
            (p_variant_id is null and ilb.variant_id is null)
            or ilb.variant_id = p_variant_id
       )
     for update;

    if v_row.id is null then
        raise exception 'Não foi possível obter saldo por local para store %, location %, product %, variant %',
            p_store_id, p_location_id, p_product_id, p_variant_id
            using errcode = 'P0001';
    end if;

    return v_row;
end;
$$;


ALTER FUNCTION "public"."get_inventory_location_balance_for_update"("p_store_id" "uuid", "p_location_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_management_products"("p_store_id" "uuid" DEFAULT NULL::"uuid", "p_recommended_action" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "product_active" boolean, "discontinued" boolean, "is_discontinued" boolean, "global_min_stock" numeric, "global_max_stock" numeric, "global_on_hand" numeric, "global_reserved" numeric, "global_available" numeric, "global_status" "text", "total_locations" integer, "active_locations" integer, "sales_locations" integer, "location_stockout_count" integer, "location_critical_count" integer, "location_excess_count" integer, "locations_with_available_stock" integer, "possible_source_locations" integer, "alert_locations" "jsonb", "recommended_action" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  WITH location_counts AS (
    SELECT
      sl.store_id,

      GREATEST(
        COUNT(*) FILTER (
          WHERE sl.active = true
            AND (
              sl.allow_sales = true
              OR sl.allow_reservations = true
              OR sl.is_default = true
            )
        ),
        1
      )::numeric AS relevant_location_count,

      COUNT(*) FILTER (
        WHERE sl.active = true
      )::integer AS active_locations,

      COUNT(*) FILTER (
        WHERE sl.active = true
          AND sl.allow_sales = true
      )::integer AS sales_locations,

      COUNT(*)::integer AS total_locations

    FROM public.stock_locations sl
    WHERE sl.store_id = p_store_id
    GROUP BY sl.store_id
  ),

  location_rows AS (
    SELECT
      p.store_id,
      p.id AS product_id,
      p.name AS product_name,
      p.category_id,
      COALESCE(p.active, true) AS product_active,
      COALESCE(p.discontinued, false) AS discontinued,
      COALESCE(p.is_discontinued, false) AS is_discontinued,

      COALESCE(p.min_stock, 0)::numeric AS global_min_stock,
      COALESCE(p.max_stock, 0)::numeric AS global_max_stock,

      sl.id AS location_id,
      sl.code AS location_code,
      sl.name AS location_name,
      sl.active AS location_active,
      sl.allow_sales,
      sl.allow_reservations,
      sl.is_default,
      sl.sort_order,

      COALESCE(ilb.on_hand, 0)::numeric AS location_on_hand,
      COALESCE(ilb.reserved, 0)::numeric AS location_reserved,
      (
        COALESCE(ilb.on_hand, 0)
        - COALESCE(ilb.reserved, 0)
      )::numeric AS location_available,

      CASE
        WHEN COALESCE(p.min_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.min_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_min_stock,

      CASE
        WHEN COALESCE(p.max_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.max_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_max_stock

    FROM public.products p
    JOIN public.stock_locations sl
      ON sl.store_id = p.store_id
    LEFT JOIN public.inventory_location_balances ilb
      ON ilb.store_id = p.store_id
     AND ilb.product_id = p.id
     AND ilb.location_id = sl.id
    LEFT JOIN location_counts lc
      ON lc.store_id = p.store_id
    WHERE p.store_id = p_store_id
  ),

  classified_locations AS (
    SELECT
      lr.*,

      CASE
        WHEN lr.product_active = false
          OR lr.discontinued = true
          OR lr.is_discontinued = true
        THEN 'product_inactive'

        WHEN lr.location_active = false
        THEN 'location_inactive'

        WHEN lr.provisional_location_min_stock <= 0
         AND lr.location_available <> 0
        THEN 'monitor_only'

        WHEN lr.provisional_location_min_stock <= 0
        THEN 'not_configured'

        WHEN lr.location_available <= 0
        THEN 'location_stockout'

        WHEN lr.location_available <= lr.provisional_location_min_stock
        THEN 'location_critical'

        WHEN lr.provisional_location_max_stock > 0
         AND lr.location_available >= lr.provisional_location_max_stock
        THEN 'location_excess'

        ELSE 'location_ok'
      END AS location_status

    FROM location_rows lr
  ),

  product_agg AS (
    SELECT
      cl.store_id,
      cl.product_id,
      cl.product_name,
      cl.category_id,
      cl.product_active,
      cl.discontinued,
      cl.is_discontinued,

      MAX(cl.global_min_stock)::numeric AS global_min_stock,
      MAX(cl.global_max_stock)::numeric AS global_max_stock,

      SUM(cl.location_on_hand)::numeric AS global_on_hand,
      SUM(cl.location_reserved)::numeric AS global_reserved,
      SUM(cl.location_available)::numeric AS global_available,

      COUNT(*)::integer AS total_locations,

      COUNT(*) FILTER (
        WHERE cl.location_active = true
      )::integer AS active_locations,

      COUNT(*) FILTER (
        WHERE cl.location_active = true
          AND cl.allow_sales = true
      )::integer AS sales_locations,

      COUNT(*) FILTER (
        WHERE cl.location_status = 'location_stockout'
      )::integer AS location_stockout_count,

      COUNT(*) FILTER (
        WHERE cl.location_status = 'location_critical'
      )::integer AS location_critical_count,

      COUNT(*) FILTER (
        WHERE cl.location_status = 'location_excess'
      )::integer AS location_excess_count,

      COUNT(*) FILTER (
        WHERE cl.location_active = true
          AND cl.location_available > 0
      )::integer AS locations_with_available_stock,

      COUNT(*) FILTER (
        WHERE cl.location_active = true
          AND cl.location_available > cl.provisional_location_min_stock
      )::integer AS possible_source_locations,

      COALESCE(
        JSONB_AGG(
          JSONB_BUILD_OBJECT(
            'location_id', cl.location_id,
            'location_code', cl.location_code,
            'location_name', cl.location_name,
            'location_status', cl.location_status,
            'available', cl.location_available,
            'on_hand', cl.location_on_hand,
            'reserved', cl.location_reserved,
            'allow_sales', cl.allow_sales,
            'is_default', cl.is_default
          )
          ORDER BY cl.sort_order, cl.location_name
        ) FILTER (
          WHERE cl.location_status IN (
            'location_stockout',
            'location_critical',
            'location_excess'
          )
        ),
        '[]'::jsonb
      ) AS alert_locations

    FROM classified_locations cl
    GROUP BY
      cl.store_id,
      cl.product_id,
      cl.product_name,
      cl.category_id,
      cl.product_active,
      cl.discontinued,
      cl.is_discontinued
  ),

  product_classified AS (
    SELECT
      pa.*,

      CASE
        WHEN pa.product_active = false
          OR pa.discontinued = true
          OR pa.is_discontinued = true
        THEN 'product_inactive'

        WHEN pa.global_min_stock > 0
         AND pa.global_available <= 0
        THEN 'global_stockout'

        WHEN pa.global_min_stock > 0
         AND pa.global_available <= pa.global_min_stock
        THEN 'global_critical'

        WHEN pa.global_min_stock > 0
         AND pa.global_available <= CEIL(pa.global_min_stock * 1.5)
        THEN 'global_attention'

        WHEN pa.global_max_stock > 0
         AND pa.global_available >= pa.global_max_stock
        THEN 'global_excess'

        ELSE 'global_ok'
      END AS global_status

    FROM product_agg pa
  ),

  product_actions AS (
    SELECT
      pc.*,

      CASE
        WHEN pc.global_status IN ('global_stockout', 'global_critical')
        THEN 'buy'

        WHEN (
          pc.location_stockout_count > 0
          OR pc.location_critical_count > 0
        )
        AND pc.possible_source_locations > 0
        AND pc.global_status NOT IN ('global_stockout', 'global_critical')
        THEN 'transfer'

        WHEN pc.global_status = 'global_excess'
        THEN 'review_excess'

        WHEN pc.global_status = 'global_attention'
          OR pc.location_critical_count > 0
        THEN 'monitor'

        ELSE 'ok'
      END AS recommended_action

    FROM product_classified pc
  )

  SELECT
    pa.store_id,
    pa.product_id,
    pa.product_name,
    pa.category_id,
    pa.product_active,
    pa.discontinued,
    pa.is_discontinued,

    pa.global_min_stock,
    pa.global_max_stock,
    pa.global_on_hand,
    pa.global_reserved,
    pa.global_available,
    pa.global_status,

    pa.total_locations,
    pa.active_locations,
    pa.sales_locations,
    pa.location_stockout_count,
    pa.location_critical_count,
    pa.location_excess_count,
    pa.locations_with_available_stock,
    pa.possible_source_locations,

    pa.alert_locations,
    pa.recommended_action

  FROM product_actions pa
  WHERE
    p_recommended_action IS NULL
    OR pa.recommended_action = p_recommended_action
  ORDER BY
    CASE pa.recommended_action
      WHEN 'buy' THEN 1
      WHEN 'transfer' THEN 2
      WHEN 'monitor' THEN 3
      WHEN 'review_excess' THEN 4
      ELSE 5
    END,
    pa.product_name
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
END;
$$;


ALTER FUNCTION "public"."get_inventory_management_products"("p_store_id" "uuid", "p_recommended_action" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_inventory_management_products"("p_store_id" "uuid", "p_recommended_action" "text", "p_limit" integer) IS 'EXCEÇÃO INTENCIONAL 6.4: RPC gerencial de produtos/estoque. Mantida para authenticated.';



CREATE OR REPLACE FUNCTION "public"."get_inventory_position_by_store"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "location_id" "uuid", "location_code" "text", "location_name" "text", "location_type" "text", "location_active" boolean, "product_id" "uuid", "product_name" "text", "category_id" "uuid", "price" numeric, "product_active" boolean, "min_stock" numeric, "max_stock" numeric, "last_entry_unit_cost" numeric, "variant_id" "uuid", "on_hand" numeric, "reserved" numeric, "available" numeric, "stock_status" "text", "updated_at" timestamp with time zone, "global_on_hand" numeric, "global_reserved" numeric, "global_available" numeric, "global_min_stock" numeric, "global_max_stock" numeric, "global_status" "text", "provisional_location_min_stock" numeric, "provisional_location_max_stock" numeric, "location_status" "text", "possible_source_locations" integer, "source_locations" "jsonb", "recommended_action" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  WITH location_counts AS (
    SELECT
      sl.store_id,
      GREATEST(
        COUNT(*) FILTER (
          WHERE sl.active = true
            AND (
              sl.allow_sales = true
              OR sl.allow_reservations = true
              OR sl.is_default = true
            )
        ),
        1
      )::numeric AS relevant_location_count
    FROM public.stock_locations sl
    WHERE sl.store_id = p_store_id
    GROUP BY sl.store_id
  ),

  balances AS (
    SELECT
      ilb.store_id,
      ilb.location_id,
      ilb.product_id,
      ilb.variant_id,
      SUM(COALESCE(ilb.on_hand, 0))::numeric AS on_hand,
      SUM(COALESCE(ilb.reserved, 0))::numeric AS reserved,
      MAX(ilb.updated_at) AS updated_at
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = p_store_id
    GROUP BY
      ilb.store_id,
      ilb.location_id,
      ilb.product_id,
      ilb.variant_id
  ),

  base AS (
    SELECT
      p.store_id,
      sl.id AS location_id,
      sl.code AS location_code,
      sl.name AS location_name,
      sl.type::text AS location_type,
      sl.active AS location_active,
      sl.allow_sales,
      sl.allow_reservations,
      sl.is_default,
      sl.sort_order,

      p.id AS product_id,
      p.name AS product_name,
      p.category_id,
      p.price,
      COALESCE(p.active, true) AS product_active,
      COALESCE(p.discontinued, false) AS discontinued,
      COALESCE(p.is_discontinued, false) AS is_discontinued,
      COALESCE(p.min_stock, 0)::numeric AS global_min_stock,
      COALESCE(p.max_stock, 0)::numeric AS global_max_stock,
      p.last_entry_unit_cost,

      b.variant_id,
      COALESCE(b.on_hand, 0)::numeric AS on_hand,
      COALESCE(b.reserved, 0)::numeric AS reserved,
      (
        COALESCE(b.on_hand, 0)
        - COALESCE(b.reserved, 0)
      )::numeric AS available,
      COALESCE(b.updated_at, now()) AS updated_at,

      CASE
        WHEN COALESCE(p.min_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.min_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_min_stock,

      CASE
        WHEN COALESCE(p.max_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.max_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_max_stock

    FROM public.products p
    JOIN public.stock_locations sl
      ON sl.store_id = p.store_id
    LEFT JOIN balances b
      ON b.store_id = p.store_id
     AND b.product_id = p.id
     AND b.location_id = sl.id
    LEFT JOIN location_counts lc
      ON lc.store_id = p.store_id
    WHERE p.store_id = p_store_id
  ),

  global_balance AS (
    SELECT
      b.store_id,
      b.product_id,
      SUM(b.on_hand)::numeric AS global_on_hand,
      SUM(b.reserved)::numeric AS global_reserved,
      SUM(b.available)::numeric AS global_available
    FROM base b
    GROUP BY
      b.store_id,
      b.product_id
  ),

  classified AS (
    SELECT
      b.*,
      gb.global_on_hand,
      gb.global_reserved,
      gb.global_available,

      CASE
        WHEN b.product_active = false
          OR b.discontinued = true
          OR b.is_discontinued = true
        THEN 'product_inactive'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= 0
        THEN 'global_stockout'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= b.global_min_stock
        THEN 'global_critical'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= CEIL(b.global_min_stock * 1.5)
        THEN 'global_attention'

        WHEN b.global_max_stock > 0
         AND gb.global_available >= b.global_max_stock
        THEN 'global_excess'

        ELSE 'global_ok'
      END AS global_status,

      CASE
        WHEN b.product_active = false
          OR b.discontinued = true
          OR b.is_discontinued = true
        THEN 'product_inactive'

        WHEN b.location_active = false
        THEN 'location_inactive'

        WHEN b.provisional_location_min_stock <= 0
         AND b.available <> 0
        THEN 'monitor_only'

        WHEN b.provisional_location_min_stock <= 0
        THEN 'not_configured'

        WHEN b.available <= 0
        THEN 'location_stockout'

        WHEN b.available <= b.provisional_location_min_stock
        THEN 'location_critical'

        WHEN b.provisional_location_max_stock > 0
         AND b.available >= b.provisional_location_max_stock
        THEN 'location_excess'

        ELSE 'location_ok'
      END AS location_status

    FROM base b
    JOIN global_balance gb
      ON gb.store_id = b.store_id
     AND gb.product_id = b.product_id
  ),

  sources AS (
    SELECT
      c.store_id,
      c.product_id,
      COUNT(*) FILTER (
        WHERE c.location_active = true
          AND c.available > c.provisional_location_min_stock
      )::integer AS possible_source_locations,

      COALESCE(
        JSONB_AGG(
          JSONB_BUILD_OBJECT(
            'location_id', c.location_id,
            'location_code', c.location_code,
            'location_name', c.location_name,
            'available', c.available,
            'on_hand', c.on_hand,
            'reserved', c.reserved,
            'location_status', c.location_status
          )
          ORDER BY c.available DESC, c.location_name
        ) FILTER (
          WHERE c.location_active = true
            AND c.available > c.provisional_location_min_stock
        ),
        '[]'::jsonb
      ) AS source_locations

    FROM classified c
    GROUP BY
      c.store_id,
      c.product_id
  )

  SELECT
    c.store_id,
    c.location_id,
    c.location_code,
    c.location_name,
    c.location_type,
    c.location_active,
    c.product_id,
    c.product_name,
    c.category_id,
    c.price,
    c.product_active,
    c.global_min_stock AS min_stock,
    c.global_max_stock AS max_stock,
    c.last_entry_unit_cost,
    c.variant_id,
    c.on_hand,
    c.reserved,
    c.available,

    CASE
      WHEN c.location_status = 'product_inactive' THEN 'inactive'
      WHEN c.location_status = 'location_stockout' THEN 'out'
      WHEN c.location_status = 'location_critical' THEN 'low'
      WHEN c.location_status = 'location_excess' THEN 'over'
      ELSE 'ok'
    END AS stock_status,

    c.updated_at,

    c.global_on_hand,
    c.global_reserved,
    c.global_available,
    c.global_min_stock,
    c.global_max_stock,
    c.global_status,

    c.provisional_location_min_stock,
    c.provisional_location_max_stock,
    c.location_status,

    COALESCE(s.possible_source_locations, 0) AS possible_source_locations,
    COALESCE(s.source_locations, '[]'::jsonb) AS source_locations,

    CASE
      WHEN c.product_active = false
        OR c.discontinued = true
        OR c.is_discontinued = true
      THEN 'ok'

      WHEN c.global_status IN ('global_stockout', 'global_critical')
      THEN 'buy'

      WHEN c.location_status IN ('location_stockout', 'location_critical')
       AND COALESCE(s.possible_source_locations, 0) > 0
       AND c.global_status NOT IN ('global_stockout', 'global_critical')
      THEN 'transfer'

      WHEN c.global_status = 'global_excess'
       AND c.location_status NOT IN ('location_stockout', 'location_critical')
      THEN 'review_excess'

      WHEN c.global_status = 'global_attention'
        OR c.location_status = 'location_critical'
      THEN 'monitor'

      ELSE 'ok'
    END AS recommended_action

  FROM classified c
  LEFT JOIN sources s
    ON s.store_id = c.store_id
   AND s.product_id = c.product_id
  ORDER BY
    CASE
      WHEN c.location_status = 'location_stockout' THEN 1
      WHEN c.location_status = 'location_critical' THEN 2
      WHEN c.global_status IN ('global_stockout', 'global_critical') THEN 3
      WHEN c.location_status = 'location_excess' THEN 4
      ELSE 5
    END,
    c.location_name,
    c.product_name;
END;
$$;


