CREATE OR REPLACE FUNCTION "public"."get_inventory_transit_by_store"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "location_id" "uuid", "location_code" "text", "location_name" "text", "product_id" "uuid", "product_name" "text", "variant_id" "uuid", "in_transit_in" numeric, "in_transit_out" numeric, "net_in_transit" numeric, "incoming_transfers_count" bigint, "outgoing_transfers_count" bigint, "incoming_transfers" "jsonb", "outgoing_transfers" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  WITH open_items AS (
    SELECT
      st.store_id,
      st.id AS transfer_id,
      st.transfer_code,
      st.source_location_id,
      st.destination_location_id,
      sti.product_id,
      p.name AS product_name,
      sti.variant_id,
      GREATEST(
        COALESCE(sti.shipped_qty, 0) - COALESCE(sti.received_qty, 0),
        0
      )::numeric AS qty_in_transit,
      st.shipped_at,
      st.created_at
    FROM public.stock_transfers st
    JOIN public.stock_transfer_items sti
      ON sti.transfer_id = st.id
     AND sti.store_id = st.store_id
    JOIN public.products p
      ON p.id = sti.product_id
     AND p.store_id = st.store_id
    WHERE st.store_id = p_store_id
      AND st.status = 'shipped'::public.stock_transfer_status
      AND GREATEST(
        COALESCE(sti.shipped_qty, 0) - COALESCE(sti.received_qty, 0),
        0
      ) > 0
  ),

  incoming AS (
    SELECT
      oi.store_id,
      oi.destination_location_id AS location_id,
      oi.product_id,
      oi.product_name,
      oi.variant_id,
      SUM(oi.qty_in_transit)::numeric AS in_transit_in,
      COUNT(DISTINCT oi.transfer_id)::bigint AS incoming_transfers_count,
      jsonb_agg(
        jsonb_build_object(
          'transfer_id', oi.transfer_id,
          'transfer_code', oi.transfer_code,
          'qty', oi.qty_in_transit,
          'source_location_id', oi.source_location_id,
          'destination_location_id', oi.destination_location_id,
          'shipped_at', oi.shipped_at
        )
        ORDER BY oi.shipped_at DESC NULLS LAST, oi.created_at DESC
      ) AS incoming_transfers
    FROM open_items oi
    GROUP BY
      oi.store_id,
      oi.destination_location_id,
      oi.product_id,
      oi.product_name,
      oi.variant_id
  ),

  outgoing AS (
    SELECT
      oi.store_id,
      oi.source_location_id AS location_id,
      oi.product_id,
      oi.product_name,
      oi.variant_id,
      SUM(oi.qty_in_transit)::numeric AS in_transit_out,
      COUNT(DISTINCT oi.transfer_id)::bigint AS outgoing_transfers_count,
      jsonb_agg(
        jsonb_build_object(
          'transfer_id', oi.transfer_id,
          'transfer_code', oi.transfer_code,
          'qty', oi.qty_in_transit,
          'source_location_id', oi.source_location_id,
          'destination_location_id', oi.destination_location_id,
          'shipped_at', oi.shipped_at
        )
        ORDER BY oi.shipped_at DESC NULLS LAST, oi.created_at DESC
      ) AS outgoing_transfers
    FROM open_items oi
    GROUP BY
      oi.store_id,
      oi.source_location_id,
      oi.product_id,
      oi.product_name,
      oi.variant_id
  ),

  merged AS (
    SELECT
      COALESCE(i.store_id, o.store_id) AS store_id,
      COALESCE(i.location_id, o.location_id) AS location_id,
      COALESCE(i.product_id, o.product_id) AS product_id,
      COALESCE(i.product_name, o.product_name) AS product_name,
      COALESCE(i.variant_id, o.variant_id) AS variant_id,

      COALESCE(i.in_transit_in, 0)::numeric AS in_transit_in,
      COALESCE(o.in_transit_out, 0)::numeric AS in_transit_out,

      COALESCE(i.incoming_transfers_count, 0)::bigint AS incoming_transfers_count,
      COALESCE(o.outgoing_transfers_count, 0)::bigint AS outgoing_transfers_count,

      COALESCE(i.incoming_transfers, '[]'::jsonb) AS incoming_transfers,
      COALESCE(o.outgoing_transfers, '[]'::jsonb) AS outgoing_transfers
    FROM incoming i
    FULL OUTER JOIN outgoing o
      ON o.store_id = i.store_id
     AND o.location_id = i.location_id
     AND o.product_id = i.product_id
     AND (
       (o.variant_id IS NULL AND i.variant_id IS NULL)
       OR o.variant_id = i.variant_id
     )
  )

  SELECT
    m.store_id,
    sl.id AS location_id,
    sl.code AS location_code,
    sl.name AS location_name,
    m.product_id,
    m.product_name,
    m.variant_id,

    m.in_transit_in,
    m.in_transit_out,
    (m.in_transit_in - m.in_transit_out)::numeric AS net_in_transit,

    m.incoming_transfers_count,
    m.outgoing_transfers_count,

    m.incoming_transfers,
    m.outgoing_transfers
  FROM merged m
  JOIN public.stock_locations sl
    ON sl.id = m.location_id
   AND sl.store_id = m.store_id
  ORDER BY
    sl.name,
    m.product_name;
END;
$$;


