COMMENT ON FUNCTION "public"."get_inventory_transit_by_store"("p_store_id" "uuid") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC de estoque em trânsito por loja. SECURITY DEFINER usado para evitar stack depth/RLS, com validação interna.';



CREATE OR REPLACE FUNCTION "public"."get_login_store_options"() RETURNS TABLE("store_id" "uuid", "store_name" "text", "store_slug" "text", "store_logo_url" "text", "role" "text", "custom_role_id" "uuid", "custom_role_name" "text", "custom_role_base_role" "text", "status" "text", "status_reason" "text", "is_owner" boolean, "is_primary_owner" boolean, "access_blocked" boolean, "access_message" "text", "sort_order" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
    SELECT
        sm.store_id,
        COALESCE(s.name, s.slug, sm.store_id::text)::text AS store_name,
        s.slug::text AS store_slug,
        s.logo_url::text AS store_logo_url,
        sm.role::text AS role,
        scr.id AS custom_role_id,
        scr.name::text AS custom_role_name,
        scr.base_role::text AS custom_role_base_role,
        sm.status::text AS status,
        sm.status_reason::text AS status_reason,
        (sm.role = 'owner') AS is_owner,
        COALESCE(s.user_id = sm.user_id, false) AS is_primary_owner,
        (sm.status = 'suspended') AS access_blocked,
        CASE
            WHEN sm.status = 'suspended'
                THEN COALESCE(
                    NULLIF(trim(sm.status_reason), ''),
                    'Seu acesso a esta loja está suspenso. Procure o responsável pela empresa.'
                )
            ELSE NULL
        END::text AS access_message,
        CASE
            WHEN sm.status = 'active' AND sm.role = 'owner' THEN 1
            WHEN sm.status = 'active' AND sm.role = 'admin' THEN 2
            WHEN sm.status = 'active' AND sm.role = 'manager' THEN 3
            WHEN sm.status = 'active' THEN 4
            WHEN sm.status = 'suspended' THEN 20
            ELSE 99
        END AS sort_order
    FROM public.store_members sm
    JOIN public.stores s
        ON s.id = sm.store_id
    LEFT JOIN public.store_custom_roles scr
        ON scr.id = sm.custom_role_id
       AND scr.store_id = sm.store_id
       AND scr.active = true
    WHERE sm.user_id = auth.uid()
      AND sm.status IN ('active', 'suspended')
    ORDER BY
        sort_order,
        store_name;
$$;


ALTER FUNCTION "public"."get_login_store_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loyalty_advanced_settings_safe"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_program jsonb;
  v_tiers jsonb;
  v_point_rules jsonb;
  v_benefit_rules jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT to_jsonb(fp)
  INTO v_program
  FROM public.fidelity_programs fp
  WHERE fp.store_id = p_store_id
  ORDER BY fp.created_at DESC
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(to_jsonb(ft) ORDER BY ft.min_points), '[]'::jsonb)
  INTO v_tiers
  FROM public.fidelity_tiers ft
  WHERE ft.store_id = p_store_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(lpr) ORDER BY lpr.priority, lpr.created_at), '[]'::jsonb)
  INTO v_point_rules
  FROM public.loyalty_point_rules lpr
  WHERE lpr.store_id = p_store_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', br.id,
        'store_id', br.store_id,
        'code', br.code,
        'name', br.name,
        'description', br.description,
        'benefit_type', br.benefit_type,
        'target_type', br.target_type,
        'target_tier_id', br.target_tier_id,
        'target_tier_name', ft.name,
        'target_customer_id', br.target_customer_id,
        'target_customer_name', c.full_name,
        'target_customer_phone', c.phone,
        'target_tag', br.target_tag,
        'discount_percent', br.discount_percent,
        'discount_amount', br.discount_amount,
        'bonus_points', br.bonus_points,
        'free_delivery', br.free_delivery,
        'minimum_order_value', br.minimum_order_value,
        'max_uses_total', br.max_uses_total,
        'max_uses_per_customer', br.max_uses_per_customer,
        'active', br.active,
        'starts_at', br.starts_at,
        'ends_at', br.ends_at,
        'conditions', br.conditions,
        'metadata', br.metadata,
        'created_at', br.created_at,
        'updated_at', br.updated_at
      )
      ORDER BY br.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_benefit_rules
  FROM public.customer_benefit_rules br
  LEFT JOIN public.fidelity_tiers ft ON ft.id = br.target_tier_id
  LEFT JOIN public.customers c ON c.id = br.target_customer_id
  WHERE br.store_id = p_store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'program', COALESCE(v_program, 'null'::jsonb),
    'tiers', v_tiers,
    'point_rules', v_point_rules,
    'benefit_rules', v_benefit_rules
  );
END;
$$;


ALTER FUNCTION "public"."get_loyalty_advanced_settings_safe"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_marketing_center_safe"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_segments jsonb;
  v_campaigns jsonb;
  v_summary jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'total_segments', COALESCE(COUNT(*), 0),
    'active_segments', COALESCE(COUNT(*) FILTER (WHERE active = true), 0)
  )
  INTO v_summary
  FROM public.customer_segments
  WHERE store_id = p_store_id;

  v_summary := v_summary || (
    SELECT jsonb_build_object(
      'total_campaigns', COALESCE(COUNT(*), 0),
      'draft_campaigns', COALESCE(COUNT(*) FILTER (WHERE status = 'draft'), 0),
      'active_campaigns', COALESCE(COUNT(*) FILTER (WHERE status = 'active'), 0),
      'scheduled_campaigns', COALESCE(COUNT(*) FILTER (WHERE status = 'scheduled'), 0)
    )
    FROM public.promotion_campaigns
    WHERE store_id = p_store_id
  );

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'store_id', q.store_id,
        'code', q.code,
        'name', q.name,
        'description', q.description,
        'segment_type', q.segment_type,
        'active', q.active,
        'rules', q.rules,
        'members_count', q.members_count,
        'created_at', q.created_at,
        'updated_at', q.updated_at
      )
      ORDER BY q.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_segments
  FROM (
    SELECT
      cs.*,
      COALESCE(COUNT(csm.id) FILTER (WHERE csm.active = true), 0)::integer AS members_count
    FROM public.customer_segments cs
    LEFT JOIN public.customer_segment_members csm ON csm.segment_id = cs.id
    WHERE cs.store_id = p_store_id
    GROUP BY cs.id
    ORDER BY cs.created_at DESC
  ) q;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', pc.id,
        'store_id', pc.store_id,
        'code', pc.code,
        'name', pc.name,
        'description', pc.description,
        'campaign_type', pc.campaign_type,
        'status', pc.status,
        'target_type', pc.target_type,
        'target_segment_id', pc.target_segment_id,
        'target_segment_name', cs.name,
        'target_customer_id', pc.target_customer_id,
        'target_tag', pc.target_tag,
        'channel', pc.channel,
        'title', pc.title,
        'message_template', pc.message_template,
        'call_to_action', pc.call_to_action,
        'landing_url', pc.landing_url,
        'benefit_rule_id', pc.benefit_rule_id,
        'sent_count', pc.sent_count,
        'delivered_count', pc.delivered_count,
        'read_count', pc.read_count,
        'clicked_count', pc.clicked_count,
        'converted_count', pc.converted_count,
        'active', pc.active,
        'starts_at', pc.starts_at,
        'ends_at', pc.ends_at,
        'scheduled_at', pc.scheduled_at,
        'created_at', pc.created_at,
        'updated_at', pc.updated_at
      )
      ORDER BY pc.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_campaigns
  FROM public.promotion_campaigns pc
  LEFT JOIN public.customer_segments cs ON cs.id = pc.target_segment_id
  WHERE pc.store_id = p_store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'summary', v_summary,
    'segments', v_segments,
    'campaigns', v_campaigns
  );
END;
$$;


ALTER FUNCTION "public"."get_marketing_center_safe"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_pending_store_invites"() RETURNS TABLE("invite_id" "uuid", "store_id" "uuid", "store_name" "text", "store_slug" "text", "store_logo_url" "text", "email" "text", "role" "text", "status" "text", "invited_by" "uuid", "invited_by_email" "text", "invited_at" timestamp with time zone, "expires_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_email text;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT au.email::text
  INTO v_email
  FROM auth.users au
  WHERE au.id = v_user_id;

  IF v_email IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.store_member_invites i
  SET
    status = 'expired',
    updated_at = now()
  WHERE i.normalized_email = lower(btrim(v_email))
    AND i.status = 'pending'
    AND i.expires_at < now();

  RETURN QUERY
  SELECT
    i.id AS invite_id,
    i.store_id,
    s.name AS store_name,
    s.slug AS store_slug,
    s.logo_url AS store_logo_url,
    i.email,
    i.role,
    i.status,
    i.invited_by,
    i.invited_by_email,
    i.invited_at,
    i.expires_at,
    i.created_at
  FROM public.store_member_invites i
  JOIN public.stores s ON s.id = i.store_id
  WHERE i.normalized_email = lower(btrim(v_email))
    AND i.status = 'pending'
    AND i.expires_at >= now()
  ORDER BY i.invited_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_my_pending_store_invites"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_store_memberships"() RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "store_name" "text", "store_slug" "text", "store_logo_url" "text", "user_id" "uuid", "role" "text", "status" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "is_owner" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    sm.id AS member_id,
    sm.store_id,
    s.name AS store_name,
    s.slug AS store_slug,
    s.logo_url AS store_logo_url,
    sm.user_id,
    sm.role,
    sm.status,
    sm.permissions,
    sm.sensitive_actions,
    (sm.role = 'owner' OR s.user_id = auth.uid()) AS is_owner,
    sm.created_at,
    sm.updated_at
  FROM public.store_members sm
  JOIN public.stores s ON s.id = sm.store_id
  WHERE sm.user_id = auth.uid()
    AND sm.status = 'active'
  ORDER BY s.name;
$$;


ALTER FUNCTION "public"."get_my_store_memberships"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_visible_activity_logs"("p_store_id" "uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_action" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_name" "text", "action" "text", "display_action" "text", "details" "jsonb", "outcome" "text", "sensitive" boolean, "visible_to_member" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member_id uuid;
  v_user_name text;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  SELECT sm.id
  INTO v_member_id
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  LIMIT 1;

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Acesso não autorizado.';
  END IF;

  SELECT identity_row.user_name
  INTO v_user_name
  FROM public.get_user_display_identity(v_user_id) AS identity_row;

  RETURN QUERY
  WITH my_events AS (
    SELECT
      l.id,
      l.store_id,
      v_user_id AS user_id,
      COALESCE(v_user_name, 'Usuário') AS user_name,
      l.action,
      COALESCE(
        NULLIF(l.display_action, ''),
        public.translate_security_action_ptbr(l.action)
      ) AS display_action,
      l.details,
      l.outcome,
      COALESCE(l.sensitive, false) AS sensitive,
      COALESCE(l.visible_to_member, false) AS visible_to_member,
      l.created_at
    FROM public.store_security_logs l
    WHERE l.store_id = p_store_id
      AND (
        l.user_id = v_user_id
        OR l.details->>'target_user_id' = v_user_id::text
      )
      AND NOT (
        l.user_id <> v_user_id
        AND l.details->>'target_user_id' = v_user_id::text
        AND l.action IN (
          'store_member_role_changed',
          'store_custom_role_assigned',
          'store_custom_role_removed'
        )
      )
      AND (
        COALESCE(l.sensitive, false) = false
        OR COALESCE(l.visible_to_member, false) = true
        OR l.details->>'target_user_id' = v_user_id::text
      )

    UNION ALL

    SELECT
      smo.id,
      smo.store_id,
      smo.user_id,
      COALESCE(v_user_name, 'Usuário') AS user_name,
      smo.occurrence_type AS action,
      smo.title AS display_action,
      jsonb_build_object(
        'title', smo.title,
        'description', smo.description,
        'severity', smo.severity,
        'source', 'store_member_occurrences',
        'created_by', smo.created_by,
        'created_by_email', smo.created_by_email,
        'metadata', COALESCE(smo.metadata, '{}'::jsonb)
      ) AS details,
      smo.severity AS outcome,
      false AS sensitive,
      smo.visible_to_member,
      smo.occurred_at AS created_at
    FROM public.store_member_occurrences smo
    WHERE smo.store_id = p_store_id
      AND smo.member_id = v_member_id
      AND smo.user_id = v_user_id
      AND smo.visible_to_member = true

    UNION ALL

    SELECT
      r.id,
      r.store_id,
      r.user_id,
      COALESCE(v_user_name, 'Usuário') AS user_name,
      ('profile_request_' || r.status)::text AS action,
      CASE r.status
        WHEN 'pending' THEN 'Solicitação cadastral criada'
        WHEN 'awaiting_member_confirmation' THEN 'Solicitação aguardando conferência'
        WHEN 'correction_requested' THEN 'Correção solicitada pelo usuário'
        WHEN 'approved' THEN 'Solicitação cadastral aprovada'
        WHEN 'rejected' THEN 'Solicitação cadastral rejeitada'
        WHEN 'cancelled' THEN 'Solicitação cadastral cancelada'
        WHEN 'applied' THEN 'Alteração cadastral aplicada'
        ELSE 'Solicitação cadastral atualizada'
      END AS display_action,
      jsonb_build_object(
        'source', 'store_member_profile_change_requests',
        'request_id', r.id,
        'request_type', r.request_type,
        'status', r.status,
        'reason', r.reason,
        'admin_notes', r.admin_notes,
        'member_feedback', r.member_feedback,
        'requested_changes', CASE WHEN r.sensitive THEN '{}'::jsonb ELSE r.requested_changes END,
        'admin_proposed_changes', CASE WHEN r.sensitive THEN '{}'::jsonb ELSE r.admin_proposed_changes END,
        'applied_changes', CASE WHEN r.sensitive THEN '{}'::jsonb ELSE r.applied_changes END,
        'reviewed_by_email', r.reviewed_by_email,
        'proposed_by_email', r.proposed_by_email,
        'reviewed_at', r.reviewed_at,
        'proposed_at', r.proposed_at,
        'member_responded_at', r.member_responded_at,
        'applied_at', r.applied_at
      ) AS details,
      CASE
        WHEN r.status IN ('rejected', 'cancelled', 'correction_requested') THEN 'warning'
        ELSE 'success'
      END AS outcome,
      r.sensitive,
      r.visible_to_member,
      r.updated_at AS created_at
    FROM public.store_member_profile_change_requests r
    WHERE r.store_id = p_store_id
      AND r.member_id = v_member_id
      AND r.user_id = v_user_id
      AND r.visible_to_member = true
  )
  SELECT
    e.id,
    e.store_id,
    e.user_id,
    e.user_name,
    e.action,
    e.display_action,
    e.details,
    e.outcome,
    e.sensitive,
    e.visible_to_member,
    e.created_at
  FROM my_events e
  WHERE
    (p_start_date IS NULL OR e.created_at::date >= p_start_date)
    AND (p_end_date IS NULL OR e.created_at::date <= p_end_date)
    AND (
      p_action IS NULL
      OR e.action ILIKE '%' || p_action || '%'
      OR e.display_action ILIKE '%' || p_action || '%'
    )
    AND (
      p_outcome IS NULL
      OR e.outcome = p_outcome
    )
  ORDER BY e.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_my_visible_activity_logs"("p_store_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_action" "text", "p_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_visible_store_member_history"("p_store_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("event_id" "uuid", "event_at" timestamp with time zone, "event_type" "text", "event_label" "text", "severity" "text", "title" "text", "description" "text", "source" "text", "visible_to_member" boolean, "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  SELECT sm.id
  INTO v_member_id
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  LIMIT 1;

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  RETURN QUERY
  SELECT
    smo.id AS event_id,
    smo.occurred_at AS event_at,
    smo.occurrence_type AS event_type,
    CASE
      WHEN smo.occurrence_type = 'admission' THEN 'Admissão / início de acesso'
      WHEN smo.occurrence_type = 'suspension' THEN 'Suspensão de acesso'
      WHEN smo.occurrence_type = 'exit' THEN 'Desligamento'
      WHEN smo.occurrence_type = 'role_change' THEN 'Alteração de função'
      WHEN smo.occurrence_type = 'training' THEN 'Treinamento'
      WHEN smo.occurrence_type = 'warning' THEN 'Advertência'
      WHEN smo.occurrence_type = 'praise' THEN 'Elogio'
      WHEN smo.occurrence_type = 'absence' THEN 'Ausência'
      WHEN smo.occurrence_type = 'incident' THEN 'Incidente'
      WHEN smo.occurrence_type = 'note' THEN 'Observação'
      WHEN smo.occurrence_type = 'other'
           AND smo.metadata->>'event_type' = 'return_from_suspension'
        THEN 'Retorno de suspensão'
      WHEN smo.occurrence_type = 'other'
           AND smo.metadata->>'event_type' = 'reactivation'
        THEN 'Reativação de acesso'
      ELSE 'Ocorrência'
    END::text AS event_label,
    smo.severity,
    smo.title,
    COALESCE(smo.description, '') AS description,
    'store_member_occurrences'::text AS source,
    smo.visible_to_member,
    smo.metadata
  FROM public.store_member_occurrences smo
  WHERE smo.store_id = p_store_id
    AND smo.member_id = v_member_id
    AND (
      smo.visible_to_member = true
      OR smo.occurrence_type IN ('admission', 'role_change', 'training')
      OR (
        smo.occurrence_type = 'other'
        AND smo.metadata->>'event_type' IN ('return_from_suspension', 'reactivation')
      )
    )
  ORDER BY smo.occurred_at DESC, smo.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 100), 300));
END;
$$;


ALTER FUNCTION "public"."get_my_visible_store_member_history"("p_store_id" "uuid", "p_limit" integer) OWNER TO "postgres";


