    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "type" "public"."stock_location_type" DEFAULT 'main'::"public"."stock_location_type" NOT NULL,
    "description" "text",
    "active" boolean DEFAULT true NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "allow_sales" boolean DEFAULT false NOT NULL,
    "allow_reservations" boolean DEFAULT false NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."stock_locations" OWNER TO "postgres";


COMMENT ON TABLE "public"."stock_locations" IS 'Locais internos de estoque por store. Ex.: Estoque Principal, Loja, Avaria, Em Trânsito.';



CREATE OR REPLACE FUNCTION "public"."get_or_create_transit_location"("p_store_id" "uuid") RETURNS "public"."stock_locations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_location public.stock_locations;
begin
    select *
      into v_location
      from public.stock_locations sl
     where sl.store_id = p_store_id
       and sl.type = 'transit'::public.stock_location_type
       and sl.active = true
     order by sl.sort_order, sl.created_at
     limit 1;

    if v_location.id is not null then
        return v_location;
    end if;

    insert into public.stock_locations (
        store_id,
        code,
        name,
        type,
        description,
        active,
        is_default,
        allow_sales,
        allow_reservations,
        sort_order,
        metadata
    )
    values (
        p_store_id,
        'TRANSIT',
        'Em Trânsito',
        'transit'::public.stock_location_type,
        'Local técnico para transferências em trânsito',
        true,
        false,
        false,
        false,
        999,
        jsonb_build_object('created_by', 'get_or_create_transit_location')
    )
    returning * into v_location;

    return v_location;
end;
$$;


ALTER FUNCTION "public"."get_or_create_transit_location"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_order_monitor_pending_orders"("p_store_id" "uuid", "p_since" timestamp with time zone, "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_orders jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_store_id',
      'orders', '[]'::jsonb
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'orders', '[]'::jsonb
      );
    END IF;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'created_at', q.created_at,
        'status', q.status,
        'customer_phone', q.customer_phone,
        'customer_name', q.customer_name,
        'metadata', q.metadata,
        'order_code', q.order_code,
        'total', q.total
      )
      ORDER BY q.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_orders
  FROM (
    SELECT
      o.id,
      o.created_at,
      o.status::text AS status,
      o.customer_phone,
      o.customer_name,
      COALESCE(o.metadata, '{}'::jsonb) AS metadata,
      o.order_code,
      o.total
    FROM public.orders o
    WHERE o.store_id = p_store_id
      AND o.status = 'reserved'::order_status
      AND o.created_at > p_since
      AND (COALESCE(o.metadata, '{}'::jsonb)->>'notified_3min') IS NULL
    ORDER BY o.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 20), 50))
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'orders', v_orders
  );
END;
$$;


ALTER FUNCTION "public"."get_order_monitor_pending_orders"("p_store_id" "uuid", "p_since" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_inventory_audit_events"("p_store_id" "uuid", "p_product_id" "uuid") RETURNS TABLE("id" "uuid", "store_id" "uuid", "user_id" "uuid", "action" "text", "entity" "text", "entity_id" "uuid", "old_data" "jsonb", "new_data" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    select
        a.id,
        a.store_id,
        a.user_id,
        a.action,
        a.entity,
        a.entity_id,
        a.old_data,
        a.new_data,
        a.created_at
    from public.v_inventory_audit_events a
    where a.store_id = p_store_id
      and (
            a.old_data ->> 'product_id' = p_product_id::text
         or a.new_data ->> 'product_id' = p_product_id::text
      )
    order by a.created_at desc, a.id desc;
$$;


