CREATE OR REPLACE FUNCTION "public"."get_product_inventory_lifecycle"("p_store_id" "uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "price" numeric, "active" boolean, "min_stock" integer, "max_stock" integer, "last_entry_unit_cost" numeric, "total_on_hand" numeric, "total_reserved" numeric, "total_available" numeric, "last_entry_at" timestamp with time zone, "last_exit_at" timestamp with time zone, "last_movement_at" timestamp with time zone, "transfer_count" bigint, "last_transfer_at" timestamp with time zone, "last_location_balance_update" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    select
        v.store_id,
        v.product_id,
        v.product_name,
        v.category_id,
        v.price,
        v.active,
        v.min_stock,
