CREATE OR REPLACE FUNCTION "public"."get_product_purchase_cost_history"("p_product_id" "uuid", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "store_id" "uuid", "product_id" "uuid", "product_name" "text", "supplier_id" "uuid", "supplier_name" "text", "supplier_trade_name" "text", "purchase_document_id" "uuid", "purchase_document_item_id" "uuid", "document_code" "text", "invoice_number" "text", "unit_cost" numeric, "quantity" numeric, "total_cost" numeric, "issue_date" "date", "effective_at" timestamp with time zone, "source" "text", "previous_unit_cost" numeric, "unit_cost_delta" numeric, "unit_cost_delta_percent" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH product_base AS (
    SELECT p.*
    FROM public.products p
    WHERE p.id = p_product_id
      AND public.is_store_member(p.store_id)
  ),

  rows AS (
    SELECT
      sph.id,
      sph.store_id,
      sph.product_id,
      p.name AS product_name,

      sph.supplier_id,
      s.name AS supplier_name,
      s.trade_name AS supplier_trade_name,

      sph.purchase_document_id,
      sph.purchase_document_item_id,
      pd.document_code,
      pd.invoice_number,

      sph.unit_cost,
      sph.quantity,
      sph.total_cost,

      sph.issue_date,
      sph.effective_at,
      sph.source,

      LAG(sph.unit_cost) OVER (
        PARTITION BY sph.product_id
        ORDER BY sph.effective_at ASC, sph.issue_date ASC NULLS LAST
      ) AS previous_unit_cost

    FROM public.supplier_price_history sph
    JOIN product_base p
      ON p.id = sph.product_id
     AND p.store_id = sph.store_id
    JOIN public.suppliers s
      ON s.id = sph.supplier_id
     AND s.store_id = sph.store_id
    LEFT JOIN public.purchase_documents pd
      ON pd.id = sph.purchase_document_id
     AND pd.store_id = sph.store_id
    WHERE sph.is_active = true
      AND sph.cancelled_at IS NULL
  )

  SELECT
    r.id,
    r.store_id,
    r.product_id,
    r.product_name,

    r.supplier_id,
    r.supplier_name,
    r.supplier_trade_name,

    r.purchase_document_id,
    r.purchase_document_item_id,
    r.document_code,
    r.invoice_number,

    r.unit_cost,
    r.quantity,
    r.total_cost,

    r.issue_date,
    r.effective_at,
    r.source,

    r.previous_unit_cost,

    CASE
      WHEN r.previous_unit_cost IS NULL THEN NULL
      ELSE ROUND(r.unit_cost - r.previous_unit_cost, 4)
    END AS unit_cost_delta,

    CASE
      WHEN r.previous_unit_cost IS NULL OR r.previous_unit_cost = 0 THEN NULL
      ELSE ROUND(((r.unit_cost - r.previous_unit_cost) / r.previous_unit_cost) * 100, 2)
    END AS unit_cost_delta_percent

  FROM rows r
  ORDER BY
    r.effective_at DESC,
    r.issue_date DESC NULLS LAST
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
$$;


ALTER FUNCTION "public"."get_product_purchase_cost_history"("p_product_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_stock_management"("p_product_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "product_active" boolean, "discontinued" boolean, "is_discontinued" boolean, "location_id" "uuid", "location_code" "text", "location_name" "text", "location_type" "text", "location_active" boolean, "is_default" boolean, "allow_sales" boolean, "allow_reservations" boolean, "location_sort_order" integer, "on_hand" numeric, "reserved" numeric, "available" numeric, "updated_at" timestamp with time zone, "global_on_hand" numeric, "global_reserved" numeric, "global_available" numeric, "global_min_stock" numeric, "global_max_stock" numeric, "global_status" "text", "provisional_location_min_stock" numeric, "provisional_location_max_stock" numeric, "location_status" "text", "possible_source_locations" integer, "source_locations" "jsonb", "recommended_action" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
BEGIN
  SELECT p.store_id
  INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao produto informado.';
  END IF;

  RETURN QUERY
  WITH location_counts AS (
    SELECT
      sl.store_id,
      GREATEST(
        COUNT(*) FILTER (
          WHERE sl.active = true
            AND (
              sl.allow_sales = true
              OR sl.allow_reservations = true
              OR sl.is_default = true
            )
        ),
        1
      )::numeric AS relevant_location_count
    FROM public.stock_locations sl
    WHERE sl.store_id = v_store_id
    GROUP BY sl.store_id
  ),

  balances AS (
    SELECT
      ilb.store_id,
      ilb.location_id,
      ilb.product_id,
      SUM(COALESCE(ilb.on_hand, 0))::numeric AS on_hand,
      SUM(COALESCE(ilb.reserved, 0))::numeric AS reserved,
      MAX(ilb.updated_at) AS updated_at
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_store_id
      AND ilb.product_id = p_product_id
    GROUP BY
      ilb.store_id,
      ilb.location_id,
      ilb.product_id
  ),

  base AS (
    SELECT
      p.store_id,
      p.id AS product_id,
      p.name AS product_name,
      p.category_id,
      COALESCE(p.active, true) AS product_active,
      COALESCE(p.discontinued, false) AS discontinued,
      COALESCE(p.is_discontinued, false) AS is_discontinued,

      sl.id AS location_id,
      sl.code AS location_code,
      sl.name AS location_name,
      sl.type::text AS location_type,
      sl.active AS location_active,
      sl.is_default,
      sl.allow_sales,
      sl.allow_reservations,
      sl.sort_order AS location_sort_order,

      COALESCE(b.on_hand, 0)::numeric AS on_hand,
      COALESCE(b.reserved, 0)::numeric AS reserved,
      (
        COALESCE(b.on_hand, 0)
        - COALESCE(b.reserved, 0)
      )::numeric AS available,
      COALESCE(b.updated_at, now()) AS updated_at,

      COALESCE(p.min_stock, 0)::numeric AS global_min_stock,
      COALESCE(p.max_stock, 0)::numeric AS global_max_stock,

      CASE
        WHEN COALESCE(p.min_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.min_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_min_stock,

      CASE
        WHEN COALESCE(p.max_stock, 0) <= 0 THEN 0::numeric
        WHEN sl.active = true
         AND (
           sl.allow_sales = true
           OR sl.allow_reservations = true
           OR sl.is_default = true
         )
        THEN GREATEST(
          1::numeric,
          CEIL(COALESCE(p.max_stock, 0)::numeric / COALESCE(lc.relevant_location_count, 1))
        )
        ELSE 0::numeric
      END AS provisional_location_max_stock

    FROM public.products p
    JOIN public.stock_locations sl
      ON sl.store_id = p.store_id
    LEFT JOIN balances b
      ON b.store_id = p.store_id
     AND b.product_id = p.id
     AND b.location_id = sl.id
    LEFT JOIN location_counts lc
      ON lc.store_id = p.store_id
    WHERE p.id = p_product_id
  ),

  global_balance AS (
    SELECT
      b.store_id,
      b.product_id,
      SUM(b.on_hand)::numeric AS global_on_hand,
      SUM(b.reserved)::numeric AS global_reserved,
      SUM(b.available)::numeric AS global_available
    FROM base b
    GROUP BY
      b.store_id,
      b.product_id
  ),

  classified AS (
    SELECT
      b.*,
      gb.global_on_hand,
      gb.global_reserved,
      gb.global_available,

      CASE
        WHEN b.product_active = false
          OR b.discontinued = true
          OR b.is_discontinued = true
        THEN 'product_inactive'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= 0
        THEN 'global_stockout'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= b.global_min_stock
        THEN 'global_critical'

        WHEN b.global_min_stock > 0
         AND gb.global_available <= CEIL(b.global_min_stock * 1.5)
        THEN 'global_attention'

        WHEN b.global_max_stock > 0
         AND gb.global_available >= b.global_max_stock
        THEN 'global_excess'

        ELSE 'global_ok'
      END AS global_status,

      CASE
        WHEN b.product_active = false
          OR b.discontinued = true
          OR b.is_discontinued = true
        THEN 'product_inactive'

        WHEN b.location_active = false
        THEN 'location_inactive'

        WHEN b.provisional_location_min_stock <= 0
         AND b.available <> 0
        THEN 'monitor_only'

        WHEN b.provisional_location_min_stock <= 0
        THEN 'not_configured'

        WHEN b.available <= 0
        THEN 'location_stockout'

        WHEN b.available <= b.provisional_location_min_stock
        THEN 'location_critical'

        WHEN b.provisional_location_max_stock > 0
         AND b.available >= b.provisional_location_max_stock
        THEN 'location_excess'

        ELSE 'location_ok'
      END AS location_status

    FROM base b
    JOIN global_balance gb
      ON gb.store_id = b.store_id
     AND gb.product_id = b.product_id
  ),

  sources AS (
    SELECT
      c.store_id,
      c.product_id,

      COUNT(*) FILTER (
        WHERE c.location_active = true
          AND c.available > c.provisional_location_min_stock
      )::integer AS possible_source_locations,

      COALESCE(
        JSONB_AGG(
          JSONB_BUILD_OBJECT(
            'location_id', c.location_id,
            'location_code', c.location_code,
            'location_name', c.location_name,
            'available', c.available,
            'on_hand', c.on_hand,
            'reserved', c.reserved,
            'location_status', c.location_status
          )
          ORDER BY c.available DESC, c.location_name
        ) FILTER (
          WHERE c.location_active = true
            AND c.available > c.provisional_location_min_stock
        ),
        '[]'::jsonb
      ) AS source_locations

    FROM classified c
    GROUP BY
      c.store_id,
      c.product_id
  )

  SELECT
    c.store_id,
    c.product_id,
    c.product_name,
    c.category_id,
    c.product_active,
    c.discontinued,
    c.is_discontinued,

    c.location_id,
    c.location_code,
    c.location_name,
    c.location_type,
    c.location_active,
    c.is_default,
    c.allow_sales,
    c.allow_reservations,
    c.location_sort_order,

    c.on_hand,
    c.reserved,
    c.available,
    c.updated_at,

    c.global_on_hand,
    c.global_reserved,
    c.global_available,
    c.global_min_stock,
    c.global_max_stock,
    c.global_status,

    c.provisional_location_min_stock,
    c.provisional_location_max_stock,
    c.location_status,

    COALESCE(s.possible_source_locations, 0) AS possible_source_locations,
    COALESCE(s.source_locations, '[]'::jsonb) AS source_locations,

    CASE
      WHEN c.product_active = false
        OR c.discontinued = true
        OR c.is_discontinued = true
      THEN 'ok'

      WHEN c.global_status IN ('global_stockout', 'global_critical')
      THEN 'buy'

      WHEN c.location_status IN ('location_stockout', 'location_critical')
       AND COALESCE(s.possible_source_locations, 0) > 0
       AND c.global_status NOT IN ('global_stockout', 'global_critical')
      THEN 'transfer'

      WHEN c.global_status = 'global_excess'
       AND c.location_status NOT IN ('location_stockout', 'location_critical')
      THEN 'review_excess'

      WHEN c.global_status = 'global_attention'
        OR c.location_status = 'location_critical'
      THEN 'monitor'

      ELSE 'ok'
    END AS recommended_action

  FROM classified c
  LEFT JOIN sources s
    ON s.store_id = c.store_id
   AND s.product_id = c.product_id
  ORDER BY
    c.is_default DESC,
    c.location_sort_order,
    c.location_name;
END;
$$;


