CREATE OR REPLACE FUNCTION "public"."get_product_stock_movements"("p_store_id" "uuid", "p_product_id" "uuid") RETURNS TABLE("id" "uuid", "store_id" "uuid", "product_id" "uuid", "product_name" "text", "order_id" "uuid", "quantity" integer, "type" "text", "reason" "text", "user_id" "uuid", "previous_stock" integer, "new_stock" integer, "created_at" timestamp with time zone, "created_at_display" "text", "affects_physical" boolean, "source" "text", "source_id" "uuid", "reason_code" "text", "metadata" "jsonb", "created_by" "uuid", "supplier_id" "uuid", "location_id" "uuid", "location_code" "text", "location_name" "text", "from_location_id" "uuid", "from_location_code" "text", "from_location_name" "text", "to_location_id" "uuid", "to_location_code" "text", "to_location_name" "text", "transfer_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission_v2(p_store_id, 'stock.view')
    OR public.user_has_store_permission_v2(p_store_id, 'stock.adjust')
    OR public.user_has_store_permission_v2(p_store_id, 'stock.transfer')
    OR public.user_has_store_permission_v2(p_store_id, 'products.view')
  ) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  SELECT
    sm.id,
    sm.store_id,
    sm.product_id,
    p.name AS product_name,
    sm.order_id,
    sm.quantity,
    sm.type::text AS type,
    sm.reason,
    sm.user_id,
    sm.previous_stock,
    sm.new_stock,
    sm.created_at,
    public.format_datetime_sao_paulo(sm.created_at) AS created_at_display,
    sm.affects_physical,
    sm.source,
    sm.source_id,
    sm.reason_code,
    sm.metadata,
    sm.created_by,
    sm.supplier_id,
    sm.location_id,
    loc.code AS location_code,
    loc.name AS location_name,
    sm.from_location_id,
    from_loc.code AS from_location_code,
    from_loc.name AS from_location_name,
    sm.to_location_id,
    to_loc.code AS to_location_code,
    to_loc.name AS to_location_name,
    sm.transfer_id
  FROM public.stock_movements sm
  JOIN public.products p
    ON p.id = sm.product_id
   AND p.store_id = sm.store_id
  LEFT JOIN public.stock_locations loc
    ON loc.id = sm.location_id
   AND loc.store_id = sm.store_id
  LEFT JOIN public.stock_locations from_loc
    ON from_loc.id = sm.from_location_id
   AND from_loc.store_id = sm.store_id
  LEFT JOIN public.stock_locations to_loc
    ON to_loc.id = sm.to_location_id
   AND to_loc.store_id = sm.store_id
  WHERE sm.store_id = p_store_id
    AND sm.product_id = p_product_id
  ORDER BY sm.created_at DESC
  LIMIT 500;
END;
$$;


ALTER FUNCTION "public"."get_product_stock_movements"("p_store_id" "uuid", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_stock_rules_safe"("p_store_id" "uuid", "p_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product jsonb;
  v_rules jsonb;
BEGIN
  IF p_store_id IS NULL OR p_product_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_parameters');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  PERFORM public.ensure_product_stock_location_rules(p_store_id, p_product_id);

  SELECT jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'min_stock', COALESCE(p.min_stock, 0),
    'max_stock', COALESCE(p.max_stock, 0)
  )
  INTO v_product
  FROM public.products p
  WHERE p.id = p_product_id
    AND p.store_id = p_store_id;

  IF v_product IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'product_not_found');
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', r.id,
        'location_id', r.location_id,
        'location_name', sl.name,
        'location_code', sl.code,
        'location_type', sl.type,
        'is_default', sl.is_default,
        'allow_sales', sl.allow_sales,
        'allow_reservations', sl.allow_reservations,
        'min_stock', r.min_stock,
        'max_stock', r.max_stock,
        'min_percent', r.min_percent,
        'max_percent', r.max_percent,
        'use_percentage', r.use_percentage,
        'active', r.active,
        'on_hand', COALESCE(ilb.on_hand, 0),
        'reserved', COALESCE(ilb.reserved, 0),
        'available', COALESCE(ilb.on_hand, 0) - COALESCE(ilb.reserved, 0)
      )
      ORDER BY sl.is_default DESC, sl.sort_order, sl.name
    ),
    '[]'::jsonb
  )
  INTO v_rules
  FROM public.product_stock_location_rules r
  JOIN public.stock_locations sl ON sl.id = r.location_id
  LEFT JOIN public.inventory_location_balances ilb
    ON ilb.store_id = r.store_id
   AND ilb.product_id = r.product_id
   AND ilb.location_id = r.location_id
  WHERE r.store_id = p_store_id
    AND r.product_id = p_product_id
    AND r.active = true;

  RETURN jsonb_build_object(
    'ok', true,
    'product', v_product,
    'rules', v_rules
  );
END;
$$;


ALTER FUNCTION "public"."get_product_stock_rules_safe"("p_store_id" "uuid", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_supplier_summary"("p_product_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "supplier_id" "uuid", "supplier_name" "text", "supplier_legal_name" "text", "supplier_trade_name" "text", "supplier_document" "text", "supplier_active" boolean, "preferred_supplier" boolean, "homologation_status" "text", "blocked" boolean, "purchase_count" bigint, "total_quantity" numeric, "total_cost" numeric, "average_unit_cost" numeric, "min_unit_cost" numeric, "max_unit_cost" numeric, "last_unit_cost" numeric, "last_purchase_date" "date", "last_effective_at" timestamp with time zone, "last_purchase_document_id" "uuid", "last_document_code" "text", "last_invoice_number" "text", "days_since_last_purchase" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH product_base AS (
    SELECT p.*
    FROM public.products p
    WHERE p.id = p_product_id
      AND public.is_store_member(p.store_id)
  ),

  price_rows AS (
    SELECT
      sph.*,
      pd.document_code,
      pd.invoice_number,
      ROW_NUMBER() OVER (
        PARTITION BY sph.supplier_id
        ORDER BY sph.effective_at DESC, sph.issue_date DESC NULLS LAST
      ) AS rn
    FROM public.supplier_price_history sph
    JOIN product_base pb
      ON pb.id = sph.product_id
     AND pb.store_id = sph.store_id
    LEFT JOIN public.purchase_documents pd
      ON pd.id = sph.purchase_document_id
     AND pd.store_id = sph.store_id
    WHERE sph.is_active = true
      AND sph.cancelled_at IS NULL
  ),

  agg AS (
    SELECT
      pr.store_id,
      pr.product_id,
      pr.supplier_id,

      COUNT(*)::bigint AS purchase_count,
      COALESCE(SUM(pr.quantity), 0)::numeric AS total_quantity,
      COALESCE(SUM(pr.total_cost), 0)::numeric AS total_cost,

      ROUND(AVG(pr.unit_cost), 4)::numeric AS average_unit_cost,
      MIN(pr.unit_cost)::numeric AS min_unit_cost,
      MAX(pr.unit_cost)::numeric AS max_unit_cost,
      MAX(pr.issue_date)::date AS last_purchase_date,
      MAX(pr.effective_at) AS last_effective_at
    FROM price_rows pr
    GROUP BY
      pr.store_id,
      pr.product_id,
      pr.supplier_id
  ),

  last_price AS (
    SELECT
      pr.store_id,
      pr.product_id,
      pr.supplier_id,
      pr.unit_cost AS last_unit_cost,
      pr.purchase_document_id AS last_purchase_document_id,
      pr.document_code AS last_document_code,
      pr.invoice_number AS last_invoice_number
    FROM price_rows pr
    WHERE pr.rn = 1
  )

  SELECT
    pb.store_id,
    pb.id AS product_id,
    pb.name AS product_name,

    s.id AS supplier_id,
    s.name AS supplier_name,
    s.legal_name AS supplier_legal_name,
    s.trade_name AS supplier_trade_name,
    s.document AS supplier_document,
    COALESCE(s.active, true) AS supplier_active,
    COALESCE(s.preferred_supplier, false) AS preferred_supplier,
    s.homologation_status,
    COALESCE(s.blocked, false) AS blocked,

    a.purchase_count,
    a.total_quantity,
    a.total_cost,

    a.average_unit_cost,
    a.min_unit_cost,
    a.max_unit_cost,
    lp.last_unit_cost,
    a.last_purchase_date,
    a.last_effective_at,
    lp.last_purchase_document_id,
    lp.last_document_code,
    lp.last_invoice_number,

    CASE
      WHEN a.last_effective_at IS NULL THEN NULL
      ELSE (
        timezone('America/Sao_Paulo', now())::date
        - timezone('America/Sao_Paulo', a.last_effective_at)::date
      )::integer
    END AS days_since_last_purchase

  FROM product_base pb
  JOIN agg a
    ON a.product_id = pb.id
   AND a.store_id = pb.store_id
  JOIN public.suppliers s
    ON s.id = a.supplier_id
   AND s.store_id = a.store_id
  LEFT JOIN last_price lp
    ON lp.store_id = a.store_id
   AND lp.product_id = a.product_id
   AND lp.supplier_id = a.supplier_id
  ORDER BY
    COALESCE(s.preferred_supplier, false) DESC,
    COALESCE(s.blocked, false) ASC,
    a.last_effective_at DESC NULLS LAST,
    a.total_cost DESC,
    s.name ASC;
$$;


ALTER FUNCTION "public"."get_product_supplier_summary"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_transfer_divergences"("p_product_id" "uuid") RETURNS TABLE("id" "uuid", "transfer_id" "uuid", "transfer_code" "text", "created_at" timestamp with time zone, "received_at" timestamp with time zone, "source_location_id" "uuid", "source_location_name" "text", "destination_location_id" "uuid", "destination_location_name" "text", "product_id" "uuid", "requested_qty" numeric, "shipped_qty" numeric, "received_qty" numeric, "divergence_qty" numeric, "divergence_resolution" "text", "divergence_reason" "text", "divergence_notes" "text", "loss_qty" numeric, "returned_to_origin_qty" numeric, "accepted_shortage_qty" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.products p
    WHERE p.id = p_product_id
      AND public.is_store_member(p.store_id)
  ) THEN
    RAISE EXCEPTION 'Acesso negado ao produto informado.';
  END IF;

  RETURN QUERY
  SELECT
    sti.id,
    st.id AS transfer_id,
    st.transfer_code,
    sti.created_at,
    st.received_at,
    st.source_location_id,
    source_loc.name AS source_location_name,
    st.destination_location_id,
    destination_loc.name AS destination_location_name,
    sti.product_id,
    sti.requested_qty,
    sti.shipped_qty,
    sti.received_qty,
    sti.divergence_qty,
    sti.divergence_resolution,
    sti.divergence_reason,
    sti.divergence_notes,
    sti.loss_qty,
    sti.returned_to_origin_qty,
    sti.accepted_shortage_qty
  FROM public.stock_transfer_items sti
  JOIN public.stock_transfers st
    ON st.id = sti.transfer_id
  LEFT JOIN public.stock_locations source_loc
    ON source_loc.id = st.source_location_id
  LEFT JOIN public.stock_locations destination_loc
    ON destination_loc.id = st.destination_location_id
  WHERE sti.product_id = p_product_id
    AND sti.divergence_qty > 0
    AND public.is_store_member(st.store_id)
  ORDER BY COALESCE(st.received_at, sti.updated_at, sti.created_at) DESC;
END;
$$;


ALTER FUNCTION "public"."get_product_transfer_divergences"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_product_transfer_divergences"("p_product_id" "uuid") IS 'Retorna divergências de transferência de um produto para exibição narrativa na Vida do Produto.';



CREATE OR REPLACE FUNCTION "public"."get_product_transit_summary"("p_product_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "location_id" "uuid", "location_code" "text", "location_name" "text", "in_transit_in" numeric, "in_transit_out" numeric, "net_in_transit" numeric, "incoming_transfers_count" bigint, "outgoing_transfers_count" bigint, "incoming_transfers" "jsonb", "outgoing_transfers" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
BEGIN
  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'Produto não informado.';
  END IF;

  SELECT p.store_id
  INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao produto informado.';
  END IF;

  RETURN QUERY
  WITH open_items AS (
    SELECT
      st.store_id,
      st.id AS transfer_id,
      st.transfer_code,
      st.source_location_id,
      st.destination_location_id,
      sti.product_id,
      p.name AS product_name,
      GREATEST(
        COALESCE(sti.shipped_qty, 0) - COALESCE(sti.received_qty, 0),
        0
      )::numeric AS qty_in_transit,
      st.shipped_at,
      st.created_at
    FROM public.stock_transfers st
    JOIN public.stock_transfer_items sti
      ON sti.transfer_id = st.id
     AND sti.store_id = st.store_id
    JOIN public.products p
      ON p.id = sti.product_id
     AND p.store_id = st.store_id
    WHERE st.store_id = v_store_id
      AND sti.product_id = p_product_id
      AND st.status = 'shipped'::public.stock_transfer_status
      AND GREATEST(
        COALESCE(sti.shipped_qty, 0) - COALESCE(sti.received_qty, 0),
        0
      ) > 0
  ),

  incoming AS (
    SELECT
      oi.store_id,
      oi.destination_location_id AS location_id,
      oi.product_id,
      oi.product_name,
      SUM(oi.qty_in_transit)::numeric AS in_transit_in,
      COUNT(DISTINCT oi.transfer_id)::bigint AS incoming_transfers_count,
      jsonb_agg(
        jsonb_build_object(
          'transfer_id', oi.transfer_id,
          'transfer_code', oi.transfer_code,
          'qty', oi.qty_in_transit,
          'source_location_id', oi.source_location_id,
          'destination_location_id', oi.destination_location_id,
          'shipped_at', oi.shipped_at
        )
        ORDER BY oi.shipped_at DESC NULLS LAST, oi.created_at DESC
      ) AS incoming_transfers
    FROM open_items oi
    GROUP BY
      oi.store_id,
      oi.destination_location_id,
      oi.product_id,
      oi.product_name
  ),

  outgoing AS (
    SELECT
      oi.store_id,
      oi.source_location_id AS location_id,
      oi.product_id,
      oi.product_name,
      SUM(oi.qty_in_transit)::numeric AS in_transit_out,
      COUNT(DISTINCT oi.transfer_id)::bigint AS outgoing_transfers_count,
      jsonb_agg(
        jsonb_build_object(
          'transfer_id', oi.transfer_id,
          'transfer_code', oi.transfer_code,
          'qty', oi.qty_in_transit,
          'source_location_id', oi.source_location_id,
          'destination_location_id', oi.destination_location_id,
          'shipped_at', oi.shipped_at
        )
        ORDER BY oi.shipped_at DESC NULLS LAST, oi.created_at DESC
      ) AS outgoing_transfers
    FROM open_items oi
    GROUP BY
      oi.store_id,
      oi.source_location_id,
      oi.product_id,
      oi.product_name
  ),

  merged AS (
    SELECT
      COALESCE(i.store_id, o.store_id) AS store_id,
      COALESCE(i.location_id, o.location_id) AS location_id,
      COALESCE(i.product_id, o.product_id) AS product_id,
      COALESCE(i.product_name, o.product_name) AS product_name,

      COALESCE(i.in_transit_in, 0)::numeric AS in_transit_in,
      COALESCE(o.in_transit_out, 0)::numeric AS in_transit_out,

      COALESCE(i.incoming_transfers_count, 0)::bigint AS incoming_transfers_count,
      COALESCE(o.outgoing_transfers_count, 0)::bigint AS outgoing_transfers_count,

      COALESCE(i.incoming_transfers, '[]'::jsonb) AS incoming_transfers,
      COALESCE(o.outgoing_transfers, '[]'::jsonb) AS outgoing_transfers
    FROM incoming i
    FULL OUTER JOIN outgoing o
      ON o.store_id = i.store_id
     AND o.location_id = i.location_id
     AND o.product_id = i.product_id
  )

  SELECT
    m.store_id,
    m.product_id,
    m.product_name,
    sl.id AS location_id,
    sl.code AS location_code,
    sl.name AS location_name,

    m.in_transit_in,
    m.in_transit_out,
    (m.in_transit_in - m.in_transit_out)::numeric AS net_in_transit,

    m.incoming_transfers_count,
    m.outgoing_transfers_count,

    m.incoming_transfers,
    m.outgoing_transfers
  FROM merged m
  JOIN public.stock_locations sl
    ON sl.id = m.location_id
   AND sl.store_id = m.store_id
  ORDER BY
    sl.name;
END;
$$;


