CREATE OR REPLACE FUNCTION "public"."get_public_delivery_methods_by_slug"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_methods jsonb;
BEGIN
  SELECT s.id
  INTO v_store_id
  FROM public.stores s
  WHERE s.slug = lower(trim(p_slug))
    AND s.public_store_enabled = true
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'store_not_found_or_disabled',
      'delivery_methods', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'code', dm.code,
        'name', dm.name,
        'description', dm.description,
        'icon', dm.icon,
        'color', dm.color,
        'fulfillment_type', dm.fulfillment_type,
        'requires_address', dm.requires_address,
        'requires_table', dm.requires_table,
        'minimum_order_value', dm.minimum_order_value,
        'delivery_fee', dm.delivery_fee,
        'estimated_minutes_min', dm.estimated_minutes_min,
        'estimated_minutes_max', dm.estimated_minutes_max
      )
      ORDER BY dm.sort_order, dm.name
    ),
    '[]'::jsonb
  )
  INTO v_methods
  FROM public.store_delivery_methods dm
  WHERE dm.store_id = v_store_id
    AND dm.active = true
    AND dm.public_enabled = true;

  RETURN jsonb_build_object(
    'ok', true,
    'delivery_methods', v_methods
