CREATE OR REPLACE FUNCTION "public"."get_public_storefront_by_slug"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store record;
  v_hours jsonb;
  v_messages jsonb;
  v_whatsapp_digits text;
BEGIN
  SELECT
    s.id,
    s.slug,
    s.name,
    s.description,
    s.logo_url,
    s.phone_number,
    s.theme_config,
    s.config,
    s.minimum_order_value,
    s.reservation_time_minutes,
    s.privacy_policy_text,
    s.terms_of_use_text,
    s.cookie_policy_text,
    s.public_store_enabled,
    s.public_catalog_enabled,
    s.contacts
  INTO v_store
  FROM public.stores s
  WHERE s.slug = lower(trim(p_slug))
    AND s.public_store_enabled = true
  LIMIT 1;

  IF v_store.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'store_not_found_or_disabled'
    );
  END IF;

  v_whatsapp_digits := regexp_replace(
    COALESCE(
      v_store.contacts->>'whatsapp_business',
      v_store.contacts->>'whatsapp',
      v_store.phone_number,
      ''
    ),
    '\D',
    '',
    'g'
  );

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'day_of_week', sh.day_of_week,
        'open_time', sh.open_time,
        'close_time', sh.close_time,
        'is_closed', sh.is_closed
      )
      ORDER BY sh.day_of_week
    ),
    '[]'::jsonb
  )
  INTO v_hours
  FROM public.store_hours sh
  WHERE sh.store_id = v_store.id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'title', sm.title,
        'message', sm.message,
        'expires_at', sm.expires_at
      )
      ORDER BY sm.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_messages
  FROM public.store_messages sm
  WHERE sm.store_id = v_store.id
    AND (sm.expires_at IS NULL OR sm.expires_at > now());

  RETURN jsonb_build_object(
    'ok', true,
    'store', jsonb_build_object(
      'id', v_store.id,
      'slug', v_store.slug,
      'name', v_store.name,
      'description', v_store.description,
      'logo_url', v_store.logo_url,
      'phone_number', v_store.phone_number,
      'theme_config', COALESCE(v_store.theme_config, '{}'::jsonb),
      'visual_config', COALESCE(v_store.config, '{}'::jsonb),
      'minimum_order_value', v_store.minimum_order_value,
      'reservation_time_minutes', v_store.reservation_time_minutes,
      'public_catalog_enabled', v_store.public_catalog_enabled,
      'privacy_policy_text', v_store.privacy_policy_text,
      'terms_of_use_text', v_store.terms_of_use_text,
      'cookie_policy_text', v_store.cookie_policy_text,
      'whatsapp', jsonb_build_object(
        'raw', COALESCE(
          v_store.contacts->>'whatsapp_business',
          v_store.contacts->>'whatsapp',
          v_store.phone_number,
          ''
        ),
        'digits', v_whatsapp_digits,
        'enabled', length(v_whatsapp_digits) >= 10
      ),
      'hours', v_hours,
      'messages', v_messages
    )
  );
END;
$$;


