CREATE OR REPLACE FUNCTION "public"."get_purchase_quotations_by_store"("p_store_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "quotation_code" "text", "supplier_id" "uuid", "supplier_name" "text", "status" "text", "sent_channel" "text", "requested_at" timestamp with time zone, "requested_at_display" "text", "responded_at" timestamp with time zone, "responded_at_display" "text", "expires_at" timestamp with time zone, "expires_at_display" "text", "items_count" integer, "total_reference" numeric, "total_quoted" numeric, "converted_purchase_document_id" "uuid", "responsible_name" "text", "notes" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    q.id,
    q.quotation_code,
    q.supplier_id,
    s.name AS supplier_name,
    q.status,
    q.sent_channel,
    q.requested_at,
    public.format_datetime_sao_paulo(q.requested_at) AS requested_at_display,
    q.responded_at,
    public.format_datetime_sao_paulo(q.responded_at) AS responded_at_display,
    q.expires_at,
    public.format_datetime_sao_paulo(q.expires_at) AS expires_at_display,
    COUNT(qi.id)::integer AS items_count,
    COALESCE(SUM(qi.requested_qty * COALESCE(qi.reference_unit_cost, 0)), 0)::numeric AS total_reference,
    COALESCE(SUM(qi.approved_qty * COALESCE(qi.quoted_unit_cost, 0)), 0)::numeric AS total_quoted,
    q.converted_purchase_document_id,
    q.responsible_name,
    q.notes
  FROM public.purchase_quotations q
  JOIN public.suppliers s
    ON s.id = q.supplier_id
  LEFT JOIN public.purchase_quotation_items qi
    ON qi.quotation_id = q.id
  WHERE q.store_id = p_store_id
    AND public.is_store_member(q.store_id)
    AND (p_status IS NULL OR q.status = p_status)
  GROUP BY
    q.id,
    q.quotation_code,
    q.supplier_id,
    s.name,
    q.status,
    q.sent_channel,
    q.requested_at,
    q.responded_at,
    q.expires_at,
    q.converted_purchase_document_id,
    q.responsible_name,
    q.notes
  ORDER BY q.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 300);
$$;


ALTER FUNCTION "public"."get_purchase_quotations_by_store"("p_store_id" "uuid", "p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_purchase_suggestions_by_store"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "min_stock" integer, "max_stock" integer, "physical_on_hand" numeric, "reserved" numeric, "available" numeric, "in_transit_in" numeric, "projected_available" numeric, "shortage_qty" numeric, "suggested_purchase_qty" numeric, "suggested_supplier_id" "uuid", "suggested_supplier_name" "text", "suggested_supplier_trade_name" "text", "suggested_supplier_blocked" boolean, "suggested_supplier_preferred" boolean, "suggested_supplier_homologation_status" "text", "suggested_unit_cost" numeric, "estimated_total_cost" numeric, "last_purchase_date" "date", "last_purchase_document_id" "uuid", "recommendation_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  WITH product_base AS (
    SELECT
      p.id AS product_id,
      p.store_id,
      p.name AS product_name,
      p.category_id,
      COALESCE(p.min_stock, 0)::integer AS min_stock,
      COALESCE(
        p.max_stock,
        GREATEST(COALESCE(p.min_stock, 0) * 2, COALESCE(p.min_stock, 0) + 1)
      )::integer AS max_stock,
      COALESCE(p.last_entry_unit_cost, 0)::numeric AS product_last_entry_unit_cost
    FROM public.products p
    WHERE p.store_id = p_store_id
      AND COALESCE(p.active, true) = true
      AND COALESCE(p.discontinued, false) = false
      AND COALESCE(p.is_discontinued, false) = false
      AND COALESCE(p.min_stock, 0) > 0
  ),

  inventory AS (
    SELECT
      ilb.store_id,
      ilb.product_id,
      COALESCE(SUM(ilb.on_hand), 0)::numeric AS physical_on_hand,
      COALESCE(SUM(ilb.reserved), 0)::numeric AS reserved,
      COALESCE(SUM(ilb.on_hand - ilb.reserved), 0)::numeric AS available
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = p_store_id
    GROUP BY ilb.store_id, ilb.product_id
  ),

  transit AS (
    SELECT
      t.store_id,
      t.product_id,
      COALESCE(SUM(t.in_transit_in), 0)::numeric AS in_transit_in
    FROM public.get_inventory_transit_by_store(p_store_id) t
    GROUP BY t.store_id, t.product_id
  ),

  eligible_price_history AS (
    SELECT
      sph.store_id,
      sph.product_id,
      sph.supplier_id,
      sph.unit_cost,
      sph.issue_date,
      sph.purchase_document_id,
      ROW_NUMBER() OVER (
        PARTITION BY sph.store_id, sph.product_id
        ORDER BY
          COALESCE(s.preferred_supplier, false) DESC,
          sph.issue_date DESC NULLS LAST,
          sph.effective_at DESC NULLS LAST,
          sph.created_at DESC NULLS LAST
      ) AS rn
    FROM public.supplier_price_history sph
    JOIN public.suppliers s
      ON s.id = sph.supplier_id
     AND s.store_id = sph.store_id
    WHERE sph.store_id = p_store_id
      AND COALESCE(sph.is_active, true) = true
      AND sph.cancelled_at IS NULL
      AND public.is_supplier_purchase_eligible(s.id) = true
  ),

  chosen AS (
    SELECT
      pb.store_id,
      pb.product_id,
      pb.product_name,
      pb.category_id,
      pb.min_stock,
      pb.max_stock,

      COALESCE(i.physical_on_hand, 0)::numeric AS physical_on_hand,
      COALESCE(i.reserved, 0)::numeric AS reserved,
      COALESCE(i.available, 0)::numeric AS available,
      COALESCE(t.in_transit_in, 0)::numeric AS in_transit_in,

      (
        COALESCE(i.available, 0)
        + COALESCE(t.in_transit_in, 0)
      )::numeric AS projected_available,

      eph.supplier_id AS suggested_supplier_id,
      s.name AS suggested_supplier_name,
      s.trade_name AS suggested_supplier_trade_name,
      COALESCE(s.blocked, false) AS suggested_supplier_blocked,
      COALESCE(s.preferred_supplier, false) AS suggested_supplier_preferred,
      s.homologation_status AS suggested_supplier_homologation_status,

      COALESCE(eph.unit_cost, pb.product_last_entry_unit_cost, 0)::numeric AS suggested_unit_cost,
      eph.issue_date AS last_purchase_date,
      eph.purchase_document_id AS last_purchase_document_id

    FROM product_base pb
    LEFT JOIN inventory i
      ON i.store_id = pb.store_id
     AND i.product_id = pb.product_id
    LEFT JOIN transit t
      ON t.store_id = pb.store_id
     AND t.product_id = pb.product_id
    LEFT JOIN eligible_price_history eph
      ON eph.store_id = pb.store_id
     AND eph.product_id = pb.product_id
     AND eph.rn = 1
    LEFT JOIN public.suppliers s
      ON s.id = eph.supplier_id
     AND s.store_id = pb.store_id
  )

  SELECT
    c.store_id,
    c.product_id,
    c.product_name,
    c.category_id,
    c.min_stock,
    c.max_stock,
    c.physical_on_hand,
    c.reserved,
    c.available,
    c.in_transit_in,
    c.projected_available,

    GREATEST(c.min_stock::numeric - c.projected_available, 0)::numeric AS shortage_qty,

    CEIL(
      GREATEST(
        c.max_stock::numeric - c.projected_available,
        c.min_stock::numeric - c.projected_available,
        1
      )
    )::numeric AS suggested_purchase_qty,

    c.suggested_supplier_id,
    c.suggested_supplier_name,
    c.suggested_supplier_trade_name,
    c.suggested_supplier_blocked,
    c.suggested_supplier_preferred,
    c.suggested_supplier_homologation_status,

    c.suggested_unit_cost,

    (
      CEIL(
        GREATEST(
          c.max_stock::numeric - c.projected_available,
          c.min_stock::numeric - c.projected_available,
          1
        )
      ) * COALESCE(c.suggested_unit_cost, 0)
    )::numeric AS estimated_total_cost,

    c.last_purchase_date,
    c.last_purchase_document_id,

    CASE
      WHEN c.suggested_supplier_id IS NULL THEN
        'Produto abaixo do mínimo global, sem fornecedor histórico elegível. Selecione fornecedor manualmente.'
      WHEN c.projected_available <= 0 THEN
        'Produto sem disponibilidade global projetada. Comprar com prioridade.'
      WHEN lower(COALESCE(c.suggested_supplier_homologation_status, 'not_evaluated')) IN ('not_evaluated', 'pending') THEN
        'Produto abaixo do mínimo global. Fornecedor ainda não aprovado; revisar antes de confirmar.'
      ELSE
        'Produto abaixo do mínimo global. Compra sugerida.'
    END AS recommendation_reason

  FROM chosen c
  WHERE c.projected_available < c.min_stock
  ORDER BY
    CASE WHEN c.projected_available <= 0 THEN 0 ELSE 1 END,
    c.suggested_supplier_name NULLS LAST,
    c.product_name;
END;
$$;


ALTER FUNCTION "public"."get_purchase_suggestions_by_store"("p_store_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_purchase_suggestions_by_store"("p_store_id" "uuid") IS 'FASE 6.5C: sugestões de compra usando somente fornecedores elegíveis. Fornecedor inelegível vira sem fornecedor histórico elegível.';



CREATE OR REPLACE FUNCTION "public"."get_security_log_visibility_defaults"("p_action" "text") RETURNS TABLE("sensitive" boolean, "visible_to_member" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    case
      when lower(coalesce(p_action, '')) in (
        'store_idle_timeout_settings_updated',
        'store idle timeout settings updated',
        'store_role_permission_template_updated',
        'role_permission_updated',
        'store_member_permission_updated',
        'member_permission_updated',
        'custom_role_created',
        'custom_role_updated',
        'custom_role_deleted',
        'sensitive_action_rule_updated',
        'pin_settings_updated',
        'token_settings_updated',
        'store_settings_updated',
        'settings_updated',
        'security.manage',
        'security.view'
      ) then true
      else false
    end as sensitive,

    case
      when lower(coalesce(p_action, '')) in (
        'session_store_selected',
        'session_disconnected',
        'session_login',
        'login',
        'logout',
        'idle_timeout',
        'browser_closed',
        'session_closed_by_browser',
        'store_member_profile_updated_by_self',
        'profile_change_request_created',
        'profile_change_request_approved',
        'profile_change_request_rejected',
        'profile_change_request_cancelled'
      ) then true

      when lower(coalesce(p_action, '')) in (
        'store_idle_timeout_settings_updated',
        'store idle timeout settings updated',
        'store_role_permission_template_updated',
        'role_permission_updated',
        'store_member_permission_updated',
        'member_permission_updated',
        'custom_role_created',
        'custom_role_updated',
        'custom_role_deleted',
        'sensitive_action_rule_updated',
        'pin_settings_updated',
        'token_settings_updated',
        'store_settings_updated',
        'settings_updated'
      ) then false

      else true
    end as visible_to_member;
$$;


ALTER FUNCTION "public"."get_security_log_visibility_defaults"("p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sensitive_action_requirement"("p_store_id" "uuid", "p_action_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_role_rank integer;
  v_rule record;
  v_allowed_by_role boolean;
  v_has_pin boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'not_authenticated',
      'action_code', p_action_code
    );
  END IF;

  SELECT sm.role
  INTO v_role
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = auth.uid()
    AND sm.status = 'active'
  ORDER BY
    CASE sm.role
      WHEN 'owner' THEN 1
      WHEN 'admin' THEN 2
      WHEN 'manager' THEN 3
      WHEN 'stock_operator' THEN 4
      WHEN 'cashier' THEN 5
      WHEN 'sales' THEN 6
      WHEN 'staff' THEN 7
      WHEN 'viewer' THEN 8
      ELSE 99
    END
  LIMIT 1;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'not_store_member',
      'action_code', p_action_code
    );
  END IF;

  SELECT
    r.action_code,
    c.module,
    c.label,
    c.description,
    c.risk_level,
    r.enabled,
    r.requirement,
    r.min_role,
    r.token_enabled,
    r.token_expiry_seconds,
    r.max_attempts,
    r.require_reason,
    r.source
  INTO v_rule
  FROM public.store_sensitive_action_rules r
  JOIN public.security_sensitive_action_catalog c ON c.code = r.action_code
  WHERE r.store_id = p_store_id
    AND r.action_code = p_action_code
    AND c.active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'action_rule_not_found',
      'action_code', p_action_code,
      'current_role', v_role
    );
  END IF;

  v_role_rank := public.app_role_rank(v_role);
  v_allowed_by_role := v_role_rank >= public.app_role_rank(v_rule.min_role);

  SELECT EXISTS (
    SELECT 1
    FROM public.user_pins up
    WHERE up.user_id = auth.uid()
  )
  INTO v_has_pin;

  RETURN jsonb_build_object(
    'allowed', COALESCE(v_rule.enabled, false) AND v_allowed_by_role,
    'reason',
      CASE
        WHEN NOT COALESCE(v_rule.enabled, false) THEN 'action_disabled'
        WHEN NOT v_allowed_by_role THEN 'insufficient_role'
        ELSE 'allowed'
      END,
    'action_code', v_rule.action_code,
    'module', v_rule.module,
    'label', v_rule.label,
    'description', v_rule.description,
    'risk_level', v_rule.risk_level,
    'requirement', v_rule.requirement,
    'min_role', v_rule.min_role,
    'current_role', v_role,
    'current_role_rank', v_role_rank,
    'min_role_rank', public.app_role_rank(v_rule.min_role),
    'token_enabled', v_rule.token_enabled,
    'token_expiry_seconds', v_rule.token_expiry_seconds,
    'max_attempts', v_rule.max_attempts,
    'require_reason', v_rule.require_reason,
    'has_pin', COALESCE(v_has_pin, false),
    'source', v_rule.source
  );
END;
$$;


ALTER FUNCTION "public"."get_sensitive_action_requirement"("p_store_id" "uuid", "p_action_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_stock_movements_safe"("p_store_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_items jsonb;
  v_total integer := 0;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_store_id',
      'items', '[]'::jsonb,
      'total', 0
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT (
      public.app_is_store_owner(p_store_id)
      OR public.user_has_store_permission_v2(p_store_id, 'stock.view')
      OR public.user_has_store_permission_v2(p_store_id, 'stock.adjust')
      OR public.user_has_store_permission_v2(p_store_id, 'stock.transfer')
      OR public.user_has_store_permission_v2(p_store_id, 'products.view')
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'items', '[]'::jsonb,
        'total', 0
      );
    END IF;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_total
  FROM public.stock_movements sm
  WHERE sm.store_id = p_store_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'product_id', q.product_id,
        'product_name', q.product_name,
        'store_id', q.store_id,
        'location_id', q.location_id,
        'location_code', q.location_code,
        'location_name', q.location_name,
        'from_location_id', q.from_location_id,
        'from_location_code', q.from_location_code,
        'from_location_name', q.from_location_name,
        'to_location_id', q.to_location_id,
        'to_location_code', q.to_location_code,
        'to_location_name', q.to_location_name,
        'transfer_id', q.transfer_id,
        'quantity', q.quantity,
        'type', q.type,
        'reason', q.reason,
        'previous_stock', q.previous_stock,
        'new_stock', q.new_stock,
        'created_at', q.created_at,
        'created_at_display', public.format_datetime_sao_paulo(q.created_at),
        'affects_physical', q.affects_physical,
        'source', q.source,
        'source_id', q.source_id,
        'reason_code', q.reason_code,
        'metadata', q.metadata,
        'order_id', q.order_id,
        'created_by', q.created_by,
        'supplier_id', q.supplier_id
      )
      ORDER BY q.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM (
    SELECT
      sm.id,
      sm.product_id,
      p.name AS product_name,
      sm.store_id,
      sm.location_id,
      loc.code AS location_code,
      loc.name AS location_name,
      sm.from_location_id,
      from_loc.code AS from_location_code,
      from_loc.name AS from_location_name,
      sm.to_location_id,
      to_loc.code AS to_location_code,
      to_loc.name AS to_location_name,
      sm.transfer_id,
      sm.quantity,
      sm.type,
      sm.reason,
      sm.previous_stock,
      sm.new_stock,
      sm.created_at,
      sm.affects_physical,
      sm.source,
      sm.source_id,
      sm.reason_code,
      COALESCE(sm.metadata, '{}'::jsonb) AS metadata,
      sm.order_id,
      sm.created_by,
      sm.supplier_id
    FROM public.stock_movements sm
    LEFT JOIN public.products p
      ON p.id = sm.product_id
     AND p.store_id = sm.store_id
    LEFT JOIN public.stock_locations loc
      ON loc.id = sm.location_id
     AND loc.store_id = sm.store_id
    LEFT JOIN public.stock_locations from_loc
      ON from_loc.id = sm.from_location_id
     AND from_loc.store_id = sm.store_id
    LEFT JOIN public.stock_locations to_loc
      ON to_loc.id = sm.to_location_id
     AND to_loc.store_id = sm.store_id
    WHERE sm.store_id = p_store_id
    ORDER BY sm.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200))
    OFFSET GREATEST(0, COALESCE(p_offset, 0))
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'items', v_items,
    'total', v_total
  );
END;
$$;


ALTER FUNCTION "public"."get_stock_movements_safe"("p_store_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_stock_transfer_detail"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_header jsonb;
  v_items jsonb;
BEGIN
  SELECT st.store_id
  INTO v_store_id
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RETURN jsonb_build_object('header', NULL, 'items', '[]'::jsonb);
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à transferência informada.';
  END IF;

  SELECT jsonb_build_object(
    'id', st.id,
    'store_id', st.store_id,
    'transfer_code', st.transfer_code,
    'status', st.status,
    'source_store_id', st.source_store_id,
    'destination_store_id', st.destination_store_id,
    'source_location_id', st.source_location_id,
    'source_location_code', source_loc.code,
    'source_location_name', source_loc.name,
    'destination_location_id', st.destination_location_id,
    'destination_location_code', destination_loc.code,
    'destination_location_name', destination_loc.name,
    'requested_at', st.requested_at,
    'requested_at_display', public.format_datetime_sao_paulo(st.requested_at),
    'approved_at', st.approved_at,
    'approved_at_display', public.format_datetime_sao_paulo(st.approved_at),
    'shipped_at', st.shipped_at,
    'shipped_at_display', public.format_datetime_sao_paulo(st.shipped_at),
    'received_at', st.received_at,
    'received_at_display', public.format_datetime_sao_paulo(st.received_at),
    'cancelled_at', st.cancelled_at,
    'cancelled_at_display', public.format_datetime_sao_paulo(st.cancelled_at),
    'notes', st.notes,
    'created_at', st.created_at,
    'created_at_display', public.format_datetime_sao_paulo(st.created_at),
    'updated_at', st.updated_at,
    'updated_at_display', public.format_datetime_sao_paulo(st.updated_at),
    'items_count', COUNT(sti.id),
    'total_requested_qty', COALESCE(SUM(sti.requested_qty), 0),
    'total_shipped_qty', COALESCE(SUM(sti.shipped_qty), 0),
    'total_received_qty', COALESCE(SUM(sti.received_qty), 0),
    'total_divergence_qty', COALESCE(SUM(sti.divergence_qty), 0)
  )
  INTO v_header
  FROM public.stock_transfers st
  JOIN public.stock_locations source_loc
    ON source_loc.id = st.source_location_id
   AND source_loc.store_id = st.store_id
  JOIN public.stock_locations destination_loc
    ON destination_loc.id = st.destination_location_id
   AND destination_loc.store_id = st.store_id
  LEFT JOIN public.stock_transfer_items sti
    ON sti.transfer_id = st.id
   AND sti.store_id = st.store_id
  WHERE st.id = p_transfer_id
  GROUP BY
    st.id,
    st.store_id,
    st.transfer_code,
    st.status,
    st.source_store_id,
    st.destination_store_id,
    st.source_location_id,
    source_loc.code,
    source_loc.name,
    st.destination_location_id,
    destination_loc.code,
    destination_loc.name,
    st.requested_at,
    st.approved_at,
    st.shipped_at,
    st.received_at,
    st.cancelled_at,
    st.notes,
    st.created_at,
    st.updated_at;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', sti.id,
        'transfer_id', sti.transfer_id,
        'store_id', sti.store_id,
        'product_id', sti.product_id,
        'product_name', p.name,
        'category_id', p.category_id,
        'price', p.price,
        'variant_id', sti.variant_id,
        'requested_qty', sti.requested_qty,
        'shipped_qty', sti.shipped_qty,
        'received_qty', sti.received_qty,
        'divergence_qty', sti.divergence_qty,
        'unit_cost', sti.unit_cost,
        'notes', sti.notes,
        'metadata', COALESCE(sti.metadata, '{}'::jsonb),
        'created_at', sti.created_at,
        'created_at_display', public.format_datetime_sao_paulo(sti.created_at),
        'updated_at', sti.updated_at,
        'updated_at_display', public.format_datetime_sao_paulo(sti.updated_at)
      )
      ORDER BY p.name
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM public.stock_transfer_items sti
  JOIN public.products p
    ON p.id = sti.product_id
   AND p.store_id = sti.store_id
  WHERE sti.transfer_id = p_transfer_id
    AND sti.store_id = v_store_id;

  RETURN jsonb_build_object(
    'header', v_header,
    'items', COALESCE(v_items, '[]'::jsonb)
  );
END;
$$;


