CREATE OR REPLACE FUNCTION "public"."get_stock_transfer_suggestions_by_store"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "source_location_id" "uuid", "source_location_code" "text", "source_location_name" "text", "source_available" numeric, "source_min_stock" numeric, "source_safe_excess" numeric, "destination_location_id" "uuid", "destination_location_code" "text", "destination_location_name" "text", "destination_available" numeric, "destination_min_stock" numeric, "destination_need" numeric, "global_available" numeric, "global_min_stock" numeric, "global_max_stock" numeric, "global_status" "text", "suggested_qty" numeric, "recommended_action" "text", "risk_level" "text", "warning_message" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  WITH rows AS (
    SELECT *
    FROM public.get_inventory_position_by_store(p_store_id)
  ),

  destinations AS (
    SELECT
      r.*
    FROM rows r
    WHERE r.recommended_action = 'transfer'
      AND r.location_status IN ('location_stockout', 'location_critical')
      AND r.global_status NOT IN ('global_stockout', 'global_critical')
  ),

  sources AS (
    SELECT
      r.*,
      GREATEST(
        0::numeric,
        COALESCE(r.available, 0) - COALESCE(r.provisional_location_min_stock, 0)
      ) AS safe_excess
    FROM rows r
    WHERE r.location_active = true
      AND COALESCE(r.available, 0) > COALESCE(r.provisional_location_min_stock, 0)
  ),

  ranked_sources AS (
    SELECT
      d.store_id,
      d.product_id,
      d.product_name,
      d.category_id,

      s.location_id AS source_location_id,
      s.location_code AS source_location_code,
      s.location_name AS source_location_name,
      s.available AS source_available,
      s.provisional_location_min_stock AS source_min_stock,
      s.safe_excess AS source_safe_excess,

      d.location_id AS destination_location_id,
      d.location_code AS destination_location_code,
      d.location_name AS destination_location_name,
      d.available AS destination_available,
      d.provisional_location_min_stock AS destination_min_stock,
      GREATEST(
        1::numeric,
        COALESCE(d.provisional_location_min_stock, 0) - COALESCE(d.available, 0)
      ) AS destination_need,

      d.global_available,
      d.global_min_stock,
      d.global_max_stock,
      d.global_status,

      ROW_NUMBER() OVER (
        PARTITION BY d.product_id, d.location_id
        ORDER BY s.safe_excess DESC, s.location_name ASC
      ) AS source_rank

    FROM destinations d
    JOIN sources s
      ON s.store_id = d.store_id
     AND s.product_id = d.product_id
     AND s.location_id <> d.location_id
    WHERE s.safe_excess > 0
  ),

  calculated AS (
    SELECT
      rs.*,
      LEAST(rs.source_safe_excess, rs.destination_need)::numeric AS suggested_qty
    FROM ranked_sources rs
    WHERE rs.source_rank = 1
  )

  SELECT
    c.store_id,
    c.product_id,
    c.product_name,
    c.category_id,

    c.source_location_id,
    c.source_location_code,
    c.source_location_name,
    c.source_available,
    c.source_min_stock,
    c.source_safe_excess,

    c.destination_location_id,
    c.destination_location_code,
    c.destination_location_name,
    c.destination_available,
    c.destination_min_stock,
    c.destination_need,

    c.global_available,
    c.global_min_stock,
    c.global_max_stock,
    c.global_status,

    c.suggested_qty,

    'transfer'::text AS recommended_action,

    CASE
      WHEN c.source_safe_excess <= c.destination_need THEN 'medium'
      WHEN c.source_safe_excess >= c.destination_need * 2 THEN 'low'
      ELSE 'low'
    END AS risk_level,

    CASE
      WHEN c.source_safe_excess <= c.destination_need
      THEN 'A origem ficará próxima do mínimo local provisório após a transferência.'
      ELSE 'Transferência sugerida com margem segura na origem.'
    END AS warning_message

  FROM calculated c
  WHERE c.suggested_qty > 0
  ORDER BY
    CASE c.global_status
      WHEN 'global_excess' THEN 1
      WHEN 'global_ok' THEN 2
      WHEN 'global_attention' THEN 3
      ELSE 4
    END,
    c.destination_location_name,
    c.product_name;
END;
$$;


