CREATE OR REPLACE FUNCTION "public"."get_stock_transfers_by_store"("p_store_id" "uuid") RETURNS TABLE("id" "uuid", "store_id" "uuid", "transfer_code" "text", "status" "public"."stock_transfer_status", "source_store_id" "uuid", "destination_store_id" "uuid", "source_location_id" "uuid", "source_location_code" "text", "source_location_name" "text", "destination_location_id" "uuid", "destination_location_code" "text", "destination_location_name" "text", "requested_at" timestamp with time zone, "requested_at_display" "text", "approved_at" timestamp with time zone, "approved_at_display" "text", "shipped_at" timestamp with time zone, "shipped_at_display" "text", "received_at" timestamp with time zone, "received_at_display" "text", "cancelled_at" timestamp with time zone, "cancelled_at_display" "text", "notes" "text", "created_at" timestamp with time zone, "created_at_display" "text", "updated_at" timestamp with time zone, "updated_at_display" "text", "items_count" bigint, "total_requested_qty" numeric, "total_shipped_qty" numeric, "total_received_qty" numeric, "total_divergence_qty" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_store_id IS NULL OR NOT public.is_store_member(p_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  SELECT
    st.id,
    st.store_id,
    st.transfer_code,
    st.status,
    st.source_store_id,
    st.destination_store_id,
    st.source_location_id,
    source_loc.code AS source_location_code,
    source_loc.name AS source_location_name,
    st.destination_location_id,
    destination_loc.code AS destination_location_code,
    destination_loc.name AS destination_location_name,
    st.requested_at,
    public.format_datetime_sao_paulo(st.requested_at) AS requested_at_display,
    st.approved_at,
    public.format_datetime_sao_paulo(st.approved_at) AS approved_at_display,
    st.shipped_at,
    public.format_datetime_sao_paulo(st.shipped_at) AS shipped_at_display,
    st.received_at,
    public.format_datetime_sao_paulo(st.received_at) AS received_at_display,
    st.cancelled_at,
    public.format_datetime_sao_paulo(st.cancelled_at) AS cancelled_at_display,
    st.notes,
    st.created_at,
    public.format_datetime_sao_paulo(st.created_at) AS created_at_display,
    st.updated_at,
    public.format_datetime_sao_paulo(st.updated_at) AS updated_at_display,
    COUNT(sti.id)::bigint AS items_count,
    COALESCE(SUM(sti.requested_qty), 0)::numeric AS total_requested_qty,
    COALESCE(SUM(sti.shipped_qty), 0)::numeric AS total_shipped_qty,
    COALESCE(SUM(sti.received_qty), 0)::numeric AS total_received_qty,
    COALESCE(SUM(sti.divergence_qty), 0)::numeric AS total_divergence_qty
  FROM public.stock_transfers st
  JOIN public.stock_locations source_loc
    ON source_loc.id = st.source_location_id
   AND source_loc.store_id = st.store_id
  JOIN public.stock_locations destination_loc
    ON destination_loc.id = st.destination_location_id
   AND destination_loc.store_id = st.store_id
  LEFT JOIN public.stock_transfer_items sti
    ON sti.transfer_id = st.id
   AND sti.store_id = st.store_id
  WHERE st.store_id = p_store_id
  GROUP BY
    st.id,
    st.store_id,
    st.transfer_code,
    st.status,
    st.source_store_id,
    st.destination_store_id,
    st.source_location_id,
    source_loc.code,
    source_loc.name,
    st.destination_location_id,
    destination_loc.code,
    destination_loc.name,
    st.requested_at,
    st.approved_at,
    st.shipped_at,
    st.received_at,
    st.cancelled_at,
    st.notes,
    st.created_at,
    st.updated_at
  ORDER BY st.created_at DESC, st.id DESC;
END;
$$;


