CREATE OR REPLACE FUNCTION "public"."get_store_config_admin"("p_store_id" "uuid") RETURNS TABLE("config" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'settings.view')
    OR public.user_has_store_permission(p_store_id, 'settings.manage')
    OR public.user_has_store_permission(p_store_id, 'products.view')
    OR public.user_has_store_permission(p_store_id, 'products.create')
    OR public.user_has_store_permission(p_store_id, 'products.update')
    OR public.user_has_store_permission(p_store_id, 'stock.view')
    OR public.user_has_store_permission(p_store_id, 'stock.adjust')
    OR public.user_has_store_permission(p_store_id, 'stock.transfer')
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(s.config, '{}'::jsonb) AS config
  FROM public.stores s
  WHERE s.id = p_store_id;
END;
$$;


