COMMENT ON FUNCTION "public"."get_store_config_admin"("p_store_id" "uuid") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC administrativa de configuração da loja. Revisar permissões finas em etapa Configurações/Admin.';



CREATE OR REPLACE FUNCTION "public"."get_store_member_access_timeline"("p_store_id" "uuid", "p_member_id" "uuid") RETURNS TABLE("event_id" "uuid", "event_at" timestamp with time zone, "event_type" "text", "event_label" "text", "severity" "text", "title" "text", "description" "text", "resulting_status" "text", "old_status" "text", "old_role" "text", "new_role" "text", "old_custom_role_id" "uuid", "new_custom_role_id" "uuid", "visible_to_member" boolean, "created_by" "uuid", "created_by_email" "text", "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Membro não informado.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = p_member_id
    AND sm.store_id = p_store_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado nesta loja.';
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.manage')
    OR public.user_has_store_permission(p_store_id, 'security.manage')
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.view')
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.manage')
    OR v_member.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Sem permissão para visualizar a timeline de acesso deste usuário.';
  END IF;

  RETURN QUERY
  SELECT
    smo.id AS event_id,
    smo.occurred_at AS event_at,
    smo.occurrence_type AS event_type,
    CASE
      WHEN smo.occurrence_type = 'admission' THEN 'Admissão / início de acesso'
      WHEN smo.occurrence_type = 'suspension' THEN 'Suspensão de acesso'
      WHEN smo.occurrence_type = 'exit' THEN 'Desligamento'
      WHEN smo.occurrence_type = 'role_change' THEN 'Alteração de função'
      WHEN smo.occurrence_type = 'other'
           AND smo.metadata->>'event_type' = 'reactivation'
        THEN 'Reativação de acesso'
      ELSE 'Ocorrência'
    END::text AS event_label,
    smo.severity,
    smo.title,
    COALESCE(smo.description, '') AS description,
    CASE
      WHEN smo.occurrence_type = 'admission' THEN 'active'
      WHEN smo.occurrence_type = 'suspension' THEN 'suspended'
      WHEN smo.occurrence_type = 'exit' THEN 'inactive'
      WHEN smo.occurrence_type = 'other'
           AND smo.metadata->>'event_type' = 'reactivation'
        THEN 'active'
      ELSE NULL
    END::text AS resulting_status,
    smo.metadata->>'old_status' AS old_status,
    smo.metadata->>'old_role' AS old_role,
    smo.metadata->>'new_role' AS new_role,
    NULLIF(smo.metadata->>'old_custom_role_id', '')::uuid AS old_custom_role_id,
    NULLIF(smo.metadata->>'new_custom_role_id', '')::uuid AS new_custom_role_id,
    smo.visible_to_member,
    smo.created_by,
    smo.created_by_email,
    smo.metadata
  FROM public.store_member_occurrences smo
  WHERE smo.store_id = p_store_id
    AND smo.member_id = p_member_id
    AND (
      smo.occurrence_type IN (
        'admission',
        'suspension',
        'exit',
        'role_change'
      )
      OR (
        smo.occurrence_type = 'other'
        AND smo.metadata->>'event_type' = 'reactivation'
      )
    )
    AND (
      v_member.user_id <> auth.uid()
      OR smo.visible_to_member = true
      OR smo.occurrence_type IN ('admission', 'role_change', 'training')
    )
  ORDER BY smo.occurred_at DESC, smo.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_store_member_access_timeline"("p_store_id" "uuid", "p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_member_full_history"("p_store_id" "uuid", "p_member_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_module" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("event_id" "text", "event_at" timestamp with time zone, "module" "text", "action" "text", "title" "text", "description" "text", "outcome" "text", "entity_type" "text", "entity_id" "uuid", "metadata" "jsonb", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Membro não informado.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = p_member_id
    AND sm.store_id = p_store_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado nesta loja.';
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.view')
    OR public.user_has_store_permission(p_store_id, 'users.manage')
    OR public.user_has_store_permission(p_store_id, 'security.view')
    OR public.user_has_store_permission(p_store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para visualizar histórico do usuário.';
  END IF;

  RETURN QUERY
  WITH events AS (
    SELECT
      ssl.id::text AS event_id,
      ssl.created_at AS event_at,
      'security'::text AS module,
      ssl.action::text AS action,
      CASE ssl.action
        WHEN 'session_store_selected' THEN 'Entrada na loja selecionada'
        WHEN 'session_logout' THEN 'Saída do sistema'
        WHEN 'store_member_permissions_updated' THEN 'Permissões individuais alteradas'
        WHEN 'store_role_permission_template_updated' THEN 'Permissão por papel alterada'
        WHEN 'store_sensitive_action_rule_updated' THEN 'Regra de ação sensível alterada'
        WHEN 'user_pin_created' THEN 'PIN cadastrado'
        WHEN 'user_pin_updated' THEN 'PIN alterado'
        WHEN 'user_pin_validated' THEN 'PIN validado'
        WHEN 'user_pin_validation_failed' THEN 'Falha na validação do PIN'
        WHEN 'store_master_password_reset' THEN 'Senha master redefinida'
        ELSE replace(initcap(replace(ssl.action, '_', ' ')), '  ', ' ')
      END::text AS title,
      COALESCE(
        ssl.details->>'reason',
        ssl.details->>'note',
        ssl.details->>'store_name',
        ssl.details->>'action_code',
        ssl.details->>'permission_code',
        ''
      )::text AS description,
      ssl.outcome::text AS outcome,
      'store_security_logs'::text AS entity_type,
      ssl.id AS entity_id,
      ssl.details AS metadata,
      'store_security_logs'::text AS source
    FROM public.store_security_logs ssl
    WHERE ssl.store_id = p_store_id
      AND ssl.user_id = v_member.user_id

    UNION ALL

    SELECT
      smo.id::text AS event_id,
      smo.occurred_at AS event_at,
      'users'::text AS module,
      smo.occurrence_type::text AS action,
      smo.title::text AS title,
      COALESCE(smo.description, '')::text AS description,
      smo.severity::text AS outcome,
      'store_member_occurrences'::text AS entity_type,
      smo.id AS entity_id,
      jsonb_build_object(
        'severity', smo.severity,
        'visible_to_member', smo.visible_to_member,
        'created_by', smo.created_by,
        'created_by_email', smo.created_by_email
      ) AS metadata,
      'store_member_occurrences'::text AS source
    FROM public.store_member_occurrences smo
    WHERE smo.store_id = p_store_id
      AND smo.member_id = p_member_id

    UNION ALL

    SELECT
      al.id::text AS event_id,
      al.created_at AS event_at,
      'audit'::text AS module,
      al.action::text AS action,
      CASE
        WHEN al.entity IS NOT NULL THEN al.action || ' em ' || al.entity
        ELSE al.action
      END::text AS title,
      COALESCE(
        al.new_data->>'reason',
        al.new_data->>'description',
        al.old_data->>'reason',
        ''
      )::text AS description,
      'success'::text AS outcome,
      COALESCE(al.entity, 'audit_logs')::text AS entity_type,
      al.entity_id AS entity_id,
      jsonb_build_object(
        'old_data', al.old_data,
        'new_data', al.new_data
      ) AS metadata,
      'audit_logs'::text AS source
    FROM public.audit_logs al
    WHERE al.store_id = p_store_id
      AND al.user_id = v_member.user_id
  )
  SELECT
    e.event_id,
    e.event_at,
    e.module,
    e.action,
    e.title,
    e.description,
    e.outcome,
    e.entity_type,
    e.entity_id,
    e.metadata,
    e.source
  FROM events e
  WHERE
    (
      p_date_from IS NULL
      OR e.event_at >= (p_date_from::timestamp AT TIME ZONE 'America/Sao_Paulo')
    )
    AND (
      p_date_to IS NULL
      OR e.event_at < ((p_date_to + 1)::timestamp AT TIME ZONE 'America/Sao_Paulo')
    )
    AND (
      p_module IS NULL
      OR e.module = p_module
    )
    AND (
      p_action IS NULL
      OR e.action ILIKE '%' || p_action || '%'
      OR e.title ILIKE '%' || p_action || '%'
    )
    AND (
      p_outcome IS NULL
      OR e.outcome = p_outcome
    )
    AND (
      p_search IS NULL
      OR (
        COALESCE(e.title, '') || ' ' ||
        COALESCE(e.description, '') || ' ' ||
        COALESCE(e.action, '') || ' ' ||
        COALESCE(e.entity_type, '')
      ) ILIKE '%' || p_search || '%'
    )
  ORDER BY e.event_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 100), 300))
  OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION "public"."get_store_member_full_history"("p_store_id" "uuid", "p_member_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_module" "text", "p_action" "text", "p_outcome" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_member_invites"("p_store_id" "uuid") RETURNS TABLE("invite_id" "uuid", "store_id" "uuid", "email" "text", "role" "text", "status" "text", "invited_by" "uuid", "invited_by_email" "text", "invited_at" timestamp with time zone, "accepted_at" timestamp with time zone, "accepted_by" "uuid", "cancelled_at" timestamp with time zone, "cancelled_by" "uuid", "cancel_reason" "text", "expires_at" timestamp with time zone, "permissions" "jsonb", "sensitive_actions" "jsonb", "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    i.id AS invite_id,
    i.store_id,
    i.email,
    i.role,
    CASE
      WHEN i.status = 'pending' AND i.expires_at < now() THEN 'expired'
      ELSE i.status
    END AS status,
    i.invited_by,
    i.invited_by_email,
    i.invited_at,
    i.accepted_at,
    i.accepted_by,
    i.cancelled_at,
    i.cancelled_by,
    i.cancel_reason,
    i.expires_at,
    i.permissions,
    i.sensitive_actions,
    i.metadata,
    i.created_at,
    i.updated_at
  FROM public.store_member_invites i
  WHERE i.store_id = p_store_id
    AND (
      public.app_is_store_owner(i.store_id)
      OR public.user_has_store_permission(i.store_id, 'users.manage')
    )
  ORDER BY
    CASE
      WHEN i.status = 'pending' AND i.expires_at < now() THEN 2
      WHEN i.status = 'pending' THEN 1
      WHEN i.status = 'accepted' THEN 3
      WHEN i.status = 'cancelled' THEN 4
      ELSE 5
    END,
    i.invited_at DESC;
$$;


ALTER FUNCTION "public"."get_store_member_invites"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_member_permission_detail"("p_member_id" "uuid") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_name" "text", "user_email" "text", "role" "text", "status" "text", "permission_code" "text", "module" "text", "action" "text", "label" "text", "description" "text", "risk_level" "text", "role_allowed" boolean, "override_value" boolean, "effective_allowed" boolean, "source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  WITH member_base AS (
    SELECT
      sm.id AS member_id,
      sm.store_id,
      sm.user_id,
      COALESCE(p.name, au.email::text, sm.user_id::text) AS user_name,
      au.email::text AS user_email,
      sm.role,
      sm.status,
      COALESCE(sm.permissions, '{}'::jsonb) AS permissions
    FROM public.store_members sm
    LEFT JOIN public.profiles p
      ON p.id = sm.user_id
    LEFT JOIN auth.users au
      ON au.id = sm.user_id
    WHERE sm.id = p_member_id
  )
  SELECT
    mb.member_id,
    mb.store_id,
    mb.user_id,
    mb.user_name,
    mb.user_email,
    mb.role,
    mb.status,

    c.code AS permission_code,
    c.module,
    c.action,
    c.label,
    c.description,
    c.risk_level,

    COALESCE(t.allowed, false) AS role_allowed,

    CASE
      WHEN mb.permissions ? c.code THEN (mb.permissions ->> c.code)::boolean
      ELSE NULL
    END AS override_value,

    CASE
      WHEN mb.role = 'owner' THEN true
      WHEN COALESCE((mb.permissions ->> 'all')::boolean, false) THEN true
      WHEN mb.permissions ? c.code THEN COALESCE((mb.permissions ->> c.code)::boolean, false)
      ELSE COALESCE(t.allowed, false)
    END AS effective_allowed,

    CASE
      WHEN mb.role = 'owner' THEN 'owner'
      WHEN COALESCE((mb.permissions ->> 'all')::boolean, false) THEN 'member_override_all'
      WHEN mb.permissions ? c.code THEN 'member_override'
      WHEN t.permission_code IS NOT NULL THEN 'role_template'
      ELSE 'default_denied'
    END AS source

  FROM member_base mb
  CROSS JOIN public.security_permission_catalog c
  LEFT JOIN public.store_role_permission_templates t
    ON t.store_id = mb.store_id
   AND t.role = mb.role
   AND t.permission_code = c.code
  WHERE c.active = true
    AND (
      public.app_is_store_owner(mb.store_id)
      OR public.user_has_store_permission(mb.store_id, 'users.manage')
      OR public.user_has_store_permission(mb.store_id, 'security.manage')
    )
  ORDER BY c.sort_order, c.module, c.action, c.code;
$$;


ALTER FUNCTION "public"."get_store_member_permission_detail"("p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_member_session_summary"("p_store_id" "uuid") RETURNS TABLE("member_id" "uuid", "user_id" "uuid", "user_name" "text", "user_email" "text", "role" "text", "status" "text", "last_seen_at" timestamp with time zone, "last_session_action" "text", "last_session_at" timestamp with time zone, "last_session_details" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with allowed as (
    select (
      public.app_is_store_owner(p_store_id)
      or public.user_has_store_permission(p_store_id, 'users.view')
      or public.user_has_store_permission(p_store_id, 'users.manage')
      or public.user_has_store_permission(p_store_id, 'security.view')
      or public.user_has_store_permission(p_store_id, 'security.manage')
      or public.user_has_store_permission(p_store_id, 'security.sessions.view')
      or public.user_has_store_permission(p_store_id, 'security.sessions.manage')
    ) as ok
  ),
  last_session as (
    select distinct on (ssl.user_id)
      ssl.user_id,
      ssl.action,
      ssl.created_at,
      ssl.details
    from public.store_security_logs ssl
    where ssl.store_id = p_store_id
      and ssl.action in (
        'session_store_selected',
        'session_logout',
        'session_disconnected',
        'logout',
        'idle_timeout',
        'browser_closed',
        'session_closed_by_browser'
      )
    order by ssl.user_id, ssl.created_at desc
  )
  select
    sm.id as member_id,
    sm.user_id,
    coalesce(p.name, au.raw_user_meta_data->>'name', au.email, sm.user_id::text)::text as user_name,
    au.email::text as user_email,
    sm.role,
    sm.status,
    sm.last_seen_at,
    ls.action as last_session_action,
    ls.created_at as last_session_at,
    ls.details as last_session_details
  from public.store_members sm
  left join public.profiles p
    on p.id = sm.user_id
  left join auth.users au
    on au.id = sm.user_id
  left join last_session ls
    on ls.user_id = sm.user_id
  cross join allowed
  where sm.store_id = p_store_id
    and allowed.ok
  order by
    case sm.role
      when 'owner' then 1
      when 'admin' then 2
      when 'manager' then 3
      when 'stock_operator' then 4
      when 'cashier' then 5
      when 'sales' then 6
      when 'staff' then 7
      when 'viewer' then 8
      else 99
    end,
    user_name;
$$;


ALTER FUNCTION "public"."get_store_member_session_summary"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_members"("p_store_id" "uuid") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_email" "text", "profile_name" "text", "profile_phone" "text", "role" "text", "status" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "invited_by" "uuid", "invited_at" timestamp with time zone, "accepted_at" timestamp with time zone, "last_seen_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT
    sm.id AS member_id,
    sm.store_id,
    sm.user_id,
    au.email::text AS user_email,
    p.name AS profile_name,
    p.phone AS profile_phone,
    sm.role,
    sm.status,
    sm.permissions,
    sm.sensitive_actions,
    sm.invited_by,
    sm.invited_at,
    sm.accepted_at,
    sm.last_seen_at,
    sm.created_at,
    sm.updated_at
  FROM public.store_members sm
  LEFT JOIN auth.users au ON au.id = sm.user_id
  LEFT JOIN public.profiles p ON p.id = sm.user_id
  WHERE sm.store_id = p_store_id
    AND public.is_store_member(p_store_id)
  ORDER BY
    CASE sm.role
      WHEN 'owner' THEN 1
      WHEN 'admin' THEN 2
      WHEN 'manager' THEN 3
      WHEN 'cashier' THEN 4
      WHEN 'stock_operator' THEN 5
      WHEN 'sales' THEN 6
      WHEN 'staff' THEN 7
      WHEN 'viewer' THEN 8
      ELSE 99
    END,
    COALESCE(p.name, au.email::text, sm.user_id::text);
$$;


ALTER FUNCTION "public"."get_store_members"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_members_for_permissions"("p_store_id" "uuid") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_name" "text", "user_email" "text", "role" "text", "status" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT
    sm.id AS member_id,
    sm.store_id,
    sm.user_id,
    COALESCE(p.name, au.raw_user_meta_data->>'name', au.email, sm.user_id::text)::text AS user_name,
    au.email::text AS user_email,
    sm.role,
    sm.status,
    COALESCE(sm.permissions, '{}'::jsonb) AS permissions,
    COALESCE(sm.sensitive_actions, '{}'::jsonb) AS sensitive_actions,
    sm.created_at,
    sm.updated_at
  FROM public.store_members sm
  LEFT JOIN public.profiles p
    ON p.id = sm.user_id
  LEFT JOIN auth.users au
    ON au.id = sm.user_id
  WHERE sm.store_id = p_store_id
    AND sm.status = 'active'
    AND sm.role <> 'owner'
    AND (
      public.app_is_store_owner(p_store_id)
      OR public.user_has_store_permission(p_store_id, 'users.manage')
      OR public.user_has_store_permission(p_store_id, 'security.manage')
    )
  ORDER BY
    CASE sm.role
      WHEN 'admin' THEN 1
      WHEN 'manager' THEN 2
      WHEN 'stock_operator' THEN 3
      WHEN 'cashier' THEN 4
      WHEN 'sales' THEN 5
      WHEN 'staff' THEN 6
      WHEN 'viewer' THEN 7
      ELSE 99
    END,
    COALESCE(p.name, au.email, sm.user_id::text);
$$;


ALTER FUNCTION "public"."get_store_members_for_permissions"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_members_v2"("p_store_id" "uuid") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_email" "text", "profile_name" "text", "profile_phone" "text", "profile_mobile_phone" "text", "profile_whatsapp_phone" "text", "profile_avatar_url" "text", "profile_cpf" "text", "profile_birthdate" "date", "profile_zip_code" "text", "profile_address" "text", "profile_address_number" "text", "profile_complement" "text", "profile_district" "text", "profile_city" "text", "profile_state" "text", "profile_instagram_url" "text", "profile_facebook_url" "text", "profile_website_url" "text", "member_email" "text", "member_phone" "text", "member_mobile_phone" "text", "member_whatsapp_phone" "text", "member_avatar_url" "text", "member_zip_code" "text", "member_address" "text", "member_address_number" "text", "member_complement" "text", "member_district" "text", "member_city" "text", "member_state" "text", "member_additional_info" "jsonb", "role" "text", "status" "text", "permissions" "jsonb", "sensitive_actions" "jsonb", "custom_role_id" "uuid", "custom_role_name" "text", "custom_role_base_role" "text", "custom_role_active" boolean, "internal_alias" "text", "job_title" "text", "department" "text", "internal_notes" "text", "started_at" timestamp with time zone, "ended_at" timestamp with time zone, "exit_reason" "text", "status_reason" "text", "onboarding_required" boolean, "onboarding_completed_at" timestamp with time zone, "invited_by" "uuid", "invited_at" timestamp with time zone, "accepted_at" timestamp with time zone, "last_seen_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_can_view_sensitive boolean := false;
  v_can_view_additional_info boolean := false;
  v_can_view_sensitive_additional_info boolean := false;
  v_can_view_owner_members boolean := false;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.view')
    OR public.user_has_store_permission(p_store_id, 'users.manage')
    OR public.user_has_store_permission(p_store_id, 'security.view')
    OR public.user_has_store_permission(p_store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para visualizar usuários desta loja.';
  END IF;

  /*
    Permissão para listar usuários proprietários/owners.
    Owner logado sempre vê.
    Admin/outros papéis só veem se users.owner.view estiver liberada.
  */
  v_can_view_owner_members :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.owner.view');

  /*
    Dados sensíveis gerais.
  */
  v_can_view_sensitive :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.view')
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.manage')
    OR public.user_has_store_permission(p_store_id, 'security.manage');

  /*
    Informações adicionais comuns.
  */
  v_can_view_additional_info :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.additional_info.view')
    OR public.user_has_store_permission(p_store_id, 'users.additional_info.manage');

  /*
    Informações adicionais sensíveis.
  */
  v_can_view_sensitive_additional_info :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.additional_info_sensitive.view')
    OR public.user_has_store_permission(p_store_id, 'users.additional_info_sensitive.manage');

  RETURN QUERY
  SELECT
    sm.id AS member_id,
    sm.store_id,
    sm.user_id,
    au.email::text AS user_email,

    p.name AS profile_name,
    p.phone AS profile_phone,
    p.mobile_phone AS profile_mobile_phone,
    p.whatsapp_phone AS profile_whatsapp_phone,
    p.avatar_url AS profile_avatar_url,

    CASE WHEN v_can_view_sensitive THEN p.cpf ELSE NULL END AS profile_cpf,
    CASE WHEN v_can_view_sensitive THEN p.birthdata ELSE NULL END AS profile_birthdate,
    CASE WHEN v_can_view_sensitive THEN p.zip_code ELSE NULL END AS profile_zip_code,
    CASE WHEN v_can_view_sensitive THEN p.address ELSE NULL END AS profile_address,
    CASE WHEN v_can_view_sensitive THEN p.address_number ELSE NULL END AS profile_address_number,
    CASE WHEN v_can_view_sensitive THEN p.complement ELSE NULL END AS profile_complement,
    CASE WHEN v_can_view_sensitive THEN p.district ELSE NULL END AS profile_district,
    CASE WHEN v_can_view_sensitive THEN p.city ELSE NULL END AS profile_city,
    CASE WHEN v_can_view_sensitive THEN p.state ELSE NULL END AS profile_state,

    p.instagram_url AS profile_instagram_url,
    p.facebook_url AS profile_facebook_url,
    p.website_url AS profile_website_url,

    sm.member_email,
    sm.member_phone,
    sm.member_mobile_phone,
    sm.member_whatsapp_phone,
    sm.member_avatar_url,
    sm.member_zip_code,
    sm.member_address,
    sm.member_address_number,
    sm.member_complement,
    sm.member_district,
    sm.member_city,
    sm.member_state,

    CASE
      WHEN v_can_view_sensitive_additional_info THEN
        COALESCE(sm.member_additional_info, '[]'::jsonb)

      WHEN v_can_view_additional_info THEN (
        SELECT COALESCE(jsonb_agg(item), '[]'::jsonb)
        FROM jsonb_array_elements(COALESCE(sm.member_additional_info, '[]'::jsonb)) item
        WHERE COALESCE((item->>'sensitive')::boolean, false) = false
      )

      ELSE '[]'::jsonb
    END AS member_additional_info,

    sm.role,
    sm.status,
    COALESCE(sm.permissions, '{}'::jsonb) AS permissions,
    COALESCE(sm.sensitive_actions, '{}'::jsonb) AS sensitive_actions,

    sm.custom_role_id,
    scr.name AS custom_role_name,
    scr.base_role AS custom_role_base_role,
    scr.active AS custom_role_active,

    sm.internal_alias,
    sm.job_title,
    sm.department,
    CASE WHEN v_can_view_sensitive THEN sm.internal_notes ELSE NULL END AS internal_notes,

    sm.started_at,
    CASE WHEN v_can_view_sensitive THEN sm.ended_at ELSE NULL END AS ended_at,
    CASE WHEN v_can_view_sensitive THEN sm.exit_reason ELSE NULL END AS exit_reason,
    sm.status_reason,

    COALESCE(sm.onboarding_required, true) AS onboarding_required,
    sm.onboarding_completed_at,

    sm.invited_by,
    sm.invited_at,
    sm.accepted_at,
    sm.last_seen_at,
    sm.created_at,
    sm.updated_at
  FROM public.store_members sm
  LEFT JOIN auth.users au
    ON au.id = sm.user_id
  LEFT JOIN public.profiles p
    ON p.id = sm.user_id
  LEFT JOIN public.store_custom_roles scr
    ON scr.id = sm.custom_role_id
   AND scr.store_id = sm.store_id
  WHERE sm.store_id = p_store_id
    AND (
      sm.role <> 'owner'
      OR v_can_view_owner_members = true
    )
  ORDER BY
    CASE sm.role
      WHEN 'owner' THEN 1
      WHEN 'admin' THEN 2
      WHEN 'manager' THEN 3
      WHEN 'cashier' THEN 4
      WHEN 'stock_operator' THEN 5
      WHEN 'sales' THEN 6
      WHEN 'staff' THEN 7
      WHEN 'viewer' THEN 8
      ELSE 99
    END,
    COALESCE(sm.internal_alias, p.name, au.email::text, sm.user_id::text);
END;
$$;


ALTER FUNCTION "public"."get_store_members_v2"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_permission_catalog"() RETURNS TABLE("permission_key" "text", "category" "text", "label" "text", "description" "text", "risk" "text", "active" boolean, "sort_order" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.permission_key,
    c.category,
    c.label,
    c.description,
    c.risk,
    c.active,
    c.sort_order
  from public.store_permission_catalog c
  where c.active = true
  order by c.sort_order, c.label;
$$;


ALTER FUNCTION "public"."get_store_permission_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_permission_matrix"("p_store_id" "uuid") RETURNS TABLE("role" "text", "permission_code" "text", "allowed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if not public.can_access_security_section(p_store_id, 'roles', false) then
    raise exception 'Você não tem permissão para visualizar permissões por papel.';
  end if;

  return query
  with roles as (
    select *
    from (
      values
        ('owner'::text, 1),
        ('admin'::text, 2),
        ('manager'::text, 3),
        ('stock_operator'::text, 4),
        ('cashier'::text, 5),
        ('sales'::text, 6),
        ('staff'::text, 7),
        ('viewer'::text, 8)
    ) as r(role, sort_order)
  ),
  catalog as (
    select
      c.permission_key as permission_code,
      c.sort_order
    from public.store_permission_catalog c
    where c.active = true
  )
  select
    r.role,
    c.permission_code,
    case
      when r.role = 'owner' then true
      else coalesce(t.allowed, false)
    end as allowed
  from roles r
  cross join catalog c
  left join public.store_role_permission_templates t
    on t.store_id = p_store_id
   and t.role = r.role
   and t.permission_code = c.permission_code
  order by
    r.sort_order,
    c.sort_order,
    c.permission_code;
end;
$$;


ALTER FUNCTION "public"."get_store_permission_matrix"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_permission_matrix_v3"("p_store_id" "uuid") RETURNS TABLE("permission_code" "text", "label" "text", "description" "text", "module" "text", "action" "text", "risk_level" "text", "macro_group" "text", "group_key" "text", "group_label" "text", "item_key" "text", "item_label" "text", "action_key" "text", "action_label" "text", "depends_on" "text", "access_permission_key" "text", "ui_sort_order" integer, "show_in_permission_ui" boolean, "owner_allowed" boolean, "admin_allowed" boolean, "manager_allowed" boolean, "stock_operator_allowed" boolean, "cashier_allowed" boolean, "sales_allowed" boolean, "staff_allowed" boolean, "viewer_allowed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if not public.can_access_security_section_v3(p_store_id, 'roles', false) then
    raise exception 'Você não tem permissão para visualizar permissões por papel.';
  end if;

  return query
  select
    c.permission_key as permission_code,
    c.label,
    c.description,
    split_part(c.permission_key, '.', 1) as module,
    coalesce(c.action_key, split_part(c.permission_key, '.', 2)) as action,
    c.risk as risk_level,

    c.macro_group,
    c.group_key,
    c.group_label,
    c.item_key,
    c.item_label,
    c.action_key,
    c.action_label,
    c.depends_on,
    c.access_permission_key,
    c.ui_sort_order,
    c.show_in_permission_ui,

    true as owner_allowed,

    coalesce(max(t.allowed::int) filter (where t.role = 'admin'), 0)::boolean as admin_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'manager'), 0)::boolean as manager_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'stock_operator'), 0)::boolean as stock_operator_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'cashier'), 0)::boolean as cashier_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'sales'), 0)::boolean as sales_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'staff'), 0)::boolean as staff_allowed,
    coalesce(max(t.allowed::int) filter (where t.role = 'viewer'), 0)::boolean as viewer_allowed

  from public.store_permission_catalog c
  left join public.store_role_permission_templates t
    on t.store_id = p_store_id
   and t.permission_code = c.permission_key
  where c.active = true
    and coalesce(c.show_in_permission_ui, true) = true
  group by
    c.permission_key,
    c.label,
    c.description,
    c.risk,
    c.sort_order,
    c.macro_group,
    c.group_key,
    c.group_label,
    c.item_key,
    c.item_label,
    c.action_key,
    c.action_label,
    c.depends_on,
    c.access_permission_key,
    c.ui_sort_order,
    c.show_in_permission_ui
  order by
    coalesce(c.ui_sort_order, c.sort_order, 99999),
    c.permission_key;
end;
$$;


ALTER FUNCTION "public"."get_store_permission_matrix_v3"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_security_activity_logs"("p_store_id" "uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_user_filter" "text" DEFAULT NULL::"text", "p_action_filter" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "store_id" "uuid", "user_id" "uuid", "user_name" "text", "user_email" "text", "action" "text", "display_action" "text", "details" "jsonb", "outcome" "text", "sensitive" boolean, "visible_to_member" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.user_has_store_permission(p_store_id, 'security.logs.view')
    or public.user_has_store_permission(p_store_id, 'security.logs.manage')
    or public.user_has_store_permission(p_store_id, 'security.manage')
  ) then
    raise exception 'Acesso não autorizado aos logs da loja.';
  end if;

  return query
  select
    l.id,
    l.store_id,
    l.user_id,
    l.user_name,
    l.user_email,
    l.action,
    coalesce(l.display_action, public.translate_security_action_ptbr(l.action)) as display_action,
    l.details,
    l.outcome,
    l.sensitive,
    l.visible_to_member,
    l.created_at
  from public.store_security_logs l
  where l.store_id = p_store_id
    and (p_start_date is null or l.created_at::date >= p_start_date)
    and (p_end_date is null or l.created_at::date <= p_end_date)
    and (
      p_user_filter is null
      or l.user_name ilike '%' || p_user_filter || '%'
      or l.user_email ilike '%' || p_user_filter || '%'
    )
    and (
      p_action_filter is null
      or l.action ilike '%' || p_action_filter || '%'
      or coalesce(l.display_action, public.translate_security_action_ptbr(l.action)) ilike '%' || p_action_filter || '%'
    )
    and (p_outcome is null or l.outcome = p_outcome)
  order by l.created_at desc;
end;
$$;


ALTER FUNCTION "public"."get_store_security_activity_logs"("p_store_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_user_filter" "text", "p_action_filter" "text", "p_outcome" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."store_security_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid",
    "user_id" "uuid",
    "user_email" "text",
    "action" "text" NOT NULL,
    "details" "jsonb" DEFAULT '{}'::"jsonb",
    "outcome" "text",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "user_name" "text",
    "sensitive" boolean DEFAULT false NOT NULL,
    "visible_to_member" boolean DEFAULT true NOT NULL,
    "display_action" "text",
    CONSTRAINT "store_security_logs_outcome_check" CHECK (("outcome" = ANY (ARRAY['success'::"text", 'failure'::"text"])))
);


ALTER TABLE "public"."store_security_logs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_security_logs"("p_limit" integer DEFAULT 50) RETURNS SETOF "public"."store_security_logs"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
  SELECT ssl.*
  FROM public.store_security_logs ssl
  WHERE (
    public.app_is_store_owner(ssl.store_id)
    OR public.user_has_store_permission(ssl.store_id, 'security.view')
    OR public.user_has_store_permission(ssl.store_id, 'security.manage')
    OR public.user_has_store_permission(ssl.store_id, 'users.manage')
  )
  ORDER BY ssl.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 50), 200));
$$;


ALTER FUNCTION "public"."get_store_security_logs"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_store_security_logs"("p_limit" integer) IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC administrativa de logs de segurança. Revisar acesso por papel/perfil em etapa Configurações/Admin.';



CREATE OR REPLACE FUNCTION "public"."get_store_security_logs"("p_store_id" "uuid", "p_limit" integer DEFAULT 200, "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_user" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."store_security_logs"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
  SELECT ssl.*
  FROM public.store_security_logs ssl
  WHERE ssl.store_id = p_store_id
    AND (
      public.app_is_store_owner(p_store_id)
      OR public.user_has_store_permission(p_store_id, 'security.view')
      OR public.user_has_store_permission(p_store_id, 'security.manage')
      OR public.user_has_store_permission(p_store_id, 'users.manage')
    )
    AND (
      p_date_from IS NULL
      OR ssl.created_at >= (p_date_from::timestamp AT TIME ZONE 'America/Sao_Paulo')
    )
    AND (
      p_date_to IS NULL
      OR ssl.created_at < ((p_date_to + 1)::timestamp AT TIME ZONE 'America/Sao_Paulo')
    )
    AND (
      p_user IS NULL
      OR (
        COALESCE(ssl.user_name, '') || ' ' || COALESCE(ssl.user_email, '')
      ) ILIKE '%' || p_user || '%'
    )
    AND (
      p_action IS NULL
      OR COALESCE(ssl.action, '') ILIKE '%' || p_action || '%'
    )
    AND (
      p_outcome IS NULL
      OR COALESCE(ssl.outcome, '') = p_outcome
    )
  ORDER BY ssl.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 200), 500));
$$;


ALTER FUNCTION "public"."get_store_security_logs"("p_store_id" "uuid", "p_limit" integer, "p_date_from" "date", "p_date_to" "date", "p_user" "text", "p_action" "text", "p_outcome" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_store_security_logs"("p_store_id" "uuid", "p_limit" integer, "p_date_from" "date", "p_date_to" "date", "p_user" "text", "p_action" "text", "p_outcome" "text") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC administrativa de logs de segurança com filtros. Revisar acesso por papel/perfil em etapa Configurações/Admin.';



CREATE OR REPLACE FUNCTION "public"."get_store_security_settings"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "idle_timeout_enabled" boolean, "idle_timeout_minutes" integer, "idle_timeout_exempt_routes" "text"[], "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.is_store_member(p_store_id)
  ) then
    raise exception 'Acesso não autorizado.';
  end if;

  insert into public.store_security_settings as sss (
    store_id,
    idle_timeout_enabled,
    idle_timeout_minutes,
    idle_timeout_exempt_routes,
    created_at,
    updated_at
  )
  values (
    p_store_id,
    true,
    30,
    array[
      '/admin',
      '/admin/dashboard',
      '/admin/orders',
      '/admin/products',
      '/admin/stock',
      '/admin/stock-locations',
      '/admin/stock-movements'
    ]::text[],
    now(),
    now()
  )
  on conflict on constraint store_security_settings_pkey
  do nothing;

  return query
  select
    sss.store_id,
    sss.idle_timeout_enabled,
    sss.idle_timeout_minutes,
    sss.idle_timeout_exempt_routes,
    sss.updated_at
  from public.store_security_settings as sss
  where sss.store_id = p_store_id;
end;
$$;


ALTER FUNCTION "public"."get_store_security_settings"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_sensitive_action_matrix"("p_store_id" "uuid") RETURNS TABLE("action_code" "text", "module" "text", "label" "text", "description" "text", "risk_level" "text", "active" boolean, "enabled" boolean, "requirement" "text", "min_role" "text", "token_enabled" boolean, "token_expiry_seconds" integer, "max_attempts" integer, "require_reason" boolean, "source" "text", "sort_order" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.code AS action_code,
    c.module,
    c.label,
    c.description,
    c.risk_level,
    c.active,
    COALESCE(r.enabled, false) AS enabled,
    COALESCE(r.requirement, 'none') AS requirement,
    COALESCE(r.min_role, 'owner') AS min_role,
    COALESCE(r.token_enabled, false) AS token_enabled,
    COALESCE(r.token_expiry_seconds, 15) AS token_expiry_seconds,
    COALESCE(r.max_attempts, 3) AS max_attempts,
    COALESCE(r.require_reason, true) AS require_reason,
    COALESCE(r.source, 'default_denied') AS source,
    c.sort_order
  FROM public.security_sensitive_action_catalog c
  LEFT JOIN public.store_sensitive_action_rules r
    ON r.store_id = p_store_id
   AND r.action_code = c.code
  WHERE c.active = true
    AND (
      public.app_is_store_owner(p_store_id)
      OR public.user_has_store_permission(p_store_id, 'security.manage')
    )
  ORDER BY c.sort_order, c.module, c.code;
$$;


ALTER FUNCTION "public"."get_store_sensitive_action_matrix"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_settings_center"("p_store_id" "uuid") RETURNS TABLE("store_id" "uuid", "name" "text", "slug" "text", "description" "text", "logo_url" "text", "phone_number" "text", "legal_name" "text", "doc_type" "text", "document" "text", "fantasy_name" "text", "establishment_type" "text", "address" "jsonb", "contacts" "jsonb", "consents" "jsonb", "privacy_policy_text" "text", "terms_of_use_text" "text", "cookie_policy_text" "text", "dpo_email" "text", "dpo_contact" "text", "public_store_enabled" boolean, "public_catalog_enabled" boolean, "minimum_order_value" numeric, "reservation_time_minutes" integer, "public_sales_location_id" "uuid", "commercial_config" "jsonb", "commercial_settings" "jsonb", "order_settings" "jsonb", "stock_settings" "jsonb", "delivery_settings" "jsonb", "payment_settings" "jsonb", "legal_settings" "jsonb", "system_settings" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_can_root boolean := false;

  v_can_store boolean := false;
  v_can_commercial boolean := false;
  v_can_orders boolean := false;
  v_can_stock boolean := false;
  v_can_delivery boolean := false;
  v_can_payment boolean := false;
  v_can_legal boolean := false;
  v_can_system boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  v_can_root :=
    public.app_is_store_owner(p_store_id)
    or public.user_has_store_permission(p_store_id, 'settings.view');

  if not v_can_root then
    raise exception 'Você não tem permissão para acessar Configurações.';
  end if;

  v_can_store := public.can_access_settings_section(p_store_id, 'store', false);
  v_can_commercial := public.can_access_settings_section(p_store_id, 'commercial', false);
  v_can_orders := public.can_access_settings_section(p_store_id, 'orders', false);
  v_can_stock := public.can_access_settings_section(p_store_id, 'stock', false);
  v_can_delivery := public.can_access_settings_section(p_store_id, 'delivery', false);
  v_can_payment := public.can_access_settings_section(p_store_id, 'payment', false);
  v_can_legal := public.can_access_settings_section(p_store_id, 'legal', false);
  v_can_system := public.can_access_settings_section(p_store_id, 'system', false);

  insert into public.store_settings as ss_insert (
    store_id
  )
  values (
    p_store_id
  )
  on conflict on constraint store_settings_pkey
  do nothing;

  return query
  select
    s.id as store_id,

    case when v_can_store then s.name else null end as name,
    case when v_can_store then s.slug else null end as slug,
    case when v_can_store then s.description else null end as description,
    case when v_can_store then s.logo_url else null end as logo_url,
    case when v_can_store then s.phone_number else null end as phone_number,

    case when v_can_store then s.legal_name else null end as legal_name,
    case when v_can_store then s.doc_type else null end as doc_type,
    case when v_can_store then s.document else null end as document,
    case when v_can_store then s.fantasy_name else null end as fantasy_name,
    case when v_can_store then s.establishment_type else null end as establishment_type,

    case when v_can_store then coalesce(s.address, '{}'::jsonb) else null end as address,
    case when v_can_store then coalesce(s.contacts, '{}'::jsonb) else null end as contacts,
    case when v_can_store then coalesce(s.consents, '{}'::jsonb) else null end as consents,

    case when v_can_legal then s.privacy_policy_text else null end as privacy_policy_text,
    case when v_can_legal then s.terms_of_use_text else null end as terms_of_use_text,
    case when v_can_legal then s.cookie_policy_text else null end as cookie_policy_text,
    case when v_can_legal then s.dpo_email else null end as dpo_email,
    case when v_can_legal then s.dpo_contact else null end as dpo_contact,

    case when v_can_orders then s.public_store_enabled else null end as public_store_enabled,
    case when v_can_orders then s.public_catalog_enabled else null end as public_catalog_enabled,
    case when v_can_orders then s.minimum_order_value else null end as minimum_order_value,
    case when v_can_orders then s.reservation_time_minutes else null end as reservation_time_minutes,
    case when v_can_orders then s.public_sales_location_id else null end as public_sales_location_id,

    case when v_can_commercial then coalesce(s.commercial_config, '{}'::jsonb) else null end as commercial_config,

    case when v_can_commercial then coalesce(ss.commercial_settings, '{}'::jsonb) else null end as commercial_settings,
    case when v_can_orders then coalesce(ss.order_settings, '{}'::jsonb) else null end as order_settings,
    case when v_can_stock then coalesce(ss.stock_settings, '{}'::jsonb) else null end as stock_settings,
    case when v_can_delivery then coalesce(ss.delivery_settings, '{}'::jsonb) else null end as delivery_settings,
    case when v_can_payment then coalesce(ss.payment_settings, '{}'::jsonb) else null end as payment_settings,
    case when v_can_legal then coalesce(ss.legal_settings, '{}'::jsonb) else null end as legal_settings,
    case when v_can_system then coalesce(ss.system_settings, '{}'::jsonb) else null end as system_settings,

    greatest(s.created_at, ss.updated_at) as updated_at
  from public.stores as s
  join public.store_settings as ss
    on ss.store_id = s.id
  where s.id = p_store_id;
end;
$$;


ALTER FUNCTION "public"."get_store_settings_center"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_360_summary"("p_supplier_id" "uuid") RETURNS TABLE("supplier_id" "uuid", "store_id" "uuid", "name" "text", "legal_name" "text", "trade_name" "text", "document" "text", "phone" "text", "email" "text", "active" boolean, "homologation_status" "text", "preferred_supplier" boolean, "blocked" boolean, "blocked_reason" "text", "last_contact_at" timestamp with time zone, "total_purchase_documents" bigint, "confirmed_purchase_documents" bigint, "draft_purchase_documents" bigint, "cancelled_purchase_documents" bigint, "total_purchased_amount" numeric, "confirmed_purchased_amount" numeric, "average_ticket" numeric, "first_purchase_date" "date", "last_purchase_date" "date", "days_since_last_purchase" integer, "distinct_products" bigint, "total_items_quantity" numeric, "contacts_count" bigint, "relationship_events_count" bigint, "open_relationship_events_count" bigint, "critical_relationship_events_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH supplier_base AS (
    SELECT s.*
    FROM public.suppliers s
    WHERE s.id = p_supplier_id
      AND public.is_store_member(s.store_id)
  ),

  docs AS (
    SELECT
      pd.supplier_id,
      COUNT(*)::bigint AS total_purchase_documents,
      COUNT(*) FILTER (WHERE pd.status = 'confirmed')::bigint AS confirmed_purchase_documents,
      COUNT(*) FILTER (WHERE pd.status = 'draft')::bigint AS draft_purchase_documents,
      COUNT(*) FILTER (WHERE pd.status = 'cancelled')::bigint AS cancelled_purchase_documents,

      COALESCE(SUM(pd.total_amount), 0)::numeric AS total_purchased_amount,
      COALESCE(SUM(pd.total_amount) FILTER (WHERE pd.status = 'confirmed'), 0)::numeric AS confirmed_purchased_amount,

      MIN(pd.issue_date)::date AS first_purchase_date,
      MAX(pd.issue_date)::date AS last_purchase_date
    FROM public.purchase_documents pd
    JOIN supplier_base sb
      ON sb.id = pd.supplier_id
     AND sb.store_id = pd.store_id
    GROUP BY pd.supplier_id
  ),

  items AS (
    SELECT
      pd.supplier_id,
      COUNT(DISTINCT pdi.product_id)::bigint AS distinct_products,
      COALESCE(SUM(pdi.quantity), 0)::numeric AS total_items_quantity
    FROM public.purchase_documents pd
    JOIN public.purchase_document_items pdi
      ON pdi.purchase_document_id = pd.id
     AND pdi.store_id = pd.store_id
    JOIN supplier_base sb
      ON sb.id = pd.supplier_id
     AND sb.store_id = pd.store_id
    WHERE pd.status <> 'cancelled'
    GROUP BY pd.supplier_id
  ),

  contacts AS (
    SELECT
      sc.supplier_id,
      COUNT(*)::bigint AS contacts_count
    FROM public.supplier_contacts sc
    JOIN supplier_base sb
      ON sb.id = sc.supplier_id
     AND sb.store_id = sc.store_id
    WHERE sc.active = true
    GROUP BY sc.supplier_id
  ),

  events AS (
    SELECT
      sre.supplier_id,
      COUNT(*)::bigint AS relationship_events_count,
      COUNT(*) FILTER (WHERE sre.status = 'open')::bigint AS open_relationship_events_count,
      COUNT(*) FILTER (WHERE sre.severity = 'critical')::bigint AS critical_relationship_events_count
    FROM public.supplier_relationship_events sre
    JOIN supplier_base sb
      ON sb.id = sre.supplier_id
     AND sb.store_id = sre.store_id
    GROUP BY sre.supplier_id
  )

  SELECT
    sb.id AS supplier_id,
    sb.store_id,

    sb.name,
    sb.legal_name,
    sb.trade_name,
    sb.document,
    sb.phone,
    sb.email,
    sb.active,

    sb.homologation_status,
    sb.preferred_supplier,
    sb.blocked,
    sb.blocked_reason,
    sb.last_contact_at,

    COALESCE(d.total_purchase_documents, 0)::bigint,
    COALESCE(d.confirmed_purchase_documents, 0)::bigint,
    COALESCE(d.draft_purchase_documents, 0)::bigint,
    COALESCE(d.cancelled_purchase_documents, 0)::bigint,

    COALESCE(d.total_purchased_amount, 0)::numeric,
    COALESCE(d.confirmed_purchased_amount, 0)::numeric,

    CASE
      WHEN COALESCE(d.confirmed_purchase_documents, 0) > 0
      THEN ROUND(d.confirmed_purchased_amount / d.confirmed_purchase_documents, 2)
      ELSE 0::numeric
    END AS average_ticket,

    d.first_purchase_date,
    d.last_purchase_date,

    CASE
      WHEN d.last_purchase_date IS NULL THEN NULL
      ELSE (CURRENT_DATE - d.last_purchase_date)::integer
    END AS days_since_last_purchase,

    COALESCE(i.distinct_products, 0)::bigint,
    COALESCE(i.total_items_quantity, 0)::numeric,

    COALESCE(c.contacts_count, 0)::bigint,
    COALESCE(e.relationship_events_count, 0)::bigint,
    COALESCE(e.open_relationship_events_count, 0)::bigint,
    COALESCE(e.critical_relationship_events_count, 0)::bigint

  FROM supplier_base sb
  LEFT JOIN docs d
    ON d.supplier_id = sb.id
  LEFT JOIN items i
    ON i.supplier_id = sb.id
  LEFT JOIN contacts c
    ON c.supplier_id = sb.id
  LEFT JOIN events e
    ON e.supplier_id = sb.id;
$$;


ALTER FUNCTION "public"."get_supplier_360_summary"("p_supplier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_contacts"("p_supplier_id" "uuid") RETURNS TABLE("id" "text", "store_id" "uuid", "supplier_id" "uuid", "name" "text", "role" "text", "department" "text", "phone" "text", "whatsapp" "text", "email" "text", "notes" "text", "is_primary" boolean, "active" boolean, "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with supplier_base as (
    select s.*
    from public.suppliers s
    where s.id = p_supplier_id
      and public.is_store_member(s.store_id)
  ),

  explicit_contacts as (
    select
      c.id::text as id,
      c.store_id,
      c.supplier_id,
      c.name,
      c.role,
      c.department,
      c.phone,
      c.whatsapp,
      c.email,
      c.notes,
      c.is_primary,
      c.active,
      c.metadata,
      c.created_at,
      c.updated_at
    from public.supplier_contacts c
    join supplier_base s
      on s.id = c.supplier_id
    where c.supplier_id = p_supplier_id
  ),

  commercial_contact as (
    select
      ('supplier:' || s.id::text || ':commercial')::text as id,
      s.store_id,
      s.id as supplier_id,
      coalesce(nullif(trim(s.commercial_contact_name), ''), 'Contato comercial') as name,
      nullif(trim(s.commercial_contact_role), '') as role,
      'commercial'::text as department,
      nullif(trim(s.commercial_phone), '') as phone,
      nullif(trim(s.commercial_whatsapp), '') as whatsapp,
      nullif(trim(s.commercial_email), '') as email,
      null::text as notes,
      true as is_primary,
      true as active,
      jsonb_build_object('source', 'suppliers.commercial_contact') as metadata,
      s.created_at,
      coalesce(s.updated_at, s.created_at) as updated_at
    from supplier_base s
    where
      nullif(trim(coalesce(s.commercial_contact_name, '')), '') is not null
      or nullif(trim(coalesce(s.commercial_phone, '')), '') is not null
      or nullif(trim(coalesce(s.commercial_whatsapp, '')), '') is not null
      or nullif(trim(coalesce(s.commercial_email, '')), '') is not null
  ),

  financial_contact as (
    select
      ('supplier:' || s.id::text || ':financial')::text as id,
      s.store_id,
      s.id as supplier_id,
      coalesce(nullif(trim(s.financial_contact_name), ''), 'Contato financeiro') as name,
      'Financeiro'::text as role,
      'financial'::text as department,
      nullif(trim(s.financial_phone), '') as phone,
      null::text as whatsapp,
      nullif(trim(s.financial_email), '') as email,
      null::text as notes,
      false as is_primary,
      true as active,
      jsonb_build_object('source', 'suppliers.financial_contact') as metadata,
      s.created_at,
      coalesce(s.updated_at, s.created_at) as updated_at
    from supplier_base s
    where
      nullif(trim(coalesce(s.financial_contact_name, '')), '') is not null
      or nullif(trim(coalesce(s.financial_phone, '')), '') is not null
      or nullif(trim(coalesce(s.financial_email, '')), '') is not null
  ),

  fiscal_contact as (
    select
      ('supplier:' || s.id::text || ':fiscal')::text as id,
      s.store_id,
      s.id as supplier_id,
      coalesce(nullif(trim(s.fiscal_contact_name), ''), 'Contato fiscal') as name,
      'Fiscal'::text as role,
      'fiscal'::text as department,
      nullif(trim(s.fiscal_phone), '') as phone,
      null::text as whatsapp,
      nullif(trim(s.fiscal_email), '') as email,
      null::text as notes,
      false as is_primary,
      true as active,
      jsonb_build_object('source', 'suppliers.fiscal_contact') as metadata,
      s.created_at,
      coalesce(s.updated_at, s.created_at) as updated_at
    from supplier_base s
    where
      nullif(trim(coalesce(s.fiscal_contact_name, '')), '') is not null
      or nullif(trim(coalesce(s.fiscal_phone, '')), '') is not null
      or nullif(trim(coalesce(s.fiscal_email, '')), '') is not null
  ),

  all_contacts as (
    select * from explicit_contacts
    union all
    select * from commercial_contact
    union all
    select * from financial_contact
    union all
    select * from fiscal_contact
  )

  select *
  from all_contacts
  order by
    is_primary desc,
    case department
      when 'commercial' then 1
      when 'financial' then 2
      when 'fiscal' then 3
      when 'logistics' then 4
      when 'support' then 5
      else 9
    end,
    name asc;
$$;


