CREATE OR REPLACE FUNCTION "public"."get_supplier_price_evolution"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "product_id" "uuid", "product_name" "text", "purchase_document_id" "uuid", "purchase_document_item_id" "uuid", "unit_cost" numeric, "quantity" numeric, "total_cost" numeric, "issue_date" "date", "effective_at" timestamp with time zone, "source" "text", "document_code" "text", "invoice_number" "text", "is_active" boolean, "cancelled_at" timestamp with time zone, "cancelled_reason" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    sph.id,
    sph.store_id,
    sph.supplier_id,
    sph.product_id,
    p.name as product_name,

    coalesce(
      sph.purchase_document_id,
      pdi.purchase_document_id
    ) as purchase_document_id,

    sph.purchase_document_item_id,
    sph.unit_cost,
    sph.quantity,
    coalesce(sph.total_cost, sph.quantity * sph.unit_cost) as total_cost,
    coalesce(sph.issue_date, d.issue_date) as issue_date,
    sph.effective_at,
    sph.source,

    d.document_code,
    d.invoice_number,

    coalesce(sph.is_active, true) as is_active,
    sph.cancelled_at,
    sph.cancelled_reason
  from public.supplier_price_history sph
  join public.products p
    on p.id = sph.product_id

  left join public.purchase_document_items pdi
    on pdi.id = sph.purchase_document_item_id

  left join public.purchase_documents d
    on d.id = coalesce(
      sph.purchase_document_id,
      pdi.purchase_document_id
    )

  where sph.supplier_id = p_supplier_id
    and public.is_store_member(sph.store_id)
  order by sph.effective_at desc, sph.created_at desc
  limit greatest(coalesce(p_limit, 200), 1);
$$;


ALTER FUNCTION "public"."get_supplier_price_evolution"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_price_evolution"("p_supplier_id" "uuid", "p_product_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 300) RETURNS TABLE("id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "product_id" "uuid", "product_name" "text", "purchase_document_id" "uuid", "purchase_document_item_id" "uuid", "unit_cost" numeric, "quantity" numeric, "total_cost" numeric, "issue_date" "date", "effective_at" timestamp with time zone, "source" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH supplier_base AS (
    SELECT s.*
    FROM public.suppliers s
    WHERE s.id = p_supplier_id
      AND public.is_store_member(s.store_id)
  )

  SELECT
    sph.id,
    sph.store_id,
    sph.supplier_id,
    sph.product_id,
    p.name AS product_name,
    sph.purchase_document_id,
    sph.purchase_document_item_id,
    sph.unit_cost,
    sph.quantity,
    sph.total_cost,
    sph.issue_date,
    sph.effective_at,
    sph.source

  FROM public.supplier_price_history sph
  JOIN supplier_base sb
    ON sb.id = sph.supplier_id
   AND sb.store_id = sph.store_id
  JOIN public.products p
    ON p.id = sph.product_id
   AND p.store_id = sph.store_id
  WHERE sph.is_active = true
    AND sph.cancelled_at IS NULL
    AND (
      p_product_id IS NULL
      OR sph.product_id = p_product_id
    )
  ORDER BY
    sph.issue_date DESC NULLS LAST,
    sph.effective_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 300), 1000));
$$;


ALTER FUNCTION "public"."get_supplier_price_evolution"("p_supplier_id" "uuid", "p_product_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_purchase_history"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("purchase_document_id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "document_code" "text", "invoice_number" "text", "issue_date" "date", "status" "text", "total_amount" numeric, "notes" "text", "created_at" timestamp with time zone, "cancelled_at" timestamp with time zone, "cancel_reason" "text", "items_count" bigint, "total_quantity" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    d.id as purchase_document_id,
    d.store_id,
    d.supplier_id,
    d.document_code,
    d.invoice_number,
    d.issue_date,
    d.status,
    coalesce(d.total_amount, 0) as total_amount,
    d.notes,
    d.created_at,
    d.cancelled_at,
    d.cancel_reason,
    count(i.id)::bigint as items_count,
    coalesce(sum(i.quantity), 0)::numeric as total_quantity
  from public.purchase_documents d
  left join public.purchase_document_items i
    on i.purchase_document_id = d.id
  where d.supplier_id = p_supplier_id
    and public.is_store_member(d.store_id)
  group by
    d.id,
    d.store_id,
    d.supplier_id,
    d.document_code,
    d.invoice_number,
    d.issue_date,
    d.status,
    d.total_amount,
    d.notes,
    d.created_at,
    d.cancelled_at,
    d.cancel_reason
  order by d.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."get_supplier_purchase_history"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_quotation_history"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("quotation_id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "quotation_code" "text", "status" "text", "requested_at" timestamp with time zone, "responded_at" timestamp with time zone, "expires_at" timestamp with time zone, "sent_channel" "text", "responsible_name" "text", "notes" "text", "converted_purchase_document_id" "uuid", "converted_document_code" "text", "converted_invoice_number" "text", "items_count" bigint, "products_count" bigint, "requested_qty" numeric, "approved_qty" numeric, "reference_total" numeric, "quoted_total" numeric, "approved_total" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    q.id as quotation_id,
    q.store_id,
    q.supplier_id,
    q.quotation_code,
    q.status,
    q.requested_at,
    q.responded_at,
    q.expires_at,
    q.sent_channel,
    q.responsible_name,
    q.notes,
    q.converted_purchase_document_id,
    d.document_code as converted_document_code,
    d.invoice_number as converted_invoice_number,

    count(i.id)::bigint as items_count,
    count(distinct i.product_id)::bigint as products_count,

    coalesce(sum(i.requested_qty), 0)::numeric as requested_qty,
    coalesce(sum(i.approved_qty), 0)::numeric as approved_qty,

    coalesce(
      sum(i.requested_qty * coalesce(i.reference_unit_cost, 0)),
      0
    )::numeric as reference_total,

    coalesce(
      sum(i.requested_qty * coalesce(i.quoted_unit_cost, 0)),
      0
    )::numeric as quoted_total,

    coalesce(
      sum(coalesce(i.approved_qty, 0) * coalesce(i.quoted_unit_cost, 0)),
      0
    )::numeric as approved_total
  from public.purchase_quotations q
  left join public.purchase_quotation_items i
    on i.quotation_id = q.id
  left join public.purchase_documents d
    on d.id = q.converted_purchase_document_id
  where q.supplier_id = p_supplier_id
    and public.is_store_member(q.store_id)
  group by
    q.id,
    q.store_id,
    q.supplier_id,
    q.quotation_code,
    q.status,
    q.requested_at,
    q.responded_at,
    q.expires_at,
    q.sent_channel,
    q.responsible_name,
    q.notes,
    q.converted_purchase_document_id,
    d.document_code,
    d.invoice_number
  order by q.requested_at desc, q.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."get_supplier_quotation_history"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_relationship_timeline"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "store_id" "uuid", "supplier_id" "uuid", "event_type" "text", "title" "text", "description" "text", "event_at" timestamp with time zone, "severity" "text", "status" "text", "related_purchase_document_id" "uuid", "related_product_id" "uuid", "related_product_name" "text", "created_by" "uuid", "created_by_email" "text", "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH supplier_base AS (
    SELECT s.*
    FROM public.suppliers s
    WHERE s.id = p_supplier_id
      AND public.is_store_member(s.store_id)
  )

  SELECT
    sre.id,
    sre.store_id,
    sre.supplier_id,
    sre.event_type,
    sre.title,
    sre.description,
    sre.event_at,
    sre.severity,
    sre.status,
    sre.related_purchase_document_id,
    sre.related_product_id,
    p.name AS related_product_name,
    sre.created_by,
    sre.created_by_email,
    sre.metadata,
    sre.created_at,
    sre.updated_at

  FROM public.supplier_relationship_events sre
  JOIN supplier_base sb
    ON sb.id = sre.supplier_id
   AND sb.store_id = sre.store_id
  LEFT JOIN public.products p
    ON p.id = sre.related_product_id
   AND p.store_id = sre.store_id
  ORDER BY
    sre.event_at DESC,
    sre.created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 500));
$$;


ALTER FUNCTION "public"."get_supplier_relationship_timeline"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_supplied_products"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 200) RETURNS TABLE("supplier_id" "uuid", "store_id" "uuid", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "product_active" boolean, "purchase_count" bigint, "total_quantity" numeric, "total_cost" numeric, "average_unit_cost" numeric, "min_unit_cost" numeric, "max_unit_cost" numeric, "last_unit_cost" numeric, "last_purchase_date" "date", "last_purchase_document_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH supplier_base AS (
    SELECT s.*
    FROM public.suppliers s
    WHERE s.id = p_supplier_id
      AND public.is_store_member(s.store_id)
  ),

  price_rows AS (
    SELECT
      sph.*,
      ROW_NUMBER() OVER (
        PARTITION BY sph.product_id
        ORDER BY sph.effective_at DESC, sph.created_at DESC
      ) AS rn
    FROM public.supplier_price_history sph
    JOIN supplier_base sb
      ON sb.id = sph.supplier_id
     AND sb.store_id = sph.store_id
    WHERE sph.is_active = true
      AND sph.cancelled_at IS NULL
  ),

  agg AS (
    SELECT
      pr.supplier_id,
      pr.store_id,
      pr.product_id,

      COUNT(*)::bigint AS purchase_count,
      COALESCE(SUM(pr.quantity), 0)::numeric AS total_quantity,
      COALESCE(SUM(pr.total_cost), 0)::numeric AS total_cost,

      ROUND(AVG(pr.unit_cost), 4)::numeric AS average_unit_cost,
      MIN(pr.unit_cost)::numeric AS min_unit_cost,
      MAX(pr.unit_cost)::numeric AS max_unit_cost,
      MAX(pr.issue_date)::date AS last_purchase_date
    FROM price_rows pr
    GROUP BY
      pr.supplier_id,
      pr.store_id,
      pr.product_id
  ),

  last_price AS (
    SELECT
      pr.supplier_id,
      pr.store_id,
      pr.product_id,
      pr.unit_cost AS last_unit_cost,
      pr.purchase_document_id AS last_purchase_document_id
    FROM price_rows pr
    WHERE pr.rn = 1
  )

  SELECT
    a.supplier_id,
    a.store_id,
    p.id AS product_id,
    p.name AS product_name,
    p.category_id,
    COALESCE(p.active, true) AS product_active,

    a.purchase_count,
    a.total_quantity,
    a.total_cost,

    a.average_unit_cost,
    a.min_unit_cost,
    a.max_unit_cost,
    lp.last_unit_cost,
    a.last_purchase_date,

    lp.last_purchase_document_id

  FROM agg a
  JOIN public.products p
    ON p.id = a.product_id
   AND p.store_id = a.store_id
  LEFT JOIN last_price lp
    ON lp.supplier_id = a.supplier_id
   AND lp.store_id = a.store_id
   AND lp.product_id = a.product_id
  ORDER BY
    a.total_cost DESC,
    p.name ASC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
$$;


ALTER FUNCTION "public"."get_supplier_supplied_products"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_unified_timeline"("p_supplier_id" "uuid", "p_limit" integer DEFAULT 150) RETURNS TABLE("id" "text", "source_kind" "text", "store_id" "uuid", "supplier_id" "uuid", "event_type" "text", "title" "text", "description" "text", "severity" "text", "status" "text", "event_at" timestamp with time zone, "created_at" timestamp with time zone, "channel" "text", "reference_label" "text", "related_product_id" "uuid", "related_purchase_document_id" "uuid", "related_purchase_quotation_id" "uuid", "related_stock_transfer_id" "uuid", "related_stock_movement_id" "uuid", "actor_email" "text", "created_by_email" "text", "metadata" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with manual_events as (
    select
      ('relationship:' || e.id::text)::text as id,
      'relationship'::text as source_kind,
      e.store_id,
      e.supplier_id,
      e.event_type,
      e.title,
      e.description,
      e.severity,
      e.status,
      e.event_at,
      e.created_at,
      'manual'::text as channel,
      null::text as reference_label,
      e.related_product_id,
      e.related_purchase_document_id,
      null::uuid as related_purchase_quotation_id,
      null::uuid as related_stock_transfer_id,
      null::uuid as related_stock_movement_id,
      null::text as actor_email,
      e.created_by_email,
      e.metadata
    from public.supplier_relationship_events e
    where e.supplier_id = p_supplier_id
  ),

  operational_events as (
    select
      ('operational:' || ote.id::text)::text as id,
      'operational'::text as source_kind,
      ote.store_id,

      coalesce(
        ote.related_supplier_id,
        pd.supplier_id,
        pq.supplier_id,
        case
          when ote.entity_type = 'supplier' then ote.entity_id
          else null
        end
      ) as supplier_id,

      ote.event_type,
      ote.title,
      ote.description,
      ote.severity,
      ote.status,
      ote.occurred_at as event_at,
      ote.created_at,
      ote.channel,

      coalesce(
        pq.quotation_code,
        pd.document_code,
        st.transfer_code,
        ote.metadata ->> 'reference_label',
        ote.metadata ->> 'document_code',
        ote.metadata ->> 'quotation_code',
        ote.metadata ->> 'transfer_code'
      ) as reference_label,

      ote.related_product_id,

      coalesce(
        ote.related_purchase_document_id,
        case
          when ote.entity_type = 'purchase_document' then ote.entity_id
          else null
        end
      ) as related_purchase_document_id,

      coalesce(
        ote.related_purchase_quotation_id,
        case
          when ote.entity_type = 'purchase_quotation' then ote.entity_id
          else null
        end
      ) as related_purchase_quotation_id,

      coalesce(
        ote.related_stock_transfer_id,
        case
          when ote.entity_type = 'stock_transfer' then ote.entity_id
          else null
        end
      ) as related_stock_transfer_id,

      coalesce(
        ote.related_stock_movement_id,
        case
          when ote.entity_type = 'stock_movement' then ote.entity_id
          else null
        end
      ) as related_stock_movement_id,

      ote.actor_email,
      null::text as created_by_email,
      ote.metadata
    from public.operational_timeline_events ote

    left join public.purchase_documents pd
      on pd.id = coalesce(
        ote.related_purchase_document_id,
        case
          when ote.entity_type = 'purchase_document' then ote.entity_id
          else null
        end
      )

    left join public.purchase_quotations pq
      on pq.id = coalesce(
        ote.related_purchase_quotation_id,
        case
          when ote.entity_type = 'purchase_quotation' then ote.entity_id
          else null
        end
      )

    left join public.stock_transfers st
      on st.id = coalesce(
        ote.related_stock_transfer_id,
        case
          when ote.entity_type = 'stock_transfer' then ote.entity_id
          else null
        end
      )

    where
      ote.related_supplier_id = p_supplier_id
      or (ote.entity_type = 'supplier' and ote.entity_id = p_supplier_id)
      or pd.supplier_id = p_supplier_id
      or pq.supplier_id = p_supplier_id
  ),

  all_events as (
    select * from manual_events
    union all
    select * from operational_events
  )

  select *
  from all_events
  where supplier_id = p_supplier_id
  order by event_at desc, created_at desc
  limit greatest(coalesce(p_limit, 150), 1);
$$;


ALTER FUNCTION "public"."get_supplier_unified_timeline"("p_supplier_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_transfer_prefill_preview"("p_product_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "product_name" "text", "source_location_id" "uuid", "source_location_code" "text", "source_location_name" "text", "destination_location_id" "uuid", "destination_location_code" "text", "destination_location_name" "text", "source_available" numeric, "destination_available" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
BEGIN
  SELECT p.store_id
  INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado.';
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado à loja informada.';
  END IF;

  RETURN QUERY
  SELECT
    p.store_id,
    p.id AS product_id,
    p.name AS product_name,

    src.id AS source_location_id,
    src.code AS source_location_code,
    src.name AS source_location_name,

    dst.id AS destination_location_id,
    dst.code AS destination_location_code,
    dst.name AS destination_location_name,

    COALESCE(src_bal.on_hand, 0) - COALESCE(src_bal.reserved, 0) AS source_available,
    COALESCE(dst_bal.on_hand, 0) - COALESCE(dst_bal.reserved, 0) AS destination_available

  FROM public.products p
  JOIN public.stock_locations src
    ON src.id = p_source_location_id
   AND src.store_id = p.store_id
  JOIN public.stock_locations dst
    ON dst.id = p_destination_location_id
   AND dst.store_id = p.store_id
  LEFT JOIN public.inventory_location_balances src_bal
    ON src_bal.store_id = p.store_id
   AND src_bal.product_id = p.id
   AND src_bal.location_id = src.id
   AND src_bal.variant_id IS NULL
  LEFT JOIN public.inventory_location_balances dst_bal
    ON dst_bal.store_id = p.store_id
   AND dst_bal.product_id = p.id
   AND dst_bal.location_id = dst.id
   AND dst_bal.variant_id IS NULL
  WHERE p.id = p_product_id;
END;
$$;


ALTER FUNCTION "public"."get_transfer_prefill_preview"("p_product_id" "uuid", "p_source_location_id" "uuid", "p_destination_location_id" "uuid") OWNER TO "postgres";


