CREATE OR REPLACE FUNCTION "public"."grant_loyalty_join_bonus"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_program RECORD;
    v_already_granted BOOLEAN;
BEGIN
    -- Check if Join Bonus should be granted:
    -- - INSERT: registering with loyalty_opt_in = true
    -- - UPDATE: toggling loyalty_opt_in to true
    IF (TG_OP = 'INSERT' AND NEW.loyalty_opt_in = TRUE) OR 
       (TG_OP = 'UPDATE' AND NEW.loyalty_opt_in = TRUE AND (OLD.loyalty_opt_in IS NULL OR OLD.loyalty_opt_in = FALSE)) THEN
        
        -- Find active loyalty program
        SELECT fp.* INTO v_program
        FROM fidelity_programs fp
        WHERE fp.store_id = NEW.store_id
        AND fp.is_active = TRUE
        AND fp.enable_join_bonus = TRUE
        LIMIT 1;
        
        IF FOUND AND v_program.join_bonus_points > 0 THEN
            -- Check if already received
            SELECT EXISTS (
                SELECT 1 FROM loyalty_transactions
                WHERE customer_id = NEW.id AND type = 'join_bonus'
            ) INTO v_already_granted;
            
            IF NOT v_already_granted THEN
                -- 1. Update points on the NEW record
                NEW.loyalty_points := COALESCE(NEW.loyalty_points, 0) + v_program.join_bonus_points;
                NEW.last_point_activity_at := NOW();
                
                -- 2. Log transaction (Allowed by SECURITY DEFINER)
                INSERT INTO loyalty_transactions (
                    program_id, customer_id, type, points, description
                ) VALUES (
                    v_program.id, NEW.id, 'join_bonus', v_program.join_bonus_points, 'Bônus de boas-vindas'
                );
                
                -- 3. Create notification (Allowed by SECURITY DEFINER)
                INSERT INTO customer_notifications (
                    customer_id, store_id, title, message, type
                ) VALUES (
                    NEW.id, NEW.store_id, '🎉 Bem-vindo ao Programa de Fidelidade!', 
                    'Você ganhou ' || v_program.join_bonus_points || ' pontos de bônus por se cadastrar!', 'success'
                );
                
                RAISE NOTICE 'Join bonus granted: % points to customer %', v_program.join_bonus_points, NEW.id;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."grant_loyalty_join_bonus"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grant_loyalty_join_bonus"() IS 'Automatically grants join bonus points when customer opts into loyalty program';



CREATE OR REPLACE FUNCTION "public"."handle_new_customer_loyalty"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    program_record record;
begin
    -- Get active program
    select * into program_record 
    from public.fidelity_programs 
    where store_id = new.store_id and is_active = true;
    
    if found and program_record.enable_join_bonus = true then
        if program_record.join_bonus_points > 0 then
            -- Update points (new record, so we can set it directly or update if default was 0)
            update public.customers
            set loyalty_points = loyalty_points + program_record.join_bonus_points
            where id = new.id;
            
            -- Log transaction
            insert into public.fidelity_transactions (
                program_id,
                customer_id,
                type,
                points,
                description
            ) values (
                program_record.id,
                new.id,
                'bonus',
                program_record.join_bonus_points,
                'Bônus de boas-vindas ao programa de fidelidade'
            );
        end if;
    end if;
    return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_customer_loyalty"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_order_points"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    program_record record;
    points_to_add integer := 0;
    stamps_earned integer := 0;
    customer_exists boolean;
begin
    -- Only proceed if order status changed to 'completed'
    if new.status = 'completed' and (old.status is null or old.status != 'completed') then
        
        -- Get active program for the store
        select * into program_record 
        from public.fidelity_programs 
        where store_id = new.store_id and is_active = true;
        
        if found then
            -- 1. CASHBACK LOGIC (Existing)
            if new.total >= coalesce(program_record.min_order_value, 0) then
                points_to_add := floor(new.total * coalesce(program_record.points_per_currency, 1.0));
            end if;

            -- 2. STAMPS LOGIC (New)
            if program_record.enable_stamps = true and new.total >= coalesce(program_record.min_order_for_stamp, 0) then
                stamps_earned := 1; -- 1 stamp per valid order
            end if;

            -- EXECUTE UPDATES
            if points_to_add > 0 or stamps_earned > 0 then
                
                -- Update customer
                update public.customers 
                set 
                    loyalty_points = loyalty_points + points_to_add,
                    current_stamps = current_stamps + stamps_earned
                where id = new.customer_id;
                
                -- Log Cashback Transaction
                if points_to_add > 0 then
                    insert into public.fidelity_transactions (
                        program_id, customer_id, type, points, description, order_id
                    ) values (
                        program_record.id, new.customer_id, 'earn', points_to_add, 
                        'Compra finalizada (Pedido #' || new.id || ')', new.id
                    );
                end if;

                -- Check for Stamp Completion (Block Reward)
                if stamps_earned > 0 then
                    -- Get new stamp count
                    declare
                        new_stamp_count integer;
                        target integer := coalesce(program_record.stamps_target, 10);
                        stamp_points integer := coalesce(program_record.points_per_stamp_block, 0);
                    begin
                        select current_stamps into new_stamp_count from public.customers where id = new.customer_id;
                        
                        -- If reached target
                        if new_stamp_count >= target then
                            if stamp_points > 0 then
                                -- Award Bonus Points
                                update public.customers 
                                set 
                                    loyalty_points = loyalty_points + stamp_points,
                                    current_stamps = new_stamp_count - target -- Reset stamps (keep excess)
                                where id = new.customer_id;

                                -- Log Stamp Reward
                                insert into public.fidelity_transactions (
                                    program_id, customer_id, type, points, description
                                ) values (
                                    program_record.id, new.customer_id, 'bonus', stamp_points, 
                                    'Completou ' || target || ' selos de fidelidade! 🎉'
                                );
                            else
                                -- Just reset stamps if no points configured (or maybe keep accumulating? Assuming cyclic)
                                update public.customers 
                                set current_stamps = new_stamp_count - target
                                where id = new.customer_id;
                            end if;
                        end if;
                    end;
                end if;

            end if;
        end if;
    end if;
    return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_order_points"() OWNER TO "postgres";


