CREATE OR REPLACE FUNCTION "public"."handle_stamp_completion"("cust_id" "uuid", "prog_record" "record") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    new_stamp_count integer;
    target integer := coalesce(prog_record.stamps_target, 10);
    stamp_points integer := coalesce(prog_record.points_per_stamp_block, 0);
begin
    select current_stamps into new_stamp_count from public.customers where id = cust_id;
    
    if new_stamp_count >= target then
        if stamp_points > 0 then
            update public.customers 
            set 
                loyalty_points = loyalty_points + stamp_points,
                current_stamps = new_stamp_count - target
            where id = cust_id;

            insert into public.fidelity_transactions (
                program_id, customer_id, type, points, description
            ) values (
                prog_record.id, cust_id, 'bonus', stamp_points, 
                'Completou ' || target || ' selos de fidelidade! 🎉'
            );
        else
            update public.customers 
            set current_stamps = new_stamp_count - target
            where id = cust_id;
        end if;
    end if;
end;
$$;


