CREATE OR REPLACE FUNCTION "public"."handle_tier_upgrade"("cust_id" "uuid", "s_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    current_pts integer;
    -- current_tier_pos integer; -- unused
    potential_tier record;
    cust_record record;
begin
    select * into cust_record from public.customers where id = cust_id;
    current_pts := cust_record.loyalty_points;
    
    -- Find highest tier eligible
    select * into potential_tier 
    from public.fidelity_tiers 
    where store_id = s_id and min_points <= current_pts 
    order by position desc, min_points desc 
    limit 1;
    
    if found then
        -- If current tier is null or new tier is higher position
        if cust_record.current_tier_id is null or potential_tier.id != cust_record.current_tier_id then
            update public.customers 
            set current_tier_id = potential_tier.id 
            where id = cust_id;
        end if;
    end if;
end;
$$;


