CREATE OR REPLACE FUNCTION "public"."inventory_apply_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_on_hand_delta numeric(12,3) := 0;
  v_reserved_delta numeric(12,3) := 0;
  v_dir text := coalesce(new.meta->>'direction', 'plus');
begin
  -- define deltas
  if new.type in ('entry', 'return') then
    v_on_hand_delta := new.quantity;

  elsif new.type in ('exit', 'sale') then
    v_on_hand_delta := -new.quantity;

  elsif new.type = 'reservation' then
    v_reserved_delta := new.quantity;

  elsif new.type = 'release' then
    v_reserved_delta := -new.quantity;

  elsif new.type = 'adjustment' then
    if v_dir = 'minus' then
      v_on_hand_delta := -new.quantity;
    else
      v_on_hand_delta := new.quantity;
    end if;
  end if;

  -- upsert saldo
  insert into public.inventory_balances (store_id, product_id, variant_id, on_hand, reserved)
  values (new.store_id, new.product_id, new.variant_id, 0, 0)
  on conflict (store_id, product_id, variant_id) do nothing;

  update public.inventory_balances
     set on_hand = on_hand + v_on_hand_delta,
         reserved = reserved + v_reserved_delta,
         updated_at = now()
   where store_id = new.store_id
     and product_id = new.product_id
     and (variant_id is not distinct from new.variant_id);

  -- validações básicas: nunca permitir negativo
  if (select on_hand from public.inventory_balances
      where store_id = new.store_id and product_id = new.product_id
        and (variant_id is not distinct from new.variant_id)) < 0 then
    raise exception 'Estoque insuficiente (on_hand ficaria negativo).';
  end if;

  if (select reserved from public.inventory_balances
      where store_id = new.store_id and product_id = new.product_id
        and (variant_id is not distinct from new.variant_id)) < 0 then
    raise exception 'Reserva inválida (reserved ficaria negativo).';
  end if;

  return new;
end;
$$;


