CREATE OR REPLACE FUNCTION "public"."is_supplier_purchase_eligible"("p_supplier_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_store_id uuid;
  v_is_eligible boolean := false;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT s.store_id
    INTO v_store_id
  FROM public.suppliers s
  WHERE s.id = p_supplier_id;

  IF v_store_id IS NULL THEN
    RETURN false;
  END IF;

  IF auth.uid() IS NULL OR NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao fornecedor.';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.suppliers s
    WHERE s.id = p_supplier_id
      AND COALESCE(s.active, true) = true
      AND COALESCE(s.blocked, false) = false
      AND lower(COALESCE(s.homologation_status, 'not_evaluated')) NOT IN (
        'rejected',
        'reproved',
        'reprovado',
        'blocked',
        'bloqueado'
      )
  )
  INTO v_is_eligible;

  RETURN COALESCE(v_is_eligible, false);
END;
$$;


ALTER FUNCTION "public"."is_supplier_purchase_eligible"("p_supplier_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_supplier_purchase_eligible"("p_supplier_id" "uuid") IS 'FASE 6.5C: regra única para definir se fornecedor pode ser usado em sugestão/criação de compras.';



CREATE OR REPLACE FUNCTION "public"."list_my_profile_change_requests"("p_store_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "admin_proposed_changes" "jsonb", "applied_changes" "jsonb", "reason" "text", "admin_notes" "text", "member_feedback" "text", "reviewed_at" timestamp with time zone, "proposed_by" "uuid", "proposed_by_email" "text", "proposed_at" timestamp with time zone, "member_responded_at" timestamp with time zone, "applied_at" timestamp with time zone, "visible_to_member" boolean, "sensitive" boolean, "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  SELECT sm.id
  INTO v_member_id
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  LIMIT 1;

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.requested_changes,
    r.admin_proposed_changes,
    r.applied_changes,
    r.reason,
    r.admin_notes,
    r.member_feedback,
    r.reviewed_at,
    r.proposed_by,
    r.proposed_by_email,
    r.proposed_at,
    r.member_responded_at,
    r.applied_at,
    r.visible_to_member,
    r.sensitive,
    r.metadata,
    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  WHERE r.store_id = p_store_id
    AND r.member_id = v_member_id
    AND r.visible_to_member = true
  ORDER BY
    CASE r.status
      WHEN 'awaiting_member_confirmation' THEN 1
      WHEN 'correction_requested' THEN 2
      WHEN 'pending' THEN 3
      WHEN 'applied' THEN 4
      WHEN 'rejected' THEN 5
      WHEN 'cancelled' THEN 6
      ELSE 9
    END,
    r.updated_at DESC,
    r.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 100), 300));
END;
$$;


ALTER FUNCTION "public"."list_my_profile_change_requests"("p_store_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_product_stock_settings_safe"("p_store_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_items jsonb;
  v_search text;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_store_id',
      'items', '[]'::jsonb
    );
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'items', '[]'::jsonb
      );
    END IF;
  END IF;

  v_search := lower(trim(COALESCE(p_search, '')));

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'name', q.name,
        'category_name', q.category_name,
        'active', q.active,
        'min_stock', q.min_stock,
        'max_stock', q.max_stock,
        'total_on_hand', q.total_on_hand,
        'total_reserved', q.total_reserved,
        'total_available', q.total_available,
        'rules_count', q.rules_count
      )
      ORDER BY q.name
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM (
    SELECT
      p.id,
      p.name,
      c.name AS category_name,
      COALESCE(p.active, true) AS active,
      COALESCE(p.min_stock, 0) AS min_stock,
      COALESCE(p.max_stock, 0) AS max_stock,
      COALESCE(SUM(ilb.on_hand), 0) AS total_on_hand,
      COALESCE(SUM(ilb.reserved), 0) AS total_reserved,
      COALESCE(SUM(ilb.on_hand - ilb.reserved), 0) AS total_available,
      COALESCE((
        SELECT COUNT(*)::integer
        FROM public.product_stock_location_rules r
        WHERE r.store_id = p.store_id
          AND r.product_id = p.id
          AND r.active = true
      ), 0) AS rules_count
    FROM public.products p
    LEFT JOIN public.categories c ON c.id = p.category_id
    LEFT JOIN public.inventory_location_balances ilb
      ON ilb.store_id = p.store_id
     AND ilb.product_id = p.id
    WHERE p.store_id = p_store_id
      AND COALESCE(p.active, true) = true
      AND COALESCE(p.discontinued, false) = false
      AND COALESCE(p.is_discontinued, false) = false
      AND (
        v_search = ''
        OR lower(p.name) ILIKE '%' || v_search || '%'
        OR lower(COALESCE(c.name, '')) ILIKE '%' || v_search || '%'
      )
    GROUP BY
      p.id,
      p.name,
      c.name,
      p.active,
      p.min_stock,
      p.max_stock
    ORDER BY p.name
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 300))
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'items', v_items
  );
END;
$$;


ALTER FUNCTION "public"."list_product_stock_settings_safe"("p_store_id" "uuid", "p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_store_custom_roles"("p_store_id" "uuid", "p_include_inactive" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "store_id" "uuid", "name" "text", "description" "text", "base_role" "text", "active" boolean, "permissions" "jsonb", "sensitive_actions" "jsonb", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select
    scr.id,
    scr.store_id,
    scr.name,
    scr.description,
    scr.base_role,
    scr.active,
    scr.permissions,
    scr.sensitive_actions,
    scr.created_by,
    scr.created_at,
    scr.updated_at
  from public.store_custom_roles scr
  where scr.store_id = p_store_id
    and (
      p_include_inactive
      or scr.active = true
    )
    and (
      public.app_is_store_owner(p_store_id)
      or public.user_has_store_permission(p_store_id, 'security.custom_roles.view')
      or public.user_has_store_permission(p_store_id, 'security.custom_roles.manage')
    )
  order by
    scr.active desc,
    case scr.base_role
      when 'admin' then 1
      when 'manager' then 2
      when 'stock_operator' then 3
      when 'cashier' then 4
      when 'sales' then 5
      when 'staff' then 6
      when 'viewer' then 7
      else 99
    end,
    scr.name;
$$;


ALTER FUNCTION "public"."list_store_custom_roles"("p_store_id" "uuid", "p_include_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_store_profile_change_requests"("p_store_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_request_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "user_email" "text", "profile_name" "text", "internal_alias" "text", "request_type" "text", "status" "text", "requested_changes" "jsonb", "current_snapshot" "jsonb", "admin_proposed_changes" "jsonb", "applied_changes" "jsonb", "reason" "text", "admin_notes" "text", "member_feedback" "text", "requested_by" "uuid", "requested_by_email" "text", "reviewed_by" "uuid", "reviewed_by_email" "text", "reviewed_at" timestamp with time zone, "proposed_by" "uuid", "proposed_by_email" "text", "proposed_at" timestamp with time zone, "member_responded_at" timestamp with time zone, "applied_at" timestamp with time zone, "visible_to_member" boolean, "sensitive" boolean, "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_can_view boolean := false;
  v_can_view_sensitive boolean := false;
BEGIN
  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  v_can_view :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.profile_requests.view')
    OR public.user_has_store_permission(p_store_id, 'users.profile_requests.review')
    OR public.user_has_store_permission(p_store_id, 'users.profile_requests.manage');

  IF NOT v_can_view THEN
    RAISE EXCEPTION 'Sem permissão para visualizar solicitações cadastrais.';
  END IF;

  v_can_view_sensitive :=
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'users.profile_requests.manage')
    OR public.user_has_store_permission(p_store_id, 'users.additional_info_sensitive.view')
    OR public.user_has_store_permission(p_store_id, 'users.additional_info_sensitive.manage')
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.view')
    OR public.user_has_store_permission(p_store_id, 'users.sensitive.manage');

  RETURN QUERY
  SELECT
    r.id AS request_id,
    r.store_id,
    r.member_id,
    r.user_id,
    au.email::text AS user_email,
    p.name AS profile_name,
    sm.internal_alias,
    r.request_type,
    r.status,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN '{}'::jsonb
      ELSE r.requested_changes
    END AS requested_changes,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN '{}'::jsonb
      ELSE r.current_snapshot
    END AS current_snapshot,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN '{}'::jsonb
      ELSE r.admin_proposed_changes
    END AS admin_proposed_changes,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN '{}'::jsonb
      ELSE r.applied_changes
    END AS applied_changes,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN 'Solicitação sensível. Conteúdo restrito.'
      ELSE r.reason
    END AS reason,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN NULL
      ELSE r.admin_notes
    END AS admin_notes,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN NULL
      ELSE r.member_feedback
    END AS member_feedback,

    r.requested_by,
    r.requested_by_email,
    r.reviewed_by,
    r.reviewed_by_email,
    r.reviewed_at,
    r.proposed_by,
    r.proposed_by_email,
    r.proposed_at,
    r.member_responded_at,
    r.applied_at,
    r.visible_to_member,
    r.sensitive,

    CASE
      WHEN r.sensitive = true AND NOT v_can_view_sensitive THEN '{}'::jsonb
      ELSE r.metadata
    END AS metadata,

    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  JOIN public.store_members sm
    ON sm.id = r.member_id
  LEFT JOIN public.profiles p
    ON p.id = r.user_id
  LEFT JOIN auth.users au
    ON au.id = r.user_id
  WHERE r.store_id = p_store_id
    AND (p_status IS NULL OR r.status = p_status)
    AND (p_request_type IS NULL OR r.request_type = p_request_type)
  ORDER BY
    CASE r.status
      WHEN 'awaiting_member_confirmation' THEN 1
      WHEN 'correction_requested' THEN 2
      WHEN 'pending' THEN 3
      WHEN 'applied' THEN 4
      WHEN 'rejected' THEN 5
      WHEN 'cancelled' THEN 6
      ELSE 9
    END,
    r.updated_at DESC,
    r.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 100), 300))
  OFFSET greatest(0, coalesce(p_offset, 0));
END;
$$;


ALTER FUNCTION "public"."list_store_profile_change_requests"("p_store_id" "uuid", "p_status" "text", "p_request_type" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_user_session_event"("p_store_id" "uuid" DEFAULT NULL::"uuid", "p_action" "text" DEFAULT 'session_event'::"text", "p_details" "jsonb" DEFAULT '{}'::"jsonb", "p_outcome" "text" DEFAULT 'success'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_user_name text;
  v_user_email text;
  v_store_id uuid;
  v_membership public.store_members%rowtype;
  v_sensitive boolean;
  v_visible_to_member boolean;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_action is null or length(trim(p_action)) = 0 then
    raise exception 'Ação não informada.';
  end if;

  if p_outcome not in ('success', 'failure') then
    raise exception 'Resultado inválido: %', p_outcome;
  end if;

  v_store_id := p_store_id;

  if v_store_id is null then
    select sm.store_id
    into v_store_id
    from public.store_members sm
    where sm.user_id = v_user_id
      and sm.status = 'active'
    order by
      case sm.role
        when 'owner' then 1
        when 'admin' then 2
        when 'manager' then 3
        else 10
      end,
      sm.created_at
    limit 1;
  end if;

  if v_store_id is null then
    raise exception 'Nenhuma loja ativa encontrada para registrar o evento.';
  end if;

  select *
  into v_membership
  from public.store_members sm
  where sm.store_id = v_store_id
    and sm.user_id = v_user_id
    and sm.status = 'active'
  limit 1;

  if not found then
    raise exception 'Usuário não possui vínculo ativo com esta loja.';
  end if;

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_user_name,
    v_user_email
  from public.get_user_display_identity(v_user_id) as identity_row;

  select
    defaults.sensitive,
    defaults.visible_to_member
  into
    v_sensitive,
    v_visible_to_member
  from public.get_security_log_visibility_defaults(p_action) as defaults;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    display_action,
    details,
    outcome,
    sensitive,
    visible_to_member,
    created_at
  )
  values (
    v_store_id,
    v_user_id,
    v_user_name,
    v_user_email,
    p_action,
    public.translate_security_action_ptbr(p_action),
    coalesce(p_details, '{}'::jsonb)
      || jsonb_build_object(
        'store_id', v_store_id,
        'member_id', v_membership.id,
        'role', v_membership.role,
        'session_event', true
      ),
    p_outcome,
    coalesce(v_sensitive, false),
    coalesce(v_visible_to_member, true),
    now()
  );

  update public.store_members sm
  set
    last_seen_at = now(),
    updated_at = now()
  where sm.id = v_membership.id;

  return jsonb_build_object(
    'ok', true,
    'store_id', v_store_id,
    'user_id', v_user_id,
    'action', p_action,
    'display_action', public.translate_security_action_ptbr(p_action),
    'outcome', p_outcome
  );
end;
$$;


ALTER FUNCTION "public"."log_user_session_event"("p_store_id" "uuid", "p_action" "text", "p_details" "jsonb", "p_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."map_stock_to_inventory_move_type"("p_movement_type" "public"."stock_movement_type") RETURNS "public"."inventory_move_type"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
begin
    case p_movement_type
        when 'entry' then
            return 'entry'::public.inventory_move_type;

        when 'exit' then
            return 'exit'::public.inventory_move_type;

        when 'reservation' then
            return 'reservation'::public.inventory_move_type;

        when 'confirmation' then
            return 'confirmation'::public.inventory_move_type;

        when 'cancellation' then
            return 'cancellation'::public.inventory_move_type;

        when 'clearance' then
            return 'clearance'::public.inventory_move_type;

        else
            raise exception 'Sem mapeamento para stock_movement_type % em inventory_move_type', p_movement_type
                using errcode = '23514';
    end case;
end;
$$;


ALTER FUNCTION "public"."map_stock_to_inventory_move_type"("p_movement_type" "public"."stock_movement_type") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_campaign_recipient_manual_sent_safe"("p_store_id" "uuid", "p_recipient_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recipient record;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF p_recipient_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_recipient_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT *
  INTO v_recipient
  FROM public.promotion_campaign_recipients pcr
  WHERE pcr.id = p_recipient_id
    AND pcr.store_id = p_store_id;

  IF v_recipient.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'recipient_not_found');
  END IF;

  UPDATE public.promotion_campaign_recipients
  SET
    status = 'sent',
    sent_at = COALESCE(sent_at, now()),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'manual_sent_at', now(),
      'manual_sent_by', auth.uid(),
      'manual_sent_by_function', 'mark_campaign_recipient_manual_sent_safe'
    )
  WHERE id = p_recipient_id
    AND store_id = p_store_id;

  UPDATE public.promotion_campaigns pc
  SET
    sent_count = (
      SELECT COUNT(*)::integer
      FROM public.promotion_campaign_recipients pcr
      WHERE pcr.campaign_id = pc.id
        AND pcr.status IN ('sent', 'delivered', 'read', 'clicked', 'converted')
    ),
    updated_at = now()
  WHERE pc.id = v_recipient.campaign_id
    AND pc.store_id = p_store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'recipient_id', p_recipient_id,
    'status', 'sent'
  );
END;
$$;


ALTER FUNCTION "public"."mark_campaign_recipient_manual_sent_safe"("p_store_id" "uuid", "p_recipient_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multi_stock_health_check"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_result jsonb;
begin
    select jsonb_build_object(
        'store_id', p_store_id,
        'locations_count', (
            select count(*) from public.stock_locations sl
            where sl.store_id = p_store_id
        ),
        'default_locations_count', (
            select count(*) from public.stock_locations sl
            where sl.store_id = p_store_id
              and sl.is_default = true
        ),
        'transfers_count', (
            select count(*) from public.stock_transfers st
            where st.store_id = p_store_id
        ),
        'divergent_transfers_count', (
            select count(*) from public.stock_transfers st
            where st.store_id = p_store_id
              and st.status = 'divergent'
        ),
        'inventory_positions_count', (
            select count(*) from public.inventory_location_balances ilb
            where ilb.store_id = p_store_id
        ),
        'ok', true
    )
    into v_result;

    return v_result;
end;
$$;


ALTER FUNCTION "public"."multi_stock_health_check"("p_store_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multi_stock_health_check"("p_store_id" "uuid") IS 'Health check resumido do módulo de multiestoque por store.';



CREATE OR REPLACE FUNCTION "public"."normalize_phone_digits"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.phone is not null then
    new.phone := regexp_replace(new.phone, '\D', '', 'g');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_phone_digits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perform_manual_adjustment"("p_product_id" "uuid", "p_quantity_change" integer, "p_reason" "text", "p_password_input" "text", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_store_id UUID;
    v_stored_hash TEXT;
    v_old_qty INTEGER;
    v_new_qty INTEGER;
BEGIN
    SELECT id, stock_password_hash INTO v_store_id, v_stored_hash
    FROM stores
    WHERE user_id = p_user_id;
    IF v_store_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Loja não encontrada para este usuário.');
    END IF;
    IF v_stored_hash IS NOT NULL AND v_stored_hash != '' AND v_stored_hash != p_password_input THEN
         RETURN jsonb_build_object('success', false, 'message', 'Senha de estoque incorreta.');
    END IF;
    SELECT stock_quantity INTO v_old_qty FROM products WHERE id = p_product_id FOR UPDATE;
    v_new_qty := v_old_qty + p_quantity_change;
    IF v_new_qty < 0 THEN
         RETURN jsonb_build_object('success', false, 'message', 'Estoque não pode ficar negativo.');
    END IF;
    UPDATE products SET stock_quantity = v_new_qty WHERE id = p_product_id;
    INSERT INTO inventory_history (
        store_id, product_id, type, quantity, balance_before, balance_after, user_id, reason
    ) VALUES (
        v_store_id,
        p_product_id,
        CASE WHEN p_quantity_change > 0 THEN 'entry'::inventory_move_type ELSE 'adjustment'::inventory_move_type END,
        p_quantity_change,
        v_old_qty,
        v_new_qty,
        p_user_id,
        p_reason
    );
    RETURN jsonb_build_object('success', true, 'new_stock', v_new_qty);
END;
$$;


ALTER FUNCTION "public"."perform_manual_adjustment"("p_product_id" "uuid", "p_quantity_change" integer, "p_reason" "text", "p_password_input" "text", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."perform_manual_adjustment"("p_product_id" "uuid", "p_quantity_change" integer, "p_reason" "text", "p_password_input" "text", "p_user_id" "uuid") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC de ajuste manual de estoque. Revisar contra o modelo atual de multiestoque por local.';



CREATE OR REPLACE FUNCTION "public"."prepare_campaign_recipients_safe"("p_store_id" "uuid", "p_campaign_id" "uuid", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign record;
  v_preview jsonb;
  v_recipient jsonb;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_message text;
  v_limit integer;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF p_campaign_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_campaign_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT *
  INTO v_campaign
  FROM public.promotion_campaigns pc
  WHERE pc.id = p_campaign_id
    AND pc.store_id = p_store_id;

  IF v_campaign.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  v_limit := GREATEST(1, LEAST(COALESCE(p_limit, 500), 1000));

  v_preview := public.build_campaign_recipients_preview_safe(
    p_store_id := p_store_id,
    p_campaign_id := p_campaign_id,
    p_limit := v_limit
  );

  IF COALESCE((v_preview->>'ok')::boolean, false) = false THEN
    RETURN v_preview;
  END IF;

  FOR v_recipient IN
    SELECT *
    FROM jsonb_array_elements(COALESCE(v_preview->'recipients', '[]'::jsonb))
  LOOP
    v_message := COALESCE(v_campaign.message_template, '');

    v_message := replace(
      v_message,
      '{{customer_name}}',
      COALESCE(v_recipient->>'customer_name', 'Cliente')
    );

    v_message := replace(
      v_message,
      '{{store_name}}',
      COALESCE(
        (
          SELECT s.name
          FROM public.stores s
          WHERE s.id = p_store_id
          LIMIT 1
        ),
        'Nossa loja'
      )
    );

    v_message := replace(
      v_message,
      '{{current_date}}',
      to_char(now(), 'DD/MM/YYYY')
    );

    INSERT INTO public.promotion_campaign_recipients (
      store_id,
      campaign_id,
      customer_id,
      channel,
      recipient_name,
      recipient_phone,
      recipient_email,
      status,
      message_preview,
      metadata
    )
    VALUES (
      p_store_id,
      p_campaign_id,
      (v_recipient->>'customer_id')::uuid,
      COALESCE(v_campaign.channel, 'whatsapp'),
      v_recipient->>'customer_name',
      v_recipient->>'phone',
      v_recipient->>'email',
      'ready',
      v_message,
      jsonb_build_object(
        'prepared_by_function', 'prepare_campaign_recipients_safe',
        'prepared_at', now()
      )
    )
    ON CONFLICT (campaign_id, customer_id)
    DO UPDATE SET
      channel = EXCLUDED.channel,
      recipient_name = EXCLUDED.recipient_name,
      recipient_phone = EXCLUDED.recipient_phone,
      recipient_email = EXCLUDED.recipient_email,
      status = CASE
        WHEN public.promotion_campaign_recipients.status IN ('sent', 'delivered', 'read', 'clicked', 'converted')
          THEN public.promotion_campaign_recipients.status
        ELSE 'ready'
      END,
      message_preview = EXCLUDED.message_preview,
      metadata = COALESCE(public.promotion_campaign_recipients.metadata, '{}'::jsonb)
        || EXCLUDED.metadata;

    IF FOUND THEN
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  UPDATE public.promotion_campaigns
  SET
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'last_recipients_prepared_at', now(),
      'last_recipients_prepared_by', auth.uid()
    ),
    updated_at = now()
  WHERE id = p_campaign_id;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign_id', p_campaign_id,
    'total_preview_recipients', COALESCE((v_preview->>'total_recipients')::integer, 0),
    'recipients_prepared', v_inserted
  );
END;
$$;


ALTER FUNCTION "public"."prepare_campaign_recipients_safe"("p_store_id" "uuid", "p_campaign_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_category_store_id_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.store_id IS DISTINCT FROM OLD.store_id THEN
    RAISE EXCEPTION 'Não é permitido alterar a loja de uma categoria existente.';
  END IF;

  RETURN NEW;
END;
$$;


