CREATE OR REPLACE FUNCTION "public"."product_has_movements"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_store_id uuid;
  v_has_movements boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT p.store_id
    INTO v_store_id
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_store_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT public.is_store_member(v_store_id) THEN
    RAISE EXCEPTION 'Acesso negado ao produto.';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.stock_movements sm
    WHERE sm.product_id = p_product_id

    UNION ALL

    SELECT 1
    FROM public.purchase_document_items pdi
    WHERE pdi.product_id = p_product_id

    UNION ALL

    SELECT 1
    FROM public.stock_transfer_items sti
    WHERE sti.product_id = p_product_id
  )
  INTO v_has_movements;

  RETURN COALESCE(v_has_movements, false);
END;
$$;


ALTER FUNCTION "public"."product_has_movements"("p_product_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."product_has_movements"("p_product_id" "uuid") IS 'EXCEÇÃO TEMPORÁRIA 6.4: helper de produto usado para validação de exclusão/edição. Revisar necessidade de exposição como RPC.';



CREATE OR REPLACE FUNCTION "public"."propose_store_profile_change_request"("p_request_id" "uuid", "p_proposed_changes" "jsonb", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "admin_proposed_changes" "jsonb", "reason" "text", "admin_notes" "text", "proposed_by" "uuid", "proposed_by_email" "text", "proposed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_email text;
  v_actor_name text;
  v_request public.store_member_profile_change_requests%ROWTYPE;
  v_member public.store_members%ROWTYPE;
  v_can_review boolean := false;
  v_now timestamp with time zone := now();
BEGIN
  v_actor_id := auth.uid();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Solicitação não informada.';
  END IF;

  IF jsonb_typeof(COALESCE(p_proposed_changes, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'As alterações propostas devem ser enviadas como objeto JSON.';
  END IF;

  IF COALESCE(p_proposed_changes, '{}'::jsonb) = '{}'::jsonb THEN
    RAISE EXCEPTION 'Informe ao menos uma alteração proposta.';
  END IF;

  SELECT *
  INTO v_request
  FROM public.store_member_profile_change_requests r
  WHERE r.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitação não encontrada.';
  END IF;

  IF v_request.status NOT IN ('pending', 'correction_requested') THEN
    RAISE EXCEPTION 'Esta solicitação não está disponível para atendimento.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = v_request.member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário não encontrado.';
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_actor_id) AS identity_row;

  v_can_review :=
    public.app_is_store_owner(v_request.store_id)
    OR public.user_has_store_permission(v_request.store_id, 'users.profile_requests.review')
    OR public.user_has_store_permission(v_request.store_id, 'users.profile_requests.manage');

  IF NOT v_can_review THEN
    RAISE EXCEPTION 'Sem permissão para atender solicitações cadastrais.';
  END IF;

  UPDATE public.store_member_profile_change_requests r
  SET
    status = 'awaiting_member_confirmation',
    admin_proposed_changes = COALESCE(p_proposed_changes, '{}'::jsonb),
    admin_notes = NULLIF(trim(COALESCE(p_admin_notes, '')), ''),
    proposed_by = v_actor_id,
    proposed_by_email = v_actor_email,
    proposed_at = v_now,
    member_feedback = NULL,
    member_responded_at = NULL,
    updated_at = v_now,
    metadata = COALESCE(r.metadata, '{}'::jsonb) || jsonb_build_object(
      'proposed_by_function', 'propose_store_profile_change_request'
    )
  WHERE r.id = v_request.id;

  INSERT INTO public.store_member_occurrences (
    store_id,
    member_id,
    user_id,
    occurrence_type,
    severity,
    title,
    description,
    occurred_at,
    visible_to_member,
    created_by,
    created_by_email,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_request.store_id,
    v_request.member_id,
    v_request.user_id,
    'note',
    CASE WHEN v_request.sensitive THEN 'high' ELSE 'info' END,
    'Alteração cadastral enviada para conferência',
    COALESCE(
      NULLIF(trim(p_admin_notes), ''),
      'O responsável preparou uma alteração cadastral para conferência do usuário.'
    ),
    v_now,
    true,
    v_actor_id,
    v_actor_email,
    jsonb_build_object(
      'origin', 'propose_store_profile_change_request',
      'request_id', v_request.id,
      'request_type', v_request.request_type,
      'admin_proposed_changes', p_proposed_changes
    ),
    v_now,
    v_now
  );

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_request.store_id,
    v_actor_id,
    v_actor_name,
    v_actor_email,
    'store_member_profile_change_request_proposed',
    jsonb_build_object(
      'request_id', v_request.id,
      'member_id', v_request.member_id,
      'target_user_id', v_request.user_id,
      'request_type', v_request.request_type,
      'proposed_changes', p_proposed_changes
    ),
    'success',
    v_now
  );

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.requested_changes,
    r.admin_proposed_changes,
    r.reason,
    r.admin_notes,
    r.proposed_by,
    r.proposed_by_email,
    r.proposed_at,
    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  WHERE r.id = v_request.id;
END;
$$;


ALTER FUNCTION "public"."propose_store_profile_change_request"("p_request_id" "uuid", "p_proposed_changes" "jsonb", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("transfer_id" "uuid", "transfer_code" "text", "status" "text", "received_at" timestamp with time zone, "total_shipped" numeric, "total_received" numeric, "total_divergence" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.stock_transfers%ROWTYPE;
  v_input record;
  v_item public.stock_transfer_items%ROWTYPE;
  v_received_qty numeric;
  v_divergence_qty numeric;
  v_resolution text;
  v_reason text;
  v_notes text;

  v_balance_id uuid;
  v_on_hand numeric;
  v_previous_stock integer;
  v_new_stock integer;

  v_has_divergence boolean := false;
BEGIN
  IF p_transfer_id IS NULL THEN
    RAISE EXCEPTION 'Transferência não informada.';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Informe os itens recebidos.';
  END IF;

  SELECT *
  INTO v_transfer
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transferência não encontrada.';
  END IF;

  IF NOT public.is_store_member(v_transfer.store_id) THEN
    RAISE EXCEPTION 'Acesso negado à transferência informada.';
  END IF;

  IF v_transfer.status <> 'shipped'::public.stock_transfer_status THEN
    RAISE EXCEPTION 'Apenas transferências enviadas podem ser recebidas. Status atual: %', v_transfer.status;
  END IF;

  -- Garante que todos os itens da transferência foram informados.
  IF (
    SELECT COUNT(*)
    FROM public.stock_transfer_items sti
    WHERE sti.transfer_id = p_transfer_id
      AND sti.store_id = v_transfer.store_id
  ) <> jsonb_array_length(p_items) THEN
    RAISE EXCEPTION 'Informe o recebimento de todos os itens da transferência.';
  END IF;

  FOR v_input IN
    SELECT *
    FROM jsonb_to_recordset(p_items) AS x(
      item_id uuid,
      received_qty numeric,
      divergence_resolution text,
      divergence_reason text,
      divergence_notes text
    )
  LOOP
    SELECT *
    INTO v_item
    FROM public.stock_transfer_items sti
    WHERE sti.id = v_input.item_id
      AND sti.transfer_id = p_transfer_id
      AND sti.store_id = v_transfer.store_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % não pertence à transferência informada.', v_input.item_id;
    END IF;

    v_received_qty := COALESCE(v_input.received_qty, 0);

    IF v_received_qty < 0 THEN
      RAISE EXCEPTION 'Item % possui quantidade recebida negativa.', v_item.id;
    END IF;

    IF v_received_qty <> trunc(v_received_qty) THEN
      RAISE EXCEPTION 'Item % possui quantidade recebida fracionada. Use unidades inteiras.', v_item.id;
    END IF;

    IF v_received_qty > COALESCE(v_item.shipped_qty, 0) THEN
      RAISE EXCEPTION
        'Item % recebeu quantidade maior do que enviada. Enviado: %, recebido: %.',
        v_item.id,
        v_item.shipped_qty,
        v_received_qty;
    END IF;

    v_divergence_qty := COALESCE(v_item.shipped_qty, 0) - v_received_qty;

    v_resolution := NULLIF(trim(COALESCE(v_input.divergence_resolution, '')), '');
    v_reason := NULLIF(trim(COALESCE(v_input.divergence_reason, '')), '');
    v_notes := NULLIF(trim(COALESCE(v_input.divergence_notes, '')), '');

    IF v_divergence_qty > 0 THEN
      v_has_divergence := true;

      IF v_resolution IS NULL OR v_resolution NOT IN ('loss', 'return_to_origin', 'accepted_shortage') THEN
        RAISE EXCEPTION 'Item % possui divergência e precisa de resolução válida.', v_item.id;
      END IF;

      IF v_reason IS NULL THEN
        RAISE EXCEPTION 'Item % possui divergência e precisa de motivo.', v_item.id;
      END IF;
    ELSE
      v_resolution := NULL;
      v_reason := NULL;
      v_notes := NULL;
    END IF;

    -- Entrada no destino apenas do que foi efetivamente recebido.
    IF v_received_qty > 0 THEN
      SELECT
        ilb.id,
        ilb.on_hand
      INTO
        v_balance_id,
        v_on_hand
      FROM public.inventory_location_balances ilb
      WHERE ilb.store_id = v_transfer.store_id
        AND ilb.location_id = v_transfer.destination_location_id
        AND ilb.product_id = v_item.product_id
        AND (
          (v_item.variant_id IS NULL AND ilb.variant_id IS NULL)
          OR ilb.variant_id = v_item.variant_id
        )
      ORDER BY ilb.updated_at DESC
      LIMIT 1
      FOR UPDATE;

      IF v_balance_id IS NULL THEN
        INSERT INTO public.inventory_location_balances (
          store_id,
          location_id,
          product_id,
          variant_id,
          on_hand,
          reserved,
          updated_at
        )
        VALUES (
          v_transfer.store_id,
          v_transfer.destination_location_id,
          v_item.product_id,
          v_item.variant_id,
          0,
          0,
          now()
        )
        RETURNING id, on_hand
        INTO v_balance_id, v_on_hand;
      END IF;

      v_previous_stock := COALESCE(v_on_hand, 0)::integer;
      v_new_stock := (COALESCE(v_on_hand, 0) + v_received_qty)::integer;

      UPDATE public.inventory_location_balances ilb
      SET
        on_hand = ilb.on_hand + v_received_qty,
        updated_at = now()
      WHERE ilb.id = v_balance_id;

      INSERT INTO public.stock_movements (
        product_id,
        order_id,
        quantity,
        type,
        reason,
        user_id,
        previous_stock,
        new_stock,
        created_at,
        store_id,
        affects_physical,
        source,
        source_id,
        reason_code,
        metadata,
        created_by,
        supplier_id,
        location_id,
        from_location_id,
        to_location_id,
        transfer_id
      )
      VALUES (
        v_item.product_id,
        NULL,
        v_received_qty::integer,
        'entry'::public.stock_movement_type,
        'Entrada por recebimento de transferência interna',
        auth.uid(),
        v_previous_stock,
        v_new_stock,
        now(),
        v_transfer.store_id,
        true,
        'stock_transfer',
        v_transfer.id,
        'transfer_received',
        jsonb_build_object(
          'transfer_id', v_transfer.id,
          'transfer_code', v_transfer.transfer_code,
          'transfer_item_id', v_item.id,
          'source_location_id', v_transfer.source_location_id,
          'destination_location_id', v_transfer.destination_location_id
        ),
        auth.uid(),
        NULL,
        v_transfer.destination_location_id,
        v_transfer.source_location_id,
        v_transfer.destination_location_id,
        v_transfer.id
      );
    END IF;

    -- Se a divergência voltou fisicamente para a origem, entra de volta na origem.
    IF v_divergence_qty > 0 AND v_resolution = 'return_to_origin' THEN
      SELECT
        ilb.id,
        ilb.on_hand
      INTO
        v_balance_id,
        v_on_hand
      FROM public.inventory_location_balances ilb
      WHERE ilb.store_id = v_transfer.store_id
        AND ilb.location_id = v_transfer.source_location_id
        AND ilb.product_id = v_item.product_id
        AND (
          (v_item.variant_id IS NULL AND ilb.variant_id IS NULL)
          OR ilb.variant_id = v_item.variant_id
        )
      ORDER BY ilb.updated_at DESC
      LIMIT 1
      FOR UPDATE;

      IF v_balance_id IS NULL THEN
        INSERT INTO public.inventory_location_balances (
          store_id,
          location_id,
          product_id,
          variant_id,
          on_hand,
          reserved,
          updated_at
        )
        VALUES (
          v_transfer.store_id,
          v_transfer.source_location_id,
          v_item.product_id,
          v_item.variant_id,
          0,
          0,
          now()
        )
        RETURNING id, on_hand
        INTO v_balance_id, v_on_hand;
      END IF;

      v_previous_stock := COALESCE(v_on_hand, 0)::integer;
      v_new_stock := (COALESCE(v_on_hand, 0) + v_divergence_qty)::integer;

      UPDATE public.inventory_location_balances ilb
      SET
        on_hand = ilb.on_hand + v_divergence_qty,
        updated_at = now()
      WHERE ilb.id = v_balance_id;

      INSERT INTO public.stock_movements (
        product_id,
        order_id,
        quantity,
        type,
        reason,
        user_id,
        previous_stock,
        new_stock,
        created_at,
        store_id,
        affects_physical,
        source,
        source_id,
        reason_code,
        metadata,
        created_by,
        supplier_id,
        location_id,
        from_location_id,
        to_location_id,
        transfer_id
      )
      VALUES (
        v_item.product_id,
        NULL,
        v_divergence_qty::integer,
        'entry'::public.stock_movement_type,
        'Retorno de divergência para origem',
        auth.uid(),
        v_previous_stock,
        v_new_stock,
        now(),
        v_transfer.store_id,
        true,
        'stock_transfer',
        v_transfer.id,
        'transfer_divergence_return_to_origin',
        jsonb_build_object(
          'transfer_id', v_transfer.id,
          'transfer_code', v_transfer.transfer_code,
          'transfer_item_id', v_item.id,
          'divergence_qty', v_divergence_qty,
          'divergence_reason', v_reason
        ),
        auth.uid(),
        NULL,
        v_transfer.source_location_id,
        v_transfer.destination_location_id,
        v_transfer.source_location_id,
        v_transfer.id
      );
    END IF;

    UPDATE public.stock_transfer_items sti
    SET
      received_qty = v_received_qty,
      divergence_qty = v_divergence_qty,
      divergence_resolution = v_resolution,
      divergence_reason = v_reason,
      divergence_notes = v_notes,
      loss_qty = CASE WHEN v_resolution = 'loss' THEN v_divergence_qty ELSE 0 END,
      returned_to_origin_qty = CASE WHEN v_resolution = 'return_to_origin' THEN v_divergence_qty ELSE 0 END,
      accepted_shortage_qty = CASE WHEN v_resolution = 'accepted_shortage' THEN v_divergence_qty ELSE 0 END,
      divergence_resolved_at = CASE WHEN v_divergence_qty > 0 THEN now() ELSE NULL END,
      metadata = COALESCE(sti.metadata, '{}'::jsonb) || jsonb_build_object(
        'receive_source', 'receive_stock_transfer',
        'received_at', now(),
        'divergence_qty', v_divergence_qty,
        'divergence_resolution', v_resolution,
        'divergence_reason', v_reason
      ),
      updated_at = now()
    WHERE sti.id = v_item.id;
  END LOOP;

  UPDATE public.stock_transfers st
  SET
    status = CASE
      WHEN v_has_divergence THEN 'divergent'::public.stock_transfer_status
      ELSE 'received'::public.stock_transfer_status
    END,
    received_by = auth.uid(),
    received_at = now(),
    notes = COALESCE(NULLIF(trim(COALESCE(p_notes, '')), ''), st.notes),
    metadata = COALESCE(st.metadata, '{}'::jsonb) || jsonb_build_object(
      'received_source', 'receive_stock_transfer',
      'has_divergence', v_has_divergence
    ),
    updated_at = now()
  WHERE st.id = p_transfer_id;

  RETURN QUERY
  SELECT
    st.id,
    st.transfer_code,
    st.status::text,
    st.received_at,
    COALESCE(SUM(sti.shipped_qty), 0)::numeric AS total_shipped,
    COALESCE(SUM(sti.received_qty), 0)::numeric AS total_received,
    COALESCE(SUM(sti.divergence_qty), 0)::numeric AS total_divergence
  FROM public.stock_transfers st
  JOIN public.stock_transfer_items sti
    ON sti.transfer_id = st.id
  WHERE st.id = p_transfer_id
  GROUP BY
    st.id,
    st.transfer_code,
    st.status,
    st.received_at;
END;
$$;


ALTER FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_items" "jsonb", "p_notes" "text") IS 'EXCEÇÃO INTENCIONAL 6.4: RPC operacional de recebimento de transferência. Trata recebimento integral, divergência, perda, retorno à origem e falta aceita.';



CREATE OR REPLACE FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_received_by" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."stock_transfers"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer public.stock_transfers;
    v_item record;
    v_receive_qty numeric;
    v_divergence_qty numeric;
    v_use_transit boolean;
    v_transit_location public.stock_locations;
    v_has_divergence boolean := false;
begin
    select *
      into v_transfer
      from public.stock_transfers
     where id = p_transfer_id
     for update;

    if v_transfer.id is null then
        raise exception 'Transferência não encontrada' using errcode = '23503';
    end if;

    if v_transfer.status <> 'shipped' then
        raise exception 'Só é possível receber transferência com status shipped' using errcode = '23514';
    end if;

    v_use_transit := coalesce((v_transfer.metadata ->> 'use_transit')::boolean, false);

    if v_use_transit then
        v_transit_location := public.get_or_create_transit_location(v_transfer.store_id);
    end if;

    for v_item in
        select *
          from public.stock_transfer_items
         where transfer_id = v_transfer.id
         order by created_at, id
    loop
        if coalesce(v_item.shipped_qty, 0) <= 0 then
            continue;
        end if;

        v_receive_qty := case
            when coalesce(v_item.received_qty, 0) > 0 then v_item.received_qty
            else v_item.shipped_qty
        end;

        if v_receive_qty < 0 then
            raise exception 'received_qty inválido no item %', v_item.id using errcode = '23514';
        end if;

        if v_receive_qty > v_item.shipped_qty then
            raise exception 'received_qty não pode ser maior que shipped_qty no item %', v_item.id
                using errcode = '23514';
        end if;

        v_divergence_qty := greatest(v_item.shipped_qty - v_receive_qty, 0);

        if v_use_transit and v_receive_qty > 0 then
            perform public.apply_stock_movement_delta_v2(
                p_store_id := v_transfer.store_id,
                p_product_id := v_item.product_id,
                p_movement_type := 'exit',
                p_quantity := v_receive_qty,
                p_reason := coalesce(p_notes, 'Saída do trânsito para recebimento'),
                p_source := 'stock_transfer',
                p_metadata := jsonb_build_object(
                    'transfer_id', v_transfer.id,
                    'transfer_code', v_transfer.transfer_code,
                    'phase', 'receive_from_transit',
                    'use_transit', true
                ),
                p_created_by := p_received_by,
                p_location_id := v_transit_location.id,
                p_from_location_id := v_transit_location.id,
                p_to_location_id := v_transfer.destination_location_id,
                p_transfer_id := v_transfer.id,
                p_variant_id := v_item.variant_id
            );
        end if;

        if v_receive_qty > 0 then
            perform public.apply_stock_movement_delta_v2(
                p_store_id := v_transfer.store_id,
                p_product_id := v_item.product_id,
                p_movement_type := 'entry',
                p_quantity := v_receive_qty,
                p_reason := coalesce(p_notes, 'Recebimento de transferência'),
                p_source := 'stock_transfer',
                p_metadata := jsonb_build_object(
                    'transfer_id', v_transfer.id,
                    'transfer_code', v_transfer.transfer_code,
                    'phase', 'receive',
                    'use_transit', v_use_transit
                ),
                p_created_by := p_received_by,
                p_location_id := v_transfer.destination_location_id,
                p_from_location_id := case when v_use_transit then v_transit_location.id else v_transfer.source_location_id end,
                p_to_location_id := v_transfer.destination_location_id,
                p_transfer_id := v_transfer.id,
                p_variant_id := v_item.variant_id
            );
        end if;

        update public.stock_transfer_items
           set received_qty = v_receive_qty,
               divergence_qty = v_divergence_qty,
               updated_at = now()
         where id = v_item.id;

        if v_divergence_qty > 0 then
            v_has_divergence := true;
        end if;
    end loop;

    update public.stock_transfers
       set status = (
             case
               when v_has_divergence then 'divergent'::public.stock_transfer_status
               else 'received'::public.stock_transfer_status
             end
           ),
           received_by = p_received_by,
           received_at = now(),
           notes = coalesce(p_notes, notes),
           updated_at = now()
     where id = v_transfer.id
    returning * into v_transfer;

    return v_transfer;
end;
$$;


ALTER FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_received_by" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_received_by" "uuid", "p_notes" "text") IS 'Recebe transferência, suportando recebimento parcial e divergência.';



CREATE OR REPLACE FUNCTION "public"."redeem_reward"("p_customer_id" "uuid", "p_reward_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_reward record;
    v_customer_points integer;
    v_voucher_code text;
    v_voucher_id uuid;
    v_program_store_id uuid;
    v_program_id uuid;
    v_existing_redemptions integer;
begin
    -- 1. Get Reward & Lock row
    select * into v_reward from public.fidelity_rewards where id = p_reward_id for update;
    
    if not found then
        return jsonb_build_object('success', false, 'message', 'Recompensa não encontrada.');
    end if;

    if v_reward.is_active = false then
        return jsonb_build_object('success', false, 'message', 'Esta recompensa não está mais ativa.');
    end if;

    -- 2. Check Stock
    -- Note: We only check if it is NOT NULL. Null means unlimited stock.
    if v_reward.stock_quantity is not null and v_reward.stock_quantity <= 0 then
        return jsonb_build_object('success', false, 'message', 'Estoque esgotado para esta recompensa.');
    end if;
    
    -- 3. Check Offer Date Validity
     if v_reward.offer_valid_until is not null and v_reward.offer_valid_until < now() then
         return jsonb_build_object('success', false, 'message', 'Esta oferta expirou.');
    end if;

    -- 4. Check Per-Customer Limit
    if v_reward.max_redemptions_per_customer is not null then
        select count(*) into v_existing_redemptions 
        from public.fidelity_vouchers 
        where customer_id = p_customer_id and reward_id = p_reward_id;
        
        if v_existing_redemptions >= v_reward.max_redemptions_per_customer then
            return jsonb_build_object('success', false, 'message', 'Você atingiu o limite de resgates para este prêmio.');
        end if;
    end if;

    -- 5. Get Customer Points
    select loyalty_points into v_customer_points from public.customers where id = p_customer_id;
    
    if v_customer_points is null or v_customer_points < v_reward.points_cost then
        return jsonb_build_object('success', false, 'message', 'Pontos insuficientes.');
    end if;

    -- Get Program ID & Store ID
    v_program_id := v_reward.program_id;
    select store_id into v_program_store_id from public.fidelity_programs where id = v_program_id;

    -- 6. Deduct Points
    update public.customers 
    set loyalty_points = loyalty_points - v_reward.points_cost
    where id = p_customer_id;

    -- 7. Generate Voucher Code (8 chars alphanumeric uppercase)
    v_voucher_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));
    
    -- 8. Create Voucher
    insert into public.fidelity_vouchers (
        store_id, 
        customer_id, 
        reward_id, 
        code, 
        status, 
        expires_at, 
        created_at
    ) values (
        v_program_store_id,
        p_customer_id,
        v_reward.id,
        v_voucher_code,
        'active',
        now() + (coalesce(v_reward.voucher_validity_days, 15) || ' days')::interval,
        now()
    ) returning id into v_voucher_id;

    -- 9. Decrement Stock
    if v_reward.stock_quantity is not null then
        update public.fidelity_rewards 
        set stock_quantity = stock_quantity - 1 
        where id = p_reward_id;
    end if;
    
    -- 10. Log Transaction
    insert into public.fidelity_transactions (
        program_id, 
        customer_id, 
        type, 
        points, 
        description
    ) values (
        v_program_id,
        p_customer_id,
        'redeem',
        v_reward.points_cost, -- recorded as positive number in column?
        -- Wait, previous logic was negative?
        -- 'redeem' type logic in `handle_new_order` uses positive input but logic might vary.
        -- Let's stick to positive number for 'amount involved', type dictates sign in UI.
        -- OR, consistent with `update customer set ... - points`.
        -- Let's verify `LoyaltyPoints` UI:
        -- `{t.type === 'earn' ... ? '+' : ''}{t.points}`
        -- If I store negative, it will show "- -50"? No, I store +50 and UI adds sign?
        -- `LoyaltyPoints` UI: `{t.type === 'earn' ? '+' : ''}{t.points}`. It doesn't force negative.
        -- So for redeem, I should probably store it as Negative so it renders "-50".
        -- Or store positive and UI handles "redeem" = negative. 
        -- Existing code: `t.type === 'earn' ? '+' : ''`. If t.points is 50, redeem shows "50". 
        -- I should store NEGATIVE for redeem to be safe or update UI. 
        -- Storing -v_reward.points_cost
        -v_reward.points_cost,
        'Resgate: ' || v_reward.title
    );
    
    return jsonb_build_object('success', true, 'voucher_code', v_voucher_code, 'voucher_id', v_voucher_id);

exception when others then
    return jsonb_build_object('success', false, 'message', SQLERRM);
end;
$$;


ALTER FUNCTION "public"."redeem_reward"("p_customer_id" "uuid", "p_reward_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redeem_reward"("p_customer_id" "uuid", "p_reward_id" "uuid") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC de fidelidade. Revisar junto com área Cliente/Fidelidade.';



CREATE OR REPLACE FUNCTION "public"."refresh_customer_commercial_summary"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_total_orders integer := 0;
  v_total_spent numeric := 0;
  v_last_order_at timestamptz;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_customer_id');
  END IF;

  SELECT c.store_id
  INTO v_store_id
  FROM public.customers c
  WHERE c.id = p_customer_id;

  IF v_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'customer_not_found');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(v_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(o.total) FILTER (WHERE o.status = 'completed'), 0),
    MAX(o.created_at)
  INTO
    v_total_orders,
    v_total_spent,
    v_last_order_at
  FROM public.orders o
  WHERE o.customer_id = p_customer_id;

  UPDATE public.customers
  SET
    total_orders = v_total_orders,
    total_spent = v_total_spent,
    last_order_at = v_last_order_at
  WHERE id = p_customer_id;

  RETURN jsonb_build_object(
    'ok', true,
    'customer_id', p_customer_id,
    'total_orders', v_total_orders,
    'total_spent', v_total_spent,
    'last_order_at', v_last_order_at
  );
END;
$$;


ALTER FUNCTION "public"."refresh_customer_commercial_summary"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_customer_segments_safe"("p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_segment record;
  v_inserted integer := 0;
  v_total integer := 0;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  DELETE FROM public.customer_segment_members csm
  USING public.customer_segments cs
  WHERE csm.segment_id = cs.id
    AND cs.store_id = p_store_id
    AND cs.segment_type IN ('behavior', 'tag')
    AND csm.source = 'rule';

  FOR v_segment IN
    SELECT *
    FROM public.customer_segments cs
    WHERE cs.store_id = p_store_id
      AND cs.active = true
      AND cs.segment_type IN ('behavior', 'tag')
  LOOP
    IF v_segment.code = 'clientes_fidelidade' THEN
      INSERT INTO public.customer_segment_members (
        store_id,
        segment_id,
        customer_id,
        source,
        active,
        metadata
      )
      SELECT
        p_store_id,
        v_segment.id,
        c.id,
        'rule',
        true,
        jsonb_build_object('refreshed_by', 'refresh_customer_segments_safe', 'refreshed_at', now())
      FROM public.customers c
      WHERE c.store_id = p_store_id
        AND COALESCE(c.loyalty_opt_in, false) = true
      ON CONFLICT (segment_id, customer_id)
      DO UPDATE SET
        active = true,
        removed_at = NULL,
        metadata = EXCLUDED.metadata;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_total := v_total + v_inserted;

    ELSIF v_segment.code = 'clientes_com_pontos' THEN
      INSERT INTO public.customer_segment_members (
        store_id,
        segment_id,
        customer_id,
        source,
        active,
        metadata
      )
      SELECT
        p_store_id,
        v_segment.id,
        c.id,
        'rule',
        true,
        jsonb_build_object('refreshed_by', 'refresh_customer_segments_safe', 'refreshed_at', now())
      FROM public.customers c
      WHERE c.store_id = p_store_id
        AND COALESCE(c.loyalty_points, 0) > 0
      ON CONFLICT (segment_id, customer_id)
      DO UPDATE SET
        active = true,
        removed_at = NULL,
        metadata = EXCLUDED.metadata;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_total := v_total + v_inserted;

    ELSIF v_segment.code = 'clientes_publicos' THEN
      INSERT INTO public.customer_segment_members (
        store_id,
        segment_id,
        customer_id,
        source,
        active,
        metadata
      )
      SELECT
        p_store_id,
        v_segment.id,
        c.id,
        'rule',
        true,
        jsonb_build_object('refreshed_by', 'refresh_customer_segments_safe', 'refreshed_at', now())
      FROM public.customers c
      WHERE c.store_id = p_store_id
        AND (
          c.data_ownership = 'customer_owned'
          OR c.source IN ('public_store', 'whatsapp', 'qr_table')
        )
      ON CONFLICT (segment_id, customer_id)
      DO UPDATE SET
        active = true,
        removed_at = NULL,
        metadata = EXCLUDED.metadata;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_total := v_total + v_inserted;

    ELSIF v_segment.code = 'clientes_vip_tag' THEN
      INSERT INTO public.customer_segment_members (
        store_id,
        segment_id,
        customer_id,
        source,
        active,
        metadata
      )
      SELECT
        p_store_id,
        v_segment.id,
        c.id,
        'rule',
        true,
        jsonb_build_object('refreshed_by', 'refresh_customer_segments_safe', 'refreshed_at', now())
      FROM public.customers c
      WHERE c.store_id = p_store_id
        AND 'vip' = ANY(COALESCE(c.tags, ARRAY[]::text[]))
      ON CONFLICT (segment_id, customer_id)
      DO UPDATE SET
        active = true,
        removed_at = NULL,
        metadata = EXCLUDED.metadata;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_total := v_total + v_inserted;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'members_refreshed', v_total
  );
END;
$$;


ALTER FUNCTION "public"."refresh_customer_segments_safe"("p_store_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_stock_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    current_stock integer;
BEGIN
    SELECT stock_quantity INTO current_stock
    FROM products
    WHERE id = NEW.product_id;
    
    IF current_stock IS NULL THEN
        RAISE EXCEPTION 'Produto não encontrado: %', NEW.product_id;
    END IF;
    
    NEW.previous_stock := current_stock;
    
    IF NEW.type IN ('entry', 'cancellation') THEN
        NEW.new_stock := current_stock + NEW.quantity;
        UPDATE products SET stock_quantity = NEW.new_stock WHERE id = NEW.product_id;
        
    ELSIF NEW.type IN ('exit', 'confirmation', 'clearance') THEN
        NEW.new_stock := current_stock + NEW.quantity;
        IF NEW.new_stock < 0 THEN
            RAISE EXCEPTION 'Estoque insuficiente para produto %. Estoque atual: %, necessário: %', 
                NEW.product_id, current_stock, ABS(NEW.quantity);
        END IF;
        UPDATE products SET stock_quantity = NEW.new_stock WHERE id = NEW.product_id;
        
    ELSIF NEW.type = 'reservation' THEN
        NEW.new_stock := current_stock;
    END IF;
    
    IF NEW.user_id IS NULL THEN
        BEGIN
            NEW.user_id := auth.uid();
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."register_stock_movement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_store_permission_v3"("p_permission_key" "text", "p_category" "text", "p_label" "text", "p_description" "text", "p_risk" "text" DEFAULT 'medium'::"text", "p_macro_group" "text" DEFAULT 'operational'::"text", "p_group_key" "text" DEFAULT NULL::"text", "p_group_label" "text" DEFAULT NULL::"text", "p_item_key" "text" DEFAULT NULL::"text", "p_item_label" "text" DEFAULT NULL::"text", "p_action_key" "text" DEFAULT NULL::"text", "p_action_label" "text" DEFAULT NULL::"text", "p_depends_on" "text" DEFAULT NULL::"text", "p_access_permission_key" "text" DEFAULT NULL::"text", "p_default_role_allowed" "jsonb" DEFAULT '{}'::"jsonb", "p_ui_sort_order" integer DEFAULT NULL::integer, "p_show_in_permission_ui" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_permission_key text := trim(coalesce(p_permission_key, ''));
  v_action_key text;
  v_action_label text;
  v_module text;
begin
  if v_permission_key = '' then
    raise exception 'Permissão não informada.';
  end if;

  v_module := split_part(v_permission_key, '.', 1);

  v_action_key := coalesce(
    nullif(trim(coalesce(p_action_key, '')), ''),
    case
      when v_permission_key like '%.view' then 'view'
      when v_permission_key like '%.manage' then 'manage'
      when v_permission_key like '%.create' then 'create'
      when v_permission_key like '%.cancel' then 'cancel'
      when v_permission_key like '%.confirm' then 'confirm'
      when v_permission_key like '%.adjust' then 'adjust'
      when v_permission_key like '%.export' then 'export'
      else coalesce(nullif(split_part(v_permission_key, '.', 2), ''), 'action')
    end
  );

  v_action_label := coalesce(
    nullif(trim(coalesce(p_action_label, '')), ''),
    case v_action_key
      when 'view' then 'Ver'
      when 'manage' then 'Gerenciar'
      when 'create' then 'Criar'
      when 'cancel' then 'Cancelar'
      when 'confirm' then 'Confirmar'
      when 'adjust' then 'Ajustar'
      when 'export' then 'Exportar'
      when 'access' then 'Acessar'
      else initcap(v_action_key)
    end
  );

  insert into public.store_permission_catalog (
    permission_key,
    category,
    label,
    description,
    risk,
    active,
    sort_order,
    macro_group,
    group_key,
    group_label,
    item_key,
    item_label,
    action_key,
    action_label,
    depends_on,
    access_permission_key,
    default_role_allowed,
    ui_sort_order,
    show_in_permission_ui,
    updated_at
  )
  values (
    v_permission_key,
    p_category,
    p_label,
    p_description,
    coalesce(p_risk, 'medium'),
    true,
    coalesce(p_ui_sort_order, 99999),
    p_macro_group,
    coalesce(p_group_key, v_module),
    coalesce(p_group_label, initcap(v_module)),
    coalesce(p_item_key, v_module),
    coalesce(p_item_label, p_label),
    v_action_key,
    v_action_label,
    p_depends_on,
    p_access_permission_key,
    coalesce(p_default_role_allowed, '{}'::jsonb),
    coalesce(p_ui_sort_order, 99999),
    coalesce(p_show_in_permission_ui, true),
    now()
  )
  on conflict (permission_key)
  do update set
    category = excluded.category,
    label = excluded.label,
    description = excluded.description,
    risk = excluded.risk,
    active = true,
    sort_order = excluded.sort_order,
    macro_group = excluded.macro_group,
    group_key = excluded.group_key,
    group_label = excluded.group_label,
    item_key = excluded.item_key,
    item_label = excluded.item_label,
    action_key = excluded.action_key,
    action_label = excluded.action_label,
    depends_on = excluded.depends_on,
    access_permission_key = excluded.access_permission_key,
    default_role_allowed = excluded.default_role_allowed,
    ui_sort_order = excluded.ui_sort_order,
    show_in_permission_ui = excluded.show_in_permission_ui,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."register_store_permission_v3"("p_permission_key" "text", "p_category" "text", "p_label" "text", "p_description" "text", "p_risk" "text", "p_macro_group" "text", "p_group_key" "text", "p_group_label" "text", "p_item_key" "text", "p_item_label" "text", "p_action_key" "text", "p_action_label" "text", "p_depends_on" "text", "p_access_permission_key" "text", "p_default_role_allowed" "jsonb", "p_ui_sort_order" integer, "p_show_in_permission_ui" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_order_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_items" "public"."order_item_reserve_input"[], "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  i public.order_item_reserve_input;
  v_avail numeric;
BEGIN
  FOREACH i IN ARRAY p_items
  LOOP
    SELECT available INTO v_avail
    FROM public.product_stock_available
    WHERE store_id = p_store_id AND product_id = i.product_id;

    IF v_avail IS NULL THEN
      RAISE EXCEPTION 'Produto não encontrado (available). store_id=% product_id=%', p_store_id, i.product_id;
    END IF;

    IF v_avail < i.quantity THEN
      RAISE EXCEPTION 'Estoque insuficiente. available=% requested=% product_id=%', v_avail, i.quantity, i.product_id;
    END IF;

    INSERT INTO public.stock_reservations (
      store_id, product_id, order_id, quantity, status, expires_at, created_at
    )
    VALUES (
      p_store_id, i.product_id, p_order_id, i.quantity, 'active', now() + interval '30 minutes', now()
    );

    -- Auditoria (não mexe físico)
    PERFORM public.apply_stock_movement_delta(
      p_store_id,
      i.product_id,
      'reservation',
      0,
      false,
      'order',
      p_order_id,
      'reserve',
      p_metadata,
      p_created_by
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."reserve_order_stock"("p_store_id" "uuid", "p_order_id" "uuid", "p_items" "public"."order_item_reserve_input"[], "p_created_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_stock"("p_order_id" "uuid", "p_product_id" "uuid", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
    v_stock INTEGER;
    v_reserved INTEGER;
    v_current_reservation INTEGER;
BEGIN
    -- Check total stock
    SELECT stock INTO v_stock FROM public.products WHERE id = p_product_id;
    
    IF v_stock IS NULL THEN
        RAISE EXCEPTION 'Product not found';
    END IF;
    
    -- Calculate active reservations (ignoring THIS specific reservation if we are updating it? 
    -- Logic: We are inserting a NEW reservation row usually. 
    -- Or replacing? Let's assume we delete old reservation for this item and insert new one 
    -- or we just check availability for the DELTA. 
    -- Simplest: Check if (Total - All_Other_Active_Reservations) >= New_Quantity
    
    SELECT COALESCE(SUM(quantity), 0) INTO v_reserved 
    FROM public.stock_reservations 
    WHERE product_id = p_product_id 
      AND expires_at > NOW()
      AND order_id != p_order_id; -- Exclude current order's reservations to avoid double counting if updating

    IF (v_stock - v_reserved) < p_quantity THEN
         RETURN jsonb_build_object('success', false, 'message', 'Estoque insuficiente');
    END IF;

    -- Delete existing reservation for this product/order to replace with new qty
    DELETE FROM public.stock_reservations 
    WHERE order_id = p_order_id AND product_id = p_product_id;

    -- Insert new reservation
    INSERT INTO public.stock_reservations (order_id, product_id, quantity, expires_at)
    VALUES (p_order_id, p_product_id, p_quantity, NOW() + INTERVAL '10 minutes');

    RETURN jsonb_build_object('success', true, 'message', 'Reservado por 10 min');
END;
$$;


ALTER FUNCTION "public"."reserve_stock"("p_order_id" "uuid", "p_product_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_stock"("p_store_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_source_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  v_avail numeric;
  v_reservation_id uuid;
BEGIN
  SELECT available INTO v_avail
  FROM public.product_stock_available
  WHERE store_id = p_store_id AND product_id = p_product_id;

  IF v_avail IS NULL THEN
    RAISE EXCEPTION 'Produto não encontrado (available).';
  END IF;

  IF v_avail < p_quantity THEN
    RAISE EXCEPTION 'Estoque indisponível. available=% requested=%', v_avail, p_quantity;
  END IF;

  INSERT INTO public.stock_reservations (
    store_id, product_id, quantity, status, order_id, created_at
  )
  VALUES (
    p_store_id, p_product_id, p_quantity, 'active', p_source_id, now()
  )
  RETURNING id INTO v_reservation_id;

  PERFORM public.apply_stock_movement_delta(
    p_store_id,
    p_product_id,
    'reservation',
    0, -- não muda físico
    false,
    'order',
    p_source_id,
    'reserve',
    p_metadata,
    p_created_by
  );

  RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION "public"."reserve_stock"("p_store_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_source_id" "uuid", "p_created_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_store_master_password"("p_store_id" "uuid", "p_new_password" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_rows_updated integer;
begin
  if p_store_id is null then
    raise exception 'Loja não informada';
  end if;

  if p_new_password is null or length(trim(p_new_password)) < 6 then
    raise exception 'A nova senha master deve ter pelo menos 6 caracteres';
  end if;

  if not exists (
    select 1
    from public.stores s
    where s.id = p_store_id
      and s.user_id = auth.uid()
  ) then
    raise exception 'Você não tem permissão para alterar esta loja';
  end if;

  update public.stores
  set stock_password_hash = crypt(trim(p_new_password), gen_salt('bf'))
  where id = p_store_id
    and user_id = auth.uid();

  get diagnostics v_rows_updated = row_count;

  if coalesce(v_rows_updated, 0) = 0 then
    raise exception 'Nenhuma linha foi atualizada ao redefinir a senha master';
  end if;
end;
$$;


ALTER FUNCTION "public"."reset_store_master_password"("p_store_id" "uuid", "p_new_password" "text") OWNER TO "postgres";


