CREATE OR REPLACE FUNCTION "public"."reset_user_pin_with_password"("p_password" "text", "p_new_pin" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_encrypted text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_new_pin is null or length(trim(p_new_pin)) < 4 then
    raise exception 'PIN inválido (mínimo 4 dígitos)';
  end if;

  select u.encrypted_password
    into v_encrypted
  from auth.users u
  where u.id = auth.uid();

  if v_encrypted is null then
    raise exception 'user not found';
  end if;

  -- valida senha
  if extensions.crypt(p_password, v_encrypted) <> v_encrypted then
    raise exception 'senha inválida';
  end if;

  -- grava novo PIN (hash)
  insert into public.user_pins (user_id, pin_hash, updated_at)
  values (
    auth.uid(),
    extensions.crypt(p_new_pin, extensions.gen_salt('bf')),
    now()
  )
  on conflict (user_id)
  do update set
    pin_hash = excluded.pin_hash,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."reset_user_pin_with_password"("p_password" "text", "p_new_pin" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reset_user_pin_with_password"("p_password" "text", "p_new_pin" "text") IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC sensível para reset de PIN com senha. Revisar com política de autorização reforçada.';



CREATE OR REPLACE FUNCTION "public"."resolve_permission_section_v3"("p_permission_code" "text") RETURNS TABLE("area" "text", "section" "text", "action" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    split_part(p_permission_code, '.', 1) as area,
    case
      when array_length(string_to_array(p_permission_code, '.'), 1) = 2 then 'root'
      else split_part(p_permission_code, '.', 2)
    end as section,
    case
      when right(p_permission_code, 5) = '.view' then 'view'
      when right(p_permission_code, 7) = '.manage' then 'manage'
      when split_part(p_permission_code, '.', 2) = 'view' then 'view'
      when split_part(p_permission_code, '.', 2) = 'manage' then 'manage'
      else split_part(p_permission_code, '.', 2)
    end as action;
$$;


ALTER FUNCTION "public"."resolve_permission_section_v3"("p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_my_profile_change_request"("p_request_id" "uuid", "p_decision" "text", "p_member_feedback" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "admin_proposed_changes" "jsonb", "applied_changes" "jsonb", "member_feedback" "text", "member_responded_at" timestamp with time zone, "applied_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_email text;
  v_actor_name text;

  v_request public.store_member_profile_change_requests%ROWTYPE;
  v_member public.store_members%ROWTYPE;
  v_profile public.profiles%ROWTYPE;

  v_now timestamp with time zone := now();
  v_changes jsonb;
  v_field text;
  v_value jsonb;

  v_applied_changes jsonb := '{}'::jsonb;

  v_text_value text;
  v_date_value date;
BEGIN
  v_actor_id := auth.uid();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Solicitação não informada.';
  END IF;

  IF p_decision NOT IN ('confirm', 'request_correction') THEN
    RAISE EXCEPTION 'Decisão inválida. Use confirm ou request_correction.';
  END IF;

  SELECT *
  INTO v_request
  FROM public.store_member_profile_change_requests r
  WHERE r.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitação não encontrada.';
  END IF;

  IF v_request.user_id <> v_actor_id THEN
    RAISE EXCEPTION 'Esta solicitação não pertence ao usuário logado.';
  END IF;

  IF v_request.status <> 'awaiting_member_confirmation' THEN
    RAISE EXCEPTION 'Esta solicitação não está aguardando conferência do usuário.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = v_request.member_id
    AND sm.user_id = v_actor_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário não encontrado.';
  END IF;

  SELECT *
  INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_actor_id
  FOR UPDATE;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_actor_id) AS identity_row;

  IF p_decision = 'request_correction' THEN
    IF length(trim(COALESCE(p_member_feedback, ''))) < 5 THEN
      RAISE EXCEPTION 'Informe uma pendência com pelo menos 5 caracteres.';
    END IF;

    UPDATE public.store_member_profile_change_requests r
    SET
      status = 'correction_requested',
      member_feedback = trim(p_member_feedback),
      member_responded_at = v_now,
      updated_at = v_now
    WHERE r.id = v_request.id;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_request.store_id,
      v_request.member_id,
      v_request.user_id,
      'note',
      'warning',
      'Pendência informada na solicitação cadastral',
      trim(p_member_feedback),
      v_now,
      true,
      v_actor_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'respond_my_profile_change_request',
        'request_id', v_request.id,
        'decision', 'request_correction',
        'request_type', v_request.request_type
      ),
      v_now,
      v_now
    );

  ELSIF p_decision = 'confirm' THEN
    v_changes := COALESCE(v_request.admin_proposed_changes, '{}'::jsonb);

    IF jsonb_typeof(v_changes) <> 'object' OR v_changes = '{}'::jsonb THEN
      RAISE EXCEPTION 'Não há alterações propostas para aplicar.';
    END IF;

    /*
      Formato aceito:
      {
        "member_zip_code": { "old": "...", "new": "...", "label": "CEP" },
        "member_address": { "old": "...", "new": "...", "label": "Endereço" }
      }
    */

    FOR v_field, v_value IN
      SELECT key, value
      FROM jsonb_each(v_changes)
    LOOP
      v_text_value := NULLIF(trim(COALESCE(v_value->>'new', '')), '');

      IF v_field = 'member_email' THEN
        UPDATE public.store_members SET member_email = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_phone' THEN
        UPDATE public.store_members SET member_phone = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_mobile_phone' THEN
        UPDATE public.store_members SET member_mobile_phone = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_whatsapp_phone' THEN
        UPDATE public.store_members SET member_whatsapp_phone = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_zip_code' THEN
        UPDATE public.store_members SET member_zip_code = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_address' THEN
        UPDATE public.store_members SET member_address = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_address_number' THEN
        UPDATE public.store_members SET member_address_number = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_complement' THEN
        UPDATE public.store_members SET member_complement = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_district' THEN
        UPDATE public.store_members SET member_district = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_city' THEN
        UPDATE public.store_members SET member_city = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'member_state' THEN
        UPDATE public.store_members SET member_state = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'internal_alias' THEN
        UPDATE public.store_members SET internal_alias = v_text_value, updated_at = v_now WHERE id = v_member.id;

      ELSIF v_field = 'name' THEN
        UPDATE public.profiles SET name = v_text_value, updated_at = v_now WHERE id = v_actor_id;

      ELSIF v_field = 'cpf' THEN
        UPDATE public.profiles SET cpf = v_text_value, updated_at = v_now WHERE id = v_actor_id;

      ELSIF v_field = 'birthdate' THEN
        v_date_value := (v_value->>'new')::date;
        UPDATE public.profiles SET birthdata = v_date_value, updated_at = v_now WHERE id = v_actor_id;

      ELSE
        RAISE EXCEPTION 'Campo não permitido para aplicação automática: %', v_field;
      END IF;

      v_applied_changes := v_applied_changes || jsonb_build_object(v_field, v_value);
    END LOOP;

    UPDATE public.store_member_profile_change_requests r
    SET
      status = 'applied',
      member_feedback = NULLIF(trim(COALESCE(p_member_feedback, '')), ''),
      member_responded_at = v_now,
      applied_changes = v_applied_changes,
      applied_at = v_now,
      updated_at = v_now,
      metadata = COALESCE(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'applied_by_function', 'respond_my_profile_change_request',
        'confirmed_by_member', true
      )
    WHERE r.id = v_request.id;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_request.store_id,
      v_request.member_id,
      v_request.user_id,
      'note',
      CASE WHEN v_request.sensitive THEN 'high' ELSE 'info' END,
      'Alteração cadastral confirmada e aplicada',
      'O usuário conferiu e confirmou a alteração cadastral preparada pelo responsável.',
      v_now,
      true,
      v_actor_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'respond_my_profile_change_request',
        'request_id', v_request.id,
        'decision', 'confirm',
        'request_type', v_request.request_type,
        'applied_changes', v_applied_changes
      ),
      v_now,
      v_now
    );
  END IF;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_request.store_id,
    v_actor_id,
    v_actor_name,
    v_actor_email,
    'store_member_profile_change_request_member_response',
    jsonb_build_object(
      'request_id', v_request.id,
      'member_id', v_request.member_id,
      'request_type', v_request.request_type,
      'decision', p_decision
    ),
    'success',
    v_now
  );

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.requested_changes,
    r.admin_proposed_changes,
    r.applied_changes,
    r.member_feedback,
    r.member_responded_at,
    r.applied_at,
    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  WHERE r.id = v_request.id;
END;
$$;


