ALTER FUNCTION "public"."return_stock_after_confirm"("p_store_id" "uuid", "p_order_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_created_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_store_profile_change_request"("p_request_id" "uuid", "p_decision" "text", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "store_id" "uuid", "member_id" "uuid", "user_id" "uuid", "request_type" "text", "status" "text", "requested_changes" "jsonb", "reason" "text", "admin_notes" "text", "reviewed_by" "uuid", "reviewed_by_email" "text", "reviewed_at" timestamp with time zone, "applied_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_email text;
  v_actor_name text;
  v_request public.store_member_profile_change_requests%ROWTYPE;
  v_member public.store_members%ROWTYPE;
  v_now timestamp with time zone := now();
  v_can_review boolean := false;

  v_changes jsonb;
  v_field text;
  v_change jsonb;
  v_new_value text;
  v_item_id text;

  v_applied_changes jsonb := '{}'::jsonb;
  v_occurrence_description text := '';
BEGIN
  v_actor_id := auth.uid();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Solicitação não informada.';
  END IF;

  IF p_decision NOT IN ('approve', 'reject', 'cancel') THEN
    RAISE EXCEPTION 'Decisão inválida. Use approve, reject ou cancel.';
  END IF;

  SELECT *
  INTO v_request
  FROM public.store_member_profile_change_requests r
  WHERE r.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitação não encontrada.';
  END IF;

  IF v_request.status NOT IN ('pending', 'correction_requested', 'awaiting_member_confirmation') THEN
    RAISE EXCEPTION 'Esta solicitação não está disponível para análise.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = v_request.member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do colaborador não encontrado.';
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_actor_id) AS identity_row;

  v_can_review :=
    public.app_is_store_owner(v_request.store_id)
    OR public.user_has_store_permission(v_request.store_id, 'users.profile_requests.review')
    OR public.user_has_store_permission(v_request.store_id, 'users.profile_requests.manage');

  IF NOT v_can_review THEN
    RAISE EXCEPTION 'Sem permissão para analisar solicitações cadastrais.';
  END IF;

  IF p_decision = 'reject' THEN
    UPDATE public.store_member_profile_change_requests r
    SET
      status = 'rejected',
      admin_notes = NULLIF(trim(COALESCE(p_admin_notes, '')), ''),
      reviewed_by = v_actor_id,
      reviewed_by_email = v_actor_email,
      reviewed_at = v_now,
      updated_at = v_now
    WHERE r.id = v_request.id;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_request.store_id,
      v_request.member_id,
      v_request.user_id,
      'note',
      'warning',
      'Solicitação cadastral rejeitada',
      COALESCE(NULLIF(trim(p_admin_notes), ''), 'Solicitação rejeitada pelo responsável.'),
      v_now,
      true,
      v_actor_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'review_store_profile_change_request',
        'request_id', v_request.id,
        'decision', 'reject',
        'request_type', v_request.request_type
      ),
      v_now,
      v_now
    );

  ELSIF p_decision = 'cancel' THEN
    UPDATE public.store_member_profile_change_requests r
    SET
      status = 'cancelled',
      admin_notes = NULLIF(trim(COALESCE(p_admin_notes, '')), ''),
      reviewed_by = v_actor_id,
      reviewed_by_email = v_actor_email,
      reviewed_at = v_now,
      updated_at = v_now
    WHERE r.id = v_request.id;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_request.store_id,
      v_request.member_id,
      v_request.user_id,
      'note',
      'info',
      'Solicitação cadastral cancelada',
      COALESCE(NULLIF(trim(p_admin_notes), ''), 'Solicitação cancelada pelo responsável.'),
      v_now,
      true,
      v_actor_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'review_store_profile_change_request',
        'request_id', v_request.id,
        'decision', 'cancel',
        'request_type', v_request.request_type
      ),
      v_now,
      v_now
    );

  ELSE
    v_changes := COALESCE(v_request.requested_changes, '{}'::jsonb);

    IF jsonb_typeof(v_changes) <> 'object' OR v_changes = '{}'::jsonb THEN
      RAISE EXCEPTION 'A solicitação não possui alterações estruturadas para aplicar.';
    END IF;

    IF v_request.request_type = 'additional_info_remove' THEN
      v_item_id := COALESCE(
        v_changes->>'item_id',
        v_changes->>'id'
      );

      IF v_item_id IS NULL OR trim(v_item_id) = '' THEN
        RAISE EXCEPTION 'Item de informação adicional não informado.';
      END IF;

      UPDATE public.store_members sm
      SET
        member_additional_info = COALESCE(
          (
            SELECT jsonb_agg(item)
            FROM jsonb_array_elements(COALESCE(sm.member_additional_info, '[]'::jsonb)) AS item
            WHERE item->>'id' <> v_item_id
          ),
          '[]'::jsonb
        ),
        updated_at = v_now
      WHERE sm.id = v_request.member_id;

      v_applied_changes := jsonb_build_object(
        'additional_info_remove',
        v_changes
      );

      v_occurrence_description :=
        'Informação adicional removida conforme solicitação aprovada.';

    ELSE
      FOR v_field, v_change IN
        SELECT key, value
        FROM jsonb_each(v_changes)
      LOOP
        v_new_value := NULLIF(trim(COALESCE(v_change->>'new', v_change->>'value', '')), '');

        IF v_field IN ('zip_code', 'member_zip_code') THEN
          UPDATE public.store_members
          SET member_zip_code = regexp_replace(COALESCE(v_new_value, ''), '\D', '', 'g'),
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('address', 'member_address') THEN
          UPDATE public.store_members
          SET member_address = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('address_number', 'member_address_number') THEN
          UPDATE public.store_members
          SET member_address_number = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('complement', 'member_complement') THEN
          UPDATE public.store_members
          SET member_complement = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('district', 'member_district') THEN
          UPDATE public.store_members
          SET member_district = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('city', 'member_city') THEN
          UPDATE public.store_members
          SET member_city = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('state', 'member_state') THEN
          UPDATE public.store_members
          SET member_state = upper(v_new_value),
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('member_email', 'email') THEN
          UPDATE public.store_members
          SET member_email = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('phone', 'member_phone') THEN
          UPDATE public.store_members
          SET member_phone = regexp_replace(COALESCE(v_new_value, ''), '\D', '', 'g'),
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('mobile_phone', 'member_mobile_phone') THEN
          UPDATE public.store_members
          SET member_mobile_phone = regexp_replace(COALESCE(v_new_value, ''), '\D', '', 'g'),
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('whatsapp_phone', 'member_whatsapp_phone') THEN
          UPDATE public.store_members
          SET member_whatsapp_phone = regexp_replace(COALESCE(v_new_value, ''), '\D', '', 'g'),
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field IN ('internal_alias', 'alias') THEN
          UPDATE public.store_members
          SET internal_alias = v_new_value,
              updated_at = v_now
          WHERE id = v_request.member_id;

        ELSIF v_field = 'name' THEN
          UPDATE public.profiles
          SET name = v_new_value,
              updated_at = v_now
          WHERE id = v_request.user_id;

        ELSIF v_field = 'cpf' THEN
          UPDATE public.profiles
          SET cpf = v_new_value,
              updated_at = v_now
          WHERE id = v_request.user_id;

        ELSIF v_field = 'birthdate' THEN
          UPDATE public.profiles
          SET birthdata = NULLIF(v_new_value, '')::date,
              updated_at = v_now
          WHERE id = v_request.user_id;

        ELSE
          RAISE EXCEPTION 'Campo não permitido para aplicação automática: %', v_field;
        END IF;

        v_applied_changes := v_applied_changes || jsonb_build_object(v_field, v_change);

        v_occurrence_description :=
          v_occurrence_description ||
          COALESCE(v_change->>'label', v_field) ||
          ': ' ||
          COALESCE(v_change->>'old', 'Não informado') ||
          ' → ' ||
          COALESCE(v_change->>'new', 'Não informado') ||
          E'\n';
      END LOOP;
    END IF;

    UPDATE public.store_member_profile_change_requests r
    SET
      status = 'applied',
      admin_notes = NULLIF(trim(COALESCE(p_admin_notes, '')), ''),
      reviewed_by = v_actor_id,
      reviewed_by_email = v_actor_email,
      reviewed_at = v_now,
      applied_at = v_now,
      applied_changes = v_applied_changes,
      updated_at = v_now,
      metadata = COALESCE(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'review_function', 'review_store_profile_change_request',
        'decision', 'approve'
      )
    WHERE r.id = v_request.id;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_request.store_id,
      v_request.member_id,
      v_request.user_id,
      'note',
      CASE WHEN v_request.sensitive THEN 'high' ELSE 'info' END,
      'Alteração cadastral aprovada e aplicada',
      COALESCE(NULLIF(trim(v_occurrence_description), ''), 'Alteração cadastral aplicada conforme solicitação aprovada.'),
      v_now,
      true,
      v_actor_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'review_store_profile_change_request',
        'request_id', v_request.id,
        'decision', 'approve',
        'request_type', v_request.request_type,
        'applied_changes', v_applied_changes
      ),
      v_now,
      v_now
    );
  END IF;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_request.store_id,
    v_actor_id,
    v_actor_name,
    v_actor_email,
    'store_member_profile_change_request_reviewed',
    jsonb_build_object(
      'request_id', v_request.id,
      'member_id', v_request.member_id,
      'target_user_id', v_request.user_id,
      'request_type', v_request.request_type,
      'decision', p_decision
    ),
    'success',
    v_now
  );

  RETURN QUERY
  SELECT
    r.id,
    r.store_id,
    r.member_id,
    r.user_id,
    r.request_type,
    r.status,
    r.requested_changes,
    r.reason,
    r.admin_notes,
    r.reviewed_by,
    r.reviewed_by_email,
    r.reviewed_at,
    r.applied_at,
    r.created_at,
    r.updated_at
  FROM public.store_member_profile_change_requests r
  WHERE r.id = v_request.id;
END;
$$;


ALTER FUNCTION "public"."review_store_profile_change_request"("p_request_id" "uuid", "p_decision" "text", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_store_role_permissions_for_new_store_v3"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.store_role_permission_templates (
    store_id,
    role,
    permission_code,
    allowed,
    updated_at
  )
  select
    new.id,
    r.role,
    c.permission_key,
    case
      when r.role = 'owner' then true
      else coalesce((c.default_role_allowed ->> r.role)::boolean, false)
    end,
    now()
  from public.store_permission_catalog c
  cross join (
    values
      ('owner'::text),
      ('admin'::text),
      ('manager'::text),
      ('stock_operator'::text),
      ('cashier'::text),
      ('sales'::text),
      ('staff'::text),
      ('viewer'::text)
  ) as r(role)
  where c.active = true
  on conflict on constraint store_role_permission_templates_unique
  do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."seed_store_role_permissions_for_new_store_v3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_admin_message"("p_store_id" "uuid", "p_title" "text", "p_message" "text", "p_recipient_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_expires_in_days" integer DEFAULT 30) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_message_id UUID;
BEGIN
    -- 1. Create the master message record
    INSERT INTO store_messages (store_id, title, message, expires_at)
    VALUES (p_store_id, p_title, p_message, now() + (p_expires_in_days || ' days')::INTERVAL)
    RETURNING id INTO v_message_id;

    -- 2. Bulk Insert into customer_notifications
    IF p_recipient_ids IS NULL THEN
        -- Send to ALL active customers of this store
        INSERT INTO customer_notifications (customer_id, store_id, title, message, message_id)
        SELECT id, p_store_id, p_title, p_message, v_message_id
        FROM customers
        WHERE store_id = p_store_id AND status = 'active';
    ELSE
        -- Send to SPECIFIC customers
        INSERT INTO customer_notifications (customer_id, store_id, title, message, message_id)
        SELECT c.id, p_store_id, p_title, p_message, v_message_id
        FROM unnest(p_recipient_ids) AS rid
        INNER JOIN customers c ON c.id = rid
        WHERE c.store_id = p_store_id;
    END IF;
END;
$$;


ALTER FUNCTION "public"."send_admin_message"("p_store_id" "uuid", "p_title" "text", "p_message" "text", "p_recipient_ids" "uuid"[], "p_expires_in_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_admin_message"("p_store_id" "uuid", "p_title" "text", "p_message" "text", "p_recipient_ids" "uuid"[], "p_expires_in_days" integer) IS 'EXCEÇÃO TEMPORÁRIA 6.4: RPC administrativa de mensagens. Revisar permissões finas em etapa Configurações/Admin.';



CREATE OR REPLACE FUNCTION "public"."send_customer_otp"("p_phone" "text", "p_store_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_phone text;
  v_otp text;
  v_hash text;
  v_expires_at timestamptz;
  v_recent_count integer;
BEGIN
  v_phone := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');

  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'message', 'Não foi possível enviar o código.');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stores s
    WHERE s.id = p_store_id
      AND s.public_store_enabled = true
  ) THEN
    RETURN jsonb_build_object('ok', false, 'message', 'Não foi possível enviar o código.');
  END IF;

  IF length(v_phone) < 10 OR length(v_phone) > 14 THEN
    RETURN jsonb_build_object('ok', false, 'message', 'Telefone inválido.');
  END IF;

  SELECT COUNT(*)
    INTO v_recent_count
  FROM public.customer_otps co
  WHERE co.store_id = p_store_id
    AND co.phone = v_phone
    AND co.created_at >= now() - interval '10 minutes';

  IF v_recent_count >= 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'rateLimited', true,
      'message', 'Muitas tentativas recentes. Aguarde alguns minutos.'
    );
  END IF;

  v_expires_at := now() + interval '5 minutes';
  v_otp := lpad((floor(random() * 1000000))::int::text, 6, '0');
  v_hash := crypt(v_otp, gen_salt('bf'));

  DELETE FROM public.customer_otps
  WHERE phone = v_phone
    AND store_id = p_store_id
    AND verified = false;

  INSERT INTO public.customer_otps (
    phone,
    store_id,
    otp_code,
    expires_at,
    verified,
    attempts
  )
  VALUES (
    v_phone,
    p_store_id,
    v_hash,
    v_expires_at,
    false,
    0
  );

  RETURN jsonb_build_object(
    'ok', true,
    'expiresAt', v_expires_at
  );
END;
$$;


ALTER FUNCTION "public"."send_customer_otp"("p_phone" "text", "p_store_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_customer_otp"("p_phone" "text", "p_store_id" "uuid") IS 'EXCEÇÃO INTENCIONAL 6.4: função pública para solicitação de OTP por cliente não autenticado. Revisar rate limit, logs e antispam na etapa Comercial/Cliente.';



