CREATE OR REPLACE FUNCTION "public"."set_stock_transfer_item_received_qty"("p_transfer_item_id" "uuid", "p_received_qty" numeric) RETURNS "public"."stock_transfer_items"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_item public.stock_transfer_items;
    v_transfer public.stock_transfers;
begin
    if p_received_qty is null or p_received_qty < 0 then
        raise exception 'p_received_qty deve ser >= 0' using errcode = '23514';
    end if;

    select *
      into v_item
      from public.stock_transfer_items
     where id = p_transfer_item_id
     for update;

    if v_item.id is null then
        raise exception 'Item da transferência não encontrado' using errcode = '23503';
    end if;

    select *
      into v_transfer
      from public.stock_transfers
     where id = v_item.transfer_id
     for update;

    if v_transfer.id is null then
        raise exception 'Transferência não encontrada' using errcode = '23503';
    end if;

    if v_transfer.status <> 'shipped' then
        raise exception 'Só é permitido definir recebimento em transferências shipped' using errcode = '23514';
    end if;

    if p_received_qty > v_item.shipped_qty then
        raise exception 'p_received_qty não pode ser maior que shipped_qty' using errcode = '23514';
    end if;

    update public.stock_transfer_items
       set received_qty = p_received_qty,
           divergence_qty = greatest(shipped_qty - p_received_qty, 0),
           updated_at = now()
     where id = v_item.id
    returning * into v_item;

    return v_item;
end;
$$;


ALTER FUNCTION "public"."set_stock_transfer_item_received_qty"("p_transfer_item_id" "uuid", "p_received_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_stock_transfer_item_shipped_qty"("p_transfer_item_id" "uuid", "p_shipped_qty" numeric) RETURNS "public"."stock_transfer_items"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_item public.stock_transfer_items;
    v_transfer public.stock_transfers;
begin
    if p_shipped_qty is null or p_shipped_qty < 0 then
        raise exception 'p_shipped_qty deve ser >= 0' using errcode = '23514';
    end if;

    select *
      into v_item
      from public.stock_transfer_items
     where id = p_transfer_item_id
     for update;

    if v_item.id is null then
        raise exception 'Item da transferência não encontrado' using errcode = '23503';
    end if;

    select *
      into v_transfer
      from public.stock_transfers
     where id = v_item.transfer_id
     for update;

    if v_transfer.id is null then
        raise exception 'Transferência não encontrada' using errcode = '23503';
    end if;

    if v_transfer.status <> 'draft' then
        raise exception 'Só é permitido definir expedição em transferências draft' using errcode = '23514';
    end if;

    if p_shipped_qty > v_item.requested_qty then
        raise exception 'p_shipped_qty não pode ser maior que requested_qty' using errcode = '23514';
    end if;

    update public.stock_transfer_items
       set shipped_qty = p_shipped_qty,
           updated_at = now()
     where id = v_item.id
    returning * into v_item;

    return v_item;
end;
$$;


