CREATE OR REPLACE FUNCTION "public"."set_store_role_permission_v3"("p_store_id" "uuid", "p_role" "text", "p_permission_code" "text", "p_allowed" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("store_id" "uuid", "role" "text", "permission_code" "text", "allowed" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_role text;
  v_permission_code text := trim(coalesce(p_permission_code, ''));
  v_allowed boolean := coalesce(p_allowed, false);
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  v_role := case lower(trim(coalesce(p_role, '')))
    when 'administrador' then 'admin'
    when 'admin' then 'admin'
    when 'gerente' then 'manager'
    when 'manager' then 'manager'
    when 'estoque' then 'stock_operator'
    when 'stock_operator' then 'stock_operator'
    when 'operador de estoque' then 'stock_operator'
    when 'caixa' then 'cashier'
    when 'cashier' then 'cashier'
    when 'vendas' then 'sales'
    when 'sales' then 'sales'
    when 'equipe' then 'staff'
    when 'staff' then 'staff'
    when 'visualizador' then 'viewer'
    when 'viewer' then 'viewer'
    else lower(trim(coalesce(p_role, '')))
  end;

  if v_role not in (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) then
    raise exception 'Papel inválido ou não editável: %', v_role;
  end if;

  if v_permission_code = '' then
    raise exception 'Permissão não informada.';
  end if;

  if not public.can_access_security_section_v3(p_store_id, 'roles', true) then
    raise exception 'Você não tem permissão para alterar permissões por papel.';
  end if;

  if not exists (
    select 1
    from public.store_permission_catalog c
    where c.permission_key = v_permission_code
      and c.active = true
  ) then
    raise exception 'Permissão inválida ou inativa: %', v_permission_code;
  end if;

  update public.store_role_permission_templates t
  set
    allowed = v_allowed,
    updated_at = now()
  where t.store_id = p_store_id
    and t.role = v_role
    and t.permission_code = v_permission_code;

  if not found then
    raise exception
      'Template não encontrado para loja %, papel %, permissão %',
      p_store_id,
      v_role,
      v_permission_code;
  end if;

  begin
    perform public.insert_security_log(
      p_store_id,
      auth.uid(),
      null,
      'store_role_permission_template_updated',
      jsonb_build_object(
        'role', v_role,
        'permission_code', v_permission_code,
        'allowed', v_allowed,
        'reason', p_reason
      ),
      'success'
    );
  exception
    when others then
      null;
  end;

  return query
  select
    t.store_id,
    t.role,
    t.permission_code,
    t.allowed,
    t.updated_at
  from public.store_role_permission_templates t
  where t.store_id = p_store_id
    and t.role = v_role
    and t.permission_code = v_permission_code;
end;
$$;


ALTER FUNCTION "public"."set_store_role_permission_v3"("p_store_id" "uuid", "p_role" "text", "p_permission_code" "text", "p_allowed" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_store_role_permissions_bulk_v3"("p_store_id" "uuid", "p_role" "text", "p_changes" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("permission_code" "text", "allowed" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_role text;
  v_change jsonb;
  v_permission_code text;
  v_allowed boolean;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if p_changes is null or jsonb_typeof(p_changes) <> 'array' then
    raise exception 'Alterações inválidas.';
  end if;

  v_role := case lower(trim(coalesce(p_role, '')))
    when 'administrador' then 'admin'
    when 'admin' then 'admin'
    when 'gerente' then 'manager'
    when 'manager' then 'manager'
    when 'estoque' then 'stock_operator'
    when 'stock_operator' then 'stock_operator'
    when 'operador de estoque' then 'stock_operator'
    when 'caixa' then 'cashier'
    when 'cashier' then 'cashier'
    when 'vendas' then 'sales'
    when 'sales' then 'sales'
    when 'equipe' then 'staff'
    when 'staff' then 'staff'
    when 'visualizador' then 'viewer'
    when 'viewer' then 'viewer'
    else lower(trim(coalesce(p_role, '')))
  end;

  if v_role not in (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) then
    raise exception 'Papel inválido ou não editável: %', v_role;
  end if;

  if not public.can_access_security_section_v3(p_store_id, 'roles', true) then
    raise exception 'Você não tem permissão para alterar permissões por papel.';
  end if;

  for v_change in
    select value
    from jsonb_array_elements(p_changes)
  loop
    v_permission_code := trim(coalesce(v_change->>'permission_code', ''));
    v_allowed := coalesce((v_change->>'allowed')::boolean, false);

    if v_permission_code = '' then
      raise exception 'Permissão não informada em uma das alterações.';
    end if;

    if not exists (
      select 1
      from public.store_permission_catalog c
      where c.permission_key = v_permission_code
        and c.active = true
    ) then
      raise exception 'Permissão inválida ou inativa: %', v_permission_code;
    end if;

    update public.store_role_permission_templates t
    set
      allowed = v_allowed,
      updated_at = now()
    where t.store_id = p_store_id
      and t.role = v_role
      and t.permission_code = v_permission_code;

    if not found then
      raise exception 'Template não encontrado para papel %, permissão %', v_role, v_permission_code;
    end if;
  end loop;

  begin
    perform public.insert_security_log(
      p_store_id,
      auth.uid(),
      null,
      'store_role_permissions_bulk_updated',
      jsonb_build_object(
        'role', v_role,
        'changes', p_changes,
        'reason', p_reason
      ),
      'success'
    );
  exception
    when others then
      null;
  end;

  return query
  select
    t.permission_code,
    t.allowed,
    t.updated_at
  from public.store_role_permission_templates t
  where t.store_id = p_store_id
    and t.role = v_role
  order by t.permission_code;
end;
$$;


ALTER FUNCTION "public"."set_store_role_permissions_bulk_v3"("p_store_id" "uuid", "p_role" "text", "p_changes" "jsonb", "p_reason" "text") OWNER TO "postgres";


