CREATE OR REPLACE FUNCTION "public"."ship_stock_transfer"("p_transfer_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_use_transit" boolean DEFAULT false) RETURNS TABLE("transfer_id" "uuid", "transfer_code" "text", "status" "text", "shipped_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.stock_transfers%ROWTYPE;
  v_item record;
  v_balance_id uuid;
  v_on_hand numeric;
  v_reserved numeric;
  v_available numeric;
  v_previous_stock integer;
  v_new_stock integer;
  v_qty numeric;
BEGIN
  IF p_transfer_id IS NULL THEN
    RAISE EXCEPTION 'Transferência não informada.';
  END IF;

  SELECT *
  INTO v_transfer
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transferência não encontrada.';
  END IF;

  IF NOT public.is_store_member(v_transfer.store_id) THEN
    RAISE EXCEPTION 'Acesso negado à transferência informada.';
  END IF;

  IF v_transfer.status <> 'draft'::public.stock_transfer_status THEN
    RAISE EXCEPTION 'Apenas transferências em rascunho podem ser enviadas. Status atual: %', v_transfer.status;
  END IF;

  IF v_transfer.source_location_id = v_transfer.destination_location_id THEN
    RAISE EXCEPTION 'Origem e destino não podem ser o mesmo local.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stock_transfer_items sti
    WHERE sti.transfer_id = p_transfer_id
      AND sti.store_id = v_transfer.store_id
  ) THEN
    RAISE EXCEPTION 'A transferência não possui itens.';
  END IF;

  FOR v_item IN
    SELECT
      sti.*
    FROM public.stock_transfer_items sti
    WHERE sti.transfer_id = p_transfer_id
      AND sti.store_id = v_transfer.store_id
    ORDER BY sti.created_at, sti.id
  LOOP
    v_qty := COALESCE(v_item.requested_qty, 0);

    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'Item % possui quantidade solicitada inválida.', v_item.id;
    END IF;

    IF v_qty <> trunc(v_qty) THEN
      RAISE EXCEPTION 'Item % possui quantidade fracionada. Transferências físicas devem usar unidades inteiras.', v_item.id;
    END IF;

    SELECT
      ilb.id,
      ilb.on_hand,
      ilb.reserved,
      COALESCE(ilb.on_hand, 0) - COALESCE(ilb.reserved, 0)
    INTO
      v_balance_id,
      v_on_hand,
      v_reserved,
      v_available
    FROM public.inventory_location_balances ilb
    WHERE ilb.store_id = v_transfer.store_id
      AND ilb.location_id = v_transfer.source_location_id
      AND ilb.product_id = v_item.product_id
      AND (
        (v_item.variant_id IS NULL AND ilb.variant_id IS NULL)
        OR ilb.variant_id = v_item.variant_id
      )
    ORDER BY ilb.updated_at DESC
    LIMIT 1
    FOR UPDATE;

    IF v_balance_id IS NULL THEN
      RAISE EXCEPTION 'Produto % sem saldo na origem.', v_item.product_id;
    END IF;

    IF COALESCE(v_available, 0) < v_qty THEN
      RAISE EXCEPTION
        'Saldo insuficiente na origem para o produto %. Disponível: %, solicitado: %.',
        v_item.product_id,
        COALESCE(v_available, 0),
        v_qty;
    END IF;

    v_previous_stock := COALESCE(v_on_hand, 0)::integer;
    v_new_stock := (COALESCE(v_on_hand, 0) - v_qty)::integer;

    UPDATE public.inventory_location_balances ilb
    SET
      on_hand = ilb.on_hand - v_qty,
      updated_at = now()
    WHERE ilb.id = v_balance_id;

    UPDATE public.stock_transfer_items sti
    SET
      shipped_qty = v_qty,
      received_qty = 0,
      divergence_qty = 0,
      divergence_resolution = NULL,
      divergence_reason = NULL,
      divergence_notes = NULL,
      loss_qty = 0,
      returned_to_origin_qty = 0,
      accepted_shortage_qty = 0,
      divergence_resolved_at = NULL,
      metadata = COALESCE(sti.metadata, '{}'::jsonb) || jsonb_build_object(
        'ship_source', 'ship_stock_transfer',
        'use_transit', COALESCE(p_use_transit, false),
        'shipped_at', now()
      ),
      updated_at = now()
    WHERE sti.id = v_item.id;

    INSERT INTO public.stock_movements (
      product_id,
      order_id,
      quantity,
      type,
      reason,
      user_id,
      previous_stock,
      new_stock,
      created_at,
      store_id,
      affects_physical,
      source,
      source_id,
      reason_code,
      metadata,
      created_by,
      supplier_id,
      location_id,
      from_location_id,
      to_location_id,
      transfer_id
    )
    VALUES (
      v_item.product_id,
      NULL,
      (v_qty::integer * -1),
      'exit'::public.stock_movement_type,
      'Saída por envio de transferência interna',
      auth.uid(),
      v_previous_stock,
      v_new_stock,
      now(),
      v_transfer.store_id,
      true,
      'stock_transfer',
      v_transfer.id,
      'transfer_shipped',
      jsonb_build_object(
        'transfer_id', v_transfer.id,
        'transfer_code', v_transfer.transfer_code,
        'transfer_item_id', v_item.id,
        'source_location_id', v_transfer.source_location_id,
        'destination_location_id', v_transfer.destination_location_id,
        'use_transit', COALESCE(p_use_transit, false)
      ),
      auth.uid(),
      NULL,
      v_transfer.source_location_id,
      v_transfer.source_location_id,
      v_transfer.destination_location_id,
      v_transfer.id
    );
  END LOOP;

  UPDATE public.stock_transfers st
  SET
    status = 'shipped'::public.stock_transfer_status,
    shipped_by = auth.uid(),
    shipped_at = now(),
    notes = COALESCE(NULLIF(trim(COALESCE(p_notes, '')), ''), st.notes),
    metadata = COALESCE(st.metadata, '{}'::jsonb) || jsonb_build_object(
      'shipped_source', 'ship_stock_transfer',
      'use_transit', COALESCE(p_use_transit, false)
    ),
    updated_at = now()
  WHERE st.id = p_transfer_id;

  RETURN QUERY
  SELECT
    st.id,
    st.transfer_code,
    st.status::text,
    st.shipped_at
  FROM public.stock_transfers st
  WHERE st.id = p_transfer_id;
END;
$$;


ALTER FUNCTION "public"."ship_stock_transfer"("p_transfer_id" "uuid", "p_notes" "text", "p_use_transit" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ship_stock_transfer"("p_transfer_id" "uuid", "p_notes" "text", "p_use_transit" boolean) IS 'EXCEÇÃO INTENCIONAL 6.4: RPC operacional de envio de transferência. SECURITY DEFINER com validação interna de loja e saldo para impedir estoque negativo.';



