CREATE OR REPLACE FUNCTION "public"."sync_permission_catalog_v3"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.security_permission_catalog (
    code,
    module,
    action,
    label,
    description,
    risk_level,
    active,
    sort_order,
    created_at,
    updated_at,
    macro_group,
    group_key,
    group_label,
    item_key,
    item_label,
    action_key,
    action_label,
    depends_on,
    access_permission_key,
    default_role_allowed,
    ui_sort_order,
    show_in_permission_ui
  )
  values (
    new.permission_key,
    split_part(new.permission_key, '.', 1),
    coalesce(new.action_key, split_part(new.permission_key, '.', 2)),
    new.label,
    new.description,
    new.risk,
    new.active,
    coalesce(new.sort_order, new.ui_sort_order, 99999),
    now(),
    now(),
    new.macro_group,
    new.group_key,
    new.group_label,
    new.item_key,
    new.item_label,
    new.action_key,
    new.action_label,
    new.depends_on,
    new.access_permission_key,
    new.default_role_allowed,
    new.ui_sort_order,
    new.show_in_permission_ui
  )
  on conflict (code)
  do update set
    module = excluded.module,
    action = excluded.action,
    label = excluded.label,
    description = excluded.description,
    risk_level = excluded.risk_level,
    active = excluded.active,
    sort_order = excluded.sort_order,
    updated_at = now(),
    macro_group = excluded.macro_group,
    group_key = excluded.group_key,
    group_label = excluded.group_label,
    item_key = excluded.item_key,
    item_label = excluded.item_label,
    action_key = excluded.action_key,
    action_label = excluded.action_label,
    depends_on = excluded.depends_on,
    access_permission_key = excluded.access_permission_key,
    default_role_allowed = excluded.default_role_allowed,
    ui_sort_order = excluded.ui_sort_order,
    show_in_permission_ui = excluded.show_in_permission_ui;

  insert into public.store_role_permission_templates (
    store_id,
    role,
    permission_code,
    allowed,
    updated_at
  )
  select
    s.id,
    r.role,
    new.permission_key,
    case
      when r.role = 'owner' then true
      else coalesce((new.default_role_allowed ->> r.role)::boolean, false)
    end,
    now()
  from public.stores s
  cross join (
    values
      ('owner'::text),
      ('admin'::text),
      ('manager'::text),
      ('stock_operator'::text),
      ('cashier'::text),
      ('sales'::text),
      ('staff'::text),
      ('viewer'::text)
  ) as r(role)
  on conflict on constraint store_role_permission_templates_unique
  do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_permission_catalog_v3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_supplier_metrics_document"("p_purchase_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.sync_supplier_price_history_for_document(p_purchase_document_id);

  update public.products p
     set last_entry_unit_cost = latest.unit_cost,
         last_stock_entry_at = latest.effective_at
    from (
      select distinct on (sph.product_id)
        sph.product_id,
        sph.unit_cost,
        sph.effective_at
      from public.supplier_price_history sph
      join public.purchase_documents pd
        on pd.id = sph.purchase_document_id
      where sph.is_active = true
        and pd.store_id = (
          select store_id
          from public.purchase_documents
          where id = p_purchase_document_id
        )
      order by sph.product_id, sph.effective_at desc, sph.created_at desc
    ) latest
   where p.id = latest.product_id;
end;
$$;


ALTER FUNCTION "public"."sync_supplier_metrics_document"("p_purchase_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_supplier_price_history_for_document"("p_purchase_document_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_doc record;
begin
  select
    pd.id,
    pd.store_id,
    pd.supplier_id,
    pd.issue_date,
    pd.status,
    pd.invoice_number,
    pd.cancel_reason,
    pd.cancelled_at,
    pd.created_at
  into v_doc
  from public.purchase_documents pd
  where pd.id = p_purchase_document_id;

  if not found then
    raise exception 'purchase_document % not found', p_purchase_document_id;
  end if;

  update public.supplier_price_history
     set is_active = false,
         cancelled_at = case
           when v_doc.status = 'cancelled' then coalesce(v_doc.cancelled_at, now())
           else cancelled_at
         end,
         cancelled_reason = case
           when v_doc.status = 'cancelled' then coalesce(v_doc.cancel_reason, 'document_cancelled')
           else cancelled_reason
         end,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'document_status', v_doc.status,
           'synced_at', now()
         )
   where purchase_document_id = v_doc.id;

  if v_doc.status = 'confirmed' then
    insert into public.supplier_price_history (
      store_id,
      supplier_id,
      product_id,
      purchase_document_id,
      purchase_document_item_id,
      unit_cost,
      quantity,
      issue_date,
      effective_at,
      source,
      is_active,
      cancelled_at,
      cancelled_reason,
      metadata
    )
    select
      v_doc.store_id,
      v_doc.supplier_id,
      pdi.product_id,
      v_doc.id,
      pdi.id,
      pdi.unit_cost,
      pdi.quantity,
      v_doc.issue_date,
      coalesce(v_doc.created_at, now()),
      'purchase_document',
      true,
      null,
      null,
      jsonb_build_object(
        'invoice_number', v_doc.invoice_number,
        'document_status', v_doc.status,
        'synced_at', now()
      )
    from public.purchase_document_items pdi
    where pdi.purchase_document_id = v_doc.id
    on conflict (purchase_document_item_id)
    do update set
      store_id = excluded.store_id,
      supplier_id = excluded.supplier_id,
      product_id = excluded.product_id,
      purchase_document_id = excluded.purchase_document_id,
      unit_cost = excluded.unit_cost,
      quantity = excluded.quantity,
      issue_date = excluded.issue_date,
      effective_at = excluded.effective_at,
      source = excluded.source,
      is_active = true,
      cancelled_at = null,
      cancelled_reason = null,
      metadata = excluded.metadata;
  end if;
end;
$$;


ALTER FUNCTION "public"."sync_supplier_price_history_for_document"("p_purchase_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."touch_store_permission_version"("p_store_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_store_id is null then
    return;
  end if;

  insert into public.store_permission_versions (
    store_id,
    version,
    reason,
    changed_by,
    changed_at
  )
  values (
    p_store_id,
    1,
    p_reason,
    auth.uid(),
    now()
  )
  on conflict (store_id)
  do update set
    version = public.store_permission_versions.version + 1,
    reason = excluded.reason,
    changed_by = excluded.changed_by,
    changed_at = now();
end;
$$;


