CREATE OR REPLACE FUNCTION "public"."trg_block_direct_stock_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
begin
  -- só bloqueia se stock_quantity estiver sendo alterado
  if new.stock_quantity is distinct from old.stock_quantity then
    -- permite apenas quando a RPC habilitar explicitamente
    if coalesce(current_setting('app.allow_stock_update', true), 'false') <> 'true' then
      raise exception 'Alteração direta de stock_quantity bloqueada. Use a RPC apply_stock_movement_delta.';
    end if;
  end if;

  return new;
end;
$$;


