CREATE OR REPLACE FUNCTION "public"."trg_log_purchase_document_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_email text;
  v_action text;
BEGIN
  SELECT email::text
  INTO v_user_email
  FROM auth.users
  WHERE id = auth.uid();

  IF TG_OP = 'INSERT' THEN
    v_action := 'Criar Documento de Compra';

    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_email,
      action,
      details,
      outcome,
      created_at
    )
    VALUES (
      NEW.store_id,
      auth.uid(),
      v_user_email,
      v_action,
      jsonb_build_object(
        'purchase_document_id', NEW.id,
        'document_code', NEW.document_code,
        'invoice_number', NEW.invoice_number,
        'supplier_id', NEW.supplier_id,
        'status', NEW.status,
        'total_amount', NEW.total_amount
      ),
      'success',
      now()
    );

    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_action := CASE
      WHEN OLD.status IS DISTINCT FROM NEW.status
        AND NEW.status = 'confirmed'
        THEN 'Confirmar Documento de Compra'
      WHEN OLD.status IS DISTINCT FROM NEW.status
        AND NEW.status = 'cancelled'
        THEN 'Cancelar Documento de Compra'
      ELSE 'Editar Documento de Compra'
    END;

    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_email,
      action,
      details,
      outcome,
      created_at
    )
    VALUES (
      NEW.store_id,
      auth.uid(),
      v_user_email,
      v_action,
      jsonb_build_object(
        'purchase_document_id', NEW.id,
        'document_code', NEW.document_code,
        'invoice_number', NEW.invoice_number,
        'supplier_id', NEW.supplier_id,
        'old', jsonb_build_object(
          'status', OLD.status,
          'total_amount', OLD.total_amount,
          'notes', OLD.notes,
          'cancelled_at', OLD.cancelled_at,
          'cancel_reason', OLD.cancel_reason
        ),
        'new', jsonb_build_object(
          'status', NEW.status,
          'total_amount', NEW.total_amount,
          'notes', NEW.notes,
          'cancelled_at', NEW.cancelled_at,
          'cancel_reason', NEW.cancel_reason
        )
      ),
      'success',
      now()
    );

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_log_purchase_document_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_log_purchase_quotation_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_email text;
  v_action text;
BEGIN
  SELECT email::text
  INTO v_user_email
  FROM auth.users
  WHERE id = auth.uid();

  IF TG_OP = 'INSERT' THEN
    v_action := 'Criar Cotação de Compra';

    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_email,
      action,
      details,
      outcome,
