        'supplier_id', NEW.supplier_id,
        'status', NEW.status,
        'sent_channel', NEW.sent_channel,
        'responsible_name', NEW.responsible_name
      ),
      'success',
      now()
    );

    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_action := CASE
      WHEN OLD.converted_purchase_document_id IS DISTINCT FROM NEW.converted_purchase_document_id
        AND NEW.converted_purchase_document_id IS NOT NULL
        THEN 'Converter Cotação em Compra'
      WHEN OLD.status IS DISTINCT FROM NEW.status
        THEN 'Alterar Status de Cotação'
      ELSE 'Editar Cotação de Compra'
    END;

    INSERT INTO public.store_security_logs (
      store_id,
      user_id,
      user_email,
      action,
      details,
      outcome,
      created_at
    )
    VALUES (
      NEW.store_id,
      auth.uid(),
      v_user_email,
      v_action,
      jsonb_build_object(
        'quotation_id', NEW.id,
        'quotation_code', NEW.quotation_code,
        'supplier_id', NEW.supplier_id,
        'old', jsonb_build_object(
          'status', OLD.status,
          'sent_channel', OLD.sent_channel,
          'responsible_name', OLD.responsible_name,
          'converted_purchase_document_id', OLD.converted_purchase_document_id
        ),
        'new', jsonb_build_object(
          'status', NEW.status,
          'sent_channel', NEW.sent_channel,
          'responsible_name', NEW.responsible_name,
          'converted_purchase_document_id', NEW.converted_purchase_document_id
        )
      ),
      'success',
      now()
    );

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


