    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.customer_id IS NOT NULL THEN
    PERFORM public.refresh_customer_commercial_summary(NEW.customer_id);
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.customer_id IS NOT NULL
     AND OLD.customer_id IS DISTINCT FROM NEW.customer_id THEN
    PERFORM public.refresh_customer_commercial_summary(OLD.customer_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


