CREATE OR REPLACE FUNCTION "public"."trg_stock_movements_operational_timeline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_name text;
  v_location_name text;
  v_event_type text;
  v_title text;
  v_description text;
  v_severity text;
  v_status text := 'done';
  v_channel text := 'manual';
  v_reference text;
  v_abs_qty numeric;
  v_is_relevant boolean := false;
BEGIN
  -- Evita duplicar eventos automáticos de compras/transferências.
  v_is_relevant :=
       COALESCE(NEW.source, '') IN (
         'manual_adjustment',
         'stock_adjustment',
         'physical_count',
         'manual',
         'inventory_count'
       )
    OR COALESCE(NEW.reason_code, '') IN (
         'manual_adjustment',
         'manual_entry',
         'manual_exit',
         'physical_count',
         'inventory_count',
         'damage',
         'loss',
         'waste',
         'breakage',
         'expired'
       )
    OR COALESCE(NEW.metadata ->> 'origin', '') IN (
         'manual_adjustment',
         'stock_adjustment',
         'physical_count',
         'inventory_count'
       )
    OR COALESCE(NEW.reason, '') ILIKE '%avaria%'
    OR COALESCE(NEW.reason, '') ILIKE '%perda%'
    OR COALESCE(NEW.reason, '') ILIKE '%quebra%'
    OR COALESCE(NEW.reason, '') ILIKE '%venc%'
    OR COALESCE(NEW.reason, '') ILIKE '%derret%';

  IF NOT v_is_relevant THEN
    RETURN NEW;
  END IF;

  SELECT p.name
    INTO v_product_name
  FROM public.products p
  WHERE p.id = NEW.product_id;

  SELECT sl.name
    INTO v_location_name
  FROM public.stock_locations sl
  WHERE sl.id = COALESCE(
    NEW.location_id,
    NULLIF(NEW.metadata ->> 'location_id', '')::uuid
  );

  v_abs_qty := abs(COALESCE(NEW.quantity, 0));

  v_reference := COALESCE(
    NEW.metadata ->> 'document_code',
    NEW.metadata ->> 'transfer_code',
    NEW.metadata ->> 'reference',
    NEW.source_id::text,
    NEW.id::text
  );

  IF NEW.type = 'entry' THEN
    v_event_type := 'stock_movement_manual_entry';
    v_title := 'Entrada manual de estoque';
    v_severity := 'success';
    v_description := COALESCE(v_location_name, 'Local não identificado')
      || ' recebeu ' || v_abs_qty::text || ' un. de '
      || COALESCE(v_product_name, 'produto') || '.';

  ELSIF NEW.type = 'exit' THEN
    v_event_type := 'stock_movement_manual_exit';
    v_title := 'Baixa manual de estoque';
    v_severity := 'warning';
    v_description := COALESCE(v_location_name, 'Local não identificado')
      || ' teve baixa de ' || v_abs_qty::text || ' un. de '
      || COALESCE(v_product_name, 'produto') || '.';

  ELSE
    v_event_type := 'stock_movement_manual_adjustment';
    v_title := 'Ajuste manual de estoque';
    v_severity := 'info';
    v_description := 'Movimentação manual registrada para '
      || COALESCE(v_product_name, 'produto') || '.';
  END IF;

  INSERT INTO public.operational_timeline_events (
    store_id,
    entity_type,
    entity_id,
    event_type,
    title,
    description,
    severity,
    status,
    actor_user_id,
    channel,
    occurred_at,
    source,
    source_id,
    old_data,
    new_data,
    metadata,
    related_product_id,
    related_stock_movement_id
  )
  VALUES (
    NEW.store_id,
    'stock_movement',
    NEW.id,
    v_event_type,
    v_title,
    v_description,
    v_severity,
    v_status,
    NEW.created_by,
    v_channel,
    NEW.created_at,
    COALESCE(NEW.source, 'stock_movement'),
    NEW.id,
    '{}'::jsonb,
    jsonb_build_object(
      'movement_type', NEW.type,
      'quantity', NEW.quantity,
      'reason', NEW.reason,
      'reason_code', NEW.reason_code,
      'product_name', v_product_name,
      'location_name', v_location_name,
      'reference', v_reference
    ),
    COALESCE(NEW.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'origin', 'stock_movement_manual_timeline',
        'product_name', v_product_name,
        'location_name', v_location_name,
        'reference', v_reference
      ),
    NEW.product_id,
    NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_stock_movements_operational_timeline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_stock_transfers_operational_timeline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_event_type text;
  v_title text;
  v_description text;
  v_severity text := 'info';
  v_status text := 'done';
  v_channel text := 'system';

  v_source_location_name text;
  v_destination_location_name text;

  v_items_count integer := 0;
  v_requested_qty numeric := 0;
  v_shipped_qty numeric := 0;
  v_received_qty numeric := 0;
  v_divergence_qty numeric := 0;

  v_should_log boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'draft'::public.stock_transfer_status THEN
      v_event_type := 'stock_transfer_created';
      v_title := 'Transferência criada';
      v_description := 'Rascunho de transferência ' || COALESCE(NEW.transfer_code, NEW.id::text) || ' criado.';
      v_severity := 'info';
      v_status := 'done';
      v_channel := 'manual';
      v_should_log := true;
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status = 'shipped'::public.stock_transfer_status THEN
        v_event_type := 'stock_transfer_shipped';
        v_title := 'Transferência enviada';
        v_description := 'Transferência ' || COALESCE(NEW.transfer_code, NEW.id::text) || ' enviada.';
        v_severity := 'success';
        v_status := 'done';
        v_channel := 'manual';
        v_should_log := true;

      ELSIF NEW.status = 'received'::public.stock_transfer_status THEN
        v_event_type := 'stock_transfer_received';
        v_title := 'Transferência recebida';
        v_description := 'Transferência ' || COALESCE(NEW.transfer_code, NEW.id::text) || ' recebida.';
        v_severity := 'success';
        v_status := 'done';
        v_channel := 'manual';
        v_should_log := true;

      ELSIF NEW.status = 'divergent'::public.stock_transfer_status THEN
        v_event_type := 'stock_transfer_received';
        v_title := 'Transferência recebida com divergência';
        v_description := 'Transferência ' || COALESCE(NEW.transfer_code, NEW.id::text) || ' recebida com divergência.';
        v_severity := 'warning';
        v_status := 'done';
        v_channel := 'manual';
        v_should_log := true;

      ELSIF NEW.status = 'cancelled'::public.stock_transfer_status THEN
        v_event_type := 'stock_transfer_cancelled';
        v_title := 'Transferência cancelada';
        v_description := 'Transferência ' || COALESCE(NEW.transfer_code, NEW.id::text) || ' cancelada.';
        v_severity := 'warning';
        v_status := 'cancelled';
        v_channel := 'manual';
        v_should_log := true;
      END IF;
    END IF;
  END IF;

  IF NOT v_should_log THEN
    RETURN NEW;
  END IF;

  SELECT sl.name
  INTO v_source_location_name
  FROM public.stock_locations sl
  WHERE sl.id = NEW.source_location_id;

  SELECT sl.name
  INTO v_destination_location_name
  FROM public.stock_locations sl
  WHERE sl.id = NEW.destination_location_id;

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(sti.requested_qty), 0)::numeric,
    COALESCE(SUM(sti.shipped_qty), 0)::numeric,
    COALESCE(SUM(sti.received_qty), 0)::numeric,
    COALESCE(SUM(sti.divergence_qty), 0)::numeric
  INTO
    v_items_count,
    v_requested_qty,
    v_shipped_qty,
    v_received_qty,
    v_divergence_qty
  FROM public.stock_transfer_items sti
  WHERE sti.transfer_id = NEW.id;

  PERFORM public.create_operational_timeline_event(
    p_store_id := NEW.store_id,
    p_entity_type := 'stock_transfer',
    p_entity_id := NEW.id,
    p_event_type := v_event_type,
    p_title := v_title,
    p_description := v_description,
    p_severity := v_severity,
    p_status := v_status,
    p_actor_user_id := COALESCE(
      NEW.shipped_by,
      NEW.received_by,
      NEW.requested_by,
      auth.uid()
    ),
    p_responsible_name := NULL,
    p_channel := v_channel,
    p_source := 'trg_stock_transfers_operational_timeline',
    p_source_id := NEW.id,
    p_old_data := CASE
      WHEN TG_OP = 'UPDATE' THEN
        jsonb_build_object(
          'status', OLD.status::text,
          'shipped_at', OLD.shipped_at,
          'received_at', OLD.received_at,
          'cancelled_at', OLD.cancelled_at
        )
      ELSE '{}'::jsonb
    END,
    p_new_data := jsonb_build_object(
      'status', NEW.status::text,
      'transfer_id', NEW.id,
      'transfer_code', NEW.transfer_code,
      'source_location_id', NEW.source_location_id,
      'source_location_name', v_source_location_name,
      'destination_location_id', NEW.destination_location_id,
      'destination_location_name', v_destination_location_name,
      'items_count', v_items_count,
      'requested_qty', v_requested_qty,
      'shipped_qty', v_shipped_qty,
      'received_qty', v_received_qty,
      'divergence_qty', v_divergence_qty,
      'requested_at', NEW.requested_at,
      'shipped_at', NEW.shipped_at,
      'received_at', NEW.received_at,
      'cancelled_at', NEW.cancelled_at,
      'cancel_reason', NEW.cancel_reason
    ),
    p_metadata := jsonb_build_object(
      'phase', '6.5I.7',
      'origin', 'stock_transfer_status_trigger',
      'transfer_code', NEW.transfer_code,
      'source_location_name', v_source_location_name,
      'destination_location_name', v_destination_location_name,
      'stock_transfer_status', NEW.status::text,
      'items_count', v_items_count,
      'requested_qty', v_requested_qty,
      'shipped_qty', v_shipped_qty,
      'received_qty', v_received_qty,
      'divergence_qty', v_divergence_qty
    ),
    p_related_stock_transfer_id := NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_stock_transfers_operational_timeline"() OWNER TO "postgres";


