CREATE OR REPLACE FUNCTION "public"."trg_touch_store_permission_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store_id uuid;
  v_reason text;
begin
  if tg_op = 'DELETE' then
    v_store_id := old.store_id;
  else
    v_store_id := new.store_id;
  end if;

  v_reason := tg_table_name || ':' || tg_op;

  perform public.touch_store_permission_version(v_store_id, v_reason);

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


