CREATE OR REPLACE FUNCTION "public"."trg_validate_purchase_document_supplier_eligibility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier record;
BEGIN
  IF NEW.supplier_id IS NULL THEN
    RAISE EXCEPTION 'Informe um fornecedor para criar o documento de compra.';
  END IF;

  SELECT
    s.id,
    s.name,
    s.store_id,
    COALESCE(s.active, false) AS active,
    COALESCE(s.blocked, false) AS blocked,
    COALESCE(s.homologation_status, 'not_evaluated') AS homologation_status
  INTO v_supplier
  FROM public.suppliers s
  WHERE s.id = NEW.supplier_id;

  IF v_supplier.id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado.';
  END IF;

  IF v_supplier.store_id IS DISTINCT FROM NEW.store_id THEN
    RAISE EXCEPTION 'Fornecedor não pertence à loja do documento.';
  END IF;

  /*
    Regra de elegibilidade:
    Novo documento operacional de compra só pode nascer para fornecedor:
    ativo + aprovado + desbloqueado.
  */
  IF v_supplier.active IS NOT TRUE THEN
    RAISE EXCEPTION 'Fornecedor inativo não pode receber novo documento de compra.';
  END IF;

  IF v_supplier.blocked IS TRUE THEN
    RAISE EXCEPTION 'Fornecedor bloqueado não pode receber novo documento de compra.';
  END IF;

  IF v_supplier.homologation_status <> 'approved' THEN
    RAISE EXCEPTION 'Fornecedor precisa estar aprovado para receber novo documento de compra.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_validate_purchase_document_supplier_eligibility"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trg_validate_purchase_document_supplier_eligibility"() IS 'Bloqueia criação/alteração de documento de compra para fornecedor inativo, bloqueado ou não aprovado.';



CREATE OR REPLACE FUNCTION "public"."trg_validate_purchase_quotation_supplier_eligibility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_supplier record;
BEGIN
  SELECT
    s.id,
    s.store_id,
    COALESCE(s.active, false) AS active,
    COALESCE(s.blocked, false) AS blocked,
    COALESCE(s.homologation_status, 'not_evaluated') AS homologation_status
  INTO v_supplier
  FROM public.suppliers s
  WHERE s.id = NEW.supplier_id;

  IF v_supplier.id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado.';
  END IF;

  IF v_supplier.store_id IS DISTINCT FROM NEW.store_id THEN
    RAISE EXCEPTION 'Fornecedor não pertence à loja da cotação.';
  END IF;

  IF v_supplier.active IS NOT TRUE THEN
    RAISE EXCEPTION 'Fornecedor inativo não pode receber cotação.';
  END IF;

  IF v_supplier.blocked IS TRUE THEN
    RAISE EXCEPTION 'Fornecedor bloqueado não pode receber cotação.';
  END IF;

  IF v_supplier.homologation_status <> 'approved' THEN
    RAISE EXCEPTION 'Fornecedor precisa estar aprovado para receber cotação.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_validate_purchase_quotation_supplier_eligibility"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_admin_customer_safe"("p_store_id" "uuid", "p_customer_id" "uuid", "p_full_name" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_cpf" "text" DEFAULT NULL::"text", "p_birth_date" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT 'active'::"text", "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_internal_notes" "text" DEFAULT NULL::"text", "p_marketing_consent" boolean DEFAULT false, "p_loyalty_opt_in" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_customer record;
  v_phone text;
begin
  if p_store_id is null or p_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_parameters');
  end if;

  if coalesce(auth.role(), '') in ('anon', 'authenticated') then
    if auth.uid() is null
       or not (
         public.app_is_store_owner(p_store_id)
         or public.user_has_store_permission(p_store_id, 'customers.manage')
       ) then
      return jsonb_build_object(
        'ok', false,
        'error', 'access_denied',
        'message', 'Você não tem permissão para editar clientes.'
      );
    end if;
  end if;

  select *
  into v_customer
  from public.customers c
  where c.id = p_customer_id
    and c.store_id = p_store_id;

  if v_customer.id is null then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  if p_status is not null
     and p_status <> all (array['active', 'inactive', 'deleted_requested']) then
    return jsonb_build_object('ok', false, 'error', 'invalid_status');
  end if;

  if coalesce(v_customer.editable_by_store, false) = false
     or v_customer.data_ownership = 'customer_owned' then

    update public.customers
    set
      status = coalesce(p_status, status),
      tags = coalesce(p_tags, tags),
      internal_notes = p_internal_notes,
      marketing_consent = coalesce(p_marketing_consent, marketing_consent),
      loyalty_opt_in = coalesce(p_loyalty_opt_in, loyalty_opt_in),
      customer_metadata = coalesce(customer_metadata, '{}'::jsonb) || jsonb_build_object(
        'last_internal_update_at', now(),
        'last_internal_update_by', auth.uid(),
        'protected_customer_data', true
      )
    where id = p_customer_id
      and store_id = p_store_id;

    return jsonb_build_object(
      'ok', true,
      'customer_id', p_customer_id,
      'protected_data', true,
      'message', 'Dados protegidos preservados. Apenas campos internos foram atualizados.'
    );
  end if;

  v_phone := regexp_replace(coalesce(p_phone, v_customer.phone), '\D', '', 'g');

  if length(v_phone) < 8 then
    return jsonb_build_object('ok', false, 'error', 'invalid_phone');
  end if;

  if exists (
    select 1
    from public.customers c
    where c.store_id = p_store_id
      and c.phone = v_phone
      and c.id <> p_customer_id
      and c.status <> 'deleted_requested'
  ) then
    return jsonb_build_object(
      'ok', false,
      'error', 'customer_phone_already_exists',
      'message', 'Já existe outro cliente com este telefone.'
    );
  end if;

  update public.customers
  set
    full_name = nullif(trim(coalesce(p_full_name, full_name)), ''),
    phone = v_phone,
    email = nullif(trim(coalesce(p_email, email)), ''),
    cpf = nullif(regexp_replace(coalesce(p_cpf, cpf, ''), '\D', '', 'g'), ''),
    birth_date = coalesce(p_birth_date, birth_date),
    status = coalesce(p_status, status),
    tags = coalesce(p_tags, tags),
    internal_notes = p_internal_notes,
    marketing_consent = coalesce(p_marketing_consent, marketing_consent),
    loyalty_opt_in = coalesce(p_loyalty_opt_in, loyalty_opt_in),
    customer_metadata = coalesce(customer_metadata, '{}'::jsonb) || jsonb_build_object(
      'last_admin_update_at', now(),
      'last_admin_update_by', auth.uid()
    )
  where id = p_customer_id
    and store_id = p_store_id;

  return jsonb_build_object(
    'ok', true,
    'customer_id', p_customer_id,
    'protected_data', false
  );
end;
$$;


ALTER FUNCTION "public"."update_admin_customer_safe"("p_store_id" "uuid", "p_customer_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_email" "text", "p_cpf" "text", "p_birth_date" "date", "p_status" "text", "p_tags" "text"[], "p_internal_notes" "text", "p_marketing_consent" boolean, "p_loyalty_opt_in" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_current_user_profile"("p_name" "text", "p_internal_alias" "text", "p_phone" "text", "p_mobile_phone" "text", "p_whatsapp_phone" "text", "p_birthdate" "date" DEFAULT NULL::"date", "p_zip_code" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_address_number" "text" DEFAULT NULL::"text", "p_complement" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_instagram_url" "text" DEFAULT NULL::"text", "p_facebook_url" "text" DEFAULT NULL::"text", "p_website_url" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "uuid", "name" "text", "internal_alias" "text", "phone" "text", "mobile_phone" "text", "whatsapp_phone" "text", "cpf" "text", "birthdate" "date", "zip_code" "text", "address" "text", "address_number" "text", "complement" "text", "district" "text", "city" "text", "state" "text", "instagram_url" "text", "facebook_url" "text", "website_url" "text", "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT *
  FROM public.update_my_profile_details(
    p_name,
    p_internal_alias,
    p_phone,
    p_mobile_phone,
    p_whatsapp_phone,
    NULL,
    p_birthdate,
    p_zip_code,
    p_address,
    p_address_number,
    p_complement,
    p_district,
    p_city,
    p_state,
    p_instagram_url,
    p_facebook_url,
    p_website_url
  );
$$;


ALTER FUNCTION "public"."update_current_user_profile"("p_name" "text", "p_internal_alias" "text", "p_phone" "text", "p_mobile_phone" "text", "p_whatsapp_phone" "text", "p_birthdate" "date", "p_zip_code" "text", "p_address" "text", "p_address_number" "text", "p_complement" "text", "p_district" "text", "p_city" "text", "p_state" "text", "p_instagram_url" "text", "p_facebook_url" "text", "p_website_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_current_user_profile"("p_name" "text", "p_internal_alias" "text", "p_phone" "text", "p_mobile_phone" "text", "p_whatsapp_phone" "text", "p_cpf" "text" DEFAULT NULL::"text", "p_birthdate" "date" DEFAULT NULL::"date", "p_zip_code" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_address_number" "text" DEFAULT NULL::"text", "p_complement" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_instagram_url" "text" DEFAULT NULL::"text", "p_facebook_url" "text" DEFAULT NULL::"text", "p_website_url" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "uuid", "name" "text", "internal_alias" "text", "phone" "text", "mobile_phone" "text", "whatsapp_phone" "text", "cpf" "text", "birthdate" "date", "zip_code" "text", "address" "text", "address_number" "text", "complement" "text", "district" "text", "city" "text", "state" "text", "instagram_url" "text", "facebook_url" "text", "website_url" "text", "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT *
  FROM public.update_my_profile_details(
    p_name,
    p_internal_alias,
    p_phone,
    p_mobile_phone,
    p_whatsapp_phone,
    p_cpf,
    p_birthdate,
    p_zip_code,
    p_address,
    p_address_number,
    p_complement,
    p_district,
    p_city,
    p_state,
    p_instagram_url,
    p_facebook_url,
    p_website_url
  );
$$;


