CREATE OR REPLACE FUNCTION "public"."update_my_profile_details"("p_name" "text", "p_internal_alias" "text", "p_phone" "text", "p_mobile_phone" "text", "p_whatsapp_phone" "text", "p_cpf" "text", "p_birthdate" "date", "p_zip_code" "text", "p_address" "text", "p_address_number" "text", "p_complement" "text", "p_district" "text", "p_city" "text", "p_state" "text", "p_instagram_url" "text", "p_facebook_url" "text", "p_website_url" "text") RETURNS TABLE("user_id" "uuid", "name" "text", "internal_alias" "text", "phone" "text", "mobile_phone" "text", "whatsapp_phone" "text", "cpf" "text", "birthdate" "date", "zip_code" "text", "address" "text", "address_number" "text", "complement" "text", "district" "text", "city" "text", "state" "text", "instagram_url" "text", "facebook_url" "text", "website_url" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_current_cpf text;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT p.cpf
  INTO v_current_cpf
  FROM public.profiles p
  WHERE p.id = v_user_id;

  IF NULLIF(trim(COALESCE(v_current_cpf, '')), '') IS NOT NULL
     AND NULLIF(trim(COALESCE(p_cpf, '')), '') IS DISTINCT FROM NULLIF(trim(COALESCE(v_current_cpf, '')), '') THEN
    RAISE EXCEPTION 'O CPF já cadastrado não pode ser alterado por esta tela. Solicite alteração ao responsável.';
  END IF;

  INSERT INTO public.profiles (
    id,
    name,
    phone,
    mobile_phone,
    whatsapp_phone,
    cpf,
    birthdata,
    zip_code,
    address,
    address_number,
    complement,
    district,
    city,
    state,
    instagram_url,
    facebook_url,
    website_url,
    updated_at
  )
  VALUES (
    v_user_id,
    NULLIF(trim(COALESCE(p_name, '')), ''),
    NULLIF(trim(COALESCE(p_phone, '')), ''),
    NULLIF(trim(COALESCE(p_mobile_phone, '')), ''),
    NULLIF(trim(COALESCE(p_whatsapp_phone, '')), ''),
    NULLIF(trim(COALESCE(p_cpf, '')), ''),
    p_birthdate,
    NULLIF(trim(COALESCE(p_zip_code, '')), ''),
    NULLIF(trim(COALESCE(p_address, '')), ''),
    NULLIF(trim(COALESCE(p_address_number, '')), ''),
    NULLIF(trim(COALESCE(p_complement, '')), ''),
    NULLIF(trim(COALESCE(p_district, '')), ''),
    NULLIF(trim(COALESCE(p_city, '')), ''),
    NULLIF(trim(COALESCE(p_state, '')), ''),
    NULLIF(trim(COALESCE(p_instagram_url, '')), ''),
    NULLIF(trim(COALESCE(p_facebook_url, '')), ''),
    NULLIF(trim(COALESCE(p_website_url, '')), ''),
    now()
  )
  ON CONFLICT (id)
  DO UPDATE SET
    name = EXCLUDED.name,
    phone = EXCLUDED.phone,
    mobile_phone = EXCLUDED.mobile_phone,
    whatsapp_phone = EXCLUDED.whatsapp_phone,
    cpf = CASE
      WHEN NULLIF(trim(COALESCE(public.profiles.cpf, '')), '') IS NULL
        THEN EXCLUDED.cpf
      ELSE public.profiles.cpf
    END,
    birthdata = EXCLUDED.birthdata,
    zip_code = EXCLUDED.zip_code,
    address = EXCLUDED.address,
    address_number = EXCLUDED.address_number,
    complement = EXCLUDED.complement,
    district = EXCLUDED.district,
    city = EXCLUDED.city,
    state = EXCLUDED.state,
    instagram_url = EXCLUDED.instagram_url,
    facebook_url = EXCLUDED.facebook_url,
    website_url = EXCLUDED.website_url,
    updated_at = now();

  RETURN QUERY
  SELECT
    p.id,
    p.name,
    NULL::text AS internal_alias,
    p.phone,
    p.mobile_phone,
    p.whatsapp_phone,
    p.cpf,
    p.birthdata,
    p.zip_code,
    p.address,
    p.address_number,
    p.complement,
    p.district,
    p.city,
    p.state,
    p.instagram_url,
    p.facebook_url,
    p.website_url,
    p.updated_at
  FROM public.profiles p
  WHERE p.id = v_user_id;
END;
$$;


ALTER FUNCTION "public"."update_my_profile_details"("p_name" "text", "p_internal_alias" "text", "p_phone" "text", "p_mobile_phone" "text", "p_whatsapp_phone" "text", "p_cpf" "text", "p_birthdate" "date", "p_zip_code" "text", "p_address" "text", "p_address_number" "text", "p_complement" "text", "p_district" "text", "p_city" "text", "p_state" "text", "p_instagram_url" "text", "p_facebook_url" "text", "p_website_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_my_store_member_alias"("p_store_id" "uuid", "p_internal_alias" "text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "internal_alias" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  RETURN QUERY
  UPDATE public.store_members sm
  SET
    internal_alias = NULLIF(trim(COALESCE(p_internal_alias, '')), ''),
    updated_at = now()
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  RETURNING
    sm.id,
    sm.store_id,
    sm.user_id,
    sm.internal_alias,
    sm.updated_at;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;
END;
$$;


ALTER FUNCTION "public"."update_my_store_member_alias"("p_store_id" "uuid", "p_internal_alias" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_my_store_member_profile"("p_store_id" "uuid", "p_internal_alias" "text" DEFAULT NULL::"text", "p_member_email" "text" DEFAULT NULL::"text", "p_member_phone" "text" DEFAULT NULL::"text", "p_member_mobile_phone" "text" DEFAULT NULL::"text", "p_member_whatsapp_phone" "text" DEFAULT NULL::"text", "p_member_zip_code" "text" DEFAULT NULL::"text", "p_member_address" "text" DEFAULT NULL::"text", "p_member_address_number" "text" DEFAULT NULL::"text", "p_member_complement" "text" DEFAULT NULL::"text", "p_member_district" "text" DEFAULT NULL::"text", "p_member_city" "text" DEFAULT NULL::"text", "p_member_state" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "internal_alias" "text", "member_email" "text", "member_phone" "text", "member_mobile_phone" "text", "member_whatsapp_phone" "text", "member_zip_code" "text", "member_address" "text", "member_address_number" "text", "member_complement" "text", "member_district" "text", "member_city" "text", "member_state" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member public.store_members%ROWTYPE;
  v_updated public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_changed_fields text[] := ARRAY[]::text[];
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  IF COALESCE(v_member.internal_alias, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_internal_alias, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'apelido');
  END IF;

  IF COALESCE(v_member.member_email, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_email, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'e-mail');
  END IF;

  IF COALESCE(v_member.member_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'telefone fixo');
  END IF;

  IF COALESCE(v_member.member_mobile_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'celular');
  END IF;

  IF COALESCE(v_member.member_whatsapp_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'WhatsApp');
  END IF;

  IF COALESCE(v_member.member_zip_code, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_zip_code, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'CEP');
  END IF;

  IF COALESCE(v_member.member_address, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_address, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'endereço');
  END IF;

  IF COALESCE(v_member.member_address_number, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_address_number, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'número');
  END IF;

  IF COALESCE(v_member.member_complement, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_complement, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'complemento');
  END IF;

  IF COALESCE(v_member.member_district, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_district, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'bairro');
  END IF;

  IF COALESCE(v_member.member_city, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_city, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'cidade');
  END IF;

  IF COALESCE(v_member.member_state, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_state, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'UF');
  END IF;

  UPDATE public.store_members sm
  SET
    internal_alias = NULLIF(trim(COALESCE(p_internal_alias, '')), ''),
    member_email = NULLIF(trim(COALESCE(p_member_email, '')), ''),
    member_phone = NULLIF(trim(COALESCE(p_member_phone, '')), ''),
    member_mobile_phone = NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''),
    member_whatsapp_phone = NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''),
    member_zip_code = NULLIF(trim(COALESCE(p_member_zip_code, '')), ''),
    member_address = NULLIF(trim(COALESCE(p_member_address, '')), ''),
    member_address_number = NULLIF(trim(COALESCE(p_member_address_number, '')), ''),
    member_complement = NULLIF(trim(COALESCE(p_member_complement, '')), ''),
    member_district = NULLIF(trim(COALESCE(p_member_district, '')), ''),
    member_city = NULLIF(trim(COALESCE(p_member_city, '')), ''),
    member_state = NULLIF(trim(COALESCE(p_member_state, '')), ''),
    updated_at = now()
  WHERE sm.id = v_member.id
  RETURNING *
  INTO v_updated;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_user_id) AS identity_row;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_updated.store_id,
    v_user_id,
    v_actor_name,
    v_actor_email,
    'store_member_profile_updated_by_self',
    jsonb_build_object(
      'member_id', v_updated.id,
      'target_user_id', v_updated.user_id,
      'changed_fields', to_jsonb(v_changed_fields),
      'origin', 'update_my_store_member_profile'
    ),
    'success',
    now()
  );

  IF cardinality(v_changed_fields) > 0 THEN
    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_updated.store_id,
      v_updated.id,
      v_updated.user_id,
      'note',
      'info',
      'Dados atualizados',
      CASE
        WHEN cardinality(v_changed_fields) = 1 THEN
          'Dado atualizado pelo próprio usuário: ' || v_changed_fields[1] || '.'
        ELSE
          'Dados atualizados pelo próprio usuário: ' || array_to_string(v_changed_fields, ', ') || '.'
      END,
      now(),
      true,
      v_user_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'update_my_store_member_profile',
        'event_type', 'self_profile_update',
        'changed_fields', to_jsonb(v_changed_fields)
      ),
      now(),
      now()
    );
  END IF;

  RETURN QUERY
  SELECT
    v_updated.id,
    v_updated.store_id,
    v_updated.user_id,
    v_updated.internal_alias,
    v_updated.member_email,
    v_updated.member_phone,
    v_updated.member_mobile_phone,
    v_updated.member_whatsapp_phone,
    v_updated.member_zip_code,
    v_updated.member_address,
    v_updated.member_address_number,
    v_updated.member_complement,
    v_updated.member_district,
    v_updated.member_city,
    v_updated.member_state,
    v_updated.updated_at;
END;
$$;


ALTER FUNCTION "public"."update_my_store_member_profile"("p_store_id" "uuid", "p_internal_alias" "text", "p_member_email" "text", "p_member_phone" "text", "p_member_mobile_phone" "text", "p_member_whatsapp_phone" "text", "p_member_zip_code" "text", "p_member_address" "text", "p_member_address_number" "text", "p_member_complement" "text", "p_member_district" "text", "p_member_city" "text", "p_member_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_my_store_member_profile"("p_store_id" "uuid", "p_internal_alias" "text" DEFAULT NULL::"text", "p_member_email" "text" DEFAULT NULL::"text", "p_member_phone" "text" DEFAULT NULL::"text", "p_member_mobile_phone" "text" DEFAULT NULL::"text", "p_member_whatsapp_phone" "text" DEFAULT NULL::"text", "p_member_zip_code" "text" DEFAULT NULL::"text", "p_member_address" "text" DEFAULT NULL::"text", "p_member_address_number" "text" DEFAULT NULL::"text", "p_member_complement" "text" DEFAULT NULL::"text", "p_member_district" "text" DEFAULT NULL::"text", "p_member_city" "text" DEFAULT NULL::"text", "p_member_state" "text" DEFAULT NULL::"text", "p_member_additional_info" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "internal_alias" "text", "member_email" "text", "member_phone" "text", "member_mobile_phone" "text", "member_whatsapp_phone" "text", "member_zip_code" "text", "member_address" "text", "member_address_number" "text", "member_complement" "text", "member_district" "text", "member_city" "text", "member_state" "text", "member_additional_info" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_member public.store_members%ROWTYPE;
  v_updated public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_changed_fields text[] := ARRAY[]::text[];
