  IF jsonb_typeof(COALESCE(p_member_additional_info, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Informações adicionais devem ser enviadas como lista.';
  END IF;

  v_next_additional_info := COALESCE(p_member_additional_info, '[]'::jsonb);

  SELECT *
  INTO v_member
  FROM public.store_members sm
  WHERE sm.store_id = p_store_id
    AND sm.user_id = v_user_id
    AND sm.status IN ('active', 'suspended')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo do usuário com a loja não encontrado.';
  END IF;

  IF COALESCE(v_member.internal_alias, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_internal_alias, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'apelido');
  END IF;

  IF COALESCE(v_member.member_email, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_email, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'e-mail');
  END IF;

  IF COALESCE(v_member.member_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'telefone fixo');
  END IF;

  IF COALESCE(v_member.member_mobile_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'celular');
  END IF;

  IF COALESCE(v_member.member_whatsapp_phone, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'WhatsApp');
  END IF;

  IF COALESCE(v_member.member_zip_code, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_zip_code, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'CEP');
  END IF;

  IF COALESCE(v_member.member_address, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_address, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'endereço');
  END IF;

  IF COALESCE(v_member.member_address_number, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_address_number, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'número');
  END IF;

  IF COALESCE(v_member.member_complement, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_complement, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'complemento');
  END IF;

  IF COALESCE(v_member.member_district, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_district, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'bairro');
  END IF;

  IF COALESCE(v_member.member_city, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_city, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'cidade');
  END IF;

  IF COALESCE(v_member.member_state, '') IS DISTINCT FROM COALESCE(NULLIF(trim(COALESCE(p_member_state, '')), ''), '') THEN
    v_changed_fields := array_append(v_changed_fields, 'UF');
  END IF;

  IF COALESCE(v_member.member_additional_info, '[]'::jsonb) IS DISTINCT FROM v_next_additional_info THEN
    v_changed_fields := array_append(v_changed_fields, 'informações adicionais');
  END IF;

  UPDATE public.store_members sm
  SET
    internal_alias = NULLIF(trim(COALESCE(p_internal_alias, '')), ''),
    member_email = NULLIF(trim(COALESCE(p_member_email, '')), ''),
    member_phone = NULLIF(trim(COALESCE(p_member_phone, '')), ''),
    member_mobile_phone = NULLIF(trim(COALESCE(p_member_mobile_phone, '')), ''),
    member_whatsapp_phone = NULLIF(trim(COALESCE(p_member_whatsapp_phone, '')), ''),
    member_zip_code = NULLIF(trim(COALESCE(p_member_zip_code, '')), ''),
    member_address = NULLIF(trim(COALESCE(p_member_address, '')), ''),
    member_address_number = NULLIF(trim(COALESCE(p_member_address_number, '')), ''),
    member_complement = NULLIF(trim(COALESCE(p_member_complement, '')), ''),
    member_district = NULLIF(trim(COALESCE(p_member_district, '')), ''),
    member_city = NULLIF(trim(COALESCE(p_member_city, '')), ''),
    member_state = NULLIF(trim(COALESCE(p_member_state, '')), ''),
    member_additional_info = v_next_additional_info,
    updated_at = now()
  WHERE sm.id = v_member.id
  RETURNING *
  INTO v_updated;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(v_user_id) AS identity_row;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_updated.store_id,
    v_user_id,
    v_actor_name,
    v_actor_email,
    'store_member_profile_updated_by_self',
    jsonb_build_object(
      'member_id', v_updated.id,
      'target_user_id', v_updated.user_id,
      'changed_fields', to_jsonb(v_changed_fields),
      'origin', 'update_my_store_member_profile'
    ),
    'success',
    now()
  );

  IF cardinality(v_changed_fields) > 0 THEN
    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_updated.store_id,
      v_updated.id,
      v_updated.user_id,
      'note',
      'info',
      'Dados atualizados',
      CASE
        WHEN cardinality(v_changed_fields) = 1 THEN
          'Dado atualizado pelo próprio usuário: ' || v_changed_fields[1] || '.'
        ELSE
          'Dados atualizados pelo próprio usuário: ' || array_to_string(v_changed_fields, ', ') || '.'
      END,
      now(),
      true,
      v_user_id,
      v_actor_email,
      jsonb_build_object(
        'origin', 'update_my_store_member_profile',
        'event_type', 'self_profile_update',
        'changed_fields', to_jsonb(v_changed_fields)
      ),
      now(),
      now()
    );
  END IF;

  RETURN QUERY
  SELECT
    v_updated.id,
    v_updated.store_id,
    v_updated.user_id,
    v_updated.internal_alias,
    v_updated.member_email,
    v_updated.member_phone,
    v_updated.member_mobile_phone,
    v_updated.member_whatsapp_phone,
    v_updated.member_zip_code,
    v_updated.member_address,
    v_updated.member_address_number,
    v_updated.member_complement,
    v_updated.member_district,
    v_updated.member_city,
    v_updated.member_state,
    v_updated.member_additional_info,
    v_updated.updated_at;
END;
$$;


ALTER FUNCTION "public"."update_my_store_member_profile"("p_store_id" "uuid", "p_internal_alias" "text", "p_member_email" "text", "p_member_phone" "text", "p_member_mobile_phone" "text", "p_member_whatsapp_phone" "text", "p_member_zip_code" "text", "p_member_address" "text", "p_member_address_number" "text", "p_member_complement" "text", "p_member_district" "text", "p_member_city" "text", "p_member_state" "text", "p_member_additional_info" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_stock_rules"("p_store_id" "uuid", "p_product_id" "uuid", "p_min_stock" numeric, "p_max_stock" numeric, "p_rules" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rule jsonb;
  v_location_id uuid;
  v_total_min_percent numeric := 0;
  v_total_max_percent numeric := 0;
BEGIN
  IF p_store_id IS NULL OR p_product_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_parameters');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF p_min_stock IS NULL OR p_min_stock < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_min_stock');
  END IF;

  IF p_max_stock IS NULL OR p_max_stock < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_max_stock');
  END IF;

  IF p_max_stock < p_min_stock THEN
    RETURN jsonb_build_object('ok', false, 'error', 'max_less_than_min');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.products p
    WHERE p.id = p_product_id
      AND p.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'product_not_found');
  END IF;

  IF jsonb_typeof(COALESCE(p_rules, '[]'::jsonb)) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_rules_payload');
  END IF;

  SELECT
    COALESCE(SUM(COALESCE((rule_item->>'min_percent')::numeric, 0)), 0),
    COALESCE(SUM(COALESCE((rule_item->>'max_percent')::numeric, 0)), 0)
  INTO v_total_min_percent, v_total_max_percent
  FROM jsonb_array_elements(COALESCE(p_rules, '[]'::jsonb)) rule_item;

  IF v_total_min_percent > 100.5 OR v_total_max_percent > 100.5 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'percent_over_100',
      'message', 'A soma dos percentuais não deve ultrapassar 100%.'
    );
  END IF;

  UPDATE public.products
  SET
    min_stock = p_min_stock::integer,
    max_stock = p_max_stock::integer
  WHERE id = p_product_id
    AND store_id = p_store_id;

  FOR v_rule IN
    SELECT value FROM jsonb_array_elements(COALESCE(p_rules, '[]'::jsonb))
  LOOP
    v_location_id := (v_rule->>'location_id')::uuid;

    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_locations sl
      WHERE sl.id = v_location_id
        AND sl.store_id = p_store_id
        AND sl.active = true
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'invalid_location',
        'location_id', v_location_id
      );
    END IF;

    INSERT INTO public.product_stock_location_rules (
      store_id,
      product_id,
      location_id,
      min_stock,
      max_stock,
      min_percent,
      max_percent,
      use_percentage,
      active
    )
    VALUES (
      p_store_id,
      p_product_id,
      v_location_id,
      NULLIF(v_rule->>'min_stock', '')::numeric,
      NULLIF(v_rule->>'max_stock', '')::numeric,
      NULLIF(v_rule->>'min_percent', '')::numeric,
      NULLIF(v_rule->>'max_percent', '')::numeric,
      COALESCE((v_rule->>'use_percentage')::boolean, true),
      COALESCE((v_rule->>'active')::boolean, true)
    )
    ON CONFLICT (store_id, product_id, location_id)
    DO UPDATE SET
      min_stock = EXCLUDED.min_stock,
      max_stock = EXCLUDED.max_stock,
      min_percent = EXCLUDED.min_percent,
      max_percent = EXCLUDED.max_percent,
      use_percentage = EXCLUDED.use_percentage,
      active = EXCLUDED.active,
      updated_at = now();
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'product_id', p_product_id,
    'min_stock', p_min_stock,
    'max_stock', p_max_stock
  );
END;
$$;


ALTER FUNCTION "public"."update_product_stock_rules"("p_store_id" "uuid", "p_product_id" "uuid", "p_min_stock" numeric, "p_max_stock" numeric, "p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_purchase_quotation_response"("p_quotation_id" "uuid", "p_items" "jsonb", "p_status" "text" DEFAULT 'answered'::"text", "p_sent_channel" "text" DEFAULT NULL::"text", "p_responsible_name" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("quotation_id" "uuid", "status" "text", "items_count" integer, "total_quoted" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quotation record;
  v_item jsonb;
  v_item_id uuid;
  v_items_count integer := 0;
  v_total_quoted numeric := 0;
  v_effective_channel text;
  v_effective_responsible text;
BEGIN
  SELECT
    q.id,
    q.store_id,
    q.supplier_id,
    q.quotation_code,
    q.status,
    q.sent_channel,
    q.responsible_name,
    q.notes
  INTO v_quotation
  FROM public.purchase_quotations q
  WHERE q.id = p_quotation_id
  FOR UPDATE;

  IF v_quotation.id IS NULL THEN
    RAISE EXCEPTION 'Cotação não encontrada.';
  END IF;

  IF NOT public.user_can_purchase_action(v_quotation.store_id, 'manage_quotation') THEN
    RAISE EXCEPTION 'Sem permissão para alterar cotações nesta loja.';
  END IF;

  IF v_quotation.status = 'converted' THEN
    RAISE EXCEPTION 'Cotação convertida não pode ser alterada.';
  END IF;

  IF p_status NOT IN ('draft', 'sent', 'answered', 'approved', 'rejected', 'cancelled') THEN
    RAISE EXCEPTION 'Status inválido para cotação.';
  END IF;

  IF v_quotation.status <> 'draft' AND p_status = 'draft' THEN
    RAISE EXCEPTION 'Cotação que já saiu de rascunho não pode voltar para rascunho.';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'Itens da cotação inválidos.';
  END IF;

  v_effective_channel := COALESCE(NULLIF(p_sent_channel, ''), v_quotation.sent_channel);
  v_effective_responsible := COALESCE(NULLIF(p_responsible_name, ''), v_quotation.responsible_name);

  FOR v_item IN
    SELECT value
    FROM jsonb_array_elements(p_items)
  LOOP
    v_item_id := (v_item->>'id')::uuid;

    IF v_item_id IS NULL THEN
      RAISE EXCEPTION 'Item da cotação sem ID.';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.purchase_quotation_items qi
      WHERE qi.id = v_item_id
        AND qi.quotation_id = p_quotation_id
        AND qi.store_id = v_quotation.store_id
    ) THEN
      RAISE EXCEPTION 'Item da cotação não encontrado ou sem permissão.';
    END IF;

    UPDATE public.purchase_quotation_items qi
    SET
      quoted_unit_cost = NULLIF(v_item->>'quoted_unit_cost', '')::numeric,
      approved_qty = COALESCE(
        NULLIF(v_item->>'approved_qty', '')::numeric,
        qi.requested_qty
      ),
      supplier_notes = NULLIF(v_item->>'supplier_notes', ''),
      updated_at = now()
    WHERE qi.id = v_item_id;

    v_items_count := v_items_count + 1;

    v_total_quoted := v_total_quoted + (
      COALESCE(NULLIF(v_item->>'approved_qty', '')::numeric, 0)
      *
      COALESCE(NULLIF(v_item->>'quoted_unit_cost', '')::numeric, 0)
    );
  END LOOP;

  UPDATE public.purchase_quotations q
  SET
    status = p_status,
    responded_at = CASE
      WHEN p_status IN ('answered', 'approved', 'rejected') THEN now()
      ELSE q.responded_at
    END,
    sent_channel = v_effective_channel,
    responsible_name = v_effective_responsible,
    notes = COALESCE(NULLIF(p_notes, ''), q.notes),
    updated_at = now()
  WHERE q.id = p_quotation_id;

  IF NULLIF(p_sent_channel, '') IS NOT NULL
     AND p_sent_channel IS DISTINCT FROM v_quotation.sent_channel THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_quotation.store_id,
      p_entity_type := 'purchase_quotation',
      p_entity_id := p_quotation_id,
      p_event_type := 'quotation_channel_changed',
      p_title := 'Canal da cotação alterado',
      p_description := 'Canal da cotação ' || v_quotation.quotation_code || ' alterado.',
      p_severity := 'info',
      p_status := 'done',
      p_responsible_name := v_effective_responsible,
      p_channel := p_sent_channel,
      p_source := 'update_purchase_quotation_response',
      p_source_id := p_quotation_id,
      p_old_data := jsonb_build_object('sent_channel', v_quotation.sent_channel),
      p_new_data := jsonb_build_object('sent_channel', p_sent_channel),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-B',
        'quotation_code', v_quotation.quotation_code
      ),
      p_related_supplier_id := v_quotation.supplier_id,
      p_related_purchase_quotation_id := p_quotation_id
    );
  END IF;

  IF NULLIF(p_responsible_name, '') IS NOT NULL
     AND p_responsible_name IS DISTINCT FROM v_quotation.responsible_name THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_quotation.store_id,
      p_entity_type := 'purchase_quotation',
      p_entity_id := p_quotation_id,
      p_event_type := 'quotation_responsible_changed',
      p_title := 'Responsável da cotação alterado',
      p_description := 'Responsável da cotação ' || v_quotation.quotation_code || ' alterado.',
      p_severity := 'info',
      p_status := 'done',
      p_responsible_name := p_responsible_name,
      p_channel := COALESCE(v_effective_channel, 'system'),
      p_source := 'update_purchase_quotation_response',
      p_source_id := p_quotation_id,
      p_old_data := jsonb_build_object('responsible_name', v_quotation.responsible_name),
      p_new_data := jsonb_build_object('responsible_name', p_responsible_name),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-B',
        'quotation_code', v_quotation.quotation_code
      ),
      p_related_supplier_id := v_quotation.supplier_id,
      p_related_purchase_quotation_id := p_quotation_id
    );
  END IF;

  IF p_status IS DISTINCT FROM v_quotation.status THEN
    PERFORM public.create_operational_timeline_event(
      p_store_id := v_quotation.store_id,
      p_entity_type := 'purchase_quotation',
      p_entity_id := p_quotation_id,
      p_event_type := CASE
        WHEN p_status = 'sent' THEN 'quotation_sent'
        WHEN p_status = 'answered' THEN 'supplier_answered'
        WHEN p_status = 'approved' THEN 'quotation_approved'
        WHEN p_status = 'rejected' THEN 'quotation_rejected'
        WHEN p_status = 'cancelled' THEN 'quotation_cancelled'
        ELSE 'quotation_status_changed'
      END,
      p_title := CASE
        WHEN p_status = 'sent' THEN 'Cotação enviada'
        WHEN p_status = 'answered' THEN 'Fornecedor respondeu'
        WHEN p_status = 'approved' THEN 'Cotação aprovada'
        WHEN p_status = 'rejected' THEN 'Cotação rejeitada'
        WHEN p_status = 'cancelled' THEN 'Cotação cancelada'
        ELSE 'Status da cotação alterado'
      END,
      p_description := 'Cotação ' || v_quotation.quotation_code || ' alterada para ' || p_status || '.',
      p_severity := CASE
        WHEN p_status IN ('answered', 'approved') THEN 'success'
        WHEN p_status IN ('rejected', 'cancelled') THEN 'warning'
        ELSE 'info'
      END,
      p_status := CASE
        WHEN p_status = 'cancelled' THEN 'cancelled'
        ELSE 'done'
      END,
      p_responsible_name := v_effective_responsible,
      p_channel := COALESCE(v_effective_channel, 'manual'),
      p_source := 'update_purchase_quotation_response',
      p_source_id := p_quotation_id,
      p_old_data := jsonb_build_object('status', v_quotation.status),
      p_new_data := jsonb_build_object(
        'status', p_status,
        'items_count', v_items_count,
        'total_quoted', v_total_quoted,
        'notes', COALESCE(NULLIF(p_notes, ''), v_quotation.notes)
      ),
      p_metadata := jsonb_build_object(
        'phase', '9.3C.6-B',
        'quotation_code', v_quotation.quotation_code
      ),
      p_related_supplier_id := v_quotation.supplier_id,
      p_related_purchase_quotation_id := p_quotation_id
    );
  END IF;

  RETURN QUERY
  SELECT
    p_quotation_id,
    p_status,
    v_items_count,
    v_total_quoted;
END;
$$;


ALTER FUNCTION "public"."update_purchase_quotation_response"("p_quotation_id" "uuid", "p_items" "jsonb", "p_status" "text", "p_sent_channel" "text", "p_responsible_name" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_purchase_quotation_response"("p_quotation_id" "uuid", "p_items" "jsonb", "p_status" "text", "p_sent_channel" "text", "p_responsible_name" "text", "p_notes" "text") IS 'Atualiza preços, quantidades aprovadas, canal, responsável e status de uma cotação de compra.';



CREATE OR REPLACE FUNCTION "public"."update_security_log_member_visibility"("p_log_id" "uuid", "p_visible_to_member" boolean, "p_sensitive" boolean DEFAULT NULL::boolean) RETURNS TABLE("id" "uuid", "sensitive" boolean, "visible_to_member" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_store_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  select l.store_id
  into v_store_id
  from public.store_security_logs l
  where l.id = p_log_id;

  if v_store_id is null then
    raise exception 'Log não encontrado.';
  end if;

  if not (
    public.app_is_store_owner(v_store_id)
    or public.user_has_store_permission(v_store_id, 'security.logs.manage')
    or public.user_has_store_permission(v_store_id, 'security.manage')
  ) then
    raise exception 'Você não tem permissão para alterar a visibilidade deste log.';
  end if;

  update public.store_security_logs l
  set
    visible_to_member = coalesce(p_visible_to_member, l.visible_to_member),
    sensitive = coalesce(p_sensitive, l.sensitive)
  where l.id = p_log_id;

  return query
  select
    l.id,
    l.sensitive,
    l.visible_to_member,
    now() as updated_at
  from public.store_security_logs l
  where l.id = p_log_id;
end;
$$;


ALTER FUNCTION "public"."update_security_log_member_visibility"("p_log_id" "uuid", "p_visible_to_member" boolean, "p_sensitive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_commercial_settings"("p_store_id" "uuid", "p_public_store_enabled" boolean, "p_public_catalog_enabled" boolean, "p_slug" "text", "p_minimum_order_value" numeric, "p_reservation_time_minutes" integer, "p_public_sales_location_id" "uuid", "p_whatsapp_business" "text" DEFAULT NULL::"text", "p_main_email" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_social_media" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug_result jsonb;
  v_slug text;
  v_contacts jsonb;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF p_minimum_order_value IS NULL OR p_minimum_order_value < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_minimum_order_value');
  END IF;

  IF p_reservation_time_minutes IS NULL
     OR p_reservation_time_minutes < 1
     OR p_reservation_time_minutes > 240 THEN
    RETURN jsonb_build_object(
      'ok',
      false,
      'error',
      'invalid_reservation_time',
      'message',
      'O tempo de reserva deve ficar entre 1 e 240 minutos.'
    );
  END IF;

  v_slug_result := public.validate_store_slug(p_store_id, p_slug);

  IF COALESCE((v_slug_result->>'ok')::boolean, false) = false THEN
    RETURN v_slug_result;
  END IF;

  v_slug := v_slug_result->>'slug';

  IF p_public_sales_location_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_locations sl
      WHERE sl.id = p_public_sales_location_id
        AND sl.store_id = p_store_id
        AND sl.active = true
    ) THEN
      RETURN jsonb_build_object(
        'ok',
        false,
        'error',
        'invalid_public_sales_location'
      );
    END IF;
  END IF;

  SELECT COALESCE(s.contacts, '{}'::jsonb)
  INTO v_contacts
  FROM public.stores s
  WHERE s.id = p_store_id;

  v_contacts :=
    COALESCE(v_contacts, '{}'::jsonb)
    || jsonb_build_object(
      'whatsapp_business', regexp_replace(COALESCE(p_whatsapp_business, ''), '\D', '', 'g'),
      'main_email', COALESCE(p_main_email, ''),
      'website', COALESCE(p_website, ''),
      'social_media', COALESCE(p_social_media, '')
    );

  UPDATE public.stores
  SET
    slug = v_slug,
    public_store_enabled = COALESCE(p_public_store_enabled, false),
    public_catalog_enabled = COALESCE(p_public_catalog_enabled, false),
    minimum_order_value = p_minimum_order_value,
    reservation_time_minutes = p_reservation_time_minutes,
    public_sales_location_id = p_public_sales_location_id,
    contacts = v_contacts,
    commercial_config = COALESCE(commercial_config, '{}'::jsonb) || jsonb_build_object(
      'commercial_settings_updated_at', now()
    )
  WHERE id = p_store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'store', jsonb_build_object(
      'id', p_store_id,
      'slug', v_slug,
      'public_store_enabled', p_public_store_enabled,
      'public_catalog_enabled', p_public_catalog_enabled,
      'minimum_order_value', p_minimum_order_value,
      'reservation_time_minutes', p_reservation_time_minutes,
      'public_sales_location_id', p_public_sales_location_id,
      'contacts', v_contacts
    )
  );
END;
$$;


