CREATE OR REPLACE FUNCTION "public"."update_store_config_admin"("p_store_id" "uuid", "p_config" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stores s
    WHERE s.id = p_store_id
      AND s.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Você não tem permissão para alterar esta loja';
  END IF;

  UPDATE public.stores
  SET config = COALESCE(p_config, '{}'::jsonb)
  WHERE id = p_store_id
    AND user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Store not found';
  END IF;
END;
$$;


