CREATE OR REPLACE FUNCTION "public"."update_store_custom_role"("p_custom_role_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_base_role" "text" DEFAULT NULL::"text", "p_active" boolean DEFAULT true, "p_permissions" "jsonb" DEFAULT '{}'::"jsonb", "p_sensitive_actions" "jsonb" DEFAULT '{}'::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "store_id" "uuid", "name" "text", "description" "text", "base_role" "text", "active" boolean, "permissions" "jsonb", "sensitive_actions" "jsonb", "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_role public.store_custom_roles%rowtype;
  v_actor_name text;
  v_actor_email text;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  select scr.*
  into v_role
  from public.store_custom_roles scr
  where scr.id = p_custom_role_id
  for update;

  if not found then
    raise exception 'Função personalizada não encontrada.';
  end if;

  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'Nome da função não informado.';
  end if;

  if coalesce(p_base_role, v_role.base_role) not in (
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) then
    raise exception 'Papel base inválido: %', p_base_role;
  end if;

  if not (
    public.app_is_store_owner(v_role.store_id)
    or public.user_has_store_permission(v_role.store_id, 'security.custom_roles.manage')
  ) then
    raise exception 'Sem permissão para alterar funções personalizadas.';
  end if;

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_actor_name,
    v_actor_email
  from public.get_user_display_identity(auth.uid()) as identity_row;

  update public.store_custom_roles scr
  set
    name = trim(p_name),
    description = nullif(trim(coalesce(p_description, '')), ''),
    base_role = coalesce(p_base_role, scr.base_role),
    active = coalesce(p_active, scr.active),
    permissions = coalesce(p_permissions, '{}'::jsonb),
    sensitive_actions = coalesce(p_sensitive_actions, '{}'::jsonb),
    updated_at = now()
  where scr.id = p_custom_role_id;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  values (
    v_role.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_custom_role_updated',
    jsonb_build_object(
      'custom_role_id', p_custom_role_id,
      'old_name', v_role.name,
      'new_name', trim(p_name),
      'old_base_role', v_role.base_role,
      'new_base_role', coalesce(p_base_role, v_role.base_role),
      'old_active', v_role.active,
      'new_active', coalesce(p_active, v_role.active),
      'old_permissions', v_role.permissions,
      'new_permissions', coalesce(p_permissions, '{}'::jsonb),
      'old_sensitive_actions', v_role.sensitive_actions,
      'new_sensitive_actions', coalesce(p_sensitive_actions, '{}'::jsonb),
      'reason', p_reason
    ),
    'success',
    now()
  );

  return query
  select
    scr.id,
    scr.store_id,
    scr.name,
    scr.description,
    scr.base_role,
    scr.active,
    scr.permissions,
    scr.sensitive_actions,
    scr.created_by,
    scr.created_at,
    scr.updated_at
  from public.store_custom_roles scr
  where scr.id = p_custom_role_id;
end;
$$;


ALTER FUNCTION "public"."update_store_custom_role"("p_custom_role_id" "uuid", "p_name" "text", "p_description" "text", "p_base_role" "text", "p_active" boolean, "p_permissions" "jsonb", "p_sensitive_actions" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_identity_settings"("p_store_id" "uuid", "p_name" "text", "p_slug" "text", "p_description" "text", "p_logo_url" "text", "p_phone_number" "text", "p_legal_name" "text", "p_doc_type" "text", "p_document" "text", "p_fantasy_name" "text", "p_establishment_type" "text", "p_address" "jsonb", "p_contacts" "jsonb", "p_consents" "jsonb", "p_privacy_policy_text" "text", "p_terms_of_use_text" "text", "p_cookie_policy_text" "text", "p_dpo_email" "text", "p_dpo_contact" "text") RETURNS TABLE("store_id" "uuid", "name" "text", "slug" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_slug text;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if not public.can_access_settings_section(p_store_id, 'store', true) then
    raise exception 'Você não tem permissão para editar dados da loja.';
  end if;

  v_slug := lower(trim(coalesce(p_slug, '')));

  if v_slug = '' then
    raise exception 'Slug não informado.';
  end if;

  if exists (
    select 1
    from public.stores s
    where s.slug = v_slug
      and s.id <> p_store_id
  ) then
    raise exception 'Este slug já está em uso por outra loja.';
  end if;

  update public.stores s
  set
    name = nullif(trim(coalesce(p_name, '')), ''),
    slug = v_slug,
    description = nullif(trim(coalesce(p_description, '')), ''),
    logo_url = nullif(trim(coalesce(p_logo_url, '')), ''),
    phone_number = nullif(trim(coalesce(p_phone_number, '')), ''),

    legal_name = nullif(trim(coalesce(p_legal_name, '')), ''),
    doc_type = nullif(trim(coalesce(p_doc_type, '')), ''),
    document = nullif(trim(coalesce(p_document, '')), ''),
    fantasy_name = nullif(trim(coalesce(p_fantasy_name, '')), ''),
    establishment_type = nullif(trim(coalesce(p_establishment_type, '')), ''),

    address = coalesce(p_address, '{}'::jsonb),
    contacts = coalesce(p_contacts, '{}'::jsonb),
    consents = coalesce(p_consents, '{}'::jsonb),

    privacy_policy_text = p_privacy_policy_text,
    terms_of_use_text = p_terms_of_use_text,
    cookie_policy_text = p_cookie_policy_text,
    dpo_email = nullif(trim(coalesce(p_dpo_email, '')), ''),
    dpo_contact = nullif(trim(coalesce(p_dpo_contact, '')), '')
  where s.id = p_store_id;

  return query
  select
    s.id,
    s.name,
    s.slug,
    now() as updated_at
  from public.stores s
  where s.id = p_store_id;
end;
$$;


ALTER FUNCTION "public"."update_store_identity_settings"("p_store_id" "uuid", "p_name" "text", "p_slug" "text", "p_description" "text", "p_logo_url" "text", "p_phone_number" "text", "p_legal_name" "text", "p_doc_type" "text", "p_document" "text", "p_fantasy_name" "text", "p_establishment_type" "text", "p_address" "jsonb", "p_contacts" "jsonb", "p_consents" "jsonb", "p_privacy_policy_text" "text", "p_terms_of_use_text" "text", "p_cookie_policy_text" "text", "p_dpo_email" "text", "p_dpo_contact" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_idle_timeout_settings"("p_store_id" "uuid", "p_idle_timeout_enabled" boolean, "p_idle_timeout_minutes" integer) RETURNS TABLE("store_id" "uuid", "idle_timeout_enabled" boolean, "idle_timeout_minutes" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_actor_name text;
  v_actor_email text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.user_has_store_permission(p_store_id, 'security.sessions.manage')
    or public.user_has_store_permission(p_store_id, 'security.manage')
  ) then
    raise exception 'Você não tem permissão para alterar configurações de sessão.';
  end if;

  if p_idle_timeout_minutes not in (15, 20, 25, 30, 35, 40, 45) then
    raise exception 'O tempo de inatividade deve ser entre 15 e 45 minutos, em intervalos de 5 minutos.';
  end if;

  insert into public.store_security_settings as sss (
    store_id,
    idle_timeout_enabled,
    idle_timeout_minutes,
    updated_at
  )
  values (
    p_store_id,
    coalesce(p_idle_timeout_enabled, true),
    p_idle_timeout_minutes,
    now()
  )
  on conflict on constraint store_security_settings_pkey
  do update set
    idle_timeout_enabled = excluded.idle_timeout_enabled,
    idle_timeout_minutes = excluded.idle_timeout_minutes,
    updated_at = now();

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_actor_name,
    v_actor_email
  from public.get_user_display_identity(v_user_id) as identity_row;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    display_action,
    details,
    outcome,
    sensitive,
    visible_to_member,
    created_at
  )
  values (
    p_store_id,
    v_user_id,
    v_actor_name,
    v_actor_email,
    'store_idle_timeout_settings_updated',
    public.translate_security_action_ptbr('store_idle_timeout_settings_updated'),
    jsonb_build_object(
      'idle_timeout_enabled', coalesce(p_idle_timeout_enabled, true),
      'idle_timeout_minutes', p_idle_timeout_minutes
    ),
    'success',
    true,
    false,
    now()
  );

  return query
  select
    sss.store_id,
    sss.idle_timeout_enabled,
    sss.idle_timeout_minutes,
    sss.updated_at
  from public.store_security_settings as sss
  where sss.store_id = p_store_id;
end;
$$;


ALTER FUNCTION "public"."update_store_idle_timeout_settings"("p_store_id" "uuid", "p_idle_timeout_enabled" boolean, "p_idle_timeout_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_member_avatar_url"("p_member_id" "uuid", "p_avatar_url" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "avatar_url" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_next_avatar_url text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members
  WHERE id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  IF NOT (
    v_member.user_id = auth.uid()
    OR public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar o avatar deste usuário.';
  END IF;

  v_next_avatar_url := NULLIF(trim(COALESCE(p_avatar_url, '')), '');

  INSERT INTO public.profiles (
    id,
    avatar_url,
    updated_at
  )
  VALUES (
    v_member.user_id,
    v_next_avatar_url,
    now()
  )
  ON CONFLICT (id)
  DO UPDATE SET
    avatar_url = EXCLUDED.avatar_url,
    updated_at = now();

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_member_avatar_updated',
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'avatar_url', v_next_avatar_url,
      'reason', p_reason
    ),
    'success',
    now()
  );

  RETURN QUERY
  SELECT
    v_member.id AS member_id,
    v_member.store_id,
    v_member.user_id,
    p.avatar_url,
    p.updated_at
  FROM public.profiles p
  WHERE p.id = v_member.user_id;
END;
$$;


ALTER FUNCTION "public"."update_store_member_avatar_url"("p_member_id" "uuid", "p_avatar_url" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_member_permissions"("p_member_id" "uuid", "p_permissions" "jsonb", "p_sensitive_actions" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "permissions" "jsonb", "sensitive_actions" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_member public.store_members%rowtype;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_old_permissions jsonb;
  v_old_sensitive_actions jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_member_id is null then
    raise exception 'Membro não informado.';
  end if;

  select sm.*
  into v_member
  from public.store_members sm
  where sm.id = p_member_id
  for update;

  if not found then
    raise exception 'Membro não encontrado.';
  end if;

  if v_member.role = 'owner' then
    raise exception 'Não é permitido alterar permissões individuais do proprietário.';
  end if;

  if v_member.user_id = auth.uid() then
    raise exception 'Você não pode alterar suas próprias permissões individuais.';
  end if;

  if not (
    public.app_is_store_owner(v_member.store_id)
    or public.user_has_store_permission(v_member.store_id, 'security.user_permissions.manage')
  ) then
    raise exception 'Você não tem permissão para alterar permissões individuais.';
  end if;

  if p_permissions is not null
     and jsonb_typeof(p_permissions) <> 'object' then
    raise exception 'Permissões individuais devem ser um objeto JSON.';
  end if;

  if p_sensitive_actions is not null
     and jsonb_typeof(p_sensitive_actions) <> 'object' then
    raise exception 'Ações sensíveis devem ser um objeto JSON.';
  end if;

  v_old_permissions := coalesce(v_member.permissions, '{}'::jsonb);
  v_old_sensitive_actions := coalesce(v_member.sensitive_actions, '{}'::jsonb);

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_actor_name,
    v_actor_email
  from public.get_user_display_identity(auth.uid()) as identity_row;

  select
    identity_row.user_name,
    identity_row.user_email
  into
    v_target_name,
    v_target_email
  from public.get_user_display_identity(v_member.user_id) as identity_row;

  update public.store_members sm
  set
    permissions = coalesce(p_permissions, '{}'::jsonb),
    sensitive_actions = coalesce(
      p_sensitive_actions,
      sm.sensitive_actions,
      '{}'::jsonb
    ),
    updated_at = now()
  where sm.id = p_member_id;

  insert into public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  values (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_member_permissions_updated',
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'role', v_member.role,
      'custom_role_id', v_member.custom_role_id,
      'old_permissions', v_old_permissions,
      'new_permissions', coalesce(p_permissions, '{}'::jsonb),
      'old_sensitive_actions', v_old_sensitive_actions,
      'new_sensitive_actions', coalesce(
        p_sensitive_actions,
        v_old_sensitive_actions,
        '{}'::jsonb
      ),
      'reason', p_reason
    ),
    'success',
    now()
  );

  return query
  select
    sm.id,
    coalesce(sm.permissions, '{}'::jsonb),
    coalesce(sm.sensitive_actions, '{}'::jsonb),
    sm.updated_at
  from public.store_members sm
  where sm.id = p_member_id;
end;
$$;


ALTER FUNCTION "public"."update_store_member_permissions"("p_member_id" "uuid", "p_permissions" "jsonb", "p_sensitive_actions" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_member_profile_details"("p_member_id" "uuid", "p_profile_name" "text" DEFAULT NULL::"text", "p_profile_phone" "text" DEFAULT NULL::"text", "p_profile_mobile_phone" "text" DEFAULT NULL::"text", "p_profile_whatsapp_phone" "text" DEFAULT NULL::"text", "p_profile_cpf" "text" DEFAULT NULL::"text", "p_profile_birthdate" "date" DEFAULT NULL::"date", "p_profile_zip_code" "text" DEFAULT NULL::"text", "p_profile_address" "text" DEFAULT NULL::"text", "p_profile_address_number" "text" DEFAULT NULL::"text", "p_profile_complement" "text" DEFAULT NULL::"text", "p_profile_district" "text" DEFAULT NULL::"text", "p_profile_city" "text" DEFAULT NULL::"text", "p_profile_state" "text" DEFAULT NULL::"text", "p_profile_instagram_url" "text" DEFAULT NULL::"text", "p_profile_facebook_url" "text" DEFAULT NULL::"text", "p_profile_website_url" "text" DEFAULT NULL::"text", "p_internal_alias" "text" DEFAULT NULL::"text", "p_job_title" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_internal_notes" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "profile_name" "text", "profile_phone" "text", "profile_mobile_phone" "text", "profile_whatsapp_phone" "text", "profile_cpf" "text", "profile_birthdate" "date", "profile_zip_code" "text", "profile_address" "text", "profile_address_number" "text", "profile_complement" "text", "profile_district" "text", "profile_city" "text", "profile_state" "text", "profile_instagram_url" "text", "profile_facebook_url" "text", "profile_website_url" "text", "internal_alias" "text", "job_title" "text", "department" "text", "internal_notes" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_old_profile jsonb;
  v_old_member jsonb;
  v_can_manage_sensitive boolean := false;
  v_can_view_sensitive boolean := false;
  v_sensitive_payload_requested boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT sm.*
  INTO v_member
  FROM public.store_members sm
  WHERE sm.id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  IF NOT (
    v_member.user_id = auth.uid()
    OR public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar os dados deste usuário.';
  END IF;

  v_can_manage_sensitive :=
    public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.sensitive.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage');

  v_can_view_sensitive :=
    v_can_manage_sensitive
    OR public.user_has_store_permission(v_member.store_id, 'users.sensitive.view');

  v_sensitive_payload_requested :=
    p_profile_cpf IS NOT NULL
    OR p_profile_birthdate IS NOT NULL
    OR p_profile_zip_code IS NOT NULL
    OR p_profile_address IS NOT NULL
    OR p_profile_address_number IS NOT NULL
    OR p_profile_complement IS NOT NULL
    OR p_profile_district IS NOT NULL
    OR p_profile_city IS NOT NULL
    OR p_profile_state IS NOT NULL
    OR p_internal_notes IS NOT NULL;

  IF v_sensitive_payload_requested AND NOT v_can_manage_sensitive THEN
    RAISE EXCEPTION 'Sem permissão para alterar dados sensíveis deste usuário.';
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  SELECT jsonb_build_object(
    'name', p.name,
    'phone', p.phone,
    'mobile_phone', p.mobile_phone,
    'whatsapp_phone', p.whatsapp_phone,
    'cpf', p.cpf,
    'birthdata', p.birthdata,
    'zip_code', p.zip_code,
    'address', p.address,
    'address_number', p.address_number,
    'complement', p.complement,
    'district', p.district,
    'city', p.city,
    'state', p.state,
    'instagram_url', p.instagram_url,
    'facebook_url', p.facebook_url,
    'website_url', p.website_url
  )
  INTO v_old_profile
  FROM public.profiles p
  WHERE p.id = v_member.user_id;

  v_old_member := jsonb_build_object(
    'internal_alias', v_member.internal_alias,
    'job_title', v_member.job_title,
    'department', v_member.department,
    'internal_notes', v_member.internal_notes
  );

  INSERT INTO public.profiles (
    id,
    name,
    phone,
    mobile_phone,
    whatsapp_phone,
    cpf,
    birthdata,
    zip_code,
    address,
    address_number,
    complement,
    district,
    city,
    state,
    instagram_url,
    facebook_url,
    website_url,
    updated_at
  )
  VALUES (
    v_member.user_id,
    NULLIF(trim(COALESCE(p_profile_name, '')), ''),
    NULLIF(trim(COALESCE(p_profile_phone, '')), ''),
    NULLIF(trim(COALESCE(p_profile_mobile_phone, '')), ''),
    NULLIF(trim(COALESCE(p_profile_whatsapp_phone, '')), ''),
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_cpf, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN p_profile_birthdate ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_zip_code, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_address, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_address_number, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_complement, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_district, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_city, '')), '') ELSE NULL END,
    CASE WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_profile_state, '')), '') ELSE NULL END,
    NULLIF(trim(COALESCE(p_profile_instagram_url, '')), ''),
    NULLIF(trim(COALESCE(p_profile_facebook_url, '')), ''),
    NULLIF(trim(COALESCE(p_profile_website_url, '')), ''),
    now()
  )
  ON CONFLICT (id)
  DO UPDATE SET
    name = EXCLUDED.name,
    phone = EXCLUDED.phone,
    mobile_phone = EXCLUDED.mobile_phone,
    whatsapp_phone = EXCLUDED.whatsapp_phone,

    cpf = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.cpf
      ELSE public.profiles.cpf
    END,
    birthdata = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.birthdata
      ELSE public.profiles.birthdata
    END,
    zip_code = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.zip_code
      ELSE public.profiles.zip_code
    END,
    address = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.address
      ELSE public.profiles.address
    END,
    address_number = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.address_number
      ELSE public.profiles.address_number
    END,
    complement = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.complement
      ELSE public.profiles.complement
    END,
    district = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.district
      ELSE public.profiles.district
    END,
    city = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.city
      ELSE public.profiles.city
    END,
    state = CASE
      WHEN v_can_manage_sensitive THEN EXCLUDED.state
      ELSE public.profiles.state
    END,

    instagram_url = EXCLUDED.instagram_url,
    facebook_url = EXCLUDED.facebook_url,
    website_url = EXCLUDED.website_url,
    updated_at = now();

  UPDATE public.store_members sm
  SET
    internal_alias = NULLIF(trim(COALESCE(p_internal_alias, '')), ''),
    job_title = NULLIF(trim(COALESCE(p_job_title, '')), ''),
    department = NULLIF(trim(COALESCE(p_department, '')), ''),
    internal_notes = CASE
      WHEN v_can_manage_sensitive THEN NULLIF(trim(COALESCE(p_internal_notes, '')), '')
      ELSE sm.internal_notes
    END,
    updated_at = now()
  WHERE sm.id = p_member_id;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_member_profile_details_updated',
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'reason', p_reason,
      'sensitive_payload_requested', v_sensitive_payload_requested,
      'can_manage_sensitive', v_can_manage_sensitive,
      'old_profile', COALESCE(v_old_profile, '{}'::jsonb),
      'old_member_details', v_old_member,
      'new_profile', jsonb_build_object(
        'name', p_profile_name,
        'phone', p_profile_phone,
        'mobile_phone', p_profile_mobile_phone,
        'whatsapp_phone', p_profile_whatsapp_phone,
        'cpf', CASE WHEN v_can_manage_sensitive THEN p_profile_cpf ELSE '[masked]' END,
        'birthdate', CASE WHEN v_can_manage_sensitive THEN p_profile_birthdate::text ELSE '[masked]' END,
        'zip_code', CASE WHEN v_can_manage_sensitive THEN p_profile_zip_code ELSE '[masked]' END,
        'address', CASE WHEN v_can_manage_sensitive THEN p_profile_address ELSE '[masked]' END,
        'address_number', CASE WHEN v_can_manage_sensitive THEN p_profile_address_number ELSE '[masked]' END,
        'complement', CASE WHEN v_can_manage_sensitive THEN p_profile_complement ELSE '[masked]' END,
        'district', CASE WHEN v_can_manage_sensitive THEN p_profile_district ELSE '[masked]' END,
        'city', CASE WHEN v_can_manage_sensitive THEN p_profile_city ELSE '[masked]' END,
        'state', CASE WHEN v_can_manage_sensitive THEN p_profile_state ELSE '[masked]' END,
        'instagram_url', p_profile_instagram_url,
        'facebook_url', p_profile_facebook_url,
        'website_url', p_profile_website_url
      ),
      'new_member_details', jsonb_build_object(
        'internal_alias', p_internal_alias,
        'job_title', p_job_title,
        'department', p_department,
        'internal_notes', CASE WHEN v_can_manage_sensitive THEN p_internal_notes ELSE '[masked]' END
      )
    ),
    'success',
    now()
  );

  RETURN QUERY
  SELECT
    sm.id AS member_id,
    sm.store_id,
    sm.user_id,
    p.name AS profile_name,
    p.phone AS profile_phone,
    p.mobile_phone AS profile_mobile_phone,
    p.whatsapp_phone AS profile_whatsapp_phone,
    CASE WHEN v_can_view_sensitive THEN p.cpf ELSE NULL END AS profile_cpf,
    CASE WHEN v_can_view_sensitive THEN p.birthdata ELSE NULL END AS profile_birthdate,
    CASE WHEN v_can_view_sensitive THEN p.zip_code ELSE NULL END AS profile_zip_code,
    CASE WHEN v_can_view_sensitive THEN p.address ELSE NULL END AS profile_address,
    CASE WHEN v_can_view_sensitive THEN p.address_number ELSE NULL END AS profile_address_number,
    CASE WHEN v_can_view_sensitive THEN p.complement ELSE NULL END AS profile_complement,
    CASE WHEN v_can_view_sensitive THEN p.district ELSE NULL END AS profile_district,
    CASE WHEN v_can_view_sensitive THEN p.city ELSE NULL END AS profile_city,
    CASE WHEN v_can_view_sensitive THEN p.state ELSE NULL END AS profile_state,
    p.instagram_url AS profile_instagram_url,
    p.facebook_url AS profile_facebook_url,
    p.website_url AS profile_website_url,
    sm.internal_alias,
    sm.job_title,
    sm.department,
    CASE WHEN v_can_view_sensitive THEN sm.internal_notes ELSE NULL END AS internal_notes,
    sm.updated_at
  FROM public.store_members sm
  LEFT JOIN public.profiles p
    ON p.id = sm.user_id
  WHERE sm.id = p_member_id;
END;
$$;


ALTER FUNCTION "public"."update_store_member_profile_details"("p_member_id" "uuid", "p_profile_name" "text", "p_profile_phone" "text", "p_profile_mobile_phone" "text", "p_profile_whatsapp_phone" "text", "p_profile_cpf" "text", "p_profile_birthdate" "date", "p_profile_zip_code" "text", "p_profile_address" "text", "p_profile_address_number" "text", "p_profile_complement" "text", "p_profile_district" "text", "p_profile_city" "text", "p_profile_state" "text", "p_profile_instagram_url" "text", "p_profile_facebook_url" "text", "p_profile_website_url" "text", "p_internal_alias" "text", "p_job_title" "text", "p_department" "text", "p_internal_notes" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_member_role"("p_member_id" "uuid", "p_role" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "role" "text", "status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_old_role text;
  v_store_id uuid;
  v_actor_email text;
BEGIN
  IF p_role NOT IN (
    'owner',
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'viewer',
    'staff'
  ) THEN
    RAISE EXCEPTION 'Papel inválido: %', p_role;
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members
  WHERE id = p_member_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  v_store_id := v_member.store_id;
  v_old_role := v_member.role;

  IF NOT public.app_is_store_owner(v_store_id) THEN
    RAISE EXCEPTION 'Apenas o proprietário da loja pode alterar papéis de usuários.';
  END IF;

  IF v_member.user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode alterar seu próprio papel.';
  END IF;

  IF v_member.role = 'owner' AND p_role <> 'owner' THEN
    RAISE EXCEPTION 'Não é permitido rebaixar o proprietário principal por esta função.';
  END IF;

  IF p_role = 'owner' THEN
    RAISE EXCEPTION 'Promoção para owner deve ser tratada em rotina específica de transferência de titularidade.';
  END IF;

  SELECT email::text
  INTO v_actor_email
  FROM auth.users
  WHERE id = auth.uid();

  UPDATE public.store_members sm
  SET
    role = p_role,
    updated_at = now()
  WHERE sm.id = p_member_id
  RETURNING sm.id, sm.store_id, sm.user_id, sm.role, sm.status, sm.updated_at
  INTO member_id, store_id, user_id, role, status, updated_at;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_store_id,
    auth.uid(),
    v_actor_email,
    'store_member_role_updated',
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'old_role', v_old_role,
      'new_role', p_role,
      'reason', p_reason
    ),
    'success',
    now()
  );

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."update_store_member_role"("p_member_id" "uuid", "p_role" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_member_status"("p_member_id" "uuid", "p_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("member_id" "uuid", "store_id" "uuid", "user_id" "uuid", "role" "text", "status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member public.store_members%ROWTYPE;
  v_old_status text;
  v_actor_name text;
  v_actor_email text;
  v_target_name text;
  v_target_email text;
  v_event_title text;
  v_event_type text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_status NOT IN ('active', 'inactive', 'suspended', 'invited') THEN
    RAISE EXCEPTION 'Status inválido: %', p_status;
  END IF;

  SELECT *
  INTO v_member
  FROM public.store_members
  WHERE id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membro não encontrado.';
  END IF;

  v_old_status := v_member.status;

  IF NOT (
    public.app_is_store_owner(v_member.store_id)
    OR public.user_has_store_permission(v_member.store_id, 'users.manage')
    OR public.user_has_store_permission(v_member.store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar status de usuários.';
  END IF;

  IF v_member.user_id = auth.uid() AND p_status <> 'active' THEN
    RAISE EXCEPTION 'Você não pode desativar ou suspender seu próprio usuário.';
  END IF;

  IF v_member.role = 'owner' AND p_status <> 'active' THEN
    RAISE EXCEPTION 'Não é permitido desativar ou suspender o proprietário principal.';
  END IF;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_target_name,
    v_target_email
  FROM public.get_user_display_identity(v_member.user_id) AS identity_row;

  UPDATE public.store_members sm
  SET
    status = p_status,

    -- Novo ciclo somente quando o usuário estava desligado/inativo.
    -- Retorno de suspensão mantém o started_at original.
    started_at = CASE
      WHEN p_status = 'active' AND v_old_status = 'inactive' THEN now()
      ELSE sm.started_at
    END,

    -- Ao reativar, limpa ended_at.
    -- Ao inativar, grava ended_at se ainda não existir.
    -- Suspensão não encerra ciclo.
    ended_at = CASE
      WHEN p_status = 'active' THEN NULL
      WHEN p_status = 'inactive' THEN COALESCE(sm.ended_at, now())
      ELSE sm.ended_at
    END,

    -- Ao reativar, limpa motivo definitivo de saída.
    -- Suspensão mantém exit_reason, pois não é desligamento.
    exit_reason = CASE
      WHEN p_status = 'active' THEN NULL
      ELSE sm.exit_reason
    END,

    status_reason = NULLIF(trim(COALESCE(p_reason, '')), ''),
    updated_at = now()
  WHERE sm.id = p_member_id
  RETURNING
    sm.id,
    sm.store_id,
    sm.user_id,
    sm.role,
    sm.status,
    sm.updated_at
  INTO
    member_id,
    store_id,
    user_id,
    role,
    status,
    updated_at;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    v_member.store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    CASE
      WHEN p_status = 'active' AND v_old_status = 'inactive'
        THEN 'store_member_reactivated'
      WHEN p_status = 'active' AND v_old_status = 'suspended'
        THEN 'store_member_suspension_removed'
      WHEN p_status = 'suspended'
        THEN 'store_member_suspended'
      WHEN p_status = 'inactive'
        THEN 'store_member_inactivated'
      ELSE 'store_member_status_updated'
    END,
    jsonb_build_object(
      'member_id', p_member_id,
      'target_user_id', v_member.user_id,
      'target_user_name', v_target_name,
      'target_user_email', v_target_email,
      'old_status', v_old_status,
      'new_status', p_status,
      'reason', p_reason
    ),
    'success',
    now()
  );

  IF p_status = 'active' AND v_old_status <> 'active' THEN
    v_event_type := CASE
      WHEN v_old_status = 'suspended' THEN 'return_from_suspension'
      ELSE 'reactivation'
    END;

    v_event_title := CASE
      WHEN v_old_status = 'suspended' THEN 'Retorno de suspensão'
      ELSE 'Reativação de acesso'
    END;

    INSERT INTO public.store_member_occurrences (
      store_id,
      member_id,
      user_id,
      occurrence_type,
      severity,
      title,
      description,
      occurred_at,
      visible_to_member,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_member.store_id,
      p_member_id,
      v_member.user_id,
      'other',
      'info',
      v_event_title,
      COALESCE(
        NULLIF(trim(p_reason), ''),
        CASE
          WHEN v_old_status = 'suspended'
            THEN 'Suspensão removida e acesso reativado.'
          ELSE 'Usuário reativado para acesso operacional.'
        END
      ),
      now(),
      false,
      auth.uid(),
      v_actor_email,
      jsonb_build_object(
        'origin', 'update_store_member_status',
        'event_type', v_event_type,
        'old_status', v_old_status,
        'new_status', p_status
      ),
      now(),
      now()
    );
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."update_store_member_status"("p_member_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_message_settings"("p_store_id" "uuid", "p_sms_gateway_token" "text", "p_config" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stores s
    WHERE s.id = p_store_id
      AND s.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Você não tem permissão para alterar esta loja';
  END IF;

  UPDATE public.stores
  SET
    sms_gateway_token = COALESCE(p_sms_gateway_token, ''),
    config = COALESCE(p_config, '{}'::jsonb)
  WHERE id = p_store_id
    AND user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Store not found';
  END IF;
END;
$$;


