CREATE OR REPLACE FUNCTION "public"."update_store_role_permission_template"("p_store_id" "uuid", "p_role" "text", "p_permission_code" "text", "p_allowed" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("store_id" "uuid", "role" "text", "permission_code" "text", "allowed" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_role text;
  v_permission_code text;
  v_allowed boolean := coalesce(p_allowed, false);
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  v_role := case lower(trim(coalesce(p_role, '')))
    when 'administrador' then 'admin'
    when 'gerente' then 'manager'
    when 'estoque' then 'stock_operator'
    when 'operador de estoque' then 'stock_operator'
    when 'caixa' then 'cashier'
    when 'vendas' then 'sales'
    when 'equipe' then 'staff'
    when 'visualizador' then 'viewer'
    when 'proprietario' then 'owner'
    when 'proprietário' then 'owner'
    else lower(trim(coalesce(p_role, '')))
  end;

  v_permission_code := trim(coalesce(p_permission_code, ''));

  if v_role = '' then
    raise exception 'Papel não informado.';
  end if;

  if v_role not in (
    'owner',
    'admin',
    'manager',
    'stock_operator',
    'cashier',
    'sales',
    'staff',
    'viewer'
  ) then
    raise exception 'Papel inválido: %', v_role;
  end if;

  if v_permission_code = '' then
    raise exception 'Permissão não informada.';
  end if;

  if not (
    public.app_is_store_owner(p_store_id)
    or public.can_access_security_section(p_store_id, 'roles', true)
  ) then
    raise exception 'Você não tem permissão para alterar permissões por papel.';
  end if;

  if v_role = 'owner' then
    raise exception 'As permissões do proprietário são sempre totais e não podem ser alteradas.';
  end if;

  if not exists (
    select 1
    from public.store_permission_catalog c
    where c.permission_key = v_permission_code
      and c.active = true
  ) then
    raise exception 'Permissão inválida ou inativa: %', v_permission_code;
  end if;

  insert into public.store_role_permission_templates (
    store_id,
    role,
    permission_code,
    allowed,
    updated_at
  )
  values (
    p_store_id,
    v_role,
    v_permission_code,
    v_allowed,
    now()
  )
  on conflict on constraint store_role_permission_templates_unique
  do update set
    allowed = excluded.allowed,
    updated_at = now();

  begin
    perform public.insert_security_log(
      p_store_id,
      auth.uid(),
      null,
      'store_role_permission_template_updated',
      jsonb_build_object(
        'role', v_role,
        'permission_code', v_permission_code,
        'allowed', v_allowed,
        'reason', p_reason
      ),
      'success'
    );
  exception
    when others then
      null;
  end;

  return query
  select
    t.store_id,
    t.role,
    t.permission_code,
    t.allowed,
    t.updated_at
  from public.store_role_permission_templates t
  where t.store_id = p_store_id
    and t.role = v_role
    and t.permission_code = v_permission_code;
end;
$$;


ALTER FUNCTION "public"."update_store_role_permission_template"("p_store_id" "uuid", "p_role" "text", "p_permission_code" "text", "p_allowed" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_sensitive_action_rule"("p_store_id" "uuid", "p_action_code" "text", "p_enabled" boolean, "p_requirement" "text", "p_min_role" "text", "p_token_enabled" boolean DEFAULT false, "p_token_expiry_seconds" integer DEFAULT 15, "p_max_attempts" integer DEFAULT 3, "p_require_reason" boolean DEFAULT true, "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("store_id" "uuid", "action_code" "text", "enabled" boolean, "requirement" "text", "min_role" "text", "token_enabled" boolean, "token_expiry_seconds" integer, "max_attempts" integer, "require_reason" boolean, "source" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_old_rule jsonb;
  v_new_rule jsonb;
  v_actor_name text;
  v_actor_email text;
  v_exists boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'Loja não informada.';
  END IF;

  IF p_action_code IS NULL OR length(trim(p_action_code)) = 0 THEN
    RAISE EXCEPTION 'Ação sensível não informada.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.security_sensitive_action_catalog c
    WHERE c.code = p_action_code
      AND c.active = true
  ) THEN
    RAISE EXCEPTION 'Ação sensível inválida ou inativa: %', p_action_code;
  END IF;

  IF p_requirement NOT IN ('none', 'pin', 'token', 'pin_and_token') THEN
    RAISE EXCEPTION 'Requisito inválido: %', p_requirement;
  END IF;

  IF p_min_role NOT IN ('owner', 'admin', 'manager', 'stock_operator', 'cashier', 'sales', 'staff', 'viewer') THEN
    RAISE EXCEPTION 'Papel mínimo inválido: %', p_min_role;
  END IF;

  IF p_token_expiry_seconds IS NULL OR p_token_expiry_seconds < 5 OR p_token_expiry_seconds > 3600 THEN
    RAISE EXCEPTION 'Tempo de expiração do token deve ficar entre 5 e 3600 segundos.';
  END IF;

  IF p_max_attempts IS NULL OR p_max_attempts < 1 OR p_max_attempts > 10 THEN
    RAISE EXCEPTION 'Número máximo de tentativas deve ficar entre 1 e 10.';
  END IF;

  IF NOT (
    public.app_is_store_owner(p_store_id)
    OR public.user_has_store_permission(p_store_id, 'security.manage')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para alterar regras de ações sensíveis.';
  END IF;

  SELECT
    jsonb_build_object(
      'enabled', r.enabled,
      'requirement', r.requirement,
      'min_role', r.min_role,
      'token_enabled', r.token_enabled,
      'token_expiry_seconds', r.token_expiry_seconds,
      'max_attempts', r.max_attempts,
      'require_reason', r.require_reason,
      'source', r.source
    ),
    true
  INTO
    v_old_rule,
    v_exists
  FROM public.store_sensitive_action_rules r
  WHERE r.store_id = p_store_id
    AND r.action_code = p_action_code
  FOR UPDATE;

  SELECT
    identity_row.user_name,
    identity_row.user_email
  INTO
    v_actor_name,
    v_actor_email
  FROM public.get_user_display_identity(auth.uid()) AS identity_row;

  IF v_exists THEN
    UPDATE public.store_sensitive_action_rules r
    SET
      enabled = p_enabled,
      requirement = p_requirement,
      min_role = p_min_role,
      token_enabled = p_token_enabled,
      token_expiry_seconds = p_token_expiry_seconds,
      max_attempts = p_max_attempts,
      require_reason = p_require_reason,
      source = 'store_override',
      updated_at = now()
    WHERE r.store_id = p_store_id
      AND r.action_code = p_action_code;
  ELSE
    INSERT INTO public.store_sensitive_action_rules (
      store_id,
      action_code,
      enabled,
      requirement,
      min_role,
      token_enabled,
      token_expiry_seconds,
      max_attempts,
      require_reason,
      source,
      created_at,
      updated_at
    )
    VALUES (
      p_store_id,
      p_action_code,
      p_enabled,
      p_requirement,
      p_min_role,
      p_token_enabled,
      p_token_expiry_seconds,
      p_max_attempts,
      p_require_reason,
      'store_override',
      now(),
      now()
    );
  END IF;

  SELECT jsonb_build_object(
    'enabled', r.enabled,
    'requirement', r.requirement,
    'min_role', r.min_role,
    'token_enabled', r.token_enabled,
    'token_expiry_seconds', r.token_expiry_seconds,
    'max_attempts', r.max_attempts,
    'require_reason', r.require_reason,
    'source', r.source
  )
  INTO v_new_rule
  FROM public.store_sensitive_action_rules r
  WHERE r.store_id = p_store_id
    AND r.action_code = p_action_code;

  INSERT INTO public.store_security_logs (
    store_id,
    user_id,
    user_name,
    user_email,
    action,
    details,
    outcome,
    created_at
  )
  VALUES (
    p_store_id,
    auth.uid(),
    v_actor_name,
    v_actor_email,
    'store_sensitive_action_rule_updated',
    jsonb_build_object(
      'action_code', p_action_code,
      'old_rule', v_old_rule,
      'new_rule', v_new_rule,
      'reason', p_reason
    ),
    'success',
    now()
  );

  RETURN QUERY
  SELECT
    r.store_id,
    r.action_code,
    r.enabled,
    r.requirement,
    r.min_role,
    r.token_enabled,
    r.token_expiry_seconds,
    r.max_attempts,
    r.require_reason,
    r.source,
    r.updated_at
  FROM public.store_sensitive_action_rules r
  WHERE r.store_id = p_store_id
    AND r.action_code = p_action_code;
END;
$$;


ALTER FUNCTION "public"."update_store_sensitive_action_rule"("p_store_id" "uuid", "p_action_code" "text", "p_enabled" boolean, "p_requirement" "text", "p_min_role" "text", "p_token_enabled" boolean, "p_token_expiry_seconds" integer, "p_max_attempts" integer, "p_require_reason" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_store_settings_section"("p_store_id" "uuid", "p_section" "text", "p_settings" "jsonb") RETURNS TABLE("store_id" "uuid", "section" "text", "settings" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_settings jsonb := coalesce(p_settings, '{}'::jsonb);
begin
  if auth.uid() is null then
    raise exception 'Usuário não autenticado.';
  end if;

  if p_store_id is null then
    raise exception 'Loja não informada.';
  end if;

  if p_section not in (
    'commercial',
    'orders',
    'stock',
    'delivery',
    'payment',
    'legal',
    'system'
  ) then
    raise exception 'Seção de configuração inválida: %', p_section;
  end if;

  if not public.can_access_settings_section(p_store_id, p_section, true) then
    raise exception 'Você não tem permissão para alterar esta seção de configurações.';
  end if;

  insert into public.store_settings as ss_insert (
    store_id
  )
  values (
    p_store_id
  )
  on conflict on constraint store_settings_pkey
  do nothing;

  update public.store_settings ss
  set
    commercial_settings = case when p_section = 'commercial' then v_settings else ss.commercial_settings end,
    order_settings = case when p_section = 'orders' then v_settings else ss.order_settings end,
    stock_settings = case when p_section = 'stock' then v_settings else ss.stock_settings end,
    delivery_settings = case when p_section = 'delivery' then v_settings else ss.delivery_settings end,
    payment_settings = case when p_section = 'payment' then v_settings else ss.payment_settings end,
    legal_settings = case when p_section = 'legal' then v_settings else ss.legal_settings end,
    system_settings = case when p_section = 'system' then v_settings else ss.system_settings end,
    updated_at = now()
  where ss.store_id = p_store_id;

  return query
  select
    ss.store_id,
    p_section as section,
    case
      when p_section = 'commercial' then ss.commercial_settings
      when p_section = 'orders' then ss.order_settings
      when p_section = 'stock' then ss.stock_settings
      when p_section = 'delivery' then ss.delivery_settings
      when p_section = 'payment' then ss.payment_settings
      when p_section = 'legal' then ss.legal_settings
      when p_section = 'system' then ss.system_settings
      else '{}'::jsonb
    end as settings,
    ss.updated_at
  from public.store_settings ss
  where ss.store_id = p_store_id;
end;
$$;


ALTER FUNCTION "public"."update_store_settings_section"("p_store_id" "uuid", "p_section" "text", "p_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_supplier_operational_status"("p_supplier_id" "uuid", "p_homologation_status" "text" DEFAULT NULL::"text", "p_preferred_supplier" boolean DEFAULT NULL::boolean, "p_blocked" boolean DEFAULT NULL::boolean, "p_blocked_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("supplier_id" "uuid", "store_id" "uuid", "homologation_status" "text", "preferred_supplier" boolean, "blocked" boolean, "blocked_reason" "text", "blocked_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store_id uuid;
  v_previous_blocked boolean;
  v_new_blocked boolean;
  v_event_title text;
BEGIN
  SELECT
    s.store_id,
    s.blocked
  INTO
    v_store_id,
    v_previous_blocked
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
    AND public.is_store_member(s.store_id)
  LIMIT 1;

  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'Fornecedor não encontrado ou sem permissão.';
  END IF;

  v_new_blocked := COALESCE(p_blocked, v_previous_blocked);

  UPDATE public.suppliers s
  SET
    homologation_status = COALESCE(p_homologation_status, s.homologation_status),
    preferred_supplier = COALESCE(p_preferred_supplier, s.preferred_supplier),
    blocked = v_new_blocked,
    blocked_reason = CASE
      WHEN v_new_blocked THEN COALESCE(NULLIF(trim(COALESCE(p_blocked_reason, '')), ''), s.blocked_reason)
      ELSE NULL
    END,
    blocked_at = CASE
      WHEN v_new_blocked = true AND s.blocked = false THEN now()
      WHEN v_new_blocked = false THEN NULL
      ELSE s.blocked_at
    END,
    updated_at = now()
  WHERE s.id = p_supplier_id
    AND s.store_id = v_store_id;

  IF p_blocked IS NOT NULL AND p_blocked <> v_previous_blocked THEN
    v_event_title := CASE
      WHEN p_blocked THEN 'Fornecedor bloqueado'
      ELSE 'Fornecedor desbloqueado'
    END;

    INSERT INTO public.supplier_relationship_events (
      store_id,
      supplier_id,
      event_type,
      title,
      description,
      severity,
      status,
      created_by,
      created_by_email,
      metadata,
      created_at,
      updated_at
    )
    VALUES (
      v_store_id,
      p_supplier_id,
      CASE WHEN p_blocked THEN 'block' ELSE 'unblock' END,
      v_event_title,
      p_blocked_reason,
      CASE WHEN p_blocked THEN 'high' ELSE 'info' END,
      'done',
      auth.uid(),
      auth.email(),
      jsonb_build_object('origin', 'supplier_operational_status_update'),
      now(),
      now()
    );
  END IF;

  RETURN QUERY
  SELECT
    s.id AS supplier_id,
    s.store_id,
    s.homologation_status,
    s.preferred_supplier,
    s.blocked,
    s.blocked_reason,
    s.blocked_at
  FROM public.suppliers s
  WHERE s.id = p_supplier_id
    AND s.store_id = v_store_id;
END;
$$;


ALTER FUNCTION "public"."update_supplier_operational_status"("p_supplier_id" "uuid", "p_homologation_status" "text", "p_preferred_supplier" boolean, "p_blocked" boolean, "p_blocked_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_customer_benefit_rule_safe"("p_store_id" "uuid", "p_rule_id" "uuid" DEFAULT NULL::"uuid", "p_code" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_benefit_type" "text" DEFAULT 'discount_percent'::"text", "p_target_type" "text" DEFAULT 'all'::"text", "p_target_tier_id" "uuid" DEFAULT NULL::"uuid", "p_target_customer_id" "uuid" DEFAULT NULL::"uuid", "p_target_tag" "text" DEFAULT NULL::"text", "p_discount_percent" numeric DEFAULT NULL::numeric, "p_discount_amount" numeric DEFAULT NULL::numeric, "p_bonus_points" integer DEFAULT NULL::integer, "p_free_delivery" boolean DEFAULT false, "p_minimum_order_value" numeric DEFAULT 0, "p_max_uses_total" integer DEFAULT NULL::integer, "p_max_uses_per_customer" integer DEFAULT NULL::integer, "p_active" boolean DEFAULT true, "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_conditions" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_rule_id uuid;
  v_code text;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF length(trim(COALESCE(p_name, ''))) < 2 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_name',
      'message', 'Informe um nome para o benefício.'
    );
  END IF;

  IF p_target_type = 'tier' AND p_target_tier_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_tier',
      'message', 'Selecione um nível de fidelidade.'
    );
  END IF;

  IF p_target_type = 'customer' AND p_target_customer_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_customer',
      'message', 'Selecione um cliente.'
    );
  END IF;

  IF p_target_type = 'tag' AND length(trim(COALESCE(p_target_tag, ''))) < 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_tag',
      'message', 'Informe uma tag de cliente.'
    );
  END IF;

  IF p_target_tier_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.fidelity_tiers ft
    WHERE ft.id = p_target_tier_id
      AND ft.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_target_tier');
  END IF;

  IF p_target_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.customers c
    WHERE c.id = p_target_customer_id
      AND c.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_target_customer');
  END IF;

  v_code := lower(trim(COALESCE(p_code, '')));

  IF v_code = '' THEN
    v_code := lower(regexp_replace(trim(p_name), '[^a-zA-Z0-9]+', '_', 'g'));
    v_code := regexp_replace(v_code, '^_+|_+$', '', 'g');
  END IF;

  IF length(v_code) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_code',
      'message', 'O código do benefício precisa ter pelo menos 3 caracteres.'
    );
  END IF;

  IF p_rule_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.customer_benefit_rules br
      WHERE br.id = p_rule_id
        AND br.store_id = p_store_id
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'benefit_not_found');
    END IF;

    UPDATE public.customer_benefit_rules
    SET
      code = v_code,
      name = trim(p_name),
      description = NULLIF(trim(COALESCE(p_description, '')), ''),
      benefit_type = p_benefit_type,
      target_type = p_target_type,
      target_tier_id = CASE WHEN p_target_type = 'tier' THEN p_target_tier_id ELSE NULL END,
      target_customer_id = CASE WHEN p_target_type = 'customer' THEN p_target_customer_id ELSE NULL END,
      target_tag = CASE WHEN p_target_type = 'tag' THEN NULLIF(trim(COALESCE(p_target_tag, '')), '') ELSE NULL END,
      discount_percent = p_discount_percent,
      discount_amount = p_discount_amount,
      bonus_points = p_bonus_points,
      free_delivery = COALESCE(p_free_delivery, false),
      minimum_order_value = COALESCE(p_minimum_order_value, 0),
      max_uses_total = p_max_uses_total,
      max_uses_per_customer = p_max_uses_per_customer,
      active = COALESCE(p_active, true),
      starts_at = p_starts_at,
      ends_at = p_ends_at,
      conditions = COALESCE(p_conditions, '{}'::jsonb),
      metadata = COALESCE(metadata, '{}'::jsonb)
        || COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'last_admin_update_at', now(),
          'last_admin_update_by', auth.uid()
        ),
      updated_at = now()
    WHERE id = p_rule_id
      AND store_id = p_store_id
    RETURNING id INTO v_rule_id;
  ELSE
    INSERT INTO public.customer_benefit_rules (
      store_id,
      code,
      name,
      description,
      benefit_type,
      target_type,
      target_tier_id,
      target_customer_id,
      target_tag,
      discount_percent,
      discount_amount,
      bonus_points,
      free_delivery,
      minimum_order_value,
      max_uses_total,
      max_uses_per_customer,
      active,
      starts_at,
      ends_at,
      conditions,
      metadata
    )
    VALUES (
      p_store_id,
      v_code,
      trim(p_name),
      NULLIF(trim(COALESCE(p_description, '')), ''),
      p_benefit_type,
      p_target_type,
      CASE WHEN p_target_type = 'tier' THEN p_target_tier_id ELSE NULL END,
      CASE WHEN p_target_type = 'customer' THEN p_target_customer_id ELSE NULL END,
      CASE WHEN p_target_type = 'tag' THEN NULLIF(trim(COALESCE(p_target_tag, '')), '') ELSE NULL END,
      p_discount_percent,
      p_discount_amount,
      p_bonus_points,
      COALESCE(p_free_delivery, false),
      COALESCE(p_minimum_order_value, 0),
      p_max_uses_total,
      p_max_uses_per_customer,
      COALESCE(p_active, true),
      p_starts_at,
      p_ends_at,
      COALESCE(p_conditions, '{}'::jsonb),
      COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'created_by', auth.uid(),
          'created_by_source', 'upsert_customer_benefit_rule_safe',
          'created_at', now()
        )
    )
    RETURNING id INTO v_rule_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'benefit_rule_id', v_rule_id,
    'code', v_code
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'benefit_code_already_exists',
      'message', 'Já existe um benefício com este código.'
    );
  WHEN check_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_benefit_payload',
      'message', 'Algum campo do benefício não atende aos valores permitidos.'
    );
END;
$_$;


