CREATE OR REPLACE FUNCTION "public"."upsert_customer_segment_safe"("p_store_id" "uuid", "p_segment_id" "uuid" DEFAULT NULL::"uuid", "p_code" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_segment_type" "text" DEFAULT 'manual'::"text", "p_active" boolean DEFAULT true, "p_rules" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_segment_id uuid;
  v_code text;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF length(trim(COALESCE(p_name, ''))) < 2 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_name',
      'message', 'Informe um nome para o segmento.'
    );
  END IF;

  IF p_segment_type NOT IN (
    'manual',
    'tag',
    'loyalty_tier',
    'behavior',
    'purchase_history',
    'campaign',
    'custom'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_segment_type',
      'message', 'Tipo de segmento inválido.'
    );
  END IF;

  v_code := lower(trim(COALESCE(p_code, '')));

  IF v_code = '' THEN
    v_code := lower(regexp_replace(trim(p_name), '[^a-zA-Z0-9]+', '_', 'g'));
    v_code := regexp_replace(v_code, '^_+|_+$', '', 'g');
  END IF;

  IF length(v_code) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_code',
      'message', 'O código do segmento precisa ter pelo menos 3 caracteres.'
    );
  END IF;

  IF p_segment_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.customer_segments cs
      WHERE cs.id = p_segment_id
        AND cs.store_id = p_store_id
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'segment_not_found',
        'message', 'Segmento não encontrado.'
      );
    END IF;

    UPDATE public.customer_segments
    SET
      code = v_code,
      name = trim(p_name),
      description = NULLIF(trim(COALESCE(p_description, '')), ''),
      segment_type = p_segment_type,
      active = COALESCE(p_active, true),
      rules = COALESCE(p_rules, '{}'::jsonb),
      metadata = COALESCE(metadata, '{}'::jsonb)
        || COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'last_admin_update_at', now(),
          'last_admin_update_by', auth.uid()
        ),
      updated_at = now()
    WHERE id = p_segment_id
      AND store_id = p_store_id
    RETURNING id INTO v_segment_id;
  ELSE
    INSERT INTO public.customer_segments (
      store_id,
      code,
      name,
      description,
      segment_type,
      active,
      rules,
      metadata
    )
    VALUES (
      p_store_id,
      v_code,
      trim(p_name),
      NULLIF(trim(COALESCE(p_description, '')), ''),
      p_segment_type,
      COALESCE(p_active, true),
      COALESCE(p_rules, '{}'::jsonb),
      COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'created_by', auth.uid(),
          'created_by_source', 'upsert_customer_segment_safe',
          'created_at', now()
        )
    )
    RETURNING id INTO v_segment_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'segment_id', v_segment_id,
    'code', v_code
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'segment_code_already_exists',
      'message', 'Já existe um segmento com este código.'
    );

  WHEN check_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_segment_payload',
      'message', 'Algum campo do segmento não atende aos valores permitidos.'
    );
END;
$_$;


