CREATE OR REPLACE FUNCTION "public"."upsert_loyalty_point_rule_safe"("p_store_id" "uuid", "p_rule_id" "uuid" DEFAULT NULL::"uuid", "p_code" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_trigger_event" "text" DEFAULT 'order_completed'::"text", "p_rule_type" "text" DEFAULT 'per_currency'::"text", "p_points_mode" "text" DEFAULT 'per_currency'::"text", "p_points_value" numeric DEFAULT 1, "p_priority" integer DEFAULT 100, "p_stackable" boolean DEFAULT true, "p_active" boolean DEFAULT true, "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_conditions" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_rule_id uuid;
  v_code text;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
