    );
  END IF;

  IF p_points_value IS NULL OR p_points_value < 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_points_value',
      'message', 'O valor de pontos precisa ser maior ou igual a zero.'
    );
  END IF;

  v_code := lower(trim(COALESCE(p_code, '')));

