      'ok', false,
      'error', 'invalid_code',
      'message', 'O código da regra precisa ter pelo menos 3 caracteres.'
    );
  END IF;

  IF p_rule_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.loyalty_point_rules lpr
      WHERE lpr.id = p_rule_id
        AND lpr.store_id = p_store_id
