      points_mode = p_points_mode,
      points_value = p_points_value,
      priority = COALESCE(p_priority, 100),
      stackable = COALESCE(p_stackable, true),
      active = COALESCE(p_active, true),
      starts_at = p_starts_at,
      ends_at = p_ends_at,
      conditions = COALESCE(p_conditions, '{}'::jsonb),
      metadata = COALESCE(metadata, '{}'::jsonb)
        || COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'last_admin_update_at', now(),
          'last_admin_update_by', auth.uid()
        ),
      updated_at = now()
    WHERE id = p_rule_id
      AND store_id = p_store_id
    RETURNING id INTO v_rule_id;
  ELSE
    INSERT INTO public.loyalty_point_rules (
      store_id,
      code,
      name,
      description,
      trigger_event,
      rule_type,
      points_mode,
      points_value,
      priority,
      stackable,
      active,
      starts_at,
      ends_at,
      conditions,
      metadata
    )
    VALUES (
      p_store_id,
      v_code,
      trim(p_name),
      NULLIF(trim(COALESCE(p_description, '')), ''),
      p_trigger_event,
      p_rule_type,
      p_points_mode,
      p_points_value,
      COALESCE(p_priority, 100),
      COALESCE(p_stackable, true),
      COALESCE(p_active, true),
      p_starts_at,
      p_ends_at,
      COALESCE(p_conditions, '{}'::jsonb),
      COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'created_by', auth.uid(),
          'created_by_source', 'upsert_loyalty_point_rule_safe',
          'created_at', now()
        )
    )
    RETURNING id INTO v_rule_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'rule_id', v_rule_id,
    'code', v_code
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
