CREATE OR REPLACE FUNCTION "public"."upsert_promotion_campaign_safe"("p_store_id" "uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_code" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_campaign_type" "text" DEFAULT 'communication'::"text", "p_status" "text" DEFAULT 'draft'::"text", "p_target_type" "text" DEFAULT 'all'::"text", "p_target_segment_id" "uuid" DEFAULT NULL::"uuid", "p_target_customer_id" "uuid" DEFAULT NULL::"uuid", "p_target_tag" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT 'whatsapp'::"text", "p_title" "text" DEFAULT NULL::"text", "p_message_template" "text" DEFAULT NULL::"text", "p_call_to_action" "text" DEFAULT NULL::"text", "p_landing_url" "text" DEFAULT NULL::"text", "p_benefit_rule_id" "uuid" DEFAULT NULL::"uuid", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_active" boolean DEFAULT true, "p_conditions" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_campaign_id uuid;
  v_code text;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_store_id');
  END IF;

  IF COALESCE(auth.role(), '') IN ('anon', 'authenticated') THEN
    IF auth.uid() IS NULL OR NOT public.is_store_member(p_store_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'access_denied');
    END IF;
  END IF;

  IF length(trim(COALESCE(p_name, ''))) < 2 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_name',
      'message', 'Informe um nome para a campanha.'
    );
  END IF;

  IF p_campaign_type NOT IN (
    'communication',
    'promotion',
    'benefit',
    'reactivation',
    'birthday',
    'loyalty',
    'custom'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_campaign_type',
      'message', 'Tipo de campanha inválido.'
    );
  END IF;

  IF p_status NOT IN (
    'draft',
    'scheduled',
    'active',
    'paused',
    'completed',
    'cancelled'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_status',
      'message', 'Status de campanha inválido.'
    );
  END IF;

  IF p_target_type NOT IN (
    'all',
    'segment',
    'customer',
    'tag',
    'loyalty_tier',
    'custom'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_target_type',
      'message', 'Tipo de público-alvo inválido.'
    );
  END IF;

  IF p_channel NOT IN (
    'whatsapp',
    'email',
    'sms',
    'in_app',
    'manual',
    'mixed'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_channel',
      'message', 'Canal inválido.'
    );
  END IF;

  IF p_target_type = 'segment' AND p_target_segment_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_segment',
      'message', 'Selecione um segmento.'
    );
  END IF;

  IF p_target_type = 'customer' AND p_target_customer_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_customer',
      'message', 'Selecione um cliente.'
    );
  END IF;

  IF p_target_type = 'tag' AND length(trim(COALESCE(p_target_tag, ''))) < 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'missing_target_tag',
      'message', 'Informe uma tag.'
    );
  END IF;

  IF p_target_segment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.customer_segments cs
    WHERE cs.id = p_target_segment_id
      AND cs.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_target_segment',
      'message', 'Segmento inválido para esta loja.'
    );
  END IF;

  IF p_target_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.customers c
    WHERE c.id = p_target_customer_id
      AND c.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_target_customer',
      'message', 'Cliente inválido para esta loja.'
    );
  END IF;

  IF p_benefit_rule_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.customer_benefit_rules br
    WHERE br.id = p_benefit_rule_id
      AND br.store_id = p_store_id
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_benefit_rule',
      'message', 'Benefício inválido para esta loja.'
    );
  END IF;

  v_code := lower(trim(COALESCE(p_code, '')));

  IF v_code = '' THEN
    v_code := lower(regexp_replace(trim(p_name), '[^a-zA-Z0-9]+', '_', 'g'));
    v_code := regexp_replace(v_code, '^_+|_+$', '', 'g');
  END IF;

  IF length(v_code) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_code',
      'message', 'O código da campanha precisa ter pelo menos 3 caracteres.'
    );
  END IF;

  IF p_campaign_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.promotion_campaigns pc
      WHERE pc.id = p_campaign_id
        AND pc.store_id = p_store_id
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'campaign_not_found',
        'message', 'Campanha não encontrada.'
      );
    END IF;

    UPDATE public.promotion_campaigns
    SET
      code = v_code,
      name = trim(p_name),
      description = NULLIF(trim(COALESCE(p_description, '')), ''),
      campaign_type = p_campaign_type,
      status = p_status,
      target_type = p_target_type,
      target_segment_id = CASE WHEN p_target_type = 'segment' THEN p_target_segment_id ELSE NULL END,
      target_customer_id = CASE WHEN p_target_type = 'customer' THEN p_target_customer_id ELSE NULL END,
      target_tag = CASE WHEN p_target_type = 'tag' THEN NULLIF(trim(COALESCE(p_target_tag, '')), '') ELSE NULL END,
      channel = p_channel,
      title = NULLIF(trim(COALESCE(p_title, '')), ''),
      message_template = NULLIF(trim(COALESCE(p_message_template, '')), ''),
      call_to_action = NULLIF(trim(COALESCE(p_call_to_action, '')), ''),
      landing_url = NULLIF(trim(COALESCE(p_landing_url, '')), ''),
      benefit_rule_id = p_benefit_rule_id,
      starts_at = p_starts_at,
      ends_at = p_ends_at,
      scheduled_at = p_scheduled_at,
      active = COALESCE(p_active, true),
      conditions = COALESCE(p_conditions, '{}'::jsonb),
      metadata = COALESCE(metadata, '{}'::jsonb)
        || COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'last_admin_update_at', now(),
          'last_admin_update_by', auth.uid()
        ),
      updated_at = now()
    WHERE id = p_campaign_id
      AND store_id = p_store_id
    RETURNING id INTO v_campaign_id;
  ELSE
    INSERT INTO public.promotion_campaigns (
      store_id,
      code,
      name,
      description,
      campaign_type,
      status,
      target_type,
      target_segment_id,
      target_customer_id,
      target_tag,
      channel,
      title,
      message_template,
      call_to_action,
      landing_url,
      benefit_rule_id,
      starts_at,
      ends_at,
      scheduled_at,
      active,
      conditions,
      metadata
    )
    VALUES (
      p_store_id,
      v_code,
      trim(p_name),
      NULLIF(trim(COALESCE(p_description, '')), ''),
      p_campaign_type,
      p_status,
      p_target_type,
      CASE WHEN p_target_type = 'segment' THEN p_target_segment_id ELSE NULL END,
      CASE WHEN p_target_type = 'customer' THEN p_target_customer_id ELSE NULL END,
      CASE WHEN p_target_type = 'tag' THEN NULLIF(trim(COALESCE(p_target_tag, '')), '') ELSE NULL END,
      p_channel,
      NULLIF(trim(COALESCE(p_title, '')), ''),
      NULLIF(trim(COALESCE(p_message_template, '')), ''),
      NULLIF(trim(COALESCE(p_call_to_action, '')), ''),
      NULLIF(trim(COALESCE(p_landing_url, '')), ''),
      p_benefit_rule_id,
      p_starts_at,
      p_ends_at,
      p_scheduled_at,
      COALESCE(p_active, true),
      COALESCE(p_conditions, '{}'::jsonb),
      COALESCE(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'created_by', auth.uid(),
          'created_by_source', 'upsert_promotion_campaign_safe',
          'created_at', now()
        )
    )
    RETURNING id INTO v_campaign_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign_id', v_campaign_id,
    'code', v_code
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'campaign_code_already_exists',
      'message', 'Já existe uma campanha com este código.'
    );

  WHEN check_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_campaign_payload',
      'message', 'Algum campo da campanha não atende aos valores permitidos.'
    );
END;
$_$;


ALTER FUNCTION "public"."upsert_promotion_campaign_safe"("p_store_id" "uuid", "p_campaign_id" "uuid", "p_code" "text", "p_name" "text", "p_description" "text", "p_campaign_type" "text", "p_status" "text", "p_target_type" "text", "p_target_segment_id" "uuid", "p_target_customer_id" "uuid", "p_target_tag" "text", "p_channel" "text", "p_title" "text", "p_message_template" "text", "p_call_to_action" "text", "p_landing_url" "text", "p_benefit_rule_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_scheduled_at" timestamp with time zone, "p_active" boolean, "p_conditions" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_purchase_action"("p_store_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_permission_code text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_store_id IS NULL THEN
    RETURN false;
  END IF;

  v_permission_code :=
    CASE p_action
      WHEN 'view' THEN 'purchases.view'
      WHEN 'create' THEN 'purchases.create'
      WHEN 'confirm' THEN 'purchases.confirm'
      WHEN 'apply' THEN 'purchases.confirm'
      WHEN 'apply_stock' THEN 'purchases.confirm'
      WHEN 'cancel' THEN 'purchases.cancel'
      WHEN 'delete' THEN 'purchases.cancel'
      ELSE NULL
    END;

  IF v_permission_code IS NULL THEN
    RETURN false;
  END IF;

  RETURN public.user_has_store_permission_v2(
    p_store_id,
    v_permission_code
  );
END;
$$;


ALTER FUNCTION "public"."user_can_purchase_action"("p_store_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_store_permission"("p_store_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
BEGIN
  RETURN public.user_has_store_permission_v2(
    p_store_id,
    p_permission_code
  );
END;
$$;


ALTER FUNCTION "public"."user_has_store_permission"("p_store_id" "uuid", "p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_store_permission_v2"("p_store_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_member_id uuid;
  v_role text;
  v_custom_role_id uuid;
  v_permissions jsonb;
  v_role_allowed boolean := false;
  v_custom_role_override boolean := NULL;
  v_individual_override boolean := NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_store_id IS NULL OR p_permission_code IS NULL OR length(trim(p_permission_code)) = 0 THEN
    RETURN false;
  END IF;

  SELECT
    sm.id,
    sm.role,
    sm.custom_role_id,
    COALESCE(sm.permissions, '{}'::jsonb)
  INTO
    v_member_id,
    v_role,
    v_custom_role_id,
    v_permissions
  FROM public.store_members sm
  LEFT JOIN public.store_custom_roles scr
    ON scr.id = sm.custom_role_id
   AND scr.store_id = sm.store_id
   AND scr.active = true
  WHERE sm.store_id = p_store_id
    AND sm.user_id = auth.uid()
    AND sm.status = 'active'
  ORDER BY
    CASE WHEN sm.role = 'owner' THEN 0 ELSE 1 END,
    CASE WHEN scr.id IS NOT NULL THEN 0 ELSE 1 END,
    sm.updated_at DESC NULLS LAST,
    sm.created_at DESC NULLS LAST
  LIMIT 1;

  IF v_member_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'owner' THEN
    RETURN true;
  END IF;

  SELECT COALESCE(srpt.allowed, false)
  INTO v_role_allowed
  FROM public.store_role_permission_templates srpt
  WHERE srpt.store_id = p_store_id
    AND srpt.role = v_role
    AND srpt.permission_code = p_permission_code
  LIMIT 1;

  v_role_allowed := COALESCE(v_role_allowed, false);

  IF v_custom_role_id IS NOT NULL THEN
    SELECT
      CASE
        WHEN scr.permissions ? p_permission_code
          THEN (scr.permissions->>p_permission_code)::boolean
        ELSE NULL
      END
    INTO v_custom_role_override
    FROM public.store_custom_roles scr
    WHERE scr.id = v_custom_role_id
      AND scr.store_id = p_store_id
      AND scr.active = true
    LIMIT 1;
  END IF;

  IF v_permissions ? p_permission_code THEN
    v_individual_override := (v_permissions->>p_permission_code)::boolean;
  END IF;

  RETURN COALESCE(
    v_individual_override,
    v_custom_role_override,
    v_role_allowed,
    false
  );
END;
$$;


