CREATE OR REPLACE FUNCTION "public"."validate_inventory_location_balances"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    if not public.stock_location_belongs_to_store(new.location_id, new.store_id) then
        raise exception 'location_id % não pertence à store_id % em inventory_location_balances',
            new.location_id, new.store_id
            using errcode = '23514';
    end if;

    if not public.product_belongs_to_store(new.product_id, new.store_id) then
        raise exception 'product_id % não pertence à store_id % em inventory_location_balances',
            new.product_id, new.store_id
            using errcode = '23514';
    end if;

    if new.on_hand < 0 then
        raise exception 'on_hand não pode ser negativo'
            using errcode = '23514';
    end if;

    if new.reserved < 0 then
        raise exception 'reserved não pode ser negativo'
            using errcode = '23514';
    end if;

    if new.reserved > new.on_hand then
        raise exception 'reserved não pode ser maior que on_hand'
            using errcode = '23514';
    end if;

    new.updated_at := now();
    return new;
end;
$$;


ALTER FUNCTION "public"."validate_inventory_location_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_movements_locations"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer_store_id uuid;
begin
    if new.store_id is null then
        raise exception 'stock_movements.store_id é obrigatório'
            using errcode = '23514';
    end if;

    if not public.product_belongs_to_store(new.product_id, new.store_id) then
        raise exception 'product_id % não pertence à store_id % em stock_movements',
            new.product_id, new.store_id
            using errcode = '23514';
    end if;

    if new.location_id is not null
       and not public.stock_location_belongs_to_store(new.location_id, new.store_id) then
        raise exception 'location_id % não pertence à store_id % em stock_movements',
            new.location_id, new.store_id
            using errcode = '23514';
    end if;

    if new.from_location_id is not null
       and not public.stock_location_belongs_to_store(new.from_location_id, new.store_id) then
        raise exception 'from_location_id % não pertence à store_id % em stock_movements',
            new.from_location_id, new.store_id
            using errcode = '23514';
    end if;

    if new.to_location_id is not null
       and not public.stock_location_belongs_to_store(new.to_location_id, new.store_id) then
        raise exception 'to_location_id % não pertence à store_id % em stock_movements',
            new.to_location_id, new.store_id
            using errcode = '23514';
    end if;

    if new.from_location_id is not null
       and new.to_location_id is not null
       and new.from_location_id = new.to_location_id then
        raise exception 'from_location_id e to_location_id não podem ser iguais em stock_movements'
            using errcode = '23514';
    end if;

    if new.transfer_id is not null then
        select st.store_id
          into v_transfer_store_id
          from public.stock_transfers st
         where st.id = new.transfer_id;

        if v_transfer_store_id is null then
            raise exception 'transfer_id % não encontrado em stock_transfers',
                new.transfer_id
                using errcode = '23503';
        end if;

        if v_transfer_store_id <> new.store_id then
            raise exception 'transfer_id % pertence à store_id %, diferente da stock_movement.store_id %',
                new.transfer_id, v_transfer_store_id, new.store_id
                using errcode = '23514';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_movements_locations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_transfer_items"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_transfer_store_id uuid;
begin
    select st.store_id
      into v_transfer_store_id
      from public.stock_transfers st
     where st.id = new.transfer_id;

    if v_transfer_store_id is null then
        raise exception 'transfer_id % não encontrado em stock_transfers',
            new.transfer_id
            using errcode = '23503';
    end if;

    if v_transfer_store_id <> new.store_id then
        raise exception 'store_id do item (%) difere do store_id da transferência (%)',
            new.store_id, v_transfer_store_id
            using errcode = '23514';
    end if;

    if not public.product_belongs_to_store(new.product_id, new.store_id) then
        raise exception 'product_id % não pertence à store_id % em stock_transfer_items',
            new.product_id, new.store_id
            using errcode = '23514';
    end if;

    if new.requested_qty < 0
       or new.shipped_qty < 0
       or new.received_qty < 0
       or new.divergence_qty < 0 then
        raise exception 'Quantidades da transferência não podem ser negativas'
            using errcode = '23514';
    end if;

    if new.shipped_qty > new.requested_qty then
        raise exception 'shipped_qty não pode ser maior que requested_qty'
            using errcode = '23514';
    end if;

    if new.received_qty > new.shipped_qty then
        raise exception 'received_qty não pode ser maior que shipped_qty'
            using errcode = '23514';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_transfer_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_transfers"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    -- Nesta fase, trabalhamos com transferência interna à mesma store.
    if new.source_store_id <> new.store_id then
        raise exception 'source_store_id deve ser igual a store_id nesta fase'
            using errcode = '23514';
    end if;

    if new.destination_store_id <> new.store_id then
        raise exception 'destination_store_id deve ser igual a store_id nesta fase'
            using errcode = '23514';
    end if;

    if new.source_location_id = new.destination_location_id then
        raise exception 'source_location_id e destination_location_id não podem ser iguais'
            using errcode = '23514';
    end if;

    if not public.stock_location_belongs_to_store(new.source_location_id, new.source_store_id) then
        raise exception 'source_location_id % não pertence à source_store_id %',
            new.source_location_id, new.source_store_id
            using errcode = '23514';
    end if;

    if not public.stock_location_belongs_to_store(new.destination_location_id, new.destination_store_id) then
        raise exception 'destination_location_id % não pertence à destination_store_id %',
            new.destination_location_id, new.destination_store_id
            using errcode = '23514';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_transfers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_store_slug"("p_store_id" "uuid", "p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_slug text;
  v_exists boolean := false;
BEGIN
  v_slug := lower(trim(COALESCE(p_slug, '')));

  IF length(v_slug) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'slug_too_short',
      'message', 'O endereço público precisa ter pelo menos 3 caracteres.'
    );
  END IF;

  IF length(v_slug) > 60 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'slug_too_long',
      'message', 'O endereço público deve ter no máximo 60 caracteres.'
    );
  END IF;

  IF v_slug !~ '^[a-z0-9]+([a-z0-9-]*[a-z0-9])?$' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_slug_format',
      'message', 'Use apenas letras minúsculas, números e hífen, sem espaços.'
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.stores s
    WHERE lower(s.slug) = v_slug
      AND s.id <> p_store_id
  )
  INTO v_exists;

  IF v_exists THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'slug_already_taken',
      'message', 'Este endereço público já está em uso.'
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'slug', v_slug
  );
END;
$_$;


ALTER FUNCTION "public"."validate_store_slug"("p_store_id" "uuid", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_user_pin"("p_pin" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_hash text;
begin
  select pin_hash into v_hash
  from public.user_pins
  where user_id = auth.uid();

  if v_hash is null then
    return false;
  end if;

  return crypt(p_pin, v_hash) = v_hash;
end;
$$;


