CREATE TABLE IF NOT EXISTS "public"."stock_movements" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "product_id" "uuid" NOT NULL,
    "order_id" "uuid",
    "quantity" integer NOT NULL,
    "type" "public"."stock_movement_type" NOT NULL,
    "reason" "text",
    "user_id" "uuid",
    "previous_stock" integer DEFAULT 0 NOT NULL,
    "new_stock" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "affects_physical" boolean DEFAULT true NOT NULL,
    "source" "text",
    "source_id" "uuid",
    "reason_code" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "supplier_id" "uuid",
    "location_id" "uuid",
    "from_location_id" "uuid",
    "to_location_id" "uuid",
    "transfer_id" "uuid",
    CONSTRAINT "check_quantity_sign" CHECK (((("type" = ANY (ARRAY['entry'::"public"."stock_movement_type", 'cancellation'::"public"."stock_movement_type"])) AND ("quantity" > 0)) OR (("type" = ANY (ARRAY['exit'::"public"."stock_movement_type", 'confirmation'::"public"."stock_movement_type", 'clearance'::"public"."stock_movement_type"])) AND ("quantity" < 0)) OR (("type" = 'reservation'::"public"."stock_movement_type") AND ("quantity" > 0)))),
    CONSTRAINT "chk_stock_movements_prev_new_when_physical" CHECK ((("affects_physical" = false) OR (("previous_stock" IS NOT NULL) AND ("new_stock" IS NOT NULL)))),
    CONSTRAINT "chk_stock_movements_qty_nonzero" CHECK (((("type" = 'reservation'::"public"."stock_movement_type") AND (("quantity" = 0) OR ("quantity" IS NULL))) OR (("type" <> 'reservation'::"public"."stock_movement_type") AND ("quantity" <> 0))))
);


ALTER TABLE "public"."stock_movements" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."inventory_history" WITH ("security_invoker"='true') AS
 SELECT "id",
    "store_id",
    "product_id",
    "type",
    "quantity",
    "previous_stock" AS "balance_before",
    "new_stock" AS "balance_after",
    "source_id" AS "order_id",
    COALESCE("created_by", "user_id") AS "user_id",
    COALESCE("reason_code", "reason", "source", 'movement'::"text") AS "reason",
    "created_at"
   FROM "public"."stock_movements" "sm";


