CREATE OR REPLACE VIEW "public"."inventory_turnover" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."name",
    "p"."store_id",
    "count"("m"."id") FILTER (WHERE ("m"."type" = 'exit'::"public"."inventory_move_type")) AS "total_exits",
    "count"("m"."id") FILTER (WHERE ("m"."type" = 'entry'::"public"."inventory_move_type")) AS "total_entries",
    "max"("m"."created_at") AS "last_movement"
   FROM ("public"."products" "p"
     LEFT JOIN "public"."inventory_movements" "m" ON (("m"."product_id" = "p"."id")))
  GROUP BY "p"."id", "p"."name", "p"."store_id";


