    CONSTRAINT "operational_timeline_events_channel_check" CHECK ((("channel" IS NULL) OR ("channel" = ANY (ARRAY['system'::"text", 'manual'::"text", 'whatsapp'::"text", 'email'::"text", 'pdf'::"text", 'phone'::"text", 'in_person'::"text", 'api'::"text", 'import'::"text", 'other'::"text"])))),
    CONSTRAINT "operational_timeline_events_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['purchase_quotation'::"text", 'purchase_document'::"text", 'stock_transfer'::"text", 'stock_movement'::"text", 'supplier'::"text", 'product'::"text", 'order'::"text", 'return'::"text", 'customer'::"text", 'system'::"text", 'other'::"text"]))),
