CREATE OR REPLACE VIEW "public"."product_stock_available" WITH ("security_invoker"='true') AS
 SELECT "p"."store_id",
    "p"."id" AS "product_id",
    ("p"."stock_quantity")::numeric AS "on_hand",
    (COALESCE("sum"("r"."quantity") FILTER (WHERE ("r"."status" = 'active'::"text")), (0)::bigint))::numeric AS "reserved",
    (("p"."stock_quantity")::numeric - (COALESCE("sum"("r"."quantity") FILTER (WHERE ("r"."status" = 'active'::"text")), (0)::bigint))::numeric) AS "available"
   FROM ("public"."products" "p"
     LEFT JOIN "public"."stock_reservations" "r" ON ((("r"."store_id" = "p"."store_id") AND ("r"."product_id" = "p"."id"))))
  GROUP BY "p"."store_id", "p"."id", "p"."stock_quantity";


ALTER VIEW "public"."product_stock_available" OWNER TO "postgres";


