    "max_percent" numeric,
    "use_percentage" boolean DEFAULT true NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "product_stock_location_rules_max_percent_check" CHECK ((("max_percent" IS NULL) OR (("max_percent" >= (0)::numeric) AND ("max_percent" <= (100)::numeric)))),
    CONSTRAINT "product_stock_location_rules_max_stock_check" CHECK ((("max_stock" IS NULL) OR ("max_stock" >= (0)::numeric))),
    CONSTRAINT "product_stock_location_rules_min_percent_check" CHECK ((("min_percent" IS NULL) OR (("min_percent" >= (0)::numeric) AND ("min_percent" <= (100)::numeric)))),
    CONSTRAINT "product_stock_location_rules_min_stock_check" CHECK ((("min_stock" IS NULL) OR ("min_stock" >= (0)::numeric)))
);


