CREATE OR REPLACE VIEW "public"."products_stale" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "store_id",
    "last_sale_at",
    ("now"() - "last_sale_at") AS "days_without_sale"
   FROM "public"."products"
  WHERE (("last_sale_at" IS NOT NULL) AND (("now"() - "last_sale_at") > '30 days'::interval));


ALTER VIEW "public"."products_stale" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."products_stock_status" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."store_id",
    "p"."name",
    "p"."min_stock",
    "p"."max_stock",
    COALESCE("b"."on_hand", (0)::numeric) AS "current_stock",
        CASE
            WHEN (COALESCE("b"."on_hand", (0)::numeric) <= (0)::numeric) THEN 'out'::"text"
            WHEN (COALESCE("b"."on_hand", (0)::numeric) <= ("p"."min_stock")::numeric) THEN 'low'::"text"
            WHEN (COALESCE("b"."on_hand", (0)::numeric) >= ("p"."max_stock")::numeric) THEN 'over'::"text"
            ELSE 'ok'::"text"
        END AS "stock_status",
    (COALESCE("b"."on_hand", (0)::numeric) - ("p"."min_stock")::numeric) AS "delta_min"
   FROM ("public"."products" "p"
     LEFT JOIN "public"."inventory_balances" "b" ON ((("b"."product_id" = "p"."id") AND ("b"."store_id" = "p"."store_id"))))
  WHERE (("p"."active" = true) AND (COALESCE("p"."is_discontinued", "p"."discontinued", false) = false));


ALTER VIEW "public"."products_stock_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."products_with_stock" WITH ("security_invoker"='true') AS
 SELECT "id",
    "store_id",
    "category_id",
    "name",
    "description",
    "price",
    "images",
    "stock_quantity" AS "physical_stock",
    "active",
    "discontinued",
    COALESCE(( SELECT "sum"("sr"."quantity") AS "sum"
           FROM "public"."stock_reservations" "sr"
          WHERE (("sr"."product_id" = "p"."id") AND ("sr"."expires_at" > "now"()))), (0)::bigint) AS "reserved_stock",
    ("stock_quantity" - COALESCE(( SELECT "sum"("sr"."quantity") AS "sum"
           FROM "public"."stock_reservations" "sr"
          WHERE (("sr"."product_id" = "p"."id") AND ("sr"."expires_at" > "now"()))), (0)::bigint)) AS "available_stock"
   FROM "public"."products" "p";


ALTER VIEW "public"."products_with_stock" OWNER TO "postgres";


