CREATE OR REPLACE VIEW "public"."purchases_ledger" WITH ("security_invoker"='true') AS
 SELECT "sm"."id",
    "sm"."store_id",
    "sm"."created_at",
    "sm"."product_id",
    "p"."name" AS "product_name",
    "sm"."supplier_id",
    "s"."name" AS "supplier_name",
    "sm"."quantity",
    NULLIF(("sm"."metadata" ->> 'invoice_number'::"text"), ''::"text") AS "invoice_number",
    NULLIF(("sm"."metadata" ->> 'notes'::"text"), ''::"text") AS "notes",
    NULLIF(("sm"."metadata" ->> 'payment_method'::"text"), ''::"text") AS "payment_method",
    NULLIF(("sm"."metadata" ->> 'paid_at'::"text"), ''::"text") AS "paid_at",
    NULLIF(("sm"."metadata" ->> 'due_date'::"text"), ''::"text") AS "due_date",
    (NULLIF(("sm"."metadata" ->> 'unit_cost'::"text"), ''::"text"))::numeric AS "unit_cost",
    (NULLIF(("sm"."metadata" ->> 'total_cost'::"text"), ''::"text"))::numeric AS "total_cost",
    "sm"."metadata"
   FROM (("public"."stock_movements" "sm"
     JOIN "public"."products" "p" ON (("p"."id" = "sm"."product_id")))
     LEFT JOIN "public"."suppliers" "s" ON (("s"."id" = "sm"."supplier_id")))
  WHERE ("sm"."type" = 'entry'::"public"."stock_movement_type");


ALTER VIEW "public"."purchases_ledger" OWNER TO "postgres";


