CREATE OR REPLACE VIEW "public"."stock_alerts_summary" WITH ("security_invoker"='true') AS
 SELECT "store_id",
    "count"(*) FILTER (WHERE ("stock_status" = 'out'::"text")) AS "out_count",
    "count"(*) FILTER (WHERE ("stock_status" = 'low'::"text")) AS "low_count",
    "count"(*) FILTER (WHERE ("stock_status" = 'over'::"text")) AS "over_count",
    "count"(*) FILTER (WHERE ("stock_status" = ANY (ARRAY['out'::"text", 'low'::"text"]))) AS "critical_count"
   FROM "public"."products_stock_status"
  GROUP BY "store_id";


