CREATE OR REPLACE VIEW "public"."v_inventory_location_management_status" WITH ("security_invoker"='true') AS
 WITH "location_balance" AS (
         SELECT "ilb"."store_id",
            "ilb"."product_id",
            "ilb"."location_id",
            "sum"(COALESCE("ilb"."on_hand", (0)::numeric)) AS "location_on_hand",
            "sum"(COALESCE("ilb"."reserved", (0)::numeric)) AS "location_reserved"
           FROM "public"."inventory_location_balances" "ilb"
          GROUP BY "ilb"."store_id", "ilb"."product_id", "ilb"."location_id"
        ), "global_balance" AS (
         SELECT "ilb"."store_id",
            "ilb"."product_id",
            "sum"(COALESCE("ilb"."on_hand", (0)::numeric)) AS "global_on_hand",
            "sum"(COALESCE("ilb"."reserved", (0)::numeric)) AS "global_reserved"
           FROM "public"."inventory_location_balances" "ilb"
          GROUP BY "ilb"."store_id", "ilb"."product_id"
        ), "store_location_counts" AS (
         SELECT "sl"."store_id",
            ("count"(*) FILTER (WHERE (("sl"."active" = true) AND (("sl"."allow_sales" = true) OR ("sl"."allow_reservations" = true) OR ("sl"."is_default" = true)))))::numeric AS "relevant_location_count",
            ("count"(*) FILTER (WHERE (("sl"."active" = true) AND ("sl"."allow_sales" = true))))::numeric AS "sales_location_count"
           FROM "public"."stock_locations" "sl"
          GROUP BY "sl"."store_id"
        ), "base" AS (
         SELECT "p"."store_id",
            "p"."id" AS "product_id",
            "p"."name" AS "product_name",
            "p"."category_id",
            COALESCE("p"."active", true) AS "product_active",
            COALESCE("p"."discontinued", false) AS "discontinued",
            COALESCE("p"."is_discontinued", false) AS "is_discontinued",
            (COALESCE("p"."min_stock", 0))::numeric AS "global_min_stock",
            (COALESCE("p"."max_stock", 0))::numeric AS "global_max_stock",
            "sl"."id" AS "location_id",
            "sl"."code" AS "location_code",
            "sl"."name" AS "location_name",
            "sl"."type" AS "location_type",
            "sl"."active" AS "location_active",
            "sl"."is_default",
            "sl"."allow_sales",
            "sl"."allow_reservations",
            "sl"."sort_order" AS "location_sort_order",
            COALESCE("lb"."location_on_hand", (0)::numeric) AS "location_on_hand",
            COALESCE("lb"."location_reserved", (0)::numeric) AS "location_reserved",
            (COALESCE("lb"."location_on_hand", (0)::numeric) - COALESCE("lb"."location_reserved", (0)::numeric)) AS "location_available",
            COALESCE("gb"."global_on_hand", (0)::numeric) AS "global_on_hand",
            COALESCE("gb"."global_reserved", (0)::numeric) AS "global_reserved",
            (COALESCE("gb"."global_on_hand", (0)::numeric) - COALESCE("gb"."global_reserved", (0)::numeric)) AS "global_available",
            COALESCE("slc"."relevant_location_count", (0)::numeric) AS "relevant_location_count",
            COALESCE("slc"."sales_location_count", (0)::numeric) AS "sales_location_count",
                CASE
                    WHEN (COALESCE("p"."min_stock", 0) <= 0) THEN (0)::numeric
                    WHEN (COALESCE("slc"."relevant_location_count", (0)::numeric) <= (0)::numeric) THEN (COALESCE("p"."min_stock", 0))::numeric
                    WHEN (("sl"."active" = true) AND (("sl"."allow_sales" = true) OR ("sl"."allow_reservations" = true) OR ("sl"."is_default" = true))) THEN GREATEST((1)::numeric, "ceil"(((COALESCE("p"."min_stock", 0))::numeric / NULLIF("slc"."relevant_location_count", (0)::numeric))))
                    ELSE (0)::numeric
                END AS "provisional_location_min_stock",
                CASE
                    WHEN (COALESCE("p"."max_stock", 0) <= 0) THEN (0)::numeric
                    WHEN (COALESCE("slc"."relevant_location_count", (0)::numeric) <= (0)::numeric) THEN (COALESCE("p"."max_stock", 0))::numeric
                    WHEN (("sl"."active" = true) AND (("sl"."allow_sales" = true) OR ("sl"."allow_reservations" = true) OR ("sl"."is_default" = true))) THEN GREATEST((1)::numeric, "ceil"(((COALESCE("p"."max_stock", 0))::numeric / NULLIF("slc"."relevant_location_count", (0)::numeric))))
                    ELSE (0)::numeric
                END AS "provisional_location_max_stock"
           FROM (((("public"."products" "p"
             JOIN "public"."stock_locations" "sl" ON (("sl"."store_id" = "p"."store_id")))
             LEFT JOIN "location_balance" "lb" ON ((("lb"."store_id" = "p"."store_id") AND ("lb"."product_id" = "p"."id") AND ("lb"."location_id" = "sl"."id"))))
             LEFT JOIN "global_balance" "gb" ON ((("gb"."store_id" = "p"."store_id") AND ("gb"."product_id" = "p"."id"))))
             LEFT JOIN "store_location_counts" "slc" ON (("slc"."store_id" = "p"."store_id")))
        ), "classified" AS (
         SELECT "b"."store_id",
            "b"."product_id",
            "b"."product_name",
            "b"."category_id",
            "b"."product_active",
            "b"."discontinued",
            "b"."is_discontinued",
            "b"."global_min_stock",
            "b"."global_max_stock",
            "b"."location_id",
            "b"."location_code",
            "b"."location_name",
            "b"."location_type",
            "b"."location_active",
            "b"."is_default",
            "b"."allow_sales",
            "b"."allow_reservations",
            "b"."location_sort_order",
            "b"."location_on_hand",
            "b"."location_reserved",
            "b"."location_available",
            "b"."global_on_hand",
            "b"."global_reserved",
            "b"."global_available",
            "b"."relevant_location_count",
            "b"."sales_location_count",
            "b"."provisional_location_min_stock",
            "b"."provisional_location_max_stock",
                CASE
                    WHEN (("b"."product_active" = false) OR ("b"."discontinued" = true) OR ("b"."is_discontinued" = true)) THEN 'product_inactive'::"text"
                    WHEN (("b"."global_min_stock" > (0)::numeric) AND ("b"."global_available" <= (0)::numeric)) THEN 'global_stockout'::"text"
                    WHEN (("b"."global_min_stock" > (0)::numeric) AND ("b"."global_available" <= "b"."global_min_stock")) THEN 'global_critical'::"text"
                    WHEN (("b"."global_min_stock" > (0)::numeric) AND ("b"."global_available" <= "ceil"(("b"."global_min_stock" * 1.5)))) THEN 'global_attention'::"text"
                    WHEN (("b"."global_max_stock" > (0)::numeric) AND ("b"."global_available" >= "b"."global_max_stock")) THEN 'global_excess'::"text"
                    ELSE 'global_ok'::"text"
                END AS "global_status",
                CASE
                    WHEN (("b"."product_active" = false) OR ("b"."discontinued" = true) OR ("b"."is_discontinued" = true)) THEN 'product_inactive'::"text"
                    WHEN ("b"."location_active" = false) THEN 'location_inactive'::"text"
                    WHEN (("b"."provisional_location_min_stock" <= (0)::numeric) AND ("b"."location_available" <> (0)::numeric)) THEN 'monitor_only'::"text"
                    WHEN ("b"."provisional_location_min_stock" <= (0)::numeric) THEN 'not_configured'::"text"
                    WHEN ("b"."location_available" <= (0)::numeric) THEN 'location_stockout'::"text"
                    WHEN ("b"."location_available" <= "b"."provisional_location_min_stock") THEN 'location_critical'::"text"
                    WHEN (("b"."provisional_location_max_stock" > (0)::numeric) AND ("b"."location_available" >= "b"."provisional_location_max_stock")) THEN 'location_excess'::"text"
                    ELSE 'location_ok'::"text"
                END AS "location_status"
           FROM "base" "b"
        )
 SELECT "store_id",
    "product_id",
    "product_name",
    "category_id",
    "product_active",
    "discontinued",
    "is_discontinued",
    "global_min_stock",
    "global_max_stock",
    "location_id",
    "location_code",
    "location_name",
    "location_type",
    "location_active",
    "is_default",
    "allow_sales",
    "allow_reservations",
    "location_sort_order",
    "location_on_hand",
    "location_reserved",
    "location_available",
    "global_on_hand",
    "global_reserved",
    "global_available",
    "relevant_location_count",
    "sales_location_count",
    "provisional_location_min_stock",
    "provisional_location_max_stock",
    "global_status",
    "location_status",
        CASE
            WHEN ("global_status" = ANY (ARRAY['global_stockout'::"text", 'global_critical'::"text"])) THEN 'buy'::"text"
            WHEN (("global_status" = ANY (ARRAY['global_ok'::"text", 'global_attention'::"text", 'global_excess'::"text"])) AND ("location_status" = ANY (ARRAY['location_stockout'::"text", 'location_critical'::"text"]))) THEN 'transfer_or_redistribute'::"text"
            WHEN ("global_status" = 'global_excess'::"text") THEN 'review_excess'::"text"
            WHEN (("global_status" = 'global_attention'::"text") OR ("location_status" = 'location_critical'::"text")) THEN 'monitor'::"text"
            ELSE 'ok'::"text"
        END AS "recommended_action"
   FROM "classified" "c";


ALTER VIEW "public"."v_inventory_location_management_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_inventory_management_summary" WITH ("security_invoker"='true') AS
 WITH "agg" AS (
         SELECT "v"."store_id",
            "v"."product_id",
            "v"."product_name",
            "v"."category_id",
            "v"."product_active",
            "v"."discontinued",
            "v"."is_discontinued",
            "max"("v"."global_min_stock") AS "global_min_stock",
            "max"("v"."global_max_stock") AS "global_max_stock",
            "max"("v"."global_on_hand") AS "global_on_hand",
            "max"("v"."global_reserved") AS "global_reserved",
            "max"("v"."global_available") AS "global_available",
            "max"("v"."global_status") AS "global_status",
            ("count"(*))::integer AS "total_locations",
            ("count"(*) FILTER (WHERE ("v"."location_active" = true)))::integer AS "active_locations",
            ("count"(*) FILTER (WHERE (("v"."allow_sales" = true) AND ("v"."location_active" = true))))::integer AS "sales_locations",
            ("count"(*) FILTER (WHERE ("v"."location_status" = 'location_stockout'::"text")))::integer AS "location_stockout_count",
            ("count"(*) FILTER (WHERE ("v"."location_status" = 'location_critical'::"text")))::integer AS "location_critical_count",
            ("count"(*) FILTER (WHERE ("v"."location_status" = 'location_excess'::"text")))::integer AS "location_excess_count",
            ("count"(*) FILTER (WHERE (("v"."location_available" > (0)::numeric) AND ("v"."location_active" = true))))::integer AS "locations_with_available_stock",
            ("count"(*) FILTER (WHERE (("v"."location_available" > "v"."provisional_location_min_stock") AND ("v"."location_active" = true))))::integer AS "possible_source_locations",
            COALESCE("jsonb_agg"("jsonb_build_object"('location_id', "v"."location_id", 'location_code', "v"."location_code", 'location_name', "v"."location_name", 'location_status', "v"."location_status", 'available', "v"."location_available", 'on_hand', "v"."location_on_hand", 'reserved', "v"."location_reserved", 'allow_sales', "v"."allow_sales", 'is_default', "v"."is_default") ORDER BY "v"."location_sort_order", "v"."location_name") FILTER (WHERE ("v"."location_status" = ANY (ARRAY['location_stockout'::"text", 'location_critical'::"text", 'location_excess'::"text"]))), '[]'::"jsonb") AS "alert_locations"
           FROM "public"."v_inventory_location_management_status" "v"
          GROUP BY "v"."store_id", "v"."product_id", "v"."product_name", "v"."category_id", "v"."product_active", "v"."discontinued", "v"."is_discontinued"
        )
 SELECT "store_id",
    "product_id",
    "product_name",
    "category_id",
    "product_active",
    "discontinued",
    "is_discontinued",
    "global_min_stock",
    "global_max_stock",
    "global_on_hand",
    "global_reserved",
    "global_available",
    "global_status",
    "total_locations",
    "active_locations",
    "sales_locations",
    "location_stockout_count",
    "location_critical_count",
    "location_excess_count",
    "locations_with_available_stock",
    "possible_source_locations",
    "alert_locations",
        CASE
            WHEN ("global_status" = ANY (ARRAY['global_stockout'::"text", 'global_critical'::"text"])) THEN 'buy'::"text"
            WHEN ((("location_stockout_count" > 0) OR ("location_critical_count" > 0)) AND ("possible_source_locations" > 0) AND ("global_status" <> ALL (ARRAY['global_stockout'::"text", 'global_critical'::"text"]))) THEN 'transfer'::"text"
            WHEN ("global_status" = 'global_excess'::"text") THEN 'review_excess'::"text"
            WHEN (("global_status" = 'global_attention'::"text") OR ("location_critical_count" > 0)) THEN 'monitor'::"text"
            ELSE 'ok'::"text"
        END AS "recommended_action"
   FROM "agg" "a";


ALTER VIEW "public"."v_inventory_management_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_inventory_position_by_location" WITH ("security_invoker"='true') AS
 SELECT "ilb"."store_id",
    "ilb"."location_id",
    "sl"."code" AS "location_code",
    "sl"."name" AS "location_name",
    "sl"."type" AS "location_type",
    "sl"."active" AS "location_active",
    "ilb"."product_id",
    "p"."name" AS "product_name",
    "p"."category_id",
    "p"."price",
    "p"."active" AS "product_active",
    "p"."min_stock",
    "p"."max_stock",
    "p"."last_entry_unit_cost",
    "ilb"."variant_id",
    "ilb"."on_hand",
    "ilb"."reserved",
    ("ilb"."on_hand" - "ilb"."reserved") AS "available",
        CASE
            WHEN (("ilb"."on_hand" - "ilb"."reserved") <= (0)::numeric) THEN 'out'::"text"
            WHEN (("ilb"."on_hand" - "ilb"."reserved") <= (COALESCE("p"."min_stock", 0))::numeric) THEN 'low'::"text"
            WHEN (("p"."max_stock" IS NOT NULL) AND ("ilb"."on_hand" > ("p"."max_stock")::numeric)) THEN 'over'::"text"
            ELSE 'ok'::"text"
        END AS "stock_status",
    "ilb"."updated_at"
   FROM (("public"."inventory_location_balances" "ilb"
     JOIN "public"."stock_locations" "sl" ON (("sl"."id" = "ilb"."location_id")))
     JOIN "public"."products" "p" ON (("p"."id" = "ilb"."product_id")));


ALTER VIEW "public"."v_inventory_position_by_location" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_inventory_position_by_location" IS 'Posição de estoque por local com dados do produto e status operacional do estoque.';



CREATE OR REPLACE VIEW "public"."v_multi_stock_module_catalog" WITH ("security_invoker"='true') AS
 SELECT "object_type",
    "object_name",
    "description"
   FROM ( VALUES ('table'::"text",'stock_locations'::"text",'Locais internos de estoque por store'::"text"), ('table'::"text",'inventory_location_balances'::"text",'Saldo por local de estoque'::"text"), ('table'::"text",'stock_transfers'::"text",'Cabeçalho das transferências internas'::"text"), ('table'::"text",'stock_transfer_items'::"text",'Itens das transferências'::"text"), ('view'::"text",'v_inventory_by_location'::"text",'Saldo por local simplificado'::"text"), ('view'::"text",'v_stock_transfers_summary'::"text",'Resumo consolidado das transferências'::"text"), ('view'::"text",'v_inventory_position_by_location'::"text",'Posição de estoque por local para frontend'::"text"), ('view'::"text",'v_stock_transfer_items_detail'::"text",'Detalhe dos itens da transferência'::"text"), ('view'::"text",'v_stock_movements_detailed'::"text",'Movimentações físicas detalhadas'::"text"), ('view'::"text",'v_inventory_audit_events'::"text",'Auditoria de reservation/cancellation'::"text"), ('view'::"text",'v_product_inventory_lifecycle'::"text",'Resumo da vida do produto'::"text"), ('function'::"text",'apply_stock_movement_delta_v2'::"text",'Motor V2 de movimentação por local'::"text"), ('function'::"text",'create_stock_transfer'::"text",'Criação de transferência'::"text"), ('function'::"text",'add_stock_transfer_item'::"text",'Inclusão de item na transferência'::"text"), ('function'::"text",'ship_stock_transfer'::"text",'Expedição da transferência'::"text"), ('function'::"text",'receive_stock_transfer'::"text",'Recebimento da transferência'::"text"), ('function'::"text",'cancel_stock_transfer'::"text",'Cancelamento da transferência'::"text"), ('function'::"text",'get_inventory_position_by_store'::"text",'Consulta de saldo por local'::"text"), ('function'::"text",'get_stock_transfers_by_store'::"text",'Consulta de transferências'::"text"), ('function'::"text",'get_stock_transfer_detail'::"text",'Consulta de detalhe da transferência'::"text"), ('function'::"text",'get_product_inventory_lifecycle'::"text",'Consulta da vida do produto'::"text"), ('function'::"text",'get_product_stock_movements'::"text",'Consulta de movimentação física'::"text"), ('function'::"text",'get_product_inventory_audit_events'::"text",'Consulta de auditoria não física'::"text")) "t"("object_type", "object_name", "description");


ALTER VIEW "public"."v_multi_stock_module_catalog" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_multi_stock_module_catalog" IS 'Catálogo técnico do módulo Multiestoque e Transferências.';



CREATE OR REPLACE VIEW "public"."v_operational_timeline_events" WITH ("security_invoker"='true') AS
 SELECT "id",
    "store_id",
    "entity_type",
        CASE "entity_type"
            WHEN 'purchase_quotation'::"text" THEN 'Cotação'::"text"
            WHEN 'purchase_document'::"text" THEN 'Compra'::"text"
            WHEN 'stock_transfer'::"text" THEN 'Transferência'::"text"
            WHEN 'stock_movement'::"text" THEN 'Movimentação de estoque'::"text"
            WHEN 'supplier'::"text" THEN 'Fornecedor'::"text"
            WHEN 'product'::"text" THEN 'Produto'::"text"
            WHEN 'order'::"text" THEN 'Pedido'::"text"
            WHEN 'return'::"text" THEN 'Devolução'::"text"
            WHEN 'customer'::"text" THEN 'Cliente'::"text"
            WHEN 'system'::"text" THEN 'Sistema'::"text"
            ELSE 'Outro'::"text"
        END AS "entity_type_label",
    "entity_id",
    "event_type",
        CASE "event_type"
            WHEN 'quotation_created'::"text" THEN 'Cotação criada'::"text"
            WHEN 'quotation_channel_defined'::"text" THEN 'Canal definido'::"text"
            WHEN 'quotation_sent'::"text" THEN 'Cotação enviada'::"text"
            WHEN 'quotation_channel_changed'::"text" THEN 'Canal alterado'::"text"
            WHEN 'quotation_responsible_changed'::"text" THEN 'Responsável alterado'::"text"
            WHEN 'supplier_answered'::"text" THEN 'Fornecedor respondeu'::"text"
            WHEN 'quotation_approved'::"text" THEN 'Cotação aprovada'::"text"
            WHEN 'quotation_rejected'::"text" THEN 'Cotação rejeitada'::"text"
            WHEN 'quotation_cancelled'::"text" THEN 'Cotação cancelada'::"text"
            WHEN 'quotation_converted_to_purchase_document'::"text" THEN 'Cotação convertida em compra'::"text"
            WHEN 'quotation_linked_purchase_cancelled'::"text" THEN 'Compra vinculada cancelada'::"text"
            WHEN 'purchase_document_created'::"text" THEN 'Compra criada'::"text"
            WHEN 'purchase_document_created_from_quotation'::"text" THEN 'Compra criada pela cotação'::"text"
            WHEN 'purchase_document_confirmed'::"text" THEN 'Compra confirmada'::"text"
            WHEN 'purchase_document_applied_to_inventory'::"text" THEN 'Compra aplicada ao estoque'::"text"
            WHEN 'purchase_document_cancelled'::"text" THEN 'Compra cancelada'::"text"
            WHEN 'purchase_document_draft_deleted'::"text" THEN 'Rascunho de compra excluído'::"text"
            WHEN 'stock_transfer_created'::"text" THEN 'Transferência criada'::"text"
            WHEN 'stock_transfer_shipped'::"text" THEN 'Transferência enviada'::"text"
            WHEN 'stock_transfer_received'::"text" THEN 'Transferência recebida'::"text"
            WHEN 'stock_transfer_cancelled'::"text" THEN 'Transferência cancelada'::"text"
            WHEN 'stock_movement_created'::"text" THEN 'Movimentação registrada'::"text"
            WHEN 'supplier_updated'::"text" THEN 'Fornecedor atualizado'::"text"
            WHEN 'supplier_blocked'::"text" THEN 'Fornecedor bloqueado'::"text"
            WHEN 'supplier_unblocked'::"text" THEN 'Fornecedor desbloqueado'::"text"
            WHEN 'product_updated'::"text" THEN 'Produto atualizado'::"text"
            ELSE "title"
        END AS "event_type_label",
    "title",
    "description",
    "severity",
    "status",
    "actor_user_id",
    "actor_email",
    "responsible_name",
    "channel",
    "occurred_at",
    "created_at",
    "updated_at",
    "source",
    "source_id",
    "old_data",
    "new_data",
    "metadata",
    "related_supplier_id",
    COALESCE(("metadata" ->> 'supplier_name'::"text"), ("new_data" ->> 'supplier_name'::"text"), ("old_data" ->> 'supplier_name'::"text")) AS "supplier_name",
    COALESCE(("metadata" ->> 'supplier_document'::"text"), ("new_data" ->> 'supplier_document'::"text"), ("old_data" ->> 'supplier_document'::"text")) AS "supplier_document",
    "related_product_id",
    COALESCE(("metadata" ->> 'product_name'::"text"), ("new_data" ->> 'product_name'::"text"), ("old_data" ->> 'product_name'::"text")) AS "product_name",
    "related_purchase_quotation_id",
    COALESCE(("metadata" ->> 'quotation_code'::"text"), ("new_data" ->> 'quotation_code'::"text"), ("old_data" ->> 'quotation_code'::"text")) AS "quotation_code",
        CASE
            WHEN ("entity_type" = 'purchase_quotation'::"text") THEN COALESCE(("new_data" ->> 'quotation_status'::"text"), ("old_data" ->> 'quotation_status'::"text"), ("new_data" ->> 'status'::"text"), ("old_data" ->> 'status'::"text"))
            ELSE NULL::"text"
        END AS "quotation_status",
    "related_purchase_document_id",
    COALESCE(("metadata" ->> 'invoice_number'::"text"), ("new_data" ->> 'invoice_number'::"text"), ("old_data" ->> 'invoice_number'::"text")) AS "purchase_invoice_number",
        CASE
            WHEN ("entity_type" = 'purchase_document'::"text") THEN COALESCE(("new_data" ->> 'purchase_document_status'::"text"), ("old_data" ->> 'purchase_document_status'::"text"), ("new_data" ->> 'status'::"text"), ("old_data" ->> 'status'::"text"))
            ELSE NULL::"text"
        END AS "purchase_document_status",
    (NULLIF(COALESCE(("metadata" ->> 'issue_date'::"text"), ("new_data" ->> 'issue_date'::"text"), ("old_data" ->> 'issue_date'::"text")), ''::"text"))::"date" AS "purchase_issue_date",
    "related_stock_transfer_id",
    COALESCE(("metadata" ->> 'transfer_code'::"text"), ("new_data" ->> 'transfer_code'::"text"), ("old_data" ->> 'transfer_code'::"text")) AS "transfer_code",
        CASE
            WHEN ("entity_type" = 'stock_transfer'::"text") THEN COALESCE(("new_data" ->> 'stock_transfer_status'::"text"), ("old_data" ->> 'stock_transfer_status'::"text"), ("new_data" ->> 'status'::"text"), ("old_data" ->> 'status'::"text"))
            ELSE NULL::"text"
        END AS "stock_transfer_status",
    "related_stock_movement_id",
    COALESCE(("metadata" ->> 'stock_movement_type'::"text"), ("new_data" ->> 'stock_movement_type'::"text"), ("old_data" ->> 'stock_movement_type'::"text")) AS "stock_movement_type",
    (NULLIF(COALESCE(("metadata" ->> 'stock_movement_quantity'::"text"), ("new_data" ->> 'stock_movement_quantity'::"text"), ("old_data" ->> 'stock_movement_quantity'::"text")), ''::"text"))::numeric AS "stock_movement_quantity",
    COALESCE(("metadata" ->> 'stock_movement_reason'::"text"), ("new_data" ->> 'stock_movement_reason'::"text"), ("old_data" ->> 'stock_movement_reason'::"text")) AS "stock_movement_reason",
        CASE
            WHEN ("entity_type" = 'purchase_document'::"text") THEN COALESCE(("metadata" ->> 'document_code'::"text"), ("new_data" ->> 'document_code'::"text"), ("old_data" ->> 'document_code'::"text"), ("metadata" ->> 'invoice_number'::"text"), ("new_data" ->> 'invoice_number'::"text"), ("old_data" ->> 'invoice_number'::"text"), ("metadata" ->> 'supplier_name'::"text"), ("new_data" ->> 'supplier_name'::"text"), ("old_data" ->> 'supplier_name'::"text"), ("entity_id")::"text")
            ELSE COALESCE(("metadata" ->> 'quotation_code'::"text"), ("new_data" ->> 'quotation_code'::"text"), ("old_data" ->> 'quotation_code'::"text"), ("metadata" ->> 'document_code'::"text"), ("new_data" ->> 'document_code'::"text"), ("old_data" ->> 'document_code'::"text"), ("metadata" ->> 'invoice_number'::"text"), ("new_data" ->> 'invoice_number'::"text"), ("old_data" ->> 'invoice_number'::"text"), ("metadata" ->> 'transfer_code'::"text"), ("new_data" ->> 'transfer_code'::"text"), ("old_data" ->> 'transfer_code'::"text"), ("metadata" ->> 'supplier_name'::"text"), ("new_data" ->> 'supplier_name'::"text"), ("old_data" ->> 'supplier_name'::"text"), ("metadata" ->> 'product_name'::"text"), ("new_data" ->> 'product_name'::"text"), ("old_data" ->> 'product_name'::"text"), ("entity_id")::"text")
        END AS "reference_label",
        CASE
            WHEN ("severity" = 'success'::"text") THEN 'Sucesso'::"text"
            WHEN ("severity" = 'warning'::"text") THEN 'Atenção'::"text"
            WHEN ("severity" = 'danger'::"text") THEN 'Crítico'::"text"
            WHEN ("severity" = 'critical'::"text") THEN 'Crítico'::"text"
            ELSE 'Informação'::"text"
        END AS "severity_label",
        CASE
            WHEN ("status" = 'open'::"text") THEN 'Aberto'::"text"
            WHEN ("status" = 'done'::"text") THEN 'Concluído'::"text"
            WHEN ("status" = 'cancelled'::"text") THEN 'Cancelado'::"text"
            WHEN ("status" = 'archived'::"text") THEN 'Arquivado'::"text"
            ELSE "status"
        END AS "status_label",
        CASE
            WHEN ("channel" = 'system'::"text") THEN 'Sistema'::"text"
            WHEN ("channel" = 'manual'::"text") THEN 'Manual'::"text"
            WHEN ("channel" = 'whatsapp'::"text") THEN 'WhatsApp'::"text"
            WHEN ("channel" = 'email'::"text") THEN 'E-mail'::"text"
            WHEN ("channel" = 'pdf'::"text") THEN 'PDF'::"text"
            WHEN ("channel" = 'phone'::"text") THEN 'Telefone'::"text"
            WHEN ("channel" = 'in_person'::"text") THEN 'Presencial'::"text"
            WHEN ("channel" = 'api'::"text") THEN 'API'::"text"
            WHEN ("channel" = 'import'::"text") THEN 'Importação'::"text"
            WHEN ("channel" = 'other'::"text") THEN 'Outro'::"text"
            ELSE "channel"
        END AS "channel_label"
   FROM "public"."operational_timeline_events" "ote";


ALTER VIEW "public"."v_operational_timeline_events" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_operational_timeline_events" IS 'View amigável da linha do tempo operacional baseada somente em operational_timeline_events, usando security_invoker=true para respeitar permissões/RLS do usuário consultante. Campos de referência são derivados de metadata/new_data/old_data.';



CREATE OR REPLACE VIEW "public"."v_supplier_price_variation" WITH ("security_invoker"='true') AS
 WITH "ranked" AS (
         SELECT "sph"."id",
            "sph"."store_id",
            "sph"."supplier_id",
            "sph"."product_id",
            "sph"."purchase_document_id",
            "sph"."purchase_document_item_id",
            "sph"."unit_cost",
            "sph"."quantity",
            "sph"."total_cost",
            "sph"."issue_date",
            "sph"."effective_at",
            "sph"."source",
            "sph"."metadata",
            "sph"."created_at",
            "sph"."is_active",
            "sph"."cancelled_at",
            "sph"."cancelled_reason",
            "row_number"() OVER (PARTITION BY "sph"."store_id", "sph"."supplier_id", "sph"."product_id" ORDER BY "sph"."effective_at" DESC, "sph"."created_at" DESC) AS "rn"
           FROM "public"."supplier_price_history" "sph"
          WHERE ("sph"."is_active" = true)
        )
 SELECT "a"."store_id",
    "a"."supplier_id",
    "a"."product_id",
    "p"."name" AS "product_name",
    "a"."unit_cost" AS "current_unit_cost",
    "b"."unit_cost" AS "previous_unit_cost",
    ("a"."unit_cost" - "b"."unit_cost") AS "delta_abs",
        CASE
            WHEN (("b"."unit_cost" IS NULL) OR ("b"."unit_cost" = (0)::numeric)) THEN NULL::numeric
            ELSE ((("a"."unit_cost" - "b"."unit_cost") / "b"."unit_cost") * (100)::numeric)
        END AS "delta_pct",
    "a"."effective_at" AS "current_purchase_at"
   FROM (("ranked" "a"
     LEFT JOIN "ranked" "b" ON ((("b"."store_id" = "a"."store_id") AND ("b"."supplier_id" = "a"."supplier_id") AND ("b"."product_id" = "a"."product_id") AND ("b"."rn" = 2))))
     JOIN "public"."products" "p" ON (("p"."id" = "a"."product_id")))
  WHERE ("a"."rn" = 1);


ALTER VIEW "public"."v_supplier_price_variation" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_supplier_alerts" WITH ("security_invoker"='true') AS
 WITH "latest_best_price" AS (
         SELECT "sph"."store_id",
            "sph"."product_id",
            "min"("sph"."unit_cost") AS "best_unit_cost"
           FROM "public"."supplier_price_history" "sph"
          WHERE ("sph"."is_active" = true)
          GROUP BY "sph"."store_id", "sph"."product_id"
        ), "variation_base" AS (
         SELECT "spv"."store_id",
            "spv"."supplier_id",
            "spv"."product_id",
            "spv"."product_name",
            "spv"."current_unit_cost",
            "spv"."previous_unit_cost",
            "spv"."delta_abs",
            "spv"."delta_pct",
            "spv"."current_purchase_at",
            "lbp"."best_unit_cost"
           FROM ("public"."v_supplier_price_variation" "spv"
             LEFT JOIN "latest_best_price" "lbp" ON ((("lbp"."store_id" = "spv"."store_id") AND ("lbp"."product_id" = "spv"."product_id"))))
        )
 SELECT "store_id",
    "supplier_id",
    "product_id",
    "product_name",
    "current_unit_cost",
    "previous_unit_cost",
    "delta_abs",
    "delta_pct",
    "current_purchase_at",
    "best_unit_cost",
    "round"(("current_unit_cost" - "best_unit_cost"), 4) AS "best_price_gap_abs",
        CASE
            WHEN (("best_unit_cost" IS NULL) OR ("best_unit_cost" = (0)::numeric)) THEN NULL::numeric
            ELSE "round"(((("current_unit_cost" - "best_unit_cost") / "best_unit_cost") * (100)::numeric), 2)
        END AS "best_price_gap_pct",
        CASE
            WHEN ("previous_unit_cost" IS NULL) THEN 'no_history'::"text"
            WHEN ("delta_pct" >= (10)::numeric) THEN 'high_increase'::"text"
            WHEN ("delta_pct" > (0)::numeric) THEN 'price_up'::"text"
            WHEN ("delta_pct" < (0)::numeric) THEN 'price_down'::"text"
            ELSE 'price_stable'::"text"
        END AS "alert_type",
        CASE
            WHEN (("best_unit_cost" IS NOT NULL) AND ("current_unit_cost" = "best_unit_cost")) THEN true
            ELSE false
        END AS "is_best_price",
        CASE
            WHEN ("current_purchase_at" IS NULL) THEN NULL::interval
            ELSE ("now"() - "current_purchase_at")
        END AS "purchase_age_interval"
   FROM "variation_base" "vb";


ALTER VIEW "public"."v_supplier_alerts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_price_alerts" WITH ("security_invoker"='true') AS
 SELECT "sa"."store_id",
    "sa"."supplier_id",
    "s"."name" AS "supplier_name",
    "sa"."product_id",
    "sa"."product_name",
    "sa"."current_unit_cost",
    "sa"."previous_unit_cost",
    "sa"."delta_abs",
    "sa"."delta_pct",
    "sa"."current_purchase_at",
    "sa"."best_unit_cost",
    "sa"."best_price_gap_abs",
    "sa"."best_price_gap_pct",
    "sa"."alert_type",
    "sa"."is_best_price"
   FROM ("public"."v_supplier_alerts" "sa"
     JOIN "public"."suppliers" "s" ON (("s"."id" = "sa"."supplier_id")));


ALTER VIEW "public"."v_procurement_price_alerts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_supplier_metrics" WITH ("security_invoker"='true') AS
 SELECT "s"."store_id",
    "s"."id" AS "supplier_id",
    "s"."name",
    "s"."active",
    "count"(DISTINCT "pd"."id") AS "total_documents",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "confirmed_documents",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'cancelled'::"text")) AS "cancelled_documents",
    "count"(DISTINCT "sph"."product_id") FILTER (WHERE ("sph"."is_active" = true)) AS "distinct_products",
    COALESCE("sum"("sph"."quantity") FILTER (WHERE ("sph"."is_active" = true)), (0)::numeric) AS "total_quantity",
    COALESCE("sum"("sph"."total_cost") FILTER (WHERE ("sph"."is_active" = true)), (0)::numeric) AS "total_spent",
    "max"("sph"."effective_at") FILTER (WHERE ("sph"."is_active" = true)) AS "last_purchase_at",
    "min"("sph"."effective_at") FILTER (WHERE ("sph"."is_active" = true)) AS "first_purchase_at",
        CASE
            WHEN ("count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) = 0) THEN (0)::numeric
            ELSE (COALESCE("sum"("sph"."total_cost") FILTER (WHERE ("sph"."is_active" = true)), (0)::numeric) / (NULLIF("count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), 0))::numeric)
        END AS "avg_ticket"
   FROM (("public"."suppliers" "s"
     LEFT JOIN "public"."purchase_documents" "pd" ON ((("pd"."supplier_id" = "s"."id") AND ("pd"."store_id" = "s"."store_id"))))
     LEFT JOIN "public"."supplier_price_history" "sph" ON (("sph"."purchase_document_id" = "pd"."id")))
  GROUP BY "s"."store_id", "s"."id", "s"."name", "s"."active";


ALTER VIEW "public"."v_supplier_metrics" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_stale_suppliers" WITH ("security_invoker"='true') AS
 SELECT "store_id",
    "supplier_id",
    "name" AS "supplier_name",
    "total_spent",
    "confirmed_documents",
    "distinct_products",
    "last_purchase_at",
        CASE
            WHEN ("last_purchase_at" IS NULL) THEN NULL::numeric
            ELSE "floor"((EXTRACT(epoch FROM ("now"() - "last_purchase_at")) / (86400)::numeric))
        END AS "days_since_last_purchase",
        CASE
            WHEN ("last_purchase_at" IS NULL) THEN 'no_history'::"text"
            WHEN (("now"() - "last_purchase_at") <= '30 days'::interval) THEN 'recent'::"text"
            WHEN (("now"() - "last_purchase_at") <= '90 days'::interval) THEN 'warm'::"text"
            ELSE 'stale'::"text"
        END AS "recency_status"
   FROM "public"."v_supplier_metrics" "vm";


ALTER VIEW "public"."v_procurement_stale_suppliers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_summary" WITH ("security_invoker"='true') AS
 SELECT "pd"."store_id",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "confirmed_documents",
    "count"(DISTINCT "pd"."supplier_id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "active_suppliers",
    "count"(DISTINCT "pdi"."product_id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "purchased_products",
    COALESCE("sum"("pdi"."total_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_spent",
    "avg"("pd"."total_amount") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "avg_ticket",
        CASE
            WHEN (COALESCE("sum"("pdi"."quantity") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) = (0)::numeric) THEN (0)::numeric
            ELSE (COALESCE("sum"("pdi"."total_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) / NULLIF("sum"("pdi"."quantity") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric))
        END AS "weighted_avg_unit_cost",
    "min"("pd"."issue_date") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "first_purchase_date",
    "max"("pd"."issue_date") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "last_purchase_date"
   FROM ("public"."purchase_documents" "pd"
     LEFT JOIN "public"."purchase_document_items" "pdi" ON (("pdi"."purchase_document_id" = "pd"."id")))
  GROUP BY "pd"."store_id";


ALTER VIEW "public"."v_procurement_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_top_price_increases" WITH ("security_invoker"='true') AS
 SELECT "store_id",
    "supplier_id",
    "supplier_name",
    "product_id",
    "product_name",
    "current_unit_cost",
    "previous_unit_cost",
    "delta_abs",
    "delta_pct",
    "current_purchase_at",
    "best_unit_cost",
    "best_price_gap_abs",
    "best_price_gap_pct",
    "alert_type",
    "is_best_price"
   FROM "public"."v_procurement_price_alerts"
  WHERE ("alert_type" = ANY (ARRAY['high_increase'::"text", 'price_up'::"text"]));


ALTER VIEW "public"."v_procurement_top_price_increases" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_top_products" WITH ("security_invoker"='true') AS
 SELECT "pd"."store_id",
    "pdi"."product_id",
    "p"."name" AS "product_name",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "confirmed_documents",
    "count"(DISTINCT "pd"."supplier_id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "suppliers_count",
    COALESCE("sum"("pdi"."quantity") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_quantity",
    COALESCE("sum"("pdi"."total_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_spent",
    "avg"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "avg_unit_cost",
    "min"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "min_unit_cost",
    "max"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "max_unit_cost",
    "max"("pd"."issue_date") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "last_purchase_date"
   FROM (("public"."purchase_documents" "pd"
     JOIN "public"."purchase_document_items" "pdi" ON (("pdi"."purchase_document_id" = "pd"."id")))
     JOIN "public"."products" "p" ON (("p"."id" = "pdi"."product_id")))
  GROUP BY "pd"."store_id", "pdi"."product_id", "p"."name";


ALTER VIEW "public"."v_procurement_top_products" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_top_products_by_supplier" WITH ("security_invoker"='true') AS
 SELECT "pd"."store_id",
    "pd"."supplier_id",
    "s"."name" AS "supplier_name",
    "pdi"."product_id",
    "p"."name" AS "product_name",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "confirmed_documents",
    COALESCE("sum"("pdi"."quantity") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_quantity",
    COALESCE("sum"("pdi"."total_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_spent",
    "avg"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "avg_unit_cost",
    "min"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "min_unit_cost",
    "max"("pdi"."unit_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "max_unit_cost",
    "max"("pd"."issue_date") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "last_purchase_date"
   FROM ((("public"."purchase_documents" "pd"
     JOIN "public"."suppliers" "s" ON (("s"."id" = "pd"."supplier_id")))
     JOIN "public"."purchase_document_items" "pdi" ON (("pdi"."purchase_document_id" = "pd"."id")))
     JOIN "public"."products" "p" ON (("p"."id" = "pdi"."product_id")))
  GROUP BY "pd"."store_id", "pd"."supplier_id", "s"."name", "pdi"."product_id", "p"."name";


ALTER VIEW "public"."v_procurement_top_products_by_supplier" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_procurement_top_suppliers" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "pd"."store_id",
            "pd"."supplier_id",
            "s"."name" AS "supplier_name",
            "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "confirmed_documents",
            "count"(DISTINCT "pdi"."product_id") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "distinct_products",
            COALESCE("sum"("pdi"."quantity") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_quantity",
            COALESCE("sum"("pdi"."total_cost") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")), (0)::numeric) AS "total_spent",
            "max"("pd"."issue_date") FILTER (WHERE ("pd"."status" = 'confirmed'::"text")) AS "last_purchase_date"
           FROM (("public"."purchase_documents" "pd"
             JOIN "public"."suppliers" "s" ON (("s"."id" = "pd"."supplier_id")))
             LEFT JOIN "public"."purchase_document_items" "pdi" ON (("pdi"."purchase_document_id" = "pd"."id")))
          GROUP BY "pd"."store_id", "pd"."supplier_id", "s"."name"
        )
 SELECT "store_id",
    "supplier_id",
    "supplier_name",
    "confirmed_documents",
    "distinct_products",
    "total_quantity",
    "total_spent",
    "last_purchase_date",
    "row_number"() OVER (PARTITION BY "store_id" ORDER BY "total_spent" DESC, "supplier_id") AS "rank_position",
        CASE
            WHEN ("sum"("total_spent") OVER (PARTITION BY "store_id") = (0)::numeric) THEN (0)::numeric
            ELSE "round"((("total_spent" / "sum"("total_spent") OVER (PARTITION BY "store_id")) * (100)::numeric), 2)
        END AS "share_pct"
   FROM "base";


ALTER VIEW "public"."v_procurement_top_suppliers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_product_inventory_lifecycle" WITH ("security_invoker"='true') AS
 WITH "loc_agg" AS (
         SELECT "ilb"."store_id",
            "ilb"."product_id",
            "sum"("ilb"."on_hand") AS "total_on_hand",
            "sum"("ilb"."reserved") AS "total_reserved",
            "sum"(("ilb"."on_hand" - "ilb"."reserved")) AS "total_available",
            "max"("ilb"."updated_at") AS "last_location_balance_update"
           FROM "public"."inventory_location_balances" "ilb"
          GROUP BY "ilb"."store_id", "ilb"."product_id"
        ), "movement_agg" AS (
         SELECT "sm"."store_id",
            "sm"."product_id",
            "max"("sm"."created_at") FILTER (WHERE ("sm"."type" = 'entry'::"public"."stock_movement_type")) AS "last_entry_at",
            "max"("sm"."created_at") FILTER (WHERE ("sm"."type" = 'exit'::"public"."stock_movement_type")) AS "last_exit_at",
            "max"("sm"."created_at") AS "last_movement_at"
           FROM "public"."stock_movements" "sm"
          GROUP BY "sm"."store_id", "sm"."product_id"
        ), "transfer_base" AS (
         SELECT "st"."store_id",
            "sti"."product_id",
            "st"."id" AS "transfer_id",
            GREATEST(COALESCE("st"."received_at", '-infinity'::timestamp with time zone), COALESCE("st"."shipped_at", '-infinity'::timestamp with time zone), COALESCE("st"."cancelled_at", '-infinity'::timestamp with time zone), COALESCE("st"."requested_at", '-infinity'::timestamp with time zone), COALESCE("st"."created_at", '-infinity'::timestamp with time zone)) AS "operational_transfer_at"
           FROM ("public"."stock_transfers" "st"
             JOIN "public"."stock_transfer_items" "sti" ON (("sti"."transfer_id" = "st"."id")))
          WHERE ("st"."status" IS NOT NULL)
        ), "transfer_agg" AS (
         SELECT "tb"."store_id",
            "tb"."product_id",
            "count"(DISTINCT "tb"."transfer_id") AS "transfer_count",
            "max"(NULLIF("tb"."operational_transfer_at", '-infinity'::timestamp with time zone)) AS "last_transfer_at"
           FROM "transfer_base" "tb"
          GROUP BY "tb"."store_id", "tb"."product_id"
        )
 SELECT "p"."store_id",
    "p"."id" AS "product_id",
    "p"."name" AS "product_name",
    "p"."category_id",
    "p"."price",
    "p"."active",
    "p"."min_stock",
    "p"."max_stock",
    "p"."last_entry_unit_cost",
    COALESCE("la"."total_on_hand", (0)::numeric) AS "total_on_hand",
    COALESCE("la"."total_reserved", (0)::numeric) AS "total_reserved",
    COALESCE("la"."total_available", (0)::numeric) AS "total_available",
    "ma"."last_entry_at",
    "ma"."last_exit_at",
    "ma"."last_movement_at",
    "ta"."transfer_count",
    "ta"."last_transfer_at",
    "la"."last_location_balance_update"
   FROM ((("public"."products" "p"
     LEFT JOIN "loc_agg" "la" ON ((("la"."store_id" = "p"."store_id") AND ("la"."product_id" = "p"."id"))))
     LEFT JOIN "movement_agg" "ma" ON ((("ma"."store_id" = "p"."store_id") AND ("ma"."product_id" = "p"."id"))))
     LEFT JOIN "transfer_agg" "ta" ON ((("ta"."store_id" = "p"."store_id") AND ("ta"."product_id" = "p"."id"))));


ALTER VIEW "public"."v_product_inventory_lifecycle" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_product_inventory_lifecycle" IS 'Resumo operacional da vida do produto: saldo, reservas, últimas movimentações e transferências.';



CREATE OR REPLACE VIEW "public"."v_stock_movements_detailed" WITH ("security_invoker"='true') AS
 SELECT "sm"."id",
    "sm"."store_id",
    "sm"."product_id",
    "p"."name" AS "product_name",
    "sm"."order_id",
    "sm"."quantity",
    "sm"."type",
    "sm"."reason",
    "sm"."user_id",
    "sm"."previous_stock",
    "sm"."new_stock",
    "sm"."created_at",
    "sm"."affects_physical",
    "sm"."source",
    "sm"."source_id",
    "sm"."reason_code",
    "sm"."metadata",
    "sm"."created_by",
    "sm"."supplier_id",
    "sm"."location_id",
    "loc"."code" AS "location_code",
    "loc"."name" AS "location_name",
    "sm"."from_location_id",
    "from_loc"."code" AS "from_location_code",
    "from_loc"."name" AS "from_location_name",
    "sm"."to_location_id",
    "to_loc"."code" AS "to_location_code",
    "to_loc"."name" AS "to_location_name",
    "sm"."transfer_id"
   FROM (((("public"."stock_movements" "sm"
     JOIN "public"."products" "p" ON (("p"."id" = "sm"."product_id")))
     LEFT JOIN "public"."stock_locations" "loc" ON (("loc"."id" = "sm"."location_id")))
     LEFT JOIN "public"."stock_locations" "from_loc" ON (("from_loc"."id" = "sm"."from_location_id")))
     LEFT JOIN "public"."stock_locations" "to_loc" ON (("to_loc"."id" = "sm"."to_location_id")));


ALTER VIEW "public"."v_stock_movements_detailed" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_stock_movements_detailed" IS 'Movimentações físicas detalhadas com origem/destino por local.';



