CREATE OR REPLACE VIEW "public"."v_stock_transfers_summary" WITH ("security_invoker"='true') AS
 SELECT "st"."id",
    "st"."store_id",
    "st"."transfer_code",
    "st"."status",
    "st"."source_store_id",
    "st"."destination_store_id",
    "st"."source_location_id",
    "src"."code" AS "source_location_code",
    "src"."name" AS "source_location_name",
    "st"."destination_location_id",
    "dst"."code" AS "destination_location_code",
    "dst"."name" AS "destination_location_name",
    "st"."requested_at",
    "st"."approved_at",
    "st"."shipped_at",
    "st"."received_at",
    "st"."cancelled_at",
    "st"."notes",
    "st"."created_at",
    "st"."updated_at",
    COALESCE("count"("sti"."id"), (0)::bigint) AS "items_count",
    COALESCE("sum"("sti"."requested_qty"), (0)::numeric) AS "total_requested_qty",
    COALESCE("sum"("sti"."shipped_qty"), (0)::numeric) AS "total_shipped_qty",
    COALESCE("sum"("sti"."received_qty"), (0)::numeric) AS "total_received_qty",
    COALESCE("sum"("sti"."divergence_qty"), (0)::numeric) AS "total_divergence_qty"
   FROM ((("public"."stock_transfers" "st"
     JOIN "public"."stock_locations" "src" ON (("src"."id" = "st"."source_location_id")))
     JOIN "public"."stock_locations" "dst" ON (("dst"."id" = "st"."destination_location_id")))
     LEFT JOIN "public"."stock_transfer_items" "sti" ON (("sti"."transfer_id" = "st"."id")))
  GROUP BY "st"."id", "st"."store_id", "st"."transfer_code", "st"."status", "st"."source_store_id", "st"."destination_store_id", "st"."source_location_id", "src"."code", "src"."name", "st"."destination_location_id", "dst"."code", "dst"."name", "st"."requested_at", "st"."approved_at", "st"."shipped_at", "st"."received_at", "st"."cancelled_at", "st"."notes", "st"."created_at", "st"."updated_at";


ALTER VIEW "public"."v_stock_transfers_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_stock_transfers_summary" IS 'Resumo consolidado das transferências por store com totais de quantidades e divergência.';



CREATE OR REPLACE VIEW "public"."v_supplier_latest_price" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("store_id", "supplier_id", "product_id") "store_id",
    "supplier_id",
    "product_id",
    "unit_cost",
    "quantity",
    "issue_date",
    "effective_at",
    "purchase_document_id"
   FROM "public"."supplier_price_history"
  WHERE ("is_active" = true)
  ORDER BY "store_id", "supplier_id", "product_id", "effective_at" DESC, "created_at" DESC;


ALTER VIEW "public"."v_supplier_latest_price" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_supplier_product_metrics" WITH ("security_invoker"='true') AS
 SELECT "sph"."store_id",
    "sph"."supplier_id",
    "sph"."product_id",
    "p"."name" AS "product_name",
    "count"(*) AS "purchase_events",
    "sum"("sph"."quantity") AS "total_quantity",
    "sum"("sph"."total_cost") AS "total_spent",
    "avg"("sph"."unit_cost") AS "avg_unit_cost",
    "min"("sph"."unit_cost") AS "min_unit_cost",
    "max"("sph"."unit_cost") AS "max_unit_cost",
    "max"("sph"."effective_at") AS "last_purchase_at",
    "min"("sph"."effective_at") AS "first_purchase_at"
   FROM ("public"."supplier_price_history" "sph"
     JOIN "public"."products" "p" ON (("p"."id" = "sph"."product_id")))
  WHERE ("sph"."is_active" = true)
  GROUP BY "sph"."store_id", "sph"."supplier_id", "sph"."product_id", "p"."name";


ALTER VIEW "public"."v_supplier_product_metrics" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_supplier_ranking" WITH ("security_invoker"='true') AS
 WITH "ranked_base" AS (
         SELECT "vm"."store_id",
            "vm"."supplier_id",
            "vm"."name",
            "vm"."total_spent",
            "vm"."total_documents",
            "vm"."confirmed_documents",
            "vm"."distinct_products",
            "vm"."last_purchase_at",
            "row_number"() OVER (PARTITION BY "vm"."store_id" ORDER BY "vm"."total_spent" DESC, "vm"."supplier_id") AS "rank_position",
            "sum"("vm"."total_spent") OVER (PARTITION BY "vm"."store_id") AS "store_total_spent"
           FROM "public"."v_supplier_metrics" "vm"
        )
 SELECT "store_id",
    "supplier_id",
    "name",
    "total_spent",
    "total_documents",
    "confirmed_documents",
    "distinct_products",
    "last_purchase_at",
    "rank_position",
        CASE
            WHEN (COALESCE("store_total_spent", (0)::numeric) = (0)::numeric) THEN (0)::numeric
            ELSE "round"((("total_spent" / "store_total_spent") * (100)::numeric), 2)
        END AS "share_pct",
        CASE
            WHEN ("rank_position" = 1) THEN 'leader'::"text"
            WHEN ("rank_position" <= 3) THEN 'top_3'::"text"
            WHEN ("rank_position" <= 10) THEN 'top_10'::"text"
            ELSE 'long_tail'::"text"
        END AS "ranking_band"
   FROM "ranked_base";


ALTER VIEW "public"."v_supplier_ranking" OWNER TO "postgres";


